window.__D("text/zohar-hebrew-translation/c009",{"p":[[9522011397,"<p>וַיְהִי מִקֵּץ שְׁנָתַיִם. רַבִּי חִיָּיא פָּתַח וְאָמַר, (משלי כט) מֶלֶךְ בְּמִשְׁפָּט יַעֲמִיד אָרֶץ וְאִישׁ תְּרוּמוֹת יֶהֶרְסֶנָּה. בֹּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם הָעֶלְיוֹן, הִתְקִין הַכֹּל כָּרָאוּי, וְהוֹצִיא אוֹרוֹת עֶלְיוֹנִים מְאִירִים לְכָל הַצְּדָדִים, וְהַכֹּל הוּא אֶחָד. וּבָרָא שָׁמַיִם שֶׁלְּמַעְלָה, וְאֶרֶץ שֶׁלְּמַעְלָה, לְתַקֵּן כֻּלָּם יַחַד לְתוֹעַלְתָּם שֶׁל הַתַּחְתּוֹנִים.</p>\n<p>בֹּא רְאֵה, מֶלֶךְ בְּמִשְׁפָּט יַעֲמִיד אָרֶץ, מִי הַמֶּלֶךְ? זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. בְּמִשְׁפָּט - זֶה יַעֲקֹב, שֶׁהוּא הַקִּיּוּם שֶׁל הָאָרֶץ, וְעַל כֵּן ו' נִזּוֹנֵית מֵה' הָעֶלְיוֹנָה, ה' הַתַּחְתּוֹנָה נִזּוֹנֵית מִן ו', שֶׁקִּיּוּם הָאָרֶץ הוּא בְּמִשְׁפָּט, שֶׁהֲרֵי הַמִּשְׁפָּט יַעֲמִיד אָרֶץ בְּכָל תִּקּוּנֶיהָ וְזָן אוֹתָהּ.</p>\n<p>דָּבָר אַחֵר, מֶלֶךְ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. בְּמִשְׁפָּט - זֶה יוֹסֵף. יַעֲמִיד אָרֶץ - שֶׁכָּתוּב (בראשית מא) וְכָל הָאָרֶץ בָּאוּ מִצְרַיְמָה לִשְׁבֹּר אֶל יוֹסֵף. וּמִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בְיַעֲקֹב, עָשָׂה אֶת יוֹסֵף שַׁלִּיט עַל הָאָרֶץ.</p>\n<p>רַבִּי יוֹסֵי אָמַר, מֶלֶךְ - זֶה יוֹסֵף. בְּמִשְׁפָּט יַעֲמִיד אָרֶץ - זֶה יַעֲקֹב. שֶׁהֲרֵי עַד שֶׁלֹּא בָא יַעֲקֹב לְמִצְרַיִם, לֹא הָיָה קִיּוּם בָּאָרֶץ מִתּוֹךְ הָרָעָב. כֵּיוָן שֶׁבָּא יַעֲקֹב לְמִצְרַיִם, בִּזְכוּתוֹ הִסְתַּלֵּק הָרָעָב וְהִתְקַיְּמָה הָאָרֶץ.</p>\n<p>דָּבָר אַחֵר, מֶלֶךְ בְּמִשְׁפָּט יַעֲמִיד אָרֶץ - זֶה דָּוִד הַמֶּלֶךְ, שֶׁכָּתוּב (שמואל ב ח) וַיְהִי דָוִד עֹשֶׂה מִשְׁפָּט וּצְדָקָה לְכָל עַמּוֹ, וְהוּא קִיֵּם אֶת הָאָרֶץ, וּבִזְכוּתוֹ עָמְדָה לְאַחַר מִכֵּן. וְאִישׁ תְּרוּמוֹת יֶהֶרְסֶנָּה - זֶה רְחַבְעָם.</p>\n<p>בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא, בִּשְׁבִיל הַצַּדִּיקִים, אַף עַל גַּב שֶׁפֻּרְעָנוּת נִגְזְרָה עַל הָעוֹלָם, הִיא מִתְעַכֶּבֶת בִּגְלָלָם וְלֹא שׁוֹלֶטֶת עַל הָעוֹלָם. כָּל יְמֵי דָוִד הַמֶּלֶךְ הִתְקַיְּמָה הָאָרֶץ בִּגְלָלוֹ. לְאַחַר שֶׁמֵּת, הִתְקַיְּמָה בִּזְכוּתוֹ, שֶׁכָּתוּב (מלכים ב כ) וְגַנּוֹתִי עַל הָעִיר הַזֹּאת לְהוֹשִׁיעָהּ לְמַעֲנִי וּלְמַעַן דָּוִד עַבְדִּי. כְּמוֹ כֵן כָּל יְמֵי יַעֲקֹב וְכָל יְמֵי יוֹסֵף לֹא שָׁלְטָה הַפֻּרְעָנוּת בָּעוֹלָם.</p>\n<p>בֹּא רְאֵה, מֶלֶךְ בְּמִשְׁפָּט יַעֲמִיד אָרֶץ - זֶה יוֹסֵף. וְאִישׁ תְּרוּמוֹת יֶהֶרְסֶנָּה - זֶה פַּרְעֹה, שֶׁהֲרֵי מִשּׁוּם שֶׁהִקְשָׁה אֶת לִבּוֹ לַקָּדוֹשׁ-בָּרוּךְ- הוּא, הֶחֱרִיב אֶת אֶרֶץ מִצְרַיִם. וּבָרִאשׁוֹנָה עַל יְדֵי יוֹסֵף הִתְקַיְּמָה הָאָרֶץ, בְּאוֹתוֹ הַחֲלוֹם שֶׁחָלַם, שֶׁכָּתוּב וַיְהִי מִקֵּץ שְׁנָתַיִם יָמִים וְגוֹ'.</p>\n<p>וַיְהִי מִקֵּץ וְגוֹ'. רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (תהלים יח) חַי ה' וּבָרוּךְ צוּרִי וְיָרוּם אֱלוֹהֵי יִשְׁעִי. אֱלוֹהֵי כָּתוּב בְּוָי\"ו. הַפָּסוּק הַזֶּה יֵשׁ לְהִתְבּוֹנֵן בּוֹ, חַי ה' - זֶה חַי, צַדִּיק יְסוֹד הָעוֹלָם, שֶׁנִּקְרָא חַי הָעוֹלָמִים. וּבָרוּךְ צוּרִי - זֶהוּ שֶׁכָּתוּב (שם קמד) בָּרוּךְ ה' צוּרִי, וְזֶה הָעוֹלָם שֶׁמִּתְקַיֵּם עַל הַצַּדִּיק הַזֶּה. וְיָרוּם אֱלוֹהֵי יִשְׁעִי. וְיָרוּם - זֶה הָעוֹלָם הָעֶלְיוֹן. אֱלוֹהֵי בְּוָא\"ו זֶה שָׁמַיִם, כְּמוֹ שֶׁנֶּאֱמַר (שם קטז) הַשָּׁמַיִם שָׁמַיִם לַה'.</p>\n<p>בֹּא רְאֵה, (כמו שנאמר) (שם סח) בָּרוּךְ אֲדנָ\"י יוֹם יוֹם יַעֲמָס לָנוּ. בָּרוּךְ אֲדנָ\"י, בְּאָלֶ\"ף דָּלֶ\"ת נוּ\"ן יוֹ\"ד, וְהַפָּסוּק הַזֶּה הוּא סוֹד הַחָכְמָה. יוֹם יוֹם - אֵלּוּ שְׁנָתַיִם יָמִים, כְּמוֹ שֶׁנֶּאֱמַר וַיְהִי מִקֵּץ שְׁנָתַיִם יָמִים. וּפַרְעֹה חֹלֵם וְהִנֵּה עֹמֵד עַל הַיְאֹר - סוֹד הוּא, כְּמוֹ שֶׁנֶּאֱמַר, זֶה יוֹסֵף, שֶׁנָּהָר (שכל הנהר) הַזֶּה הוּא יוֹסֵף הַצַּדִּיק.</p>\n<p>וְהִנֵּה מִן הַיְאֹר עֹלֹת שֶׁבַע פָּרוֹת יְפוֹת מַרְאֶה וּבְרִיאֹת בָּשָׂר וַתִּרְעֶינָה בָּאָחוּ. וְהִנֵּה מִן הַיְאֹר, שֶׁהֲרֵי מֵהַנָּהָר הַזֶּה מִתְבָּרְכוֹת כָּל אוֹתָן הַדְּרָגוֹת שֶׁלְּמַטָּה, מִשּׁוּם שֶׁאוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא הוּא מַשְׁקֶה וְזָן אֶת הַכֹּל, וְיוֹסֵף הוּא נָהָר שֶׁתִּתְבָּרֵךְ כָּל אֶרֶץ מִצְרַיִם בִּשְׁבִילוֹ.</p>\n<p>וּבֹא רְאֵה, אוֹתוֹ הַנָּהָר, שֶׁבַע דְּרָגוֹת נִשְׁקוֹת וּמִתְבָּרְכוֹת מִמֶּנּוּ, וְאֵלּוּ הֵם יְפוֹת מַרְאֶה וּבְרִיאֹת בָּשָׂר. וַתִּרְעֶינָה בָּאָחוּ, בְּחִבּוּר וְאַחֲוָה, שֶׁאֵין נִמְצָא בָהֶם פֵּרוּד וְכֻלָּם לְשֶׁבַח עוֹמְדִים. שֶׁהִנֵּה כָּל שֶׁבַע הַדְּרָגוֹת הַלָּלוּ שֶׁאָמַרְנוּ הוּא סוֹד, כְּמוֹ שֶׁנֶּאֱמַר (אסתר ב) וְאֵת שֶׁבַע הַנְּעָרוֹת הָרְאֻיוֹת לָתֶת לָהּ מִבֵּית הַמֶּלֶךְ וְגוֹ'. וְעַל כֵּן שֶׁבַע פָּרוֹת יְפוֹת מַרְאֶה, וּכְנֶגֶד זֶה כָּתוּב שִׁבְעַת הַסָּרִיסִים הַמְשָׁרְתִים אֶת פְּנֵי הַמֶּלֶךְ וְגוֹ'.</p>\n<p>רַבִּי יִצְחָק אָמַר, שֶׁבַע הַפָּרוֹת הַטּוֹבוֹת הֵם דְּרָגוֹת עֶלְיוֹנוֹת עַל הָאֲחֵרוֹת, וְשֶׁבַע הַפָּרוֹת הָרָעוֹת - הַדְּרָגוֹת הָאֲחֵרוֹת שֶׁלְּמַטָּה. אֵלּוּ מִצַּד הַקְּדֻשָּׁה, וְאֵלּוּ מִצַּד הַטֻּמְאָה.</p>\n<p>שֶׁבַע הַשִּׁבֳּלִים - רַבִּי יְהוּדָה אָמַר, אֵלּוּ הָרִאשׁוֹנוֹת הֵן טוֹבוֹת, מִשּׁוּם שֶׁהֵן מִצַּד הַיָּמִין שֶׁכָּתוּב בּוֹ כִּי טוֹב, וְאֵלּוּ הָרָעִים הֵם לְמַטָּה מֵהֶם. שֶׁבַע הַשִּׁבֳּלִים הֵן מִצַּד הַטָּהֳרָה, וְאֵלּוּ מִצַּד הַטֻּמְאָה, וְכָל הַדְּרָגוֹת עוֹמְדוֹת אֵלּוּ עַל אֵלּוּ וְאֵלּוּ כְּנֶגֶד אֵלּוּ, וְאֶת כֻּלָּם רָאָה פַּרְעֹה בַּחֲלוֹמוֹ.</p>\n<p>אָמַר רַבִּי יֵיסָא, וְכִי לְאוֹתוֹ פַרְעֹה הָרָשָׁע הֶרְאוּ לוֹ אֶת כָּל אֵלֶּה? אָמַר לוֹ רַבִּי יְהוּדָה, כְּמוֹתָם רָאָה, שֶׁכַּמָּה דְרָגוֹת עַל דְּרָגוֹת אֵלּוּ כְּנֶגֶד אֵלּוּ וְאֵלּוּ עַל אֵלּוּ, וְהוּא רָאָה בְּאוֹתָן הַדְּרָגוֹת שֶׁלְּמַטָּה.</p>\n<p>וְהִנֵּה שָׁנִינוּ, שֶׁהֲרֵי כְּמוֹ שֶׁהוּא הָאָדָם, כָּךְ מַרְאִים לוֹ בַּחֲלוֹמוֹ, וְכָךְ רוֹאֵה, וְכָךְ הַנְּשָׁמָה עוֹלָה לְהַכִּיר, כָּל אֶחָד וְאֶחָד כְּפִי דַרְגָּתוֹ כָּרָאוּי לוֹ, וּמִשּׁוּם כָּךְ פַּרְעֹה רָאָה כָּרָאוּי לוֹ, וְלֹא יוֹתֵר.</p>\n<p>וַיְהִי מִקֵּץ וְגוֹ'. רַבִּי חִזְקִיָּה פָּתַח וְאָמַר, (קהלת ג) לַכֹּל זְמַן וְעֵת לְכָל חֵפֶץ תַּחַת הַשָּׁמָיִם. בּא רְאֵה, כָּל מַה שֶּׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַטָּה, לַכֹּל שָׂם עֵת וּזְמַן קָצוּב. שָׂם זְמַן לָאוֹר וְלַחֹשֶׁךְ, שָׂם זְמַן לָאוֹר שֶׁל שְׁאָר הָעַמִּים, שֶׁהֵם שׁוֹלְטִים עַכְשָׁו עַל הָעוֹלָם, וּזְמַן שָׂם לַחֲשֵׁכָה, שֶׁהִיא הַגָּלוּת שֶׁל יִשְׂרָאֵל תַּחַת שִׁלְטוֹנָם. זְמַן שָׂם הַקָּדוֹשׁ בָּרוּךְ הוּא לַכֹּל, וּמִשּׁוּם כָּךְ לַכֹּל זְמַן וְעֵת לְכָל חֵפֶץ. מַה זֶּה וְעֵת לְכָל חֵפֶץ? זְמַן וְעִדָּן הוּא לַכֹּל, לְכָל אוֹתוֹ הָרָצוֹן שֶׁנִּמְצָא לְמַטָּה.</p>\n<p>דָּבָר אַחֵר וְעֵת לְכָל חֵפֶץ - מַה זֶּה עֵת? כַּכָּתוּב (תהלים קיט) עֵת לַעֲשׂוֹת לַה' הֵפֵרוּ תוֹרָתֶךְ. וְכָתוּב (ויקרא יז) וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ. וְהִיא הַדַּרְגָּה הַמְמֻנָּה, וְהִנֵּה פֵּרְשׁוּהָ. וּמִשּׁוּם כָּךְ עֵת הוּא הַמְמֻנֶּה לְכָל חֵפֶץ תַּחַת הַשָּׁמָיִם. וַיְהִי מִקֵּץ שְׁנָתַיִם יָמִים, מֵהַצַּד שֶׁל אוֹתוֹ קֵץ הַחֹשֶׁךְ רָאָה פַּרְעֹה בַּחֲלוֹמוֹ, וּמִשָּׁם יָדַע וְהִתְגַּלָּה לוֹ אוֹתוֹ הַחֲלוֹם.</p>"],[9522011398,"<p>וַיְהִי בַבֹּקֶר וַתִּפָּעֶם רוּחוֹ וַיִּשְׁלַח וַיִּקְרָא אֶת כָּל חַרְטֻמֵּי מִצְרַיִם וְאֶת כָּל חֲכָמֶיהָ וְגוֹ'. וַתִּפָּעֶם רוּחוֹ, מַה זֶּה וַתִּפָּעֶם? רַבִּי יוֹסֵי אָמַר, הִנֵּה פֵּרְשׁוּהָ שֶׁבְּפַרְעֹה כָּתוּב וַתִּפָּעֶם, וּבִנְבוּכַדְנֶצַּר כָּתוּב (דניאל ב) וַתִּתְפָּעֶם, וּבֵאֲרוּהָ שֶׁהִנֵּה בְּפַרְעֹה כָּתוּב וַתִּפָּעֶם מִשּׁוּם שֶׁהָיָה יוֹדֵעַ אֶת הַחֲלוֹם, וְהַפִּתְרוֹן לֹא הָיָה יוֹדֵעַ, אֲבָל נְבוּכַדְנֶצַּר רָאָה הַחֲלוֹם וְרָאָה הַפִּתְרוֹן, וְהַכֹּל נִשְׁכַּח מִמֶּנּוּ.</p>\n<p>אֲבָל בֹּא רְאֵה, וַתִּפָּעֶם רוּחוֹ, כְּמוֹ שֶׁנֶּאֱמַר (שופטים יג) לְפַעֲמוֹ, שֶׁהָיְתָה הָרוּחַ בָּאָה וְהוֹלֶכֶת וּבָאָה וְהוֹלֶכֶת וְלֹא הָיְתָה מִתְיַשֶּׁבֶת עִמּוֹ עֲדַיִן כָּרָאוּי, וְעַל כֵּן כָּתוּב (שם) וַתָּחֶל רוּחַ ה' לְפַעֲמוֹ, שֶׁאָז הָיְתָה הָרֵאשִׁית. אַף כָּאן רוּחוֹ הִתְעוֹרְרָה בּוֹ, וְהָלַךְ וְהִתְעוֹרֵר, וְלֹא הָיְתָה מְיֻשֶּׁבֶת עִמּוֹ לָדַעַת. נְבוּנַדְנֶצַּר וַתִּתְפָּעֶם רוּחוֹ, בְּהִתְעוֹרְרוּת הָיָה מִתְעוֹרֵר עַל כָּל אֶחָד פַּעֲמַיִם, שָׁבִים וְהוֹלְכִים וְשָׁבִים. וְזֶהוּ כְּמוֹ שֶׁנֶּאֱמַר (במדבר כד) כְּפַעַם בְּפַעַם, פַּעַם בָּזֶה וּפַעַם בָּזֶה, וְלֹא מִתְיַשֶּׁבֶת דַּעְתּוֹ וְרוּחוֹ.</p>\n<p>וַיִּשְׁלַח וַיִּקְרָא אֶת כָּל חַרְטֻמֵּי מִצְרַיִם - אֵלּוּ הַמְכַשְּׁפִים. וְאֶת כָּל חֲכָמֶיהָ - אֵלּוּ חַכְמֵי הַמַּזָּלוֹת. וְכֻלָּם הָיוּ מִסְתַּכְּלִים לָדַעַת וְלֹא יָכְלוּ לְהַשִּׂיג.</p>\n<p>אָמַר רַבִּי יִצְחָק, אַף עַל גַּב שֶׁנֶּאֱמַר שֶׁאֵין מַרְאִים לְאָדָם אֶלָּא בְּאוֹתָהּ הַדַּרְגָּה שֶׁלּוֹ - שׁוֹנֶה אֵצֶל הַמְּלָכִים, שֶׁמַּרְאִים לָהֶם דְּבָרִים עֶלְיוֹנִים וּמְשֻׁנִּים מִבְּנֵי אָדָם אֲחֵרִים. כְּמוֹ שֶׁמֶּלֶךְ דַּרְגָּתוֹ עֶלְיוֹנָה עַל כָּל שְׁאָר הָאֲחֵרִים, כָּךְ גַּם מַרְאִים לוֹ בְּדַרְגָּה עֶלְיוֹנָה עַל כָּל שְׁאָר הָאֲחֵרִים, כְּמוֹ שֶׁנֶּאֱמַר אֵת אֲשֶׁר הָאֱלֹהִים עֹשֶׂה הֶרְאָה אֶת פַּרְעֹה, אֲבָל לִשְׁאָר בְּנֵי הָאָדָם אֵין מְגַלֶּה לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת מַה שֶּׁהוּא עוֹשֶׂה, פְּרָט לַנְּבִיאִים אוֹ לַחֲסִידִים אוֹ לְחַכְמֵי הַדּוֹר, וְהִנֵּה פֵּרְשׁוּהָ.</p>\n<p>בֹּא רְאֵה, כָּתוּב אֹתִי הֵשִׁיב עַל כַּנִּי וְאֹתוֹ תָלָה. מִכָּאן שֶׁהַחֲלוֹם הוֹלֵךְ אַחַר הַפִּתְרוֹן. מִי הֵשִׁיב עַל כַּנִּי? אֶלָּא זֶה יוֹסֵף. וְאֹתוֹ תָלָה - בְּאוֹתוֹ הַפִּתְרוֹן שֶׁפָּתַר לוֹ, וְכָתוּב וַיְהִי כַּאֲשֶׁר פָּתַר לָנוּ כֵּן הָיָה.</p>"],[9522011399,"<p>וַיִּשְׁלַח פַּרְעֹה וַיִּקְרָא אֶת יוֹסֵף וַיְרִיצֻהוּ מִן הַבּוֹר וְגוֹ'. רַבִּי אַבָּא פָּתַח וְאָמַר, (תהלים קמז) רוֹצֶה ה' אֶת יְרֵאָיו אֶת הַמְיַחֲלִים לְחַסְדּוֹ. כַּמָּה הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְרַצֶּה בַּצַּדִּיקִים, מִשּׁוּם שֶׁהַצַּדִּיקִים הֵם עוֹשִׂים (שלום ועושים) שָׁלוֹם לְמַעְלָה וְעוֹשִׂים שָׁלוֹם לְמַטָּה, וּמַכְנִיסִים כַּלָּה לְבַעְלָהּ, וּמִשּׁוּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְרַצֶּה בָהֶם בְּאוֹתָם שֶׁיְּרֵאִים מִמֶּנּוּ וְעוֹשִׂים אֶת רְצוֹנוֹ.</p>\n<p>לַמְיַחֲלִים לְחַסְדּוֹ, מִי הֵם הַמְיַחֲלִים לְחַסְדּוֹ? הֱוֵה אוֹמֵר, אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה בַּלַּיְלָה וּמִשְׁתַּתְּפִים עִם הַשְּׁכִינָה. וּכְשֶׁבָּא הַבֹּקֶר, הֵם מְצַפִּים לְחַסְדּוֹ, וַהֲרֵי בֵּאֲרוּהָ, בִּזְמַן שֶׁאָדָם מִשְׁתַּדֵּל בַּתּוֹרָה בַּלַּיְלָה, חוּט שֶׁל חֶסֶד נִמְשָׁךְ עָלָיו בַּיּוֹם, כַּכָּתוּב (שם מב) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמִּי. מָה הַטַּעַם יוֹמָם יְצַוֶּה ה' חַסְדּוֹ? מִשּׁוּם שֶׁבַּלַּיְלָה שִׁירֹה עִמִּי. וּמִשּׁוּם כָּךְ כָּתוּב רוֹצֶה ה' אֶת יְרֵאָיו, וְלֹא בִּירֵאָיו. כְּמִי שֶׁרוֹצֶה בִּרְצוֹנוֹ אֶת הָאַחֵר וּמִתְרַצֶּה לוֹ לְהִתְפַּיֵּס עִמּוֹ, וּמִשּׁוּם כָּךְ רוֹצֶה ה' אֶת יְרֵאָיו וְלֹא בִּירֵאָיו.</p>\n<p>כְּמוֹ כֵן יוֹסֵף הָיָה עָצוּב בְּעֶצֶב הָרוּחַ וּבְעֶצֶב הַלֵּב, שֶׁהָיָה אָסוּר שָׁם. כֵּיוָן שֶׁפַּרְעֹה שָׁלַח בִּשְׁבִילוֹ, מַה כָּתוּב? וַיְרִיצֻהוּ. הִתְפַּיְּסוּ לוֹ וְהֶחֱזִירוּ לוֹ דִּבְרֵי שִׂמְחָה, דְּבָרִים לְשַׂמֵּחַ אֶת הַלֵּב, מִשּׁוּם שֶׁהָיָה עָצוּב מִן הַבּוֹר. בֹּא רְאֵה, בָּרִאשׁוֹנָה נָפַל בְּבוֹר, וּבְבוֹר הִתְעַלָּה אַחַר כָּךְ.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, בְּטֶרֶם אֵרַע לְיוֹסֵף אוֹתוֹ הַמַּעֲשֶׂה, לֹא נִקְרָא צַדִּיק. כֵּיוָן שֶׁשָּׁמַר אוֹתָהּ בְּרִית הַמִּילָה, נִקְרָא צַדִּיק, וְאוֹתָהּ הַדַּרְגָּה שֶׁל בְּרִית הַקֹּדֶשׁ הִתְעַטְּרָה עִמּוֹ, וּמַה שֶּׁהָיָה (עושה) בַּבּוֹר בָּרִאשׁוֹנָה, הִתְעַלָּה עִמּוֹ. וְכָתוּב וַיְרִיצֻהוּ מִן הַבּוֹר. הִתְעַלָּה מִזֶּה וְהִתְעַטֵּר בִּבְאֵר מַיִם חַיִּים.</p>\n<p>וַיִּשְׁלַח פַּרְעֹה וַיִּקְרָא אֶת יוֹסֵף, הָיָה צָרִיךְ לִהְיוֹת לִקְרֹא לְיוֹסֵף! אֶלָּא, וַיִּקְרָא אֶת יוֹסֵף - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (שם קה) עד עת בא דברו אמרת ה' צרפתהו. עד עת בא דברו, זהו שכתוב ויקרא את יוסף. כתוב כאן ויקרא את יוסף, וכתוב שם ויקרא אל משה. ויגלח ויחלף שמלתיו, בשביל כבוד המלך, והנה פרשוה.</p>\n<p>רַבִּי אֶלְעָזָר פָּתַח, (תהלים קה) ויבא ישראל מצרים ויעקב גר בארץ חם. בא ראה שהקדוש ברוך הוא מגלגל גלגולים בעולם, ומקים נדרים ושבועות כדי לקים שבועה וגזרה שהוא גוזר.</p>\n<p>שֶׁהֲרֵי שָׁנִינוּ, אִם לֹא שֶׁחֲבִיבוּת וְאַהֲבָה שֶׁאָהַב הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָאָבוֹת, הָיָה רָאוּי לְהוֹרִיד אֶת יַעֲקֹב לְמִצְרַיִם בִּכְבָלִים שֶׁל בַּרְזֶל. וּבְאַהֲבָתוֹ אוֹתָם הִמְלִיךְ לְיוֹסֵף בְּנוֹ, וְעָשָׂה אוֹתוֹ מֶלֶךְ שֶׁשּׁוֹלֵט עַל כָּל הָאָרֶץ, וְיָרְדוּ כָל הַשְּׁבָטִים בְּכָבוֹד, וְיַעֲקֹב כְּמֶלֶךְ.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב? (שם) וַיָּבֹא יִשְׂרָאֵל מִצְרָיִם וְיַעֲקֹב גָּר בְּאֶרֶץ חָם. כֵּיוָן שֶׁכָּתוּב וַיָּבא יִשְׂרָאֵל מִצְרָיִם, לֹא יָדַעְנוּ שֶׁיַּעֲקֹב גָּר בְּאֶרֶץ חָם? לָמָּה צָרִיךְ אֶת זֶה? אֶלָּא, וַיָּבֹא יִשְׂרָאֵל מִצְרָיִם - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְיַעֲקֹב גָּר בְּאֶרֶץ חָם - זֶה יַעֲקֹב. שֶׁהֲרֵי בִּשְׁבִיל יַעֲקֹב וּבָנָיו בָּאָה הַשְּׁכִינָה לְמִצְרַיִם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא גִּלְגֵּל גִּלְגּוּלִים וְהוֹרִיד אֶת יוֹסֵף בָּרִאשׁוֹנָה, שֶׁבִּזְכוּתוֹ הִתְקַיְּמָה הַבְּרִית עִמּוֹ, וְהִשְׁלִיט אוֹתוֹ עַל כָּל הָאָרֶץ.</p>\n<p>מַה כָּתוּב? שָׁלַח מֶלֶךְ וַיַּתִּירֵהוּ מֹשֵׁל עַמִּים וַיְפַתְּחֵהוּ. רַבִּי שִׁמְעוֹן אָמַר, כָּתוּב (תהלים קמו) ה' מַתִּיר אֲסוּרִים וְגוֹ', וְכָאן כָּתוּב שָׁלַח מֶלֶךְ וַיַּתִּירֵהוּ, לָמָּה מֹשֵׁל עַמִּים וַיְפַתְּחֵהוּ? אֶלָּא שָׁלַח מֶלֶךְ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. מֹשֵׁל עַמִּים - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. שָׁלַח מֶלֶךְ - הַמֶּלֶךְ הָעֶלְיוֹן שָׁלַח וַיַּתִּירֵהוּ. וּמִי הוּא שֶׁשָּׁלַח לוֹ? זֶה הַמַּלְאָךְ הַגּוֹאֵל, שֶׁהוּא מוֹשֵׁל עַמִּים, שֶׁהוּא מוֹשֵׁל עַל הַתַּחְתּוֹנִים, וְהַכֹּל הוּא מִן הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>וַיְרִיצֻהוּ - חָסֵר וָא\"ו, וּמִי הוּא? זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם שֶׁאֵין מִי שֶׁאוֹסֵר וּפוֹתֵחַ, רַק הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (איוב יב) יִסְגֹּר עַל אִישׁ וְלֹא יִפָּתֵחַ, וְכָתוּב (שם לד) וְהוּא יַשְׁקִיט וּמִי יַרְשִׁיעַ וְיַסְתֵּר פָּנִים וּמִי יְשׁוּרֶנּוּ וְעַל גּוֹי וְעַל אָדָם יָחַד, שֶׁהֲרֵי הַכֹּל בּוֹ, וְכָתוּב (דניאל ד) וְכִרְצוֹנוֹ עוֹשֶׂה בִּצְבָא הַשָּׁמַיִם וְדַיָּרֵי הָאָרֶץ, וְאֵין מִי שֶׁיִּמְחֶה בְיָדוֹ וְיֹאמַר לוֹ מֶה עָשִׂיתָ. וּמִשּׁוּם כָּךְ כָּתוּב וַיְרִיצֻהוּ מִן הַבּוֹר וְגוֹ'.</p>\n<p>מַה זֶה וַיְרִיצֻהוּ? כְּמוֹ שֶׁנֶּאֱמַר (איוב לג) יֶעְתַּר אֶל אֱלוֹהַּ וַיִּרְצֵהוּ. כְּמוֹ כֵן וַיְרִיצֻהוּ מִן הַבּוֹר, וְאַחַר כָּךְ וַיָּבֹא אֶל פַּרְעֹה. דָּבָר אַחֵר וַיְרִיצֻהוּ, שֶׁהִמְשִׁיךְ עָלָיו חוּט שֶׁל חֶסֶד לָתֵת לוֹ חֵן לִפְנֵי פַרְעֹה. אֱלֹהִים יַעֲנֶה אֶת שְׁלוֹם פַּרְעֹה, כְּדֵי לְהַקְדִּים לוֹ שָׁלוֹם וְלִפְתֹּחַ בְּשָׁלוֹם.</p>\n<p>רַבִּי אַבָּא אָמַר, בֹּא רְאֵה, בְּאוֹתוֹ פַרְעֹה הָרָשָׁע, שֶׁהוּא אָמַר (שמות ד) לֹא יָדַעְתִּי אֶת ה', וּפַרְעֹה הָיָה חָכָם מִכָּל מְכַשְּׁפָיו, אֶלָּא וַדַּאי הַשֵּׁם שֶׁל אֱלֹהִים הָיָה יוֹדֵעַ, שֶׁהֲרֵי כָּתוּב הֲנִמְצָא כָזֶה אִישׁ אֲשֶׁר רוּחַ אֱלֹהִים בּוֹ. וּמִשּׁוּם שֶׁמֹּשֶׁה לֹא בָא אֵלָיו אֶלָּא בַּשֵּׁם שֶׁל ה', וְלֹא בַּשֵּׁם שֶׁל אֱלֹהִים, וְזֶה הָיָה קָשֶׁה לְפָנָיו מִן הַכֹּל, שֶׁהוּא הָיָה יוֹדֵעַ שֶׁהֲרֵי הַשֵּׁם שֶׁל אֱלֹהִים שׁוֹלֵט בָּאָרֶץ, וּבַשֵּׁם שֶׁל ה' לֹא הָיָה יוֹדֵעַ, וְעַל כֵּן קָשֶׁה לְפָנָיו הַשֵּׁם הַזֶּה.</p>\n<p>וְזְהִוּ שֶׁכָּתוּב (שם ט) וַיְחַזֵּק ה' אֶת לֵב פַּרְעֹה. שֶׁדָּבָר זֶה הָיָה מְחַזֵּק אֶת לִבּוֹ וּמַקְשֶׁה אוֹתוֹ, וְעַל כֵּן מֹשֶׁה לֹא הוֹדִיעַ לוֹ דָּבָר שֶׁל שֵׁם אַחֵר, אֶלָּא הַשֵּׁם שֶׁל ה' לְבַדּוֹ, וּפֵרְשׁוּהָ.</p>\n<p>פָּתַח וְאָמַר, (תהלים קיג) מִי כַּה' אֱלֹהֵינוּ הַמַּגְבִּיהִי לָשָׁבֶת וְגוֹ'. מִי כַּה' אֱלֹהֵינוּ הַמַּגְבִּיהִי לָשָׁבֶת - שֶׁהִתְעַלָּה מֵעַל כִּסֵּא כְבוֹדוֹ, (על כסא כבודו למעלה) וְלֹא הִתְגַּלָּה לְמַטָּה. בְּשָׁעָה שֶׁאֵין נִמְצָאִים צַדִּיקִים בָּעוֹלָם, הֲרֵי הוּא מִסְתַּלֵּק מֵהֶם וְלֹא מִתְגַּלֶּה לָהֶם. הַמַּשְׁפִּילִי לִרְאוֹת - בְּשָׁעָה שֶׁהַצַּדִּיקִים הֵם נִמְצָאִים בָּעוֹלָם, הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹרֵד בְּדַרְגוֹתָיו כְּנֶגֶד הַתַּחְתּוֹנִים לְהַשְׁגִּיחַ עַל הָעוֹלָם, לְהֵיטִיב לָהֶם.</p>\n<p>שֶׁהֲרֵי כְּשֶׁאֵין נִמְצָאִים הַצַּדִּיקִים בָּעוֹלָם, הוּא מִסְתַּלֵּק וּמַסְתִּיר מֵהֶם פָּנִים וְלֹא מַשְׁגִּיחַ עֲלֵיהֶם, מִשּׁוּם שֶׁהַצַּדִּיקִים הֵם הַיְסוֹד וְהַקִּיּוּם שֶׁל הָעוֹלָם, שֶׁכָּתוּב (משלי י) וְצַדִּיק יְסוֹד עוֹלָם.</p>\n<p>וְעַל כֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא גִלָּה אֶת שְׁמוֹ הַקָּדוֹשׁ, רַק לְיִשְׂרָאֵל לְבַדָּם, שֶׁהֵם חֵלֶק גּוֹרָלוֹ וְנַחֲלָתוֹ, וְאֶת הָעוֹלָם חִלֵּק הַקָּדוֹשׁ בָּרוּךְ הוּא לִמְמֻנִּים מְגִנִּים, וְהִנֵּה נִתְבָּאֵר, שֶׁכָּתוּב (דברים לב) בְּהַנְחֵל עֶלְיוֹן גּוֹיִם וְגוֹ', וְכָתוּב כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ.</p>\n<p>רַבִּי חִיָּיא וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יוֹסֵי לְרַבִּי חִיָּיא, תְּמֵהַנִי עַל זֶה שֶׁאָמַר שְׁלֹמֹה, כָּל הַדְּבָרִים (המלים) סְתוּמִים וְלֹא נוֹדָעִים, שֶׁהֲרֵי קֹהֶלֶת סְתוּם (המלים) הַסְּתוּמִים.</p>\n<p>פָּתַח וְאָמַר, (קהלת א) כָּל הַדְּבָרִים יְגֵעִים לֹא יוּכַל אִישׁ לְדַבֵּר לֹא תִשְׂבַּע עַיִן לִרְאוֹת וְלֹא תִמָּלֵא אֹזֶן מִשְּׁמֹעַ. כָּל הַדְּבָרִים יְגֵעִים, וְכִי כָּל הַדְּבָרִים יְגֵעִים הֵם לְדִבּוּר שֶׁאָמַר לֹא יוּכַל אִישׁ לְדַבֵּר? וְלֹא תִשְׂבַּע עַיִן לִרְאוֹת וְלֹא תִמָּלֵא אֹזֶן מִשְּׁמֹעַ, מָה הַטַּעַם אֵלּוּ? אֶלָּא מִשּׁוּם שֶׁשְּׁנַיִם מֵהֶם, וְהֵם הָעֵינַיִם וְהָאָזְנַיִם, לֹא עוֹמְדִים בִּרְשׁוּתוֹ שֶׁל הָאָדָם, וְהַפֶּה הוּא בִּרְשׁוּתוֹ, וְכָל (מה) שְׁלֹשֶׁת הַלָּלוּ לֹא יְכוֹלִים לְהַשְׁלִים אֶת הַכֹּל וּלְהַשִּׂיג אֶת הַכֹּל.</p>\n<p>אָמַר רַבִּי חִיָּיא, כָּךְ זֶה, שֶׁדִּבּוּר שֶׁל אָדָם לֹא יָכוֹל לְדַבֵּר, וְהָעֵינַיִם לִרְאוֹת וְהָאָזְנַיִם לִשְׁמֹעַ, וְאֵין כָּל חָדָשׁ תַּחַת הַשֶּׁמֶשׁ. וּבא רְאֵה, אֲפִלּוּ בְּרִיּוֹת וְרוּחוֹת שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא תַּחַת הַשֶּׁמֶשׁ לֹא יְכוֹלִים לְדַבֵּר כָּל דִּבְרֵי הָעוֹלָם, וְהָעַיִן לֹא יְכוֹלָה לִשְׁלֹט וְלִרְאוֹת וְהָאֹזֶן לִשְׁמֹעַ. וּמִשּׁוּם כָּךְ שְׁלֹמֹה שֶׁהָיָה יוֹדֵעַ כָּל דָּבָר הָיָה אוֹמֵר אֶת זֶה.</p>\n<p>וּבֹא וּרְאֵה, כָּל מַעֲשֵׂי הָעוֹלָם תְּלוּיִים בְּכַמָּה רוּחוֹת, וְכָל בְּנֵי הָעוֹלם לֹא יוֹדְעִים וְלֹא מַשְׁגִּיחִים עַל מָה עוֹמְדִים בָּעוֹלָם, וַאֲפִלּוּ שְׁלֹמֹה הַמֶּלֶךְ, שֶׁהָיָה חָכָם מִכָּל בְּנֵי הָעוֹלָם, לֹא יָכֹל לַעֲמֹד בָּהֶם.</p>\n<p>פָּתַח וְאָמַר, (קהלת ג) אֶת הַכֹּל עָשָׂה יָפֶה בְעִתּוֹ גַּם אֶת הָעֹלָם נָתַן בְּלִבָּם מִבְּלִי אֲשֶׁר לֹא יִמְצָא הָאָדָם אֶת הַמַּעֲשֶׂה אֲשֶׁר עָשָׂה הָאֱלֹהִים וְגוֹ'. בֹּא רְאֵה, אַשְׁרֵי אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה וְיוֹדְעִים לְהִסְתַּכֵּל בָּרוּחַ (בסוד) שֶׁל הַחָכְמָה. אֶת הַכֹּל עָשָׂה יָפֶה בְעִתּוֹ - בְּכָל הַמַּעֲשִׂים שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם, בְּכָל מַעֲשֶׂה וּמַעֲשֶׂה יֵשׁ דַּרְגָּה מְמֻנָּה עַל אוֹתוֹ הַמַּעֲשֶׂה בָּעוֹלָם, הֵן לְטוֹב וְהֵן לְרַע. מֵהֶם דְּרָגוֹת לְיָמִין, וּמֵהֶם דְּרָגוֹת לִשְׂמֹאל. הוֹלֵךְ הָאָדָם לְיָמִין, אוֹתוֹ הַמַּעֲשֶׂה שֶׁעָשָׂה, אוֹתָהּ הַדַּרְגָּה הַמְמֻנָּה (של ימין) לַצַּד הַהוּא וְעוֹשָׂה לוֹ סִיּוּעַ, וְכַמָּה הֵם שֶׁמְּסַיְּעִים לוֹ. הוֹלֵךְ אָדָם לִשְׂמֹאל וְעוֹשֶׂה מַעֲשָׂיו, אוֹתוֹ הַמַּעֲשֶׂה שֶׁעָשָׂה, הוּא (דרגת השמאל) הַמְמֻנֶּה לַצַּד הַהוּא, וּמְקַטְרֵג לוֹ וּמוֹבִיל אוֹתוֹ לְאוֹתוֹ הַצַּד וּמַסְטֶה אוֹתוֹ. וּמִשּׁוּם כָּךְ, אוֹתוֹ הַמַּעֲשֶׂה שֶׁאָדָם עוֹשֶׂה כָּרָאוּי, אוֹתוֹ הַמְמֻנֶּה שֶׁל צַד הַיָּמִין מְסַיֵּעַ לוֹ. וְזֶה הוּא בְּעִתּוֹ, יָפֶה בְעִתּוֹ, שֶׁאוֹתוֹ הַמַּעֲשֶׂה מִתְקַשֵּׁר בְּעִתּוֹ כָּרָאוּי לוֹ.</p>\n<p>גַּם אֶת הָעֹלָם נָתַן בְּלִבָּם - כָּל הָעוֹלָם וְכָל מַעֲשֵׂי הָעוֹלָם אֵינָם אֶלָּא בִּרְצוֹן הַלֵּב, כְּשֶׁעוֹלֶה בִרְצוֹן (הלב, וכשעולה ברצון) הָאָדָם. אַשְׁרֵי הַצַּדִּיקִים שֶׁמּוֹשְׁכִים מַעֲשִׂים טוֹבִים לְהֵיטִיב לָהֶם וּלְכָל הָעוֹלָם, וְהֵם יוֹדְעִים לְהִתְדַּבֵּק בְּעֵת שָׁלוֹם, וּבְכֹחַ הַצְּדָקָה שֶׁעוֹשִׂים לְמַטָּה הֵם מוֹשְׁכִים אוֹתָהּ הַדַּרְגָּה שֶׁנִּקְרֵאת כֹּל, לְהָאִיר בְּעִתּוֹ.</p>\n<p>אוֹי לָרְשָׁעִים שֶׁאֵין יוֹדְעִים הָעֵת שֶׁל אוֹתוֹ מַעֲשֶׂה וְלֹא מַשְׁגִּיחִים לַעֲשׂוֹת מַעֲשֵׂיהֶם בָּעוֹלָם עַל הַתִּקּוּן שֶׁצָּרִיךְ לָעוֹלָם וּלְתַקֵּן הַמַּעֲשֶׂה בְּאוֹתָהּ הַדַּרְגָּה שֶׁרְאוּיָה לוֹ. מָה הַטַּעַם? מִשּׁוּם שֶׁלֹּא יוֹדְעִים.</p>\n<p>וְעַל כֵּן נִתָּן הַכֹּל בִּרְצוֹנָם שֶׁל בְּנֵי הָאָדָם, שֶׁכָּתוּב מִבְּלִי אֲשֶׁר לֹא יִמְצָא הָאָדָם אֶת הַמַּעֲשֶׂה אֲשֶׁר עָשָׂה הָאֱלֹהִים מֵרֹאשׁ וְעַד סוֹף. וּמִשּׁוּם כָּךְ שֶׁאוֹתָם הַמַּעֲשִׂים לֹא נַעֲשׂוּ לְתַקֵּן בְּדַרְגָּתָם כָּרָאוּי שֶׁיִּכָּלֵל הַמַּעֲשֶׂה הַזֶּה בַּדַּרְגָּה הַזּוֹ שֶׁלֹּא כְתִקּוּן, אֶלָּא כְּפִי רְצוֹן הָאָדָם. מַה כָּתוּב אַחֲרָיו? יָדַעְתִּי כִּי אֵין טוֹב בָּם כִּי אִם לִשְׂמוֹחַ וְלַעֲשׂוֹת טוֹב בְּחַיָּיו. יָדַעְתִּי כִּי אֵין טוֹב בָּם, בְּאוֹתָם הַמַּעֲשִׂים שֶׁלֹּא נַעֲשׂוּ כָּרָאוּי. כִּי אִם לִשְׂמוֹחַ, בְּכָל מַה שֶּׁיָּבא עָלָיו וְלָתֵת הוֹדָאָה לַקָּדוֹשׁ-בָּרוּךְ-הוּא וְלַעֲשׂוֹת טוֹב בְּחַיָּיו. שֶׁהֲרֵי אִם אוֹתוֹ הַמַּעֲשֶׂה גּוֹרֵם לוֹ רַע, מִשּׁוּם אוֹתָהּ הַדַּרְגָּה שֶׁמְּמֻנָּה עָלָיו, יֵשׁ לוֹ לִשְׂמֹחַ בּוֹ וּלְהוֹדוֹת עָלָיו, שֶׁהוּא גָרַם לְעַצְמוֹ, וְהוּא הוֹלֵךְ בְּלִי יְדִיעָה כַּצִּפּוֹר הַזּוֹ בְּתוֹךְ מַלְכֹּדֶת.</p>\n<p>וְכָל זֶה מִנַּיִן לָנוּ? שֶׁכָּתוּב (שם ט) כִּי גַּם לֹא יֵדַע הָאָדָם אֶת עִתּוֹ כַּדָּגִים שֶׁנֶּאֱחָזִים בִּמְצוֹדָה רָעָה וְכַצִּפֳּרִים הָאֲחֻזוֹת בַּפָּח כָּהֵם יוּקָשִׁים בְּנֵי הָאָדָם לְעֵת רָעָה כְּשֶׁתִּפּוֹל עֲלֵיהֶם פִּתְאוֹם. כִּי גַּם לֹא יֵדַע הָאָדָם אֶת עִתּוֹ, מַה זֶּה עִתּוֹ? עִתּוֹ שֶׁל אוֹתוֹ הַמַּעֲשֶׂה שֶׁעוֹשֶׂה, כְּמוֹ שֶׁנֶּאֱמַר אֶת הַכֹּל עָשָׂה יָפֶה בְעִתּוֹ. וּמִשּׁוּם כָּךְ הֵם כַּצִּפֳּרִים הָאֲחֻזוֹת בַּפָּח. וּמִשּׁוּם כָּךְ אַשְׁרֵי אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה וְיוֹדְעִים דַּרְכֵי וּשְׁבִילֵי הַתּוֹרָה שֶׁל הַמֶּלֶךְ הָעֶלְיוֹן לָלֶכֶת בָּהּ בְּדֶרֶךְ הָאֱמֶת.</p>\n<p>וּבֹא רְאֵה, לְעוֹלָם אַל יִפְתַּח אָדָם אֶת פִּיו לְרָעָה, שֶׁהוּא לֹא יוֹדֵעַ מִי נוֹטֵל אוֹתוֹ הַדָּבָר, וּכְשֶׁלֹּא יוֹדֵעַ אָדָם, נִכְשָׁל בָּהּ. וְכַאֲשֶׁר הַצַּדִּיקִים פּוֹתְחִים אֶת פִּיהֶם, כֻּלָּם שָׁלוֹם. בֹּא רְאֵה, כְּשֶׁיּוֹסֵף הִתְחִיל לְדַבֵּר עִם פַּרְעֹה, מַה כָּתוּב? אֱלֹהִים יַעֲנֶה אֶת שְׁלוֹם פַּרְעֹה. אָמַר רַבִּי יְהוּדָה, הִנֵּה נִתְבָּאֵר שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עַל שְׁלוֹם הַמַּלְכוּת, כְּמוֹ שֶׁנֶּאֱמַר וַיְצַוֵּם אֶל בְּנֵי יִשְׂרָאֵל וְאֶל פַּרְעֹה מֶלֶךְ מִצְרַיִם, וּבֵאֲרוּהוּ.</p>"],[9522011400,"<p>רַבִּי חִיָּיא אָמַר, פַּרְעֹה רָצָה לְנַסּוֹת אֶת יוֹסֵף, וְהֶחֱלִיף לוֹ אֶת הַחֲלוֹם, וּמִשּׁוּם שֶׁיּוֹסֵף יָדַע אֶת הַדְּרָגוֹת, הִסְתַּכֵּל בְּכָל דָּבָר וְדָבָר וְאָמַר כָּךְ רָאִיתָ, כָּל דָּבָר וְדָבָר כָּרָאוּי לוֹ.</p>\n<p>זְהִוּ שֶׁכָּתוּב: וַיֹּאמֶר פַּרְעֹה אֶל יוֹסֵף אַחֲרֵי הוֹדִיעַ אֱלֹהִים אוֹתְךְ אֶת כָּל זאת אֵין נָבוֹן וְחָכָם כָּמוֹךְ. אַחֲרֵי הוֹדִיעַ אֱלֹהִים, אַחֲרַי הָיִיתָ בַּשָּׁעָה הַהִיא שֶׁחָלַמְתִּי אֶת הַחֲלוֹם, שָׁם הָיִיתָ מָצוּי. וּמִשּׁוּם כָּךְ אָמַר (אמת את כל זאת ידעת, ואיך ידעת פתרונו) את כל זאת, ידעת את החלום איך היה וידעת פתרונו.</p>\n<p>אָמַר רַבִּי יִצְחק, אִם כָּךְ, יוֹסֵף אָמַר הַכֹּל, הַחֲלוֹם וּפִתְרוֹנוֹ, כְּמוֹ דָנִיֵּאל שֶׁאָמַר אֶת הַחֲלוֹם וְאֶת פִּתְרוֹנוֹ! אָמַר לוֹ, לֹא זֶה כְּמוֹ זֶה. (שהרי) יוֹסֵף הִסְתַּכֵּל מִתּוֹךְ דִּבּוּרוֹ שֶׁל פַּרְעֹה, שֶׁהָיָה אוֹמֵר בִּדְרָגוֹת יְדוּעוֹת, וְרָאָה אוֹתוֹ שֶׁטָּעָה, וְאָמַר לוֹ לֹא כָּךְ, אֶלָּא כָּךְ זֶה, מִשּׁוּם שֶׁהַדְּרָגוֹת בָּאוֹת כְּסִדְרָן. אֲבָל דָּנִיֵּאל לֹא הִסְתַּכֵּל מִתּוֹךְ דִּבּוּרוֹ שֶׁל נְבוּכַדְנֶצַּר כְּלוּם, (שלא) וְהַכֹּל אָמַר לוֹ, אֶת הַחֲלוֹם וּפִתְרוֹנוֹ.</p>\n<p>מַה כָּתוּב בְּדָנִיֵּאל? (דניאל ב) אָז לְדָנִיֵּאל בְּחֶזְיוֹן הַלַּיְלָה סוֹד גִּלָּה. בְּחֶזְיוֹן הַלַּיְלָה, מִי חֶזְיוֹן הַלַּיְלָה? זֶה גַבְרִיאֵל, שֶׁהוּא חִזָּיוֹן, מַרְאֶה מִן מַרְאֶה.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב, (יחזקאל מג) וְהִנֵּה כְּבוֹד אֱלֹהֵי יִשְׂרָאֵל בָּא מִדֶּרֶךְ הַקָּדִים וְקוֹלוֹ כְּקוֹל מַיִם רַבִּים וְהָאָרֶץ הֵאִירָה מִכְּבֹדוֹ. מַה כָּתוּב אַחֲרָיו? וּכְמַרְאֵה הַמַּרְאֶה אֲשֶׁר רָאִיתִי בְּבאִי לְשַׁחֵת אֶת הָעִיר וּמַרְאוֹת כַּמַּרְאֶה אֲשֶׁר רָאִיתִי אֶל נְהַר כְּבָר וָאֶפֹּל אֶל פָּנָי. כָּל הַמַּרְאוֹת הַלָּלוּ הֵן שֵׁשׁ. שֶׁאוֹתָן הַמַּרְאוֹת, וּמַרְאֶה שֶׁל הַחִזָּיוֹן, מַרְאֶה יֵשׁ לוֹ, שֶׁיֵּרָאוּ בוֹ הַגְּוָנִים שֶׁלְּמַעְלָה, וְנִרְאִים בַּמַּרְאֶה הַהוּא. וְיֵשׁ מַרְאֶה לַמַּרְאֶה, וּמַרְאֶה לַמַּרְאֶה זֶה עַל זֶה, וְכֻלָּם עוֹמְדִים בִּדְרָגוֹת יְדוּעוֹת וְשׁוֹלְטִים, וְנִקְרָאִים מַרְאֵה הַלַּיְלָה, וּבָהֶם מִתְפָּרְשִׁים כָּל הַחֲלוֹמוֹת שֶׁל הָעוֹלָם, וְאֵלּוּ הֵם כְּמוֹ שֶׁלְּמַעְלָה, עֲלֵיהֶם.</p>\n<p>וּמִשּׁוּם כָּךְ דָּנִיֵּאל בְּחֶזְיוֹן הַלַּיְלָה גִּלָּה סוֹד. לֹא כָתוּב הִתְגַּלָּה, אֶלָּא סוֹד גִּלָּה, אַחַת מֵאֵלּוּ הַדְּרָגוֹת, גִּלָּה לוֹ אוֹתוֹ חֲלוֹם וּפִתְרוֹנוֹ. אֲבָל יוֹסֵף מִתּוֹךְ דִּבְרֵי פַרְעֹה הִסְתַּכֵּל בַּדְּרָגוֹת הָעֶלְיוֹנוֹת וְאָמַר.</p>\n<p>וּמִשּׁוּם כָּךְ מִנָּה אוֹתוֹ עַל כָּל אֶרֶץ מִצְרַיִם, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לְיוֹסֵף מִשֶּׁלּוֹ. עַל הַפֶּה שֶׁלֹּא נָשַׁק לָעֲבֵרָה, כָּתוּב וְעַל פִּיךְ יִשַּׁק כָּל עַמִּי. הַיָּד שֶׁלֹּא קָרְבָה לָעֲבֵרָה, כָּתוּב וַיִּתֵּן אֹתָהּ עַל יַד יוֹסֵף. הַצַּוָּאר שֶׁלֹּא קָרַב לָעֲבֵרָה, כָּתוּב וַיָּשֶׂם רְבִד הַזָּהָב עַל צַוָּארוֹ. הַגּוּף שֶׁלֹּא קָרַב לָעֲבֵרָה - וַיַּלְבֵּשׁ אֹתוֹ בִּגְדֵי שֵׁשׁ. הָרֶגֶל שֶׁל רָכְבָה לָעֲבֵרָה, כָּתוּב וַיַּרְכֵּב אֹתוֹ בְּמִרְכֶּבֶת הַמִּשְׁנֶה אֲשֶׁר לוֹ. הַמַּחֲשָׁבָה שֶׁלֹּא חָשַׁב - נִקְרָא נָבוֹן וְחָכָם. הַלֵּב שֶׁלֹּא הִרְהֵר - וַיִּקְרְאוּ לְפָנָיו אַבְרֵךְ. וְהַכֹּל מִשֶּׁלּוֹ הוּא נָטַל.</p>\n<p>מַה כָּתוּב? וַיֵּצֵא יוֹסֵף מִלִּפְנֵי פַרְעֹה וַיַּעֲבֹר בְּכָל אֶרֶץ מִצְרָיִם. אָמַר רַבִּי חִזְקִיָּה, מָה הַטַּעַם וַיַּעֲבֹר בְּכָל אֶרֶץ מִצְרָיִם? כְּדֵי לִשְׁלֹט, שֶׁכָּךְ מַכְרִיזִים לְפָנָיו, וּכְדֵי לִכְנֹס הַתְּבוּאָה בְּכָל מָקוֹם וּמָקוֹם. רַבִּי אֶלְעָזָר אָמַר, כִּנֵּס יוֹסֵף תְּבוּאָה בְּכָל מָקוֹם כְּדֵי שֶׁלֹּא תִרְקַב.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, כָּל מַה שֶּׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה, הַכֹּל הוּא לְגַלְגֵּל גִּלְגּוּלִים, מִשּׁוּם שֶׁרָצָה לְקַיֵּם הַגְּזֵרָה. בּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, הֵבִיא כָּל מַה שֶּׁצָּרִיךְ הָעוֹלָם בָּרִאשׁוֹנָה, וְאַחַר כָּךְ הֵבִיא אֶת הָאָדָם לָעוֹלָם וּמָצָא מָזוֹן.</p>\n<p>(בא ראה) כְּמוֹ כֵן הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לְאַבְרָהָם, (בראשית טו) יָדֹעַ תֵּדַע כִּי גֵר יִהְיֶה זַרְעֲךְ בְּאֶרֶץ לֹא לָהֶם וְגוֹ', וְאַחֲרֵי כֵן יֵצְאוּ בִּרְכֻשׁ גָּדוֹל. כְּשֶׁבָּא יוֹסֵף לְאֶרֶץ מִצְרַיִם, לֹא מָצָא בָּהּ רְכוּשׁ גָּדוֹל. גִּלְגֵּל גִּלְגּוּלִים, וְהֵבִיא רָעָב עַל הָעוֹלָם, וְכָל הָעוֹלָם הָיוּ מְבִיאִים כֶּסֶף וְזָהָב לְמִצְרַיִם, וְהִתְמַלְּאָה כָּל אֶרֶץ מִצְרַיִם כֶּסֶף וְזָהָב. לְאַחַר שֶׁהַכֹּל נִתְקַן רְכוּשׁ גָּדוֹל, הֵבִיא אֶת יַעֲקֹב לְמִצְרַיִם.</p>\n<p>שֶׁכָּךָ דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא - בָּרִאשׁוֹנָה בּוֹרֵא (מקדים) רְפוּאָה, וְאַחַר כָּךְ מַכֶּה. כָּךְ בָּרִאשׁוֹנָה הִתְקִין רְכוּשׁ גָּדוֹל, וְאַחַר כָּךְ הֵבִיא אוֹתָם לַגָּלוּת, וְעַל כֵּן גִּלְגֵּל גִּלְגּוּלִים וְהֵבִיא רָעָב עַל (כל) הָעוֹלָם, כְּדֵי שֶׁיִּהְיוּ מְבִיאִים כֶּסֶף וְזָהָב כָּל הָעוֹלָם לְמִצְרַיִם.</p>\n<p>בֹּא רְאֵה, מִשּׁוּם יוֹסֵף שֶׁהוּא צַדִּיק, הוּא גָרַם עֹשֶׁר שֶׁל כֶּסֶף וְזָהָב שֶׁיִּטְלוּ יִשְׂרָאֵל, כַּכָּתוּב (תהלים קה) וַיּוֹצִיאֵם בְּכֶסֶף וְזָהָב וְאֵין בִּשְׁבָטָיו כּוֹשֵׁל. וּמִיָּדוֹ שֶׁל הַצַּדִּיק זֶה בָּא לְיִשְׂרָאֵל, וְהַכֹּל לְזַכּוֹת אוֹתָם לָעוֹלָם הַבָּא.</p>\n<p>פָּתַח וְאָמַר, (קהלת ט) רְאֵה חַיִּים עִם אִשָּׁה אֲשֶׁר אָהַבְתָּ וְגוֹ'. בּא רְאֵה, הַפָּסוּק הַזֶּה הוּא בְּסוֹד עֶלְיוֹן, וּבֵאֲרוּהוּ. רְאֵה חַיִּים - אֵלּוּ חַיֵּי הָעוֹלָם הַבָּא, שֶׁאַשְׁרֵי הָאִישׁ שֶׁזּוֹכֶה לוֹ כָּרָאוּי.</p>\n<p>עִם אִשָּׁה אֲשֶׁר אָהַבְתָּ - זוֹ כְּנֶסֶת יִשְׂרָאֵל, מִשּׁוּם שֶׁבָּהּ כָּתוּב אַהֲבָה, שֶׁכָּתוּב (ירמיה לא) וְאַהֲבַת עוֹלָם אֲהַבְתִּיךְ. מָתַי? בְּשָׁעָה שֶׁצַּד הַיָּמִין אוֹחֵז אוֹתָהּ, שֶׁכָּתוּב (שם) עַל כֵּן מְשַׁכְתִּיךְ חָסֶד.</p>\n<p>כָּל יְמֵי חַיֵי הֶבְלֶךְ, מִשּׁוּם שֶׁהִיא נִקְשֶׁרֶת בַּחַיִּים, וְהִיא הָעוֹלָם שֶׁשּׁוֹרִים בָּהּ חַיִּים. שֶׁהֲרֵי הָעוֹלָם הַזֶּה לֹא שׁוֹרִים בּוֹ חַיִּים, מִשּׁוּם שֶׁהֵם תַּחַת הַשֶּׁמֶשׁ, וְלֹא מַגִּיעִים לְכָאן אוֹתָם הָאוֹרוֹת שֶׁל אוֹתָהּ הַשֶּׁמֶשׁ, וְהִסְתַּלְּקוּ מֵהָעוֹלָם מִיּוֹם שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, שֶׁכָּתוּב (ישעיה יג) חָשַׁךְ הַשֶּׁמֶשׁ בְּצֵאתוֹ וְגוֹ'. מַה זֶּה חָשַׁךְ הַשֶּׁמֶשׁ? שֶׁסִּלֵּק אֶת אוֹרוֹ וְלֹא מֵאִיר, כְּמוֹ שֶׁנֶּאֱמַר (שם נז) הַצַּדִּיק אָבָד וְגוֹ'.</p>\n<p>כִּי הוּא חֶלְקְךְ בַּחַיִּים - זֶהוּ הַשֶּׁמֶשׁ עִם הַלְּבָנָה. וּצְרִיכִים לְהַכְנִיס הַלְּבָנָה בַּשֶּׁמֶשׁ וְהַשֶּׁמֶשׁ בַּלְּבָנָה שֶׁלֹּא לְהַפְרִידָם, וְזֶה הוּא חֵלֶק הָאָדָם לְהִכָּנֵס עִמָּם לָעוֹלָם הַבָּא.</p>\n<p>מַה כָּתוּב אַחֲרָיו? (קהלת ט) כָּל אֲשֶׁר תִּמְצָא יָדְךְ לַעֲשׂוֹת בְּכֹחֲךְ עֲשֵׂה כִּי אֵין מַעֲשֶׂה וְחֶשְׁבּוֹן וְדַעַת וְחָכְמָה בִּשְׁאוֹל אֲשֶׁר אַתָּה הֹלֵךְ שָׁמָּה. הַפָּסוּק הַזֶּה יֵשׁ לְהִתְבּוֹנֵן בּוֹ. כָּל אֲשֶׁר תִּמְצָא יָדְךְ לַעֲשׂוֹת, וְכִי הֻתְּרָה הָרְצוּעָה שֶׁאָדָם יַעֲשֶׂה כָּל מַה שֶּׁיָּכוֹל? אֶלָּא כָּתוּב לַעֲשׂוֹת בְּכֹחֲךְ. מַה זֶּה בְּכֹחֲךְ? זוֹ נִשְׁמָתוֹ שֶׁל הָאָדָם, שֶׁהִיא הַכֹּחַ שֶׁל הָאָדָם, לִזְכּוֹת בָּהּ לָעוֹלָם הַזֶּה וְלָעוֹלָם הַבָּא.</p>\n<p>דָּבָר אַחֵר בְּכֹחֲךְ - זוֹ הָאִשָּׁה שֶׁאָמַרְנוּ, שֶׁהִיא הַכֹּחַ לְהִתְחַזֵּק בָּהּ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. וְצָרִיךְ בֶּן אָדָם לִזְכּוֹת בָּהּ בְּזֶה הָעוֹלָם בְּכֹחַ זֶה, כְּדֵי שֶׁיִּתְגַּבֵּר בָּהּ לָעוֹלָם הַהוּא.</p>\n<p>מָה הַטַּעַם? מִשּׁוּם שֶׁאַחַר שֶׁיָּצָא הָאָדָם מִן הָעוֹלָם הַזֶּה, אֵין בּוֹ כֹּחַ לַעֲשׂוֹת דָּבָר וְלוֹמַר, עַכְשָׁו מִכָּאן וָהָלְאָה אֶעֱשֶׂה מַעֲשִׂים טוֹבִים. שֶׁוַּדַּאי שֶׁאֵין מַעֲשֶׂה וְחֶשְׁבּוֹן וְדַעַת וְחָכְמָה בִּשְׁאוֹל אֲשֶׁר וְגוֹ'. אִם לֹא זוֹכֶה אָדָם בָּעוֹלָם הַזֶּה, לֹא יִזְכֶּה בּוֹ אַחַר כָּךְ לָעוֹלָם הַהוּא. וּבֵאֲרוּהָ, מִי שֶׁלֹּא מַתְקִין צֵידָה לָלֶכֶת מִן הָעוֹלָם הַזֶּה, לֹא יֹאכַל בָּעוֹלָם הַהוּא. וְיֵשׁ מַעֲשִׂים טוֹבִים שֶׁעוֹשֶׂה אָדָם בָּעוֹלָם הַזֶּה שֶׁיֹּאכַל מֵהֶם כָּאן, וְהַכֹּל נִשְׁאָר לָעוֹלָם הַבָּא וּלְהִזּוֹן מֵהֶם.</p>\n<p>בֹּא רְאֵה, יוֹסֵף זָכָה בָּעוֹלָם הַזֶּה וְזָכָה בָּעוֹלָם הַבָּא, מִשּׁוּם שֶׁרָצָה לְהֵאָחֵז בְּאִשָּׁה יִרְאַת ה', כְּמוֹ שֶׁנֶּאֱמַר (בראשית לט) וְחָטָאתִי לֵאלֹהִים. וּמִשּׁוּם כָּךְ זָכָה לִשְׁלֹט בָּעוֹלָם הַזֶּה וְזִכָּה אֶת יִשְׂרָאֵל.</p>\n<p>מַה כָּתוּב? (שם מז) וַיְלַקֵּט יוֹסֵף אֶת כָּל הַכֶּסֶף, וְכָךְ רָאוּי. שֶׁהֲרֵי אוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, הוּא לוֹקֵט הַכֹּל, וְכָל הָעֹשֶׁר עוֹמֵד בּוֹ. וְזֶה סוֹד הַכָּתוּב (שם א) וַיִּתֵּן אֹתָם אֱלֹהִים בִּרְקִיעַ הַשָּׁמָיִם, וְהַכֹּל הוּא כָּרָאוּי, וַדַּאי יוֹסֵף צָרִיךְ לִשְׁלֹט עַל הַמַּלְכוּת.</p>\n<p>וּבֹא רְאֵה, כָּתוּב וַיַּרְכֵּב אֹתוֹ בְּמִרְכֶּבֶת הַמִּשְׁנֶה. מִי מִרְכֶּבֶת הַמִּשְׁנֶה? הַקָּדוֹשׁ בָּרוּךְ הוּא עָשַׂה אֶת הַצַּדִּיק שַׁלִּיט, מִשּׁוּם שֶׁהִנֵּה מִמֶּנּוּ נִזּוֹן הָעוֹלָם, וְצָרִיךְ לְהִזּוֹן, וְלַקָּדוֹשׁ-בָּרוּךְ-הוּא יֵשׁ מֶרְכָּבָה עֶלְיוֹנָה, וְיֵשׁ לוֹ מֶרְכָּבָה תַחְתּוֹנָה. הַמֶּרְכָּבָה הַתַּחְתּוֹנָה הִיא מִרְכֶּבֶת הַמִּשְׁנֶה, וְיוֹסֵף נִקְרָא צַדִּיק, וְלוֹ רָאוּי לִהְיוֹת רוֹכֵב עַל מִרְכֶּבֶת הַמִּשְׁנֶה אֲשֶׁר לוֹ, לַקָּדוֹשׁ-בָּרוּךְ- הוּא, וְהַכֹּל הוּא בְּסוֹד עֶלְיוֹן שֶׁיִּהְיֶה כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>בֹּא רְאֵה. וַיִּקְרְאוּ לְפָנָיו אַבְרֵךְ, מַה זֶּה אַבְרֵךְ? הַקֶּשֶׁר שֶׁנִּקְשָׁרִים הַשֶּׁמֶשׁ עִם הַלְּבָנָה, וְהַכֹּל כּוֹרְעִים כְּנֶגֶד הַמָּקוֹם הַזֶּה. וְנָתוֹן אוֹתוֹ עַל כָּל הָעוֹלָם, וְכֻלָּם מוֹדִים אֵלָיו, מִשּׁוּם זֶה הַכֹּל הוּא בְּסוֹד עֶלְיוֹן.</p>\n<p>בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה אֶת מַלְכוּת הָאָרֶץ כְּעֵין מַלְכוּת הָרָקִיעַ, וְהַכֹּל זֶה כְּמוֹ זֶה. וְכָל מַה שֶּׁנַּעֲשֶׂה בָּאָרֶץ, עוֹמֵד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרִאשׁוֹנָה. בֹּא רְאֵה, הַמַּלְכוּת הַקְּדוֹשָׁה לֹא קִבְּלָה מַלְכוּת שְׁלֵמָה עַד שֶׁהִתְחַבְּרָה עִם הָאָבוֹת, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה אוֹתָהּ הַמַּלְכוּת הָעֶלְיוֹנָה שֶׁתָּאִיר מִסּוֹד הָאָבוֹת.</p>\n<p>וּכְשֶׁיּוֹסֵף הַצַּדִּיק יָרַד לְמִצְרַיִם בָּרִאשׁוֹנָה, הוּא מָשַׁךְ אַחַר כָּךְ עִמּוֹ אֶת הַשְּׁכִינָה, שֶׁהֲרֵי אֵין שְׁכִינָה הוֹלֶכֶת אֶלָּא אַחַר הַצַּדִּיק, וּמִשּׁוּם כָּךְ נִמְשַׁךְ יוֹסֵף לְמִצְרַיִם בָּרִאשׁוֹנָה, וְנָטַל אֶת כָּל עֹשֶׁר הָעוֹלָם כָּרָאוּי, וְאַחַר כָּךְ יָרְדָה שְׁכִינָה לְמִצְרַיִם וְכָל הַשְּׁבָטִים עִמָּהּ.</p>\n<p>וּמִשּׁוּם כָּךְ יוֹסֵף, שֶׁשָּׁמַר אֶת הַבְּרִית, זָכָה לְהִתְעַטֵּר בִּמְקוֹמוֹ, וְזָכָה לַמַּלְכוּת שֶׁלְּמַעְלָה וְלַמַּלְכוּת שֶׁלְּמַטָּה. וְעַל כֵּן, כָּל מִי שֶׁשּׁוֹמֵר בְּרִית הַקֹּדֶשׁ כְּאִלּוּ קִיֵּם כָּל הַתּוֹרָה הַקְּדוֹשָׁה כֻּלָּהּ, שֶׁהֲרֵי הַבְּרִית שְׁקוּלָה כְּכָל הַתּוֹרָה.</p>"],[9522011401,"<p>וַיַּרְא יַעֲקֹב כִּי יֶשׁ שֶׁבֶר בְּמִצְרָיִם וַיֹּאמֶר יַעֲקֹב לְבָנָיו וְגוֹ'. רַבִּי חִיָּיא פָּתַח וְאָמַר, (זכריה יב) מַשָּׂא דְבַר ה' עַל יִשְׂרָאֵל נְאֻם ה' נֹטֶה שָׁמַיִם וְיֹסֵד אָרֶץ וְיֹצֵר רוּחַ אָדָם בְּקִרְבּוֹ. בַּפָּסוּק הַזֶּה יֵשׁ לְהִתְבּוֹנֵן. מַשָּׂא דְבַר ה'. בְּכָל הַמְּקוֹמוֹת הָאֵלֶּה שֶׁאָמַר מַשָּׂא, לָמָּה מַשָּׂא? אֶלָּא בְּכָל מָקוֹם שֶׁהוּא עַל הַדִּין שֶׁל שְׁאָר הָעַמִּים וְאָמַר מַשָּׂא - זֶה לְטוֹב. בְּכָל מָקוֹם שֶׁהוּא עַל יִשְׂרָאֵל וְאוֹמֵר מַשָּׂא - זֶה לְרַע.</p>\n<p>בְּכָל מָקוֹם שֶׁהוּא עַל הַדִּין שֶׁל שְׁאָר הָעַמִּים לְטוֹב, מִשּׁוּם שֶׁמַּשָּׂא הוּא מַעֲמָסָה, כִּבְיָכוֹל זוֹ מַעֲמָסָה עַל הַקָּדוֹשׁ בָּרוּךְ הוּא הַשָּׁלוֹם שֶׁל הָעַמִּים עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, וּכְשֶׁנִּגְזָר הַדִּין עֲלֵיהֶם, עוֹבֶרֶת מִמֶּנּוּ הַמַּעֲמָסָה הַזּוֹ שֶׁהוּא סוֹבֵל עֲלֵיהֶם. בְּכָל מָקוֹם שֶׁנִּגְזָר דִּין עַל יִשְׂרָאֵל וְאוֹמֵר מַשָּׂא, כִּבְיָכוֹל מַעֲמָסָה הִיא עַל הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמִשּׁוּם כָּךְ מַשָּׂא מֵהַצַּד הַזֶּה וּמֵהַצַּד הַזֶּה, זֶה מַשָּׂא.</p>\n<p>כֵּיוָן שֶׁאָמַר נֹטֶה שָׁמַיִם וְיֹסֵד אָרֶץ, לָמָּה צָרִיךְ וְיֹצֵר רוּחַ אָדָם בְּקִרְבּוֹ? וְכִי לֹא הָיִינוּ יוֹדְעִים שֶׁהוּא יֹצֵר רוּחַ אָדָם? אֶלָּא לְהַרְאוֹת דַּרְגָּה יְדוּעָה, שֶׁכָּל הָרוּחוֹת וְהַנְּשָׁמוֹת שֶׁל הָעוֹלָם עוֹמְדוֹת בְּאוֹתָהּ הַדַּרְגָּה.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, הַפָּסוּק הַזֶּה קָשֶׁה. אִם אָמַר וְיֹצֵר רוּחַ אָדָם וְלֹא יוֹתֵר - יָפֶה. אֲבָל מַה זֶּה בְּקִרְבּוֹ? אֶלָּא זֶה סוֹד בִּשְׁנֵי צְדָדִים, שֶׁהֲרֵי מֵהַנָּהָר הַהוּא שֶׁשּׁוֹפֵעַ וְיוֹצֵא, מִשָּׁם יוֹצְאוֹת וּפוֹרְחוֹת כָּל הַנְּשָׁמוֹת וּמִתְכַּנְּסוֹת לְמָקוֹם אֶחָד, וְאוֹתָהּ הַדַּרְגָּה הִיא יֹצֵר רוּחַ אָדָם בְּקִרְבּוֹ. וְזֶה כְּמוֹ אִשָּׁה שֶׁמִּתְעַבֶּרֶת מִן הַזָּכָר, וְאוֹתוֹ הַוָּלָד מְצַיֶּרֶת לָהּ בְּמֵעֶיהָ, עַד שֶׁהַכֹּל מִצְטַיֵּר בְּצִיּוּר מֻשְׁלָם בְּמֵעֶיהָ. כָּךְ וְיֹצֵר רוּחַ אָדָם בְּקִרְבּוֹ, בְּקִרְבּוֹ זֶה עוֹמֵד, עַד שֶׁנִּבְרָא הָאָדָם בָּעוֹלָם וְנוֹתֵן לוֹ.</p>\n<p>דָּבָר אַחֵר וְיֹצֵר רוּחַ אָדָם בְּקִרְבּוֹ - בְּקִרְבּוֹ שֶׁל אָדָם מַמָּשׁ. מִשּׁוּם שֶׁכַּאֲשֶׁר נִבְרָא הָאָדָם וְהַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן לוֹ אֶת נִשְׁמָתוֹ וְיוֹצֵא לָאֲוִיר שֶׁל הָעוֹלָם, אוֹתָהּ הָרוּחַ שֶׁבְּתוֹכוֹ לֹא מוֹצֵאת גּוּף לְהִתְפַּשֵּׁט בְּתוֹכוֹ, וְעוֹמֶדֶת בְּצַד אֶחָד בְּתוֹכוֹ.</p>\n<p>וּכְשֶׁאָדָם מִתְפַּשֵּׁט גּוּפוֹ, אוֹתָהּ הָרוּחַ מִתְפַּשֶּׁטֶת וְנוֹתֶנֶת בּוֹ כֹּחַ. וְכֵן כְּמוֹ שֶׁהַגּוּף מִתְגַּדֵּל, כָּךְ הָרוּחַ נוֹתֶנֶת בּוֹ כֹּחַ שֶׁיִּתְחַזֵּק הָאָדָם עִמָּהּ, וּמִשּׁוּם כָּךְ יֹצֵר רוּחַ אָדָם בְּקִרְבּוֹ מַמָּשׁ.</p>\n<p>וְאִם תֹּאמַר, יֹצֵר רוּחַ אָדָם מַה זֶּה? מִשּׁוּם שֶׁהָרוּחַ הַהִיא צְרִיכָה כֹּחַ שֶׁלְּמַעְלָה יוֹתֵר לְהִסְתַּיֵּעַ עִמָּהּ, וְעַל כֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא יֹצֵר רוּחַ אָדָם בְּקִרְבּוֹ, וְנוֹתֵן לוֹ סִיּוּעַ לָאָדָם.</p>\n<p>בֹּא רְאֵה, כְּשֶׁאוֹתָהּ הָרוּחַ צְרִיכָה סִיּוּעַ - כְּמוֹ שֶׁהוּא אוֹתוֹ הָאָדָם וּכְמוֹ שֶׁאוֹתוֹ הַגּוּף נִתְקָן, כָּךְ גַּם מְתַקְּנִים לוֹ אֶת אוֹתָהּ הָרוּחַ וּמוֹסִיפִים לוֹ רוּחַ לְהִתְתַּקֵּן, וְזֶה הוּא יֹצֵר רוּחַ אָדָם בְּקִרְבּוֹ.</p>\n<p>וּבֹא רְאֵה, כֵּיוָן שֶׁאָבַד יוֹסֵף מֵאָבִיו, יַעֲקֹב אִבֵּד אוֹתָהּ תּוֹסֶפֶת הָרוּחַ שֶׁהָיְתָה בּוֹ, וְהִסְתַּלְּקָה מִמֶּנּוּ הַשְּׁכִינָה. אַחַר כָּךְ מַה כָּתוּב? (בראשית מה) וַתְּחִי רוּחַ יַעֲקֹב אֲבִיהֶם. וְכִי עַד עַכְשָׁו הָיָה מֵת? אֶלָּא אוֹתָהּ תּוֹסֶפֶת הָרוּחַ הִסְתַּלְּקָה מִמֶּנּוּ הַשְּׁכִינָה וְלֹא הָיְתָה בְתוֹכוֹ, מִשּׁוּם שֶׁהָעֶצֶב שֶׁהָיָה בּוֹ גָּרַם לוֹ, (ואם גרמה לו לזה) שֶׁלֹּא הָיְתָה רוּחַ בְּקִיּוּמָהּ, וּמִשּׁוּם כָּךְ וַתְּחִי רוּחַ יַעֲקֹב אֲבִיהֶם.</p>\n<p>וְכָאן כָּתוּב וַיַּרְא יַעֲקֹב, שֶׁעַד עַכְשָׁו לֹא הִתְבַּשֵּׂר. מִנַּיִן הָיָה יוֹדֵעַ? אֶלָּא וַיַּרְא יַעֲקֹב, שֶׁרָאָה אֶת כָּל דַּיָּרֵי הָאָרֶץ שֶׁהוֹלְכִים לְמִצְרַיִם וּמְבִיאִים תְּבוּאָה. זֶהוּ שֶׁכָּתוּב וַיַּרְא יַעֲקֹב.</p>\n<p>רַבִּי יִצְחָק אָמַר, בּא רְאֵה, דָּוִד הַמֶּלֶךְ זָכָה לְהִתְחַבֵּר עִם הָאָבוֹת, וְיָרַשׁ אֶת מְקוֹמוֹ בְתוֹכָם. זֶהוּ שֶׁכָּתוּב אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה.</p>\n<p>רַבִּי יֵיסָא וְרַבִּי חִזְקִיָּה הָיוּ הוֹלְכִים מִקַּפּוֹטְקִיָּא לְלוֹד, וְהָיָה עִמָּהֶם יְהוּדִי אֶחָד שֶׁמַּחֲזִיק נוֹד שֶׁל יַיִן. בְּעוֹדָם הוֹלְכִים, אָמַר רַבִּי יֵיסָא לְרַבִּי חִזְקִיָּה, פְּתַח פִּיךְ וֶאֱמֹר דָּבָר אֶחָד מֵאוֹתָם הַדְּבָרִים הַמְעֻלִּים שֶׁל הַתּוֹרָה שֶׁאַתָּה אוֹמֵר כָּל יוֹם לִפְנֵי הַמָּאוֹר הַקָּדוֹשׁ.</p>\n<p>פָּתַח וְאָמַר, (משלי ג) דְּרָכֶיהָ דַרְכֵי נֹעַם וְכָל נְתִיבתֶיהָ שָׁלוֹם. דְּרָכֶיהָ דַרְכֵי נֹעַם - אֵלּוּ דַּרְכֵי הַתּוֹרָה. שֶׁמִּי שֶׁהוֹלֵךְ בְּדַרְכֵי הַתּוֹרָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מַשְׁרֶה עָלָיו אֶת נְעִימוּת הַשְּׁכִינָה שֶׁלֹּא תָזוּז מִמֶּנּוּ לְעוֹלָמִים. וְכָל נְתִיבֹתֶיהָ שָׁלוֹם - שֶׁכָּל נְתִיבוֹת הַתּוֹרָה כֻּלָּם שָׁלוֹם. שָׁלוֹם לוֹ לְמַעְלָה, שָׁלוֹם לוֹ לְמַטָּה. שָׁלוֹם לוֹ בָּעוֹלָם הַזֶּה, שָׁלוֹם לוֹ בָּעוֹלָם הַבָּא.</p>\n<p>אָמַר הַיְּהוּדִי הַהוּא, כְּמוֹ מַטְבֵּעַ בְּכִיס נִמְצָא בַּפָּסוּק הַזֶּה. אָמְרוּ לוֹ, מִנַּיִן לְךְ? אָמַר לָהֶם, שָׁמַעְתִּי מֵאַבָּא, וְלָמַדְתִּי כָּאן דָּבָר (טוב) בַּפָּסוּק הַזֶּה. פָּתַח וְאָמַר, הַפָּסוּק הַזֶּה הוּא בִּשְׁנֵי גְוָנִים וּבִשְׁנֵי צְדָדִים. קוֹרְאִים בּוֹ דְּרָכִים וְקוֹרְאִים בּוֹ נְתִיבוֹת. קוֹרְאִים בּוֹ נֹעַם, וְקוֹרְאִים בּוֹ שָׁלוֹם. מִי הַדְּרָכִים וּמִי הַנְּתִיבוֹת? מִי הַנֹּעַם וּמִי הַשָּׁלוֹם?</p>\n<p>אֶלָּא דְּרָכֶיהָ דַרְכֵי נֹעַם, הַיְנוּ שֶׁכָּתוּב (ישעיה מג) הַנּוֹתֵן בַּיָּם דָּרֶךְ. שֶׁהֲרֵי בְּכָל מָקוֹם שֶׁנִּקְרָא בַתּוֹרָה דֶּרֶךְ, זוֹ דֶרֶךְ פְּתוּחָה לַכֹּל. כַּדֶּרֶךְ הַזּוֹ שֶׁפְּתוּחָה לְכָל אָדָם, כָּךְ דְּרָכֶיהָ דַרְכֵי נֹעַם. אֵלּוּ הַדְּרָכִים שֶׁפְּתוּחִים מִן הָאָבוֹת, שֶׁכָּרוּ בַּיָּם הַגָּדוֹל, וְנִכְנָסִים לְתוֹכוֹ, וּמֵאוֹתָם הַדְּרָכִים נִפְתָּחִים לְכָל עֵבֶר וּלְכָל צִדְדֵי הָעוֹלָם.</p>\n<p>וְהַנֹּעִם הַזֶּה הִיא נְעִימוּת שֶׁיּוֹצֵאת מִן הָעוֹלָם הַבָּא, וּמִן הָעוֹלָם הַבָּא מְאִירִים כָּל הַמְּאוֹרוֹת וְנִפְרָדִים לְכָל עֵבֶר, וְאוֹתוֹ הַטּוֹב וְאוֹתוֹ הָאוֹר שֶׁל הָעוֹלָם הַבָּא שֶׁיּוֹנְקִים (שיורשים) הָאָבוֹת נִקְרָא נֹעַם. דָּבָר אַחֵר - הָעוֹלָם הַבָּא נִקְרָא נֹעַם, וּכְשֶׁמִּתְעוֹרֵר הָעוֹלָם הַבָּא, כָּל הַשִּׂמְחָה וְכָל הַטּוּב וְכָל הָאוֹרוֹת וְכָל הַחֵרוּת שֶׁל הָעוֹלָם מִתְעוֹרְרִים, וּמִשּׁוּם כָּךְ נִקְרָא נֹעַם.</p>\n<p>וְעַל זֶה שָׁנִינוּ, הָרְשָׁעִים שֶׁל הַגֵּיהִנֹּם, בְּשָׁעָה שֶׁנִּכְנֶסֶת הַשַּׁבָּת, כֻּלָּם נָחִים, וְיֵשׁ לָהֶם חֵרוּת וּמְנוּחָה. בְּשָׁעָה שֶׁיּוֹצֵאת הַשַּׁבָּת, יֵשׁ לָנוּ לְעוֹרֵר שִׂמְחָה עֶלְיוֹנָה עָלֵינוּ שֶׁנִּנָּצֵל מֵאוֹתוֹ הָעֹנֶשׁ שֶׁל הָרְשָׁעִים שֶׁנִּדּוֹנוּ (שחזרו) מִן הַשָּׁעָה הַהִיא וָהָלְאָה. וְיֵשׁ לָנוּ לְהִתְעוֹרֵר וְלוֹמַר, (תהלים צ) וִיהִי נֹעַם אֲדנָי אֱלֹהֵינוּ עָלֵינוּ. זֶהוּ הַנֹּעַם הָעֶלְיוֹן, שִׂמְחַת (חרות) הַכֹּל, וְעַל כֵּן דְּרָכֶיהָ דַרְכֵי נֹעַם.</p>\n<p>וְכָל נְתִיבתֶיהָ שָׁלוֹם, מִי זֶה נְתִיבתֶיהָ? אֵלּוּ הֵם הַשְּׁבִילִים שֶׁיּוֹצְאִים מִלְמַעְלָה, וְאֶת כֻּלָּם לוֹקֵחַ הַבְּרִית הַיְחִידִי שֶׁנִּקְרָא שָׁלוֹם, שְׁלוֹם הַבַּיִת, וּמַכְנִיס אוֹתָם לַיָּם הַגָּדוֹל כְּשֶׁהוּא בִּגְבוּרָתוֹ, וְאָז נוֹתֵן לוֹ שָׁלוֹם. זֶהוּ שֶׁכָּתוּב וְכָל נְתִיבתֶיהָ שָׁלוֹם. בֹּא רְאֵה, יוֹסֵף הָיָה בְּרִית שָׁלוֹם, וְהָיָה מֶלֶךְ בְּמִצְרַיִם וְשַׁלִּיט עַל הָאָרֶץ, וְיַעֲקֹב, מִשּׁוּם שֶׁהִסְתַּלְּקָה מִמֶּנּוּ הַשְּׁכִינָה, לֹא הָיָה יוֹדֵעַ.</p>\n<p>וְעִם כָּל זֶה, לְיַעֲקֹב הָיָה שֶׁבֶר, כְּדֵי לִקְנוֹת תְּבוּאָה בְּמִצְרַיִם, וּרְאֵה שֶׁהוּא שֶׁבֶר עַל שֶׁבֶר, שֶׁיֵּרְדוּ בָנָיו לְמִצְרַיִם, וַיֹּאמֶר יַעֲקֹב לְבָנָיו לָמָּה תִּתְרָאוּ, כְּדֵי שֶׁלֹּא תַרְאוּ עַצְמְכֶם אֶלָּא כְּמוֹ רְעֵבִים, כְּמוֹ אֲנָשִׁים שֶׁאֵין לָהֶם שּבַע.</p>\n<p>אָמַר רַבִּי חִזְקִיָּה, וַדַּאי סוֹד יֵשׁ כָּאן, שֶׁהֲרֵי בְּכָל זְמַן שֶׁהוּא צַעַר בָּעוֹלָם, לֹא צָרִיךְ הָאָדָם לְהַרְאוֹת אֶת עַצְמוֹ בַּשּׁוּק, כְּדֵי שֶׁלֹּא יִתָּפֵס בַּחֲטָאָיו, וְעַל כֵּן אָמַר לָמָּה תִּתְרָאוּ, וְהִנֵּה נִתְבָּאֵר.</p>\n<p>דָּבָר אַחֵר וַיַּרְא יַעֲקֹב כִּי יֶשׁ שֶׁבֶר בְּמִצְרָיִם - תְּבוּאָה מַמָּשׁ, שֶׁהֲרֵי עַל כֵּן שָׁלַח הַקָּדוֹשׁ בָּרוּךְ הוּא רָעָב לָעוֹלָם, כְּדֵי לְהוֹרִיד אֶת יַעֲקֹב וְאֶת בָּנָיו לְשָׁם, וְעַל זֶה רָאָה אֶת בְּנֵי הָאָרֶץ שֶׁהָיוּ מְבִיאִים מִשָּׁם תְּבוּאָה.</p>\n<p>וַיַּרְא יַעֲקֹב כִּי יֶשׁ שֶׁבֶר בְּמִצְרָיִם. בְּשָׁעָה שֶׁמֵּת יִצְחָק, בָּאוּ יַעֲקֹב וְעֵשָׂו לַחֲלֹק, וְעֵשָׂו יָצָא מֵחֶלְקוֹ שֶׁל הָאָרֶץ וּמֵהַכֹּל, וְיַעֲקֹב שֶׁיִּסְבֹּל אֶת הַגָּלוּת יִטֹּל הַכֹּל. וְעַל זֶה רָאָה אוֹתוֹ הַשֶּׁבֶר שֶׁהָיָה לוֹ בְּמִצְרַיִם הוּא וּבָנָיו לִסְבֹּל אֶת הַגָּלוּת, וְעַל זֶה וַיֹּאמֶר יַעֲקֹב לְבָנָיו לָמָּה תִּתְרָאוּ, מִלִּפְנֵי הַדִּין שֶׁלְּמַעְלָה, שֶׁלֹּא יִמָּצֵא עֲלֵיכֶם מְקַטְרֵג. וַיֹּאמֶר הִנֵּה שָׁמַעְתִּי כִּי יֶשׁ שֶׁבֶר בְּמִצְרָיִם רְדוּ שָׁמָּה. הֲרֵי פֵּרְשׁוּהָ רְד\"וּ, כַּחֶשְׁבּוֹן הַזֶּה הָיוּ יִשְׂרָאֵל בְּמִצְרַיִם.</p>"],[9522011402,"<p>וְיוֹסֵף הוּא הַשַּׁלִּיט עַל הָאָרֶץ וְגוֹ'. רַבִּי יֵיסָא פָּתַח וְאָמַר, (תהלים כז) וְעַתָּה יָרוּם רֹאשִׁי עַל אֹיְבַי סְבִיבוֹתַי וְאֶזְבְּחָה בְאָהֳלוֹ זִבְחֵי תְרוּעָה אָשִׁירָה וַאֲזַמְּרָה לַה'. בֹּא רְאֵה, כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְרַצֶּה מֵהָאָדָם, הוּא זוֹקֵף אוֹתוֹ עַל כָּל בְּנֵי הָעוֹלָם וְעוֹשֶׂה אוֹתוֹ הָרֹאשׁ שֶׁל הַכֹּל, וְכָל שׂוֹנְאָיו נִכְנָעִים תַּחְתָּיו.</p>\n<p>אֶת דָּוִד הַמֶּלֶךְ שָׂנְאוּ אֶחָיו, דָּחוּ אוֹתוֹ מֵהֶם - הַקָּדוֹשׁ בָּרוּךְ הוּא הֵרִים אוֹתוֹ עַל כָּל בְּנֵי הָעוֹלָם. בָּא חָמִיו - בָּרַח מִלְּפָנָיו, הַקָּדוֹשׁ בָּרוּךְ הוּא הֵרִים אוֹתוֹ עַל כָּל מַלְכוּתוֹ, וְכֻלָּם הָיוּ כוֹרְעִים וְסוֹגְדִים לְפָנָיו. וְאֶת יוֹסֵף דָּחוּ אֶחָיו, אַחַר כָּךְ כֻּלָּם כָּרְעוּ וְהִשְׁתַּחֲווּ לְפָנָיו, זֶהוּ שֶׁכָּתוּב וַיָּבֹאוּ אֲחֵי יוֹסֵף וַיִּשְׁתַּחֲווּ לוֹ אַפַּיִם אָרְצָה.</p>\n<p>דָּבָר אַחֵר וְעַתָּה יָרוּם רֹאשִׁי - מַה זֶּה וְעַתָּה? כְּמוֹ וְאַתָּה. רַבִּי יְהוּדָה אָמַר, הִנֵּה נִתְבָּאֵר, עֵת שֶׁהִיא הַדַּרְגָּה הָעֶלְיוֹנָה. וּמִי הִיא אוֹתָהּ הָעֵת? זוֹ הֵ\"א, וְנִקְרֵאת עַתָּה. וְעַתָּה - זֶה הוּא וּבֵית דִּינוֹ.</p>\n<p>יָרוּם רֹאשִׁי - לְהָרִים אוֹתָהּ בְּכָבוֹד וּמַלְכוּת. עַל אֹיְבַי סְבִיבוֹתַי - אֵלּוּ שְׁאָר מַלְכֵי הָאָרֶץ. וְאֶזְבְּחָה בְאָהֳלוֹ - זוֹ יְרוּשָׁלַיִם. בְּאָהֳלוֹ - זֶה אֹהֶל מוֹעֵד. זִבְחֵי תְרוּעָה - שֶׁיִּשְׁמַע כָּל הָעוֹלָם. אָשִׁירָה וַאֲזַמְּרָה - מֵאוֹתוֹ צַד שֶׁהִיא הַתְּרוּעָה. שֶׁהֲרֵי מִשָּׁם, מֵהַצַּד שֶׁל הַתְּרוּעָה, בָּאָה הַשִּׁירָה וְהַתִּשְׁבַּחַת.</p>\n<p>דָּבָר אַחֵר וְעַתָּה יָרוּם רֹאשִׁי - זוֹ כְּנֶסֶת יִשְׂרָאֵל. עַל אֹיְבַי סְבִיבוֹתַי - זֶה עֵשָׂו וְכָל הַשָּׂרִים שֶׁלּוֹ. וְאֶזְבְּחָה בְאָהֳלוֹ - אֵלּוּ יִשְׂרָאֵל. זִבְחֵי תְרוּעָה - שֶׁכָּתוּב (שם נא) זִבְחֵי אֱלֹהִים רוּחַ נִשְׁבָּרָה, כְּדֵי לְהַעֲבִיר אֶת הַדִּין מִן הָעוֹלָם. אָשִׁירָה וַאֲזַמְּרָה - לְהוֹדוֹת וּלְשַׁבֵּחַ לַקָּדוֹשׁ-בָּרוּךְ-הוּא לְלֹא הֶפְסֵק לְעוֹלָם.</p>\n<p>דָּבָר אַחֵר וְעַתָּה יָרוּם רֹאשִׁי - בַּכֹּל, יֵצֶר טוֹב עַל יֵצֶר רָע, שֶׁכָּתוּב עַל אֹיְבַי סְבִיבוֹתַי, זֶה הַיֵּצֶר הָרָע שֶׁהוּא סְבִיב הָאָדָם, וְהוּא שׂוֹנֵא אוֹתוֹ בַּכֹּל. וְאֶזְבְּחָה בְאָהֳלוֹ זִבְחֵי תְרוּעָה - זוֹ הַתּוֹרָה שֶׁנִּתְּנָה מִצַּד הָאֵשׁ, כַּכָּתוּב (דברים לג) מִימִינוֹ אֵשׁ דָּת לָמוֹ. שֶׁהֲרֵי בִּשְׁבִיל הַתּוֹרָה יָרוּם רֹאשׁוֹ (של האדם) וְנִשְׁבָּרִים כָּל שׂוֹנְאָיו לְפָנָיו, כַּכָּתוּב (תהלים יח) תַּכְרִיעַ קָמַי תַּחְתָּי.</p>\n<p>דָּבָר אַחֵר וְעַתָּה יָרוּם רֹאשִׁי - לְהִכָּלֵל עִם הָאָבוֹת, שֶׁהֲרֵי דָּוִד הַמֶּלֶךְ יֵשׁ לוֹ לְהִדָּבֵק עִם הָאָבוֹת, וְאָז יִתְרוֹמֵם וְיַעֲלֶה לְמַעְלָה, וְהוּא בְּקֶשֶׁר אֶחָד עִמָּם. עַל אֹיְבַי סְבִיבוֹתַי - אֵלּוּ הֵם שֶׁבְּצַד הַשְּׂמֹאל, כֻּלָּם בַּעֲלֵי הַדִּינִים שֶׁמִּתְכַּוְּנִים לְחַבֵּל, וְאָז הַשֶּׁמֶשׁ מִתְחַבֵּר לַלְּבָנָה, וְהַכֹּל הוּא אֶחָד.</p>\n<p>בֹּא רְאֵה, כָּתוּב וְיוֹסֵף הוּא הַשַּׁלִּיט עַל הָאָרֶץ. זֶה הַשֶּׁמֶשׁ שֶׁשּׁוֹלֵט בַּלְּבָנָה וּמֵאִיר לָהּ וְזָן אוֹתָהּ. הוּא הַמַּשְׁבִּיר לְכָל עַם הָאָרֶץ, שֶׁהֲרֵי אוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, מִמֶּנּוּ כֻּלָּם נִזּוֹנִים וּמִשָּׁם פּוֹרְחוֹת הַנְּשָׁמוֹת לַכֹּל, וּמִשּׁוּם כָּךְ כֻּלָּם מִשְׁתַּחֲוִים אֶל אוֹתוֹ הַמָּקוֹם, שֶׁהֲרֵי אֵין לְךְ דָּבָר בָּעוֹלָם שֶׁלֹּא תָלוּי בְּמַזָּל, וּבֵאֲרוּהוּ.</p>"],[9522011403,"<p>וַיַּכֵּר יוֹסֵף אֶת אֶחָיו וְהֵם לֹא הִכִּרֻהוּ. רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (תהלים מט) לָמָּה אִירָע בִּימֵי רָע עֲון עֲקֵבַי יְסוּבֵּנִי. בּא רְאֵה, שְׁלֹשָׁה הֵם שֶׁפּוֹחֲדִים וְלֹא יוֹדְעִים מִמָּה הֵם פּוֹחֲדִים, וּבֵאֲרוּהוּ. אֲבָל מִי שֶׁפּוֹחֵד וְלֹא יוֹדֵעַ מִמַּה הוּא פּוֹחֵד - מִשּׁוּם אוֹתָם הַחֲטָאִים שֶׁלֹּא יוֹדֵעַ שֶׁהֵם חֲטָאִים, וְלֹא מַשְׁגִּיחַ בָּהֶם, וְהוּא פּוֹחֵד מִימֵי רָע.</p>\n<p>מִי הֵם יְמֵי רָע? אֵלּוּ הֵם הַיָּמִים שֶׁהֵם מִזְדַּמְּנִים בְּאוֹתוֹ רָע, וּמִי הֵם? זֶה (הוא) יֵצֶר הָרָע, שֶׁהוּא נִקְרָא רָע, וְיֵשׁ לוֹ יָמִים יְדוּעִים שֶׁנִּתֶּנֶת לוֹ רְשׁוּת בָּעוֹלָם לְהַסְטִין לְכָל אוֹתָם שֶׁמְּטַמְּאִים אֶת דַּרְכֵיהֶם. שֶׁמִּי שֶׁבָּא לְהִטָּמֵא - מְטַמְּאִים אוֹתוֹ, וְאֵלֶּה הֵם שֶׁנִּקְרָאִים יְמֵי רָע, וְאֵלּוּ מְמֻנִּים עַל אוֹתָם חֲטָאִים שֶׁדָּשִׁים אוֹתָם בְּנֵי אָדָם בְּעִקְבֵיהֶם.</p>\n<p>בֹּא רְאֵה, כָּל אוֹתָם שֶׁמְּטַמְּאִים אֶת דַּרְכֵיהֶם, כַּמָּה קְבוּצוֹת שֶׁל מַזִּיקִים מִזְדַּמְּנִים אֶצְלָם וּמְטַמְּאִים אוֹתָם. בְּדֶרֶךְ שֶׁאָדָם רוֹצֶה לָלֶכֶת - בְּאוֹתָהּ הַדֶּרֶךְ מַנְהִיגִים אוֹתוֹ מַמָּשׁ. בָּא אָדָם לְהִטָּהֵר - כַּמָּה הֵם שֶׁמְּסַיְּעִים לוֹ.</p>\n<p>הֲרֵי שָׁנִינוּ, שֶׁכְּשֶׁאָדָם קָם בַּבֹּקֶר, צָרִיךְ לִרְחֹץ יָדָיו מִתּוֹךְ נַטְלָה שֶׁל מַיִם, שֶׁהוּא כְּלִי לִטֹּל מִמֶּנּוּ מַיִם, מִתּוֹךְ מִי שֶׁרָחַץ יָדוֹ בָּרִאשׁוֹנָה, כְּמוֹ שֶׁבֵּאֲרוּהוּ. וּבֹא רְאֵה, בִּשְׁבִיל הַנַּטְלָה הַזּוֹ בֵּאַרְנוּ אֶת הַדָּבָר.</p>\n<p>וְעוֹד, שֶׁצָּרִיךְ אָדָם לִטֹּל יַד יָמִין בִּשְׂמֹאל, כְּדֵי לְהַשְׁלִיט יָמִין עַל שְׂמֹאל, וְיִרְחַץ הַיָּמִין מִן הַשְּׂמֹאל, וּמִשּׁוּם זֶה הִיא נְטִילָה. וְעַל כֵּן מִי שֶׁנּוֹטֵל יָדוֹ, יִטֹּל יָמִין בִּשְׂמֹאל, לְהַשְׁלִיט הַיָּמִין עַל הַשְּׂמֹאל, כְּדֵי שֶׁלֹּא יִתֵּן מָקוֹם לַיֵּצֶר הָרָע לִשְׁלֹט כְּלָל, וְהִנֵּה בֵּאַרְנוּ.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁדִּין הָרָע שׁוֹלֵט, לֹא מֵשִׁיב יָדוֹ מִלְּהָרַע, וּבְשָׁעָה שֶׁהַיָּמִין שׁוֹלֵט עַל הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת לִשְׁבֹּר אוֹתָם, חָס הַקָּדוֹשׁ בָּרוּךְ הוּא עֲלֵיהֶם וְלֹא מְכַלֶּה אוֹתָם.</p>\n<p>וּמִשּׁוּם כָּךְ, כָּל מִי שֶׁהוּא חוֹטֵא, בְּאוֹתָם הַחֲטָאִים שֶׁדָּשׁ בָּהֶם בְּרַגְלָיו, לֹא יָדַע עֲלֵיהֶם, וּפוֹחֵד תָּמִיד. דָּוִד הַמֶּלֶךְ הָיָה תָמִיד נִשְׁמָר מֵהַחֲטָאִים הַלָּלוּ, וּכְשֶׁהָיָה יוֹצֵא לַקְּרָב, הָיָה מְפַשְׁפֵּשׁ בָּהֶם, וְעַל כֵּן לֹא פָחַד לְהִלָּחֵם עִמָּהֶם בַּקְּרָב.</p>\n<p>וּבֹא רְאֵה, אַרְבָּעָה מְלָכִים הָיוּ, מַה שֶּׁבִּקֵּשׁ זֶה לֹא בִקֵּשׁ זֶה. דָּוִד אָמַר (תהלים יח) אֶרְדּוֹף אוֹיְבַי וְאַשִּׂיגֵם וְלֹא אָשׁוּב עַד כַּלּוֹתָם. מָה הַטַּעַם? מִשּׁוּם שֶׁהָיָה נִשְׁמָר מִן הַחֲטָאִים הַלָּלוּ, וְלֹא נָתַן מָקוֹם לְשׂוֹנְאָיו לִשְׁלֹט, וְעַל כֵּן רָצָה לִרְדּף אַחֲרֵיהֶם תָּמִיד, וְהֵם לֹא יִרְדְּפוּ אַחֲרָיו לִתְבֹּעַ אֶת חֲטָאָיו וְיִפֹּל בִּידֵיהֶם.</p>\n<p>אָסָא הָיָה מְפַחֵד יוֹתֵר. אַף עַל גַּב שֶׁהָיָה מְפַשְׁפֵּשׁ בַּחֲטָאָיו, וְלֹא כְּמוֹ דָוִד הַמֶּלֶךְ, הוּא רָצָה לִרְדֹּף אַחֲרֵיהֶם, וְלֹא לְהִלָּחֵם בָּהֶם, וְיַהֲרֹג אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכָךְ הָיָה, שֶׁכָּתוּב (דברי הימים ב יד) וַיִּרְדְּפֵם אָסָא וְהָעָם אֲשֶׁר עִמּוֹ וְגוֹ', וְכָתוּב וַיִּגֹּף ה' אֶת הַכּוּשִׁים לִפְנֵי אָסָא וְלִפְנֵי יְהוּדָה וַיָּנֻסוּ הַכֻּשִׁים. (וכן) מַה כָּתוּב בְּדָוִד? (שמואל א ל) וַיַּכֵּם דָּוִד מֵהַנֶּשֶׁף וְעַד הָעֶרֶב לְמָחֳרָתָם. אֲבָל אָסָא, הוּא רוֹדֵף וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַכֶּה.</p>\n<p>גַּם יְהוֹשָׁפָט מֶלֶךְ יְהוּדָה כָּךְ הָיָה מְבַקֵּשׁ וְאוֹמֵר, אֵינִי יָכוֹל לִרְדֹּף וְלֹא לַהֲרֹג, אֶלָּא אֲנִי אֲזַמֵּר, וְאַתָּה תַּהֲרֹג אוֹתָם, מִשּׁוּם שֶׁלֹּא הָיָה כָּל כָּךְ מְפַשְׁפֵּשׁ כְּמוֹ אָסָא, וְכָךְ עָשָׂה לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (דברי הימים ב כ) וּבְעֵת הֵחֵלּוּ בְרִנָּה וּתְהִלָּה נָתַן ה' מְאָרְבִים עַל בְּנֵי עַמּוֹן מוֹאָב וְהַר שֵׂעִיר הַבָּאִים לִיהוּדָה וַיִּנָּגֵפוּ.</p>\n<p>חִזְקִיָּה מֶלֶךְ יְהוּדָה אַף כָּךְ גַּם אָמַר, אֵינִי יָכוֹל לֹא לְזַמֵּר וְלֹא לִרְדֹּף וְלֹא לְהִלָּחֵם בַּקְּרָב, מִשּׁוּם שֶׁפָּחַד מֵהַחֲטָאִים הַלָּלוּ שֶׁאָמַרְנוּ. מַה כָּתוּב? (מלכים ב יט) וַיְהִי בַּלַּיְלָה הַהוּא וַיֵּצֵא מַלְאַךְ ה' וַיַּךְ בְּמַחֲנֵה אַשּׁוּר מֵאָה וּשְׁמוֹנִים וַחֲמִשָּׁה אָלֶף וַיַּשְׁכִּימוּ בַבֹּקֶר וְהִנֵּה כֻלָּם פְּגָרִים מֵתִים. וְחִזְקִיָּה הָיָה יוֹשֵׁב בְּבֵיתוֹ, וְשׁוֹכֵב בְּמִטָּתוֹ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הָרַג אוֹתָם.</p>\n<p>וּמָה הַצַּדִּיקִים הַלָּלוּ הָיוּ פוֹחֲדִים מִן הַחֲטָאִים הַלָּלוּ - שְׁאָר בְּנֵי הָעוֹלָם עַל אַחַת כַּמָּה וְכַמָּה. מִשּׁוּם כָּךְ יֵשׁ לָאָדָם לְהִשָּׁמֵר מֵהַחֲטָאִים הַלָּלוּ וּלְפַשְׁפֵּשׁ בָּהֶם כְּמוֹ שֶׁאָמַרְנוּ, כְּדֵי שֶׁלֹּא יִשְׁלְטוּ עָלָיו אוֹתָם יְמֵי רָע, שֶׁלֹּא מְרַחֲמִים עָלָיו.</p>\n<p>בֹּא רְאֵה, וַיַּכֵּר יוֹסֵף אֶת אֶחָיו. בְּשָׁעָה שֶׁנָּפְלוּ בְיָדוֹ, הוּא רִחַם עֲלֵיהֶם, מִשּׁוּם שֶׁהוּא שָׁלֵם, וְהֵם לֹא הִכִּרֻהוּ. שֶׁאוֹתָם שִׁמְעוֹן וְלֵוִי בָּאוּ מִצַּד הַדִּין הַקָּשֶׁה, וְעַל כֵּן לֹא רִחֲמוּ עָלָיו, שֶׁהֲרֵי כָּל אוֹתָם בַּעֲלֵי הַדִּין הַקָּשֶׁה לֹא מְרַחֲמִים עַל בְּנֵי אָדָם בְּשָׁעָה שֶׁנּוֹפְלִים בִּידֵיהֶם.</p>\n<p>וּמִשּׁוּם כָּךְ אָמַר דָּוִד (תהלים מט) לָמָּה אִירָא. לֹא כָתוּב יָרֵאתִי, אֶלָּא אִירָא, (אלא) שֶׁיֵּשׁ (שאין) לִי לִפְחֹד מֵאוֹתָם יְמֵי רָע, כְּפִי שֶׁאָמַרְנוּ. עֲון עֲקֵבַי יְסוּבֵּנִי, מִי הֵם עֲקֵבַי? אֵלּוּ הֵם בְּסוֹד הָאֱמוּנָה, שֶׁכָּתוּב (בראשית כה) וְיָדוֹ אֹחֶזֶת בַּעֲקֵב עֵשָׂו. זֶה הוּא הֶעָקֵב, וְהֵם הָעֲקֵבִים שֶׁמִּסְתַּכְּלִים בָּהֶם תָּמִיד, בְּאוֹתוֹ הַחֵטְא שֶׁאָדָם דָּשׁ בּוֹ תָּמִיד בַּעֲקֵבוֹ.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב? (ישעיה ה) הוֹי מֹשְׁכֵי הֶעָון בְּחַבְלֵי הַשָּׁוְא וְכַעֲבוֹת הָעֲגָלָה חַטָּאָה. בְּחַבְלֵי הַשָּׁוְא - שֶׁדָּשׁ בּוֹ בֶּעָקֵב וְלֹא חוֹשֵׁשׁ עָלָיו, וְאַחַר כָּךְ מִתְחַזֵּק וְנַעֲשֶׂה (בחבלי השוא) כַּעֲבוֹת הָעֲגָלָה, וּמִתְחַזֵּק אוֹתוֹ הַחֵטְא, וּמַסְטֶה אוֹתוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁיּוֹדְעִים לְהִשָּׁמֵר מֵחֲטָאֵיהֶם, וְהֵם תָּמִיד מְפַשְׁפְּשִׁים בְּמַעֲשֵׂיהֶם כְּדֵי שֶׁלֹּא יִמָּצֵא עֲלֵיהֶם מְקַטְרֵג בָּעוֹלָם הַזֶּה, וְלֹא יַשְׂטִינוּ עֲלֵיהֶם לָעוֹלָם הַבָּא, שֶׁהֲרֵי הַתּוֹרָה מְתַקֶּנֶת לָהֶם דְּרָכִים וּשְׁבִילִים לָלֶכֶת בָּהֶם, שֶׁכָּתוּב (משלי ג) דְּרָכֶיהָ דַרְכֵי נֹעַם וְכָל נְתִיבתֶיהָ שָׁלוֹם.</p>"],[9522011404,"<p>וַיִּזְכֹּר יוֹסֵף אֵת הַחֲלֹמוֹת אֲשֶׁר חָלַם לָהֶם וְגוֹ'. רַבִּי חִיָּיא פָּתַח וְאָמַר, (שם כד) בִּנְפֹל אוֹיִבְךְ אַל תִּשְׂמָח וּבִכָּשְׁלוֹ אַל יָגֵל לִבֶּךְ. בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה אֶת הָאָדָם שֶׁיִּזְכֶּה לִכְבוֹדוֹ וּלְשַׁמֵּשׁ לְפָנָיו תָּמִיד וּלְהִשְׁתַּדֵּל בַּתּוֹרָה יָמִים וְלֵילוֹת, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְרַצֶּה בָהּ בַתּוֹרָה תָּמִיד.</p>\n<p>וְכֵיוָן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָא אֶת הָאָדָם, נָתַן לְפָנָיו תּוֹרָה, וְלִמֵּד אוֹתוֹ בָּהּ לָדַעַת אֶת דְּרָכֶיהָ. מִנַּיִן לָנוּ? שֶׁכָּתוּב (איוב כח) אָז רָאָהּ וַיְסַפְּרָהּ הֱכִינָהּ וְגַם חֲקָרָהּ. וְאַחַר כָּךְ, וַיֹּאמֶר לָאָדָם הֵן יִרְאַת ה' הִיא חָכְמָה וְסוּר מֵרָע בִּינָה. כֵּיוָן שֶׁהִסְתַּכֵּל בָּהּ וְלֹא שָׁמַר אוֹתָהּ, עָבַר עַל מִצְוַת רִבּוֹנוֹ וְנִתְפַּס בְּחֶטְאוֹ.</p>\n<p>וְכָל אוֹתָם שֶׁעָבְרוּ עַל דָּבָר אֶחָד שֶׁל הַתּוֹרָה נִתְפְּסוּ בָהּ. שְׁלֹמֹה הַמֶּלֶךְ שֶׁהִתְחַכֵּם עַל כָּל בְּנֵי הָעוֹלָם, עָבַר עַל דָּבָר אֶחָד שֶׁל הַתּוֹרָה, וְגָרַם לוֹ לְהַעֲבִיר מִמֶּנּוּ אֶת מַלְכוּתוֹ וּלְפַלֵּג אֶת הַמַּלְכוּת מִבְּנוֹ. מִי שֶׁעוֹבֵר עַל הַתּוֹרָה עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>וְיוֹסֵף שֶׁהָיָה יוֹדֵעַ תּוֹרָה, וְאֶחָיו נָפְלוּ בְיָדוֹ, לָמָּה גִלְגֵּל עֲלֵיהֶם כָּל הַגִּלְגּוּל הַזֶּה, וַהֲרֵי הוּא יָדַע אֶת הַתּוֹרָה שֶׁלִּמֵּד אוֹתוֹ אָבִיו? אֶלָּא חַס וְשָׁלוֹם שֶׁיּוֹסֵף גִּלְגֵּל עֲלֵיהֶם גִּלְגּוּלִים לִנְקֹם מֵהֶם, אֶלָּא כָּל זֶה לֹא עָשָׂה אֶלָּא לְהָבִיא אֶת אָחִיו בִּנְיָמִין אֶצְלוֹ, שֶׁתְּשׁוּקָתוֹ הָיְתָה אֵלָיו, וְהוּא לֹא הִשְׁאִיר אֶת אֶחָיו לִפֹּל, שֶׁהֲרֵי כָּתוּב וַיְצַו יוֹסֵף וַיְמַלְּאוּ אֶת כְּלֵיהֶם בָּר וְגוֹ', וְכָל זֶה כְּדֵי שֶׁלֹּא יִפְּלוּ.</p>\n<p>רַבִּי יְהוּדָה אָמַר, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַלְּבָנָה, הָיָה תָמִיד מִסְתַּכֵּל בָּהּ, כַּכָּתוּב (דברים יא) תָּמִיד עֵינֵי ה' אֱלֹהֶיךְ בָּהּ. הַשְׁגָּחָתוֹ בָהּ תָּמִיד. וְכָתוּב אָז רָאָהּ, שֶׁהֲרֵי הַשֶּׁמֶשׁ בְּהַשְׁגָּחָתוֹ בָהּ מְאִירָה. וַיְסַפְּרָהּ, מַה זֶּה וַיְסַפְּרָהּ? כְּמוֹ שֶׁנֶּאֱמַר (איוב כח) מְקוֹם סַפִּיר אֲבָנֶיהָ.</p>\n<p>הֱכִינָהּ, שֶׁהִיא יוֹשֶׁבֶת בְּתִקּוּן בִּשְׁנֵים עָשָׂר תְּחוּמִים מְחֻלֶּקֶת לְשִׁבְעִים שָׂרִים, הִתְקִין אוֹתָהּ בְּשִׁבְעָה עַמּוּדִים עֶלְיוֹנִים לְהֵאוֹר וְלָשֶׁבֶת עַל שְׁלֵמוּת. וְגַם חֲקָרָהּ, לְהַשְׁגִּיחַ עָלֶיהָ תָּמִיד, פַּעַם אַחַר פַּעַם, שֶׁאֵין פּוֹסֵק לְעוֹלָמִים.</p>\n<p>וְאַחַר כָּךְ הִזְהִיר אֶת הָאָדָם וְאָמַר, וַיֹּאמֶר לָאָדָם הֵן יִרְאַת ה' הִיא חָכְמָה וְסוּר מֵרָע בִּינָה, שֶׁהֲרֵי הִיא מִתְעַטֶּרֶת עַל הַתַּחְתּוֹנִים לִירָא וְלָדַעַת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בִּגְלָלָהּ. וְסוּר מֵרָע בִּינָה, בֵּרוּר מֵהַפְּסֹלֶת שֶׁלֹּא לִקְרַב עִמּוֹ, וְאָז הַשְׁגָּחַת (המצאות) הַבִּינָה לָדַעַת וּלְהִסְתַּכֵּל בִּכְבוֹד הַמֶּלֶךְ הָעֶלְיוֹן.</p>\n<p>רַבִּי יוֹסֵי קָם לַיְלָה אֶחָד לְהִשְׁתַּדֵּל בַּתּוֹרָה, וְהָיָה שָׁם עִמּוֹ יְהוּדִי אֶחָד שֶׁפָּגַשׁ בּוֹ בְּאוֹתוֹ הַבַּיִת. פָּתַח רַבִּי יוֹסֵי וְאָמַר, (משלי י) לֹא יוֹעִילוּ אוֹצְרוֹת רֶשַׁע וּצְדָקָה תַּצִּיל מִמָּוֶת. לֹא יוֹעִילוּ אוֹצְרוֹת רֶשַׁע - אֵלּוּ הֵם שֶׁלֹּא מִשְׁתַּדְּלִים בַּתּוֹרָה, וְהוֹלְכִים אַחַר דִּבְרֵי הָעוֹלָם וְלִכְנֹס אוֹצְרוֹת רֶשַׁע. מַה כָּתוּב? (קהלת ה) וְאָבַד הָעֹשֶׁר הַהוּא בְּעִנְיַן רָע, מִשּׁוּם שֶׁהֵם אוֹצְרוֹת רֶשַׁע.</p>\n<p>וּצְדָקָה תַּצִּיל מִמָּוֶת - אֵלּוּ שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה וְיוֹדְעִים דְּרָכֶיהָ לְהִשְׁתַּדֵּל בָּהּ, שֶׁהֲרֵי הַתּוֹרָה נִקְרֵאת עֵץ חַיִּים, וְנִקְרֵאת צְדָקָה, שֶׁכָּתוּב (דברים ו) וּצְדָקָה תִּהְיֶה לָּנוּ. דָּבָר אַחֵר וּצְדָקָה תַּצִּיל מִמָּוֶת - זוֹ צְדָקָה מַמָּשׁ, וְהִיא בִּשְׁנֵי גְוָנִים וּבִשְׁנֵי צְדָדִים. קוֹרֵא לוֹ תּוֹרָה וְקוֹרֵא לוֹ צְדָקָה, וְהַכֹּל אֶחָד.</p>\n<p>אָמַר אוֹתוֹ הַיְּהוּדִי, וְקוֹרֵא לוֹ שָׁלוֹם. אָמַר רַבִּי יוֹסֵי, כָּךְ זֶה וַדַּאי שֶׁנִּקְרֵאת שָׁלוֹם. קָם אוֹתוֹ הַיְּהוּדִי וְהִשְׁתַּתֵּף עִמּוֹ. פָּתַח אוֹתוֹ הַיְּהוּדִי וְאָמַר, (משלי כח) עֹבֵד אַדְמָתוֹ יִשְׂבַּע לָחֶם וּמְרַדֵּף רֵיקִים יִשְׂבַּע רִישׁ. הַפָּסוּק הַזֶּה קָשֶׁה, וְכִי שְׁלֹמֹה הַמֶּלֶךְ, שֶׁהוּא חָכָם מִכָּל בְּנֵי הָעוֹלָם, אֵיךְ אָמַר שֶׁיִּתְאַמֵּץ אָדָם לַעֲבֹד אֶת הָאֲדָמָה וּלְהִשְׁתַּדֵּל אַחֲרֶיהָ וְיַעֲזֹב חַיֵּי עוֹלָם?</p>\n<p>אֶלָּא סוֹד הוּא. פָּתַח וְאָמַר, (בראשית ב) וַיִּקַּח ה' אֱלֹהִים אֶת הָאָדָם וַיַּנִּחֵהוּ בְגַן עֵדֶן לְעָבְדָהּ וּלְשָׁמְרָהּ, וּבֵאֲרוּהוּ שֶׁהוּא בְּסוֹד הַקָּרְבָּנוֹת. בּא רְאֵה, לְעָבְדָהּ - זֶה הַמֶּלֶךְ הָעֶלְיוֹן. וּלְשָׁמְרָהּ - זֶה הַמֶּלֶךְ הַתַּחְתּוֹן. הָעוֹלָם הָעֶלְיוֹן וְהָעוֹלָם הַתַּחְתּוֹן. לְעָבְדָהּ - (לזכר) בַּסּוֹד שֶׁל זָכוֹר. וּלְשָׁמְרָהּ - בַּסּוֹד שֶׁל שָׁמוֹר.</p>\n<p>וּמִשּׁוּם כָּךְ עֹבֵד אַדְמָתוֹ זֶה גַן עֵדֶן, שֶׁצָּרִיךְ לַעֲשׂוֹת וְלַעֲבֹד וְלִמְשֹׁךְ לָהּ בְּרָכוֹת מִלְמַעְלָה, וּכְשֶׁמִּתְבָּרֶכֶת וְנִמְשָׁכוֹת לָהּ בְּרָכוֹת מִלְמַעְלָה, גַּם הוּא מִתְבָּרֵךְ עִמָּהּ. בּא רְאֵה שֶׁהַכֹּהֵן שֶׁמְּבָרֵךְ מִתְבָּרֵךְ, כְּמוֹ שֶׁנֶּאֱמַר (במדבר ו) וַאֲנִי אֲבָרֲכֵם. וּמִשּׁוּם כָּךְ עֹבֵד אַדְמָתוֹ יִשְׂבַּע לָחֶם - זֶהוּ הַמָּזוֹן שֶׁלְּמַעְלָה. וּמְרַדֵּף רֵיקִים - מִי שֶׁיִּתְדַּבֵּק בַּצַּד הָאַחֵר שֶׁהוּא מְרַדֵּף רֵיקִים - יִשְׂבַּע רִישׁ וַדַּאי. אָמַר רַבִּי יוֹסֵי, אַשְׁרֶיךְ שֶׁזָּכִיתָ לַדָּבָר הַזֶּה.</p>\n<p>עוֹד פָּתַח וְאָמַר פָּסוּק אַחֲרָיו, (משלי כח) אִישׁ אֱמוּנוֹת רַב בְּרָכוֹת. זֶהוּ אָדָם שֶׁבּוֹ אֱמוּנַת הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ רַבִּי יֵיסָא הַזָּקֵן, שֶׁאַף עַל גַּב שֶׁהָיָה לוֹ מַאֲכָל שֶׁל אוֹתוֹ הַיּוֹם לֶאֱכֹל, לֹא הָיָה מַתְקִין אוֹתוֹ עַד שֶׁהָיָה מְבַקֵּשׁ מְזוֹנוֹ לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ. אַחַר שֶׁהִתְפַּלֵּל תְּפִלָּתוֹ וּבִקֵּשׁ מְזוֹנוֹ מִלִּפְנֵי הַמֶּלֶךְ, אָז הָיָה מַתְקִין, וְהָיָה תָמִיד אוֹמֵר: לֹא נַתְקִין עַד שֶׁיִּנָּתְנוּ מִבֵּית הַמֶּלֶךְ.</p>\n<p>וְאָץ לְהַעֲשִׁיר לֹא יִנָּקֶה, מִשּׁוּם שֶׁלֹּא רָצָה לְהִשְׁתַּדֵּל בַּתּוֹרָה, שֶׁהִיא הַחַיִּים שֶׁל הָעוֹלָם הַזֶּה וְהַחַיִּים שֶׁל הָעוֹלָם הַבָּא. עַכְשָׁו שֶׁהִיא הַשָּׁעָה לְהִשְׁתַּדֵּל בַּתּוֹרָה - נִשְׁתַּדֵּל.</p>\n<p>פָּתַח אוֹתוֹ הָאִישׁ בְּסוֹד הַחֲלוֹם וְאָמַר, וַיִּזְכֹּר יוֹסֵף אֵת הַחֲלֹמוֹת אֲשֶׁר חָלַם לָהֶם וְגוֹ'. וַיִּזְכֹּר יוֹסֵף אֵת הַחֲלֹמוֹת, וְכִי לָמָּה יוֹסֵף (אמר או) זָכַר לָהֶם אוֹתָם הַחֲלוֹמוֹת שֶׁחָלַם לָהֶם, וּמַה הוֹעִיל לוֹ אִלּוּ לֹא הִזְכִּיר לָהֶם, שֶׁהֲרֵי יוֹסֵף הָיָה חָכָם, וְכָתוּב כָּל עָרוּם יַעֲשֶׂה בְדָעַת וּכְסִיל יִפְרֹשׂ אִוֶּלֶת?</p>\n<p>אֲבָל כֵּיוָן שֶׁרָאָה שֶׁהֵם בָּאוּ וּמִשְׁתַּחֲוִים לוֹ אַפַּיִם עַל הָאָרֶץ, אָז נִזְכַּר מִמַּה שֶּׁחָלַם לָהֶם כְּשֶׁהָיָה עִמָּהֶם, שֶׁכָּתוּב וְהִנֵּה קָמָה אֲלֻמָּתִי וְגַם נִצָּבָה וְהִנֵּה תְסֻבֶּינָה אֲלֻמֹּתֵיכֶם וַתִּשְׁתַּחֲוֶיןָ לַאֲלֻמָּתִי. אָמַר יוֹסֵף בְּשָׁעָה שֶׁרָאָה שֶׁכּוֹרְעִים אֶחָיו לְפָנָיו, שֶׁכָּתוּב וַיָּבאוּ אֲחֵי יוֹסֵף וַיִּשְׁתַּחֲווּ לוֹ אַפַּיִם אָרְצָה, אָז וַיִּזְכֹּר יוֹסֵף אֵת הַחֲלֹמוֹת אֲשֶׁר חָלַם, שֶׁהֲרֵי רָאָה שֶׁהֵם קַיָּמִים.</p>\n<p>עוֹד, וַיִּזְכֹּר יוֹסֵף אֵת הַחֲלֹמוֹת אֲשֶׁר חָלַם - זָכַר אוֹתָם, מִשּׁוּם שֶׁאֵין שִׁכְחָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. שֶׁהֲרֵי חֲלוֹם שֶׁהוּא טוֹב, צָרִיךְ אָדָם לְהַזְכִּירוֹ, שֶׁלֹּא יִשָּׁכַח, וְאָז מִתְקַיֵּם, שֶׁהֲרֵי כְּמוֹ שֶׁנִּשְׁכָּח לִפְנֵי הָאָדָם, כָּךְ נִשְׁכָּח עָלָיו.</p>\n<p>בֹּא רְאֵה, חֲלוֹם שֶׁלֹּא נִפְתַּר, כְּאִגֶּרֶת שֶׁלֹּא נִקְרְאָה. וּבֹא רְאֵה, מִשּׁוּם שֶׁלֹּא נִזְכָּר, כְּמִי שֶׁלֹּא הִכִּיר אוֹתוֹ. וְעַל זֶה, מִי שֶׁנִּשְׁכַּח מִמֶּנּוּ חֲלוֹם וְלֹא יָדַע אוֹתוֹ, לֹא עוֹמֵד עָלָיו לְהִתְקַיֵּם. וּמִשּׁוּם זֶה יוֹסֵף הָיָה זוֹכֵר אֶת חֲלוֹמוֹ, כְּדֵי לְהִתְקַיֵּם, מִשּׁוּם שֶׁלֹּא יִשָּׁכַח הַחֲלוֹם מִמֶּנּוּ לְעוֹלָם, וְהָיָה תָמִיד מְצַפֶּה לוֹ. וַיֹּאמֶר אֲלֵהֶם מְרַגְּלִים אַתֶּם. הוּא זָכַר אֶת הַחֲלוֹם, אֲבָל לֹא אָמַר לָהֶם דָּבָר, אֶלָּא מְרַגְּלִים אַתֶּם.</p>\n<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, (קהלת ה) כִּי בָּא הַחֲלוֹם בְּרֹב עִנְיָן וְקוֹל כְּסִיל בְּרֹב דְּבָרִים. כִּי בָּא הַחֲלוֹם בְּרֹב עִנְיָן, הִנֵּה פֵּרְשׁוּהָ שֶׁכַּמָּה הֵם הָעוֹזְרִים בַּחֲלוֹם, וּמְמֻנִּים דְּרָגוֹת עַל דְּרָגוֹת, עַד שֶׁהַחֲלוֹמוֹת מֵהֶם כֻּלָּם אֱמֶת, וּמֵהֶם שֶׁיֵּשׁ בָּהֶם אֱמֶת וְכָזָב. אֲבָל לְאוֹתָם צַדִּיקֵי הָאֱמֶת, אֵין מִתְגַּלִּים לָהֶם דְּבָרִים כּוֹזְבִים כְּלוּם, אֶלָּא כֻּלָּם אֱמֶת.</p>\n<p>בֹּא רְאֵה דָּנִיֵּאל מַה כָּתוּב בּוֹ, (דניאל ב) אָז לְדָנִיֵּאל בְּחֶזְיוֹן הַלַּיְלָה סוֹד גִּלָּה, וְכָתוּב (שם ז) דָּנִיּאֵל רָאָה חֲלוֹם בִּהְיוֹתוֹ יָשֵׁן עַל מִשְׁכָּבוֹ, אָז כָּתַב אֶת הַחֲלוֹם. וְאִם יֵשׁ בּוֹ דְּבָרִים כּוֹזְבִים, לָמָּה נִכְתַּב בֵּין הַכְּתוּבִים? אֶלָּא אוֹתָם צַדִּיקֵי אֱמֶת, בְּשָׁעָה שֶׁנִּשְׁמוֹתֵיהֶם עוֹלוֹת, לֹא מִתְחַבְּרִים בָּהֶם אֶלָּא דְבָרִים קְדוֹשִׁים, שֶׁמּוֹדִיעִים לוֹ דִּבְרֵי אֱמֶת, דְּבָרִים קַיָּמִים, שֶׁלֹּא מְשַׁקְּרִים לְעוֹלָמִים.</p>\n<p>וְאִם תֹּאמַר, הִנֵּה שָׁנִינוּ שֶׁדָּוִד הַמֶּלֶךְ לֹא רָאָה חֲלוֹם טוֹב, הִנֵּה נִשְׁמָע שֶׁהָיָה רוֹאֶה דָוִד דְּבָרִים שֶׁלֹּא אֱמֶת? אֶלָּא וַדַּאי, כָּל יָמָיו הָיָה מִשְׁתַּדֵּל לִשְׁפֹּךְ דָּמִים וְנִלְחַם קְרָבוֹת, וְכָל חֲלוֹמוֹת לֹא הָיוּ אֶלָּא חֲלוֹמוֹת רָעִים, חֻרְבָּן וּשְׁמָמָה וְדָם וּשְׁפִיכוּת דָּמִים, וְלֹא חֲלוֹם שֶׁל שָׁלוֹם.</p>\n<p>וְאִם תֹּאמַר, לְאָדָם טוֹב מַרְאִים חֲלוֹם רָע? כָּךְ זֶה וַדַּאי. כָּל אוֹתָם רָעוֹת שֶׁעֲתִידִים לְהַשִּׂיג - עַל אוֹתָם שֶׁעוֹבְרִים עַל דִּבְרֵי תוֹרָה, וְאוֹתָם עֳנָשִׁים שֶׁעֲתִידִים לְהֵעָנֵשׁ בָּעוֹלָם הַהוּא כֻּלָּם רוֹאֶה, כְּדֵי שֶׁכָּל שָׁעָה תִּהְיֶה יִרְאַת אֲדוֹנוֹ עָלָיו. וְהִנֵּה הֵעִירוּ שֶׁכָּתוּב (קהלת ג) וְהָאֱלֹהִים עָשָׂה שֶׁיִּירְאוּ מִלְּפָנָיו - זֶה חֲלוֹם רָע. וְעַל זֶה לְאוֹתוֹ צַדִּיק מַרְאִים לוֹ חֲלוֹם רָע, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>בֹּא רְאֵה, שֶׁהִנֵּה שָׁנִינוּ, שֶׁאוֹתוֹ אָדָם שֶׁרוֹאֶה חֲלוֹם, צָרִיךְ לוֹ לִפְתֹּחַ אֶת פִּיו בּוֹ לִפְנֵי אֲנָשִׁים שֶׁאוֹהֲבִים אוֹתוֹ, כְּדֵי שֶׁיַּעֲלֶה רְצוֹנָם אֵלָיו לְטוֹב וְיִפְתְּחוּ פִיהֶם לְטוֹב, וְיִמָּצֵא הָרָצוֹן וְהַדָּבָר הַכֹּל לְטוֹב. הָרָצוֹן שֶׁהוּא הַמַּחֲשָׁבָה רֵאשִׁית הַכֹּל, וְהַמִּלָּה שֶׁהִיא סִיּוּם הַכֹּל. וְעַל כֵּן נִמְצָא שֶׁהִנֵּה הוּא שְׁלֵמוּת בְּסוֹד עֶלְיוֹן. וּמִשּׁוּם כָּךְ הַכֹּל מִתְקַיֵּם, וּצְרִיכִים אוֹהֲבֵי הָאִישׁ לְהִתְקַיֵּם בְּאוֹתוֹ פִּתְרוֹן טוֹב, וְהַכֹּל הוּא כָּרָאוּי.</p>\n<p>וּמִשּׁוּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹדִיעַ לָאָדָם כָּל אֶחָד וְאֶחָד בְּאוֹתָהּ הַדַּרְגָּה שֶׁלּוֹ כְּמוֹ שֶׁהוּא, וּבְאוֹתוֹ גָוֶן שֶׁכָּל אֶחָד וְאֶחָד אוֹמֵר שֶׁיִּהְיֶה חֲלוֹם. אָמַר אוֹתוֹ יְהוּדִי, וַדַּאי שֶׁהַחֲלוֹם אֵינוֹ אֶלָּא לְאָדָם צַדִּיק, שֶׁהוּא רָאָה חֲלוֹם כָּרָאוּי.</p>\n<p>וּבֹא וּרְאֵה, שֶׁכַּאֲשֶׁר אָדָם יָשֵׁן עַל מִטָּתוֹ, נִשְׁמָתוֹ יוֹצֵאת וּמְשׁוֹטֶטֶת בָּעוֹלָם לְמַעְלָה וְנִכְנֶסֶת לְמָקוֹם שֶׁנִּכְנֶסֶת, וְכַמָּה קְבוּצוֹת מַזִּיקִים עוֹמְדִים וְהוֹלְכִים בָּעוֹלָם וּפוֹגְשִׁים אֶת אוֹתָהּ הַנְּשָׁמָה. אִם הִיא צַדִּיקָה, עוֹלָה לְמַעְלָה וְרוֹאָה מַה שֶּׁרוֹאָה. וְאִם לֹא, נֶאֱחֶזֶת בַּצַּד הַהוּא, וּמוֹדִיעִים לָהּ דְּבָרִים כּוֹזְבִים אוֹ דְבָרִים שֶׁעֲתִידִים לָבֹא לַזְּמַן הַקָּרוֹב. וּכְשֶׁמִּתְעוֹרֶרֶת אוֹתָהּ הַנְּשָׁמָה שֶׁבּוֹ, הִיא מוֹדִיעָה לוֹ מַה שֶּׁרָאֲתָה.</p>\n<p>וְעַל כֵּן לְאָדָם שֶׁאֵינוֹ צַדִּיק מוֹדִיעִים לוֹ חֲלוֹם טוֹב שֶׁאֵינוֹ אֱמֶת, הַכֹּל כְּדֵי לְהַסְטוֹתוֹ מֵאוֹתָהּ דֶּרֶךְ הָאֱמֶת. כֵּיוָן שֶׁהוּא הֵסִיט אֶת דַּרְכּוֹ מִדֶּרֶךְ הָאֱמֶת, מְטַמְּאִים אוֹתוֹ. שֶׁכָּל מִי שֶׁבָּא לְהִטָּהֵר - מְטַהֲרִים אוֹתוֹ, וּמִי שֶׁבָּא לְהִטָּמֵא - מְטַמְּאִים אוֹתוֹ. הִנֵּה וַדַּאי כָּךְ נִתְבָּאֵר.</p>\n<p>יָשְׁבוּ עַד שֶׁעָלָה הַבּקֶר. אָמַר רַבִּי יוֹסֵי, וַדַּאי לֹא זָכַר שְׁמוֹ שֶׁל יוֹסֵף בְּאוֹתָם דְּגָלִים, שֶׁכָּתוּב (במדבר ב) דֶּגֶל מַחֲנֵה אֶפְרַיִם, וְלֹא כָתוּב דֶּגֶל מַחֲנֵה יוֹסֵף, מִשּׁוּם שֶׁהִתְגָּאָה עַל אֶחָיו, וְהִנֵּה נִתְבָּאֵר.</p>\n<p>אָמַר אוֹתוֹ הַיְּהוּדִי, וַדַּאי שָׁמַעְתִּי, שֶׁיּוֹסֵף הוּא בְּעוֹלַם הַזָּכָר, וְכָל הַשְּׁבָטִים הֵם בְּעוֹלַם הַנְּקֵבָה, וְעַל כֵּן לֹא נִכְלָל יוֹסֵף עִמָּהֶם, מִשּׁוּם שֶׁהוּא בְּעוֹלַם הַזָּכָר עִמָּהֶם.</p>\n<p>מַה כָּתוּב? כֻּלָּנוּ בְּנֵי אִישׁ אֶחָד נָחְנוּ. נָחְנוּ? אַחְנוּ הָיָה צָרִיךְ לִכְתֹּב! לָמָּה חָסֵר א'? אֶלָּא מִשּׁוּם שֶׁסּוֹד הַבְּרִית לֹא נִמְצָא עִמָּם. הִסְתַּלֵּק מִשָּׁם א', שֶׁהֲרֵי א' הוּא זָכָר. וְעַל כֵּן ב' הִיא נְקֵבָה, א' זָכָר. וּמִשּׁוּם כָּךְ א' הִסְתַּלֵּק מִשָּׁם, וְנִשְׁאֲרוּ אוֹתָן נְקֵבוֹת אֵצֶל הַשְּׁכִינָה.</p>\n<p>אַחַר כָּךְ אָמְרוּ כֵּנִים אֲנַחְנוּ. נוֹסְפָה א'. אָמְרוּ וְלֹא יָדְעוּ מָה אָמְרוּ, מִשּׁוּם שֶׁיּוֹסֵף נִמְצָא שָׁם, וְהִשְׁלִימוּ הַדָּבָר וְאָמְרוּ אֲנַחְנוּ. מִנַּיִן לָנוּ? שֶׁכָּתוּב וַיֹּאמְרוּ שְׁנֵיהֶם עָשָׂר עֲבָדֶיךְ אַחִים אֲנַחְנוּ. וְיוֹסֵף הוּא בַּחֶשְׁבּוֹן. כְּשֶׁנִּכְנַס בַּחֶשְׁבּוֹן, אָמְרוּ אֲנַחְנוּ. וּכְשֶׁלֹּא נִכְנַס בַּחֶשְׁבּוֹן, אָמְרוּ נָחְנוּ.</p>\n<p>אָמַר רַבִּי יוֹסֵי, כָּל הַדְּבָרִים הַלָּלוּ שֶׁאָמַרְנוּ כָאן, הַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם, שֶׁהֲרֵי הַשְּׁכִינָה לֹא זָזָה מִכָּאן, כַּכָּתוּב (מלאכי ג) אָז נִדְבְּרוּ יִרְאֵי ה' אִישׁ אֶל רֵעֵהוּ וַיַּקְשֵׁב ה' וַיִּשְׁמָע וַיִּכָּתֵב סֵפֶר זִכָּרוֹן לְפָנָיו לְיִרְאֵי ה' וּלְחֹשְׁבֵי שְׁמוֹ.</p>"],[9522011405,"<p>וַיְּאסֹף אֹתָם אֶל מִשְׁמָר שְׁלֹשֶׁת יָמִים. אָמַר רַבִּי אֶלְעָזָר, שְׁלֹשֶׁת הַיָּמִים הַלָּלוּ לָמָּה? אֶלָּא שְׁלֹשֶׁת הַיָּמִים הַלָּלוּ כְּנֶגֶד שְׁלֹשֶׁת הַיָּמִים שֶׁל שְׁכֶם, שֶׁכָּתוּב (בראשית לד) וַיְהִי בַיּוֹם הַשְּׁלִישִׁי בִּהְיוֹתָם כֹּאֲבִים.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב בּוֹ, וַיֹּאמֶר אֲלֵהֶם יוֹסֵף בַּיּוֹם הַשְּׁלִישִׁי זאת עֲשׂוּ וִחְיוּ. לְהַרְאוֹת שֶׁהוּא לֹא עָשָׂה כְּמוֹ שֶׁהֵם עָשׂוּ בִּשְׁכֶם, שֶׁגָּרְמוּ לְאַנְשֵׁי שְׁכֶם לְקַבֵּל עֲלֵיהֶם אֶת זֹאת, סוֹד הַבְּרִית, וְאַחַר שֶׁעָשׂוּ הַבְּרִית הַזּוֹ, הָרְגוּ אוֹתָם, וְלֹא נִשְׁאַר מֵהֶם אֶחָד. וְהוּא מַה כָּתוּב? זֹאת עֲשׂוּ וִחְיוּ. מָה הַטַּעַם? מִשּׁוּם שֶׁאֶת הָאֱלֹהִים אֲנִי יָרֵא, שָׁמַר הַבְּרִית. וְכָל הַגִּלְגּוּל הַזֶּה לֹא הָיָה אֶלָּא בִּשְׁבִיל בִּנְיָמִין.</p>\n<p>וַיֹּאמְרוּ אִישׁ אֶל אָחִיו אֲבָל אֲשֵׁמִים אֲנַחְנוּ עַל אָחִינוּ וְגוּ'. וַיֹּאמְרוּ אִישׁ אֶל אָחִיו - זֶה שִׁמְעוֹן וְלֵוִי, כְּמוֹ שֶׁהָיָה בָּרִאשׁוֹנָה שֶׁכָּתוּב (שם לז) וַיֹּאמְרוּ אִישׁ אֶל אָחִיו הִנֵּה בַּעַל הַחֲלֹמוֹת הַלָּזֶה בָּא. מַה לְּהַלָּן שִׁמְעוֹן וְלֵוִי - אַף כָּאן שִׁמְעוֹן וְלֵוִי.</p>\n<p>בֹּא רְאֵה, מִי אִישׁ וּמִי אָחִיו? אֶלָּא אִישׁ זֶה שִׁמְעוֹן. כָּתוּב כָּאן אִישׁ, וְכָתוּב שָׁם (במדבר כה) וְהִנֵּה אִישׁ מִבְּנֵי יִשְׂרָאֵל בָּא. מַה לְּהַלָּן מִשִּׁמְעוֹן - אַף כָּאן גַּם שִׁמְעוֹן. וּמִשּׁוּם שֶׁחָזַר בִּתְשׁוּבָה, בָּכָה וְהִתְנַחֵם עַל זֶה, וְאָמַר לְלֵוִי אֲבָל אֲשֵׁמִים אֲנַחְנוּ. עַל כֵּן נִבְנָה מַזָּלוֹ שׁוֹר, כְּמוֹ שֶׁמַּזָּלוֹ שֶׁל יוֹסֵף שׁוֹר, שֶׁכָּתוּב (דברים לג) בְּכוֹר שׁוֹרוֹ הָדָר לוֹ. וּמַזָּלוֹ שֶׁל שִׁמְעוֹן הוּא שׁוֹר.</p>"],[9522011406,"<p>וְעַל כֵּן וַיִּקַּח מֵאִתָּם אֶת שִׁמְעוֹן, כְּדֵי שֶׁלֹּא יְקַטְרֵג עִם לֵוִי, מִשּׁוּם שֶׁשִּׁמְעוֹן וְלֵוִי, כְּשֶׁשְּׁנֵיהֶם מִתְחַבְּרִים, יְכוֹלִים לְקַטְרֵג. וַיֶּאֱסֹר אֹתוֹ לְעֵינֵיהֶם. הִנֵּה פֵּרְשׁוּהָ, לְעֵינֵיהֶם אֲסָרוֹ, וְאַחַר שֶׁיָּצְאוּ הָיָה מַאֲכִיל אוֹתוֹ וּמַשְׁקֶה אוֹתוֹ.</p>\n<p>וְאִם תֹּאמַר שֶׁהוּא רְצוֹנוֹ שֶׁל יוֹסֵף, מִשּׁוּם שֶׁכָּתוּב (משלי כה) אִם רָעֵב שֹׂנַאֲךְ הַאֲכִילֵהוּ לָחֶם וְאִם צָמֵא הַשְׁקֵהוּ מָיִם. אִם כָּךְ, יוֹסֵף שֶׁהוּא צַדִּיק אֵיךְ עָשָׂה כָּךְ, שֶׁהֲרֵי כָּתוּב (שם) כִּי גֶחָלִים אַתָּה חֹתֶה עַל רֹאשׁוֹ וַה' יְשַׁלֶּם לָךְ.</p>\n<p>אֶלָּא חַס וְחָלִילָה שֶׁיּוֹסֵף לְכָךְ הוּא חָשַׁשׁ, אֶלָּא כְּאָדָם לְאָחִיו כָּךְ גַּם הָיָה עוֹשֶׂה, הִתְנַהֵג עִמּוֹ בְּאַחֲוָה וְלֹא בְצוּרָה אַחֶרֶת, וְלֹא עִמּוֹ בִּלְבַדּוֹ, אֶלָּא עִם כָּל אֶחָיו, כְּמוֹ שֶׁכָּתוּב וַיְצַו יוֹסֵף וַיְמַלְאוּ אֶת כְּלֵיהֶם בָּר וּלְהָשִׁיב כַּסְפֵּיהֶם אִישׁ אֶל שַׂקּוֹ וְלָתֵת לָהֶם צֵדָה לַדָּרֶךְ וַיַּעַשׂ לָהֶם כֵּן, כְּדֵי לְהִתְנַהֵג עִמָּם בְּאַחֲוָה.</p>\n<p>רַבִּי יוֹסֵי פָּתַח וְאָמַר, (נחום א) אִם שְׁלֵמִים וְכֵן רַבִּים וְכֵן נָגוֹזּוּ וְעָבָר וְעִנִּתִךְ לֹא אֲעַנֵּךְ עוֹד. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ, שֶׁכַּאֲשֶׁר הָעָם בְּכֻלָּם יֵשׁ שָׁלוֹם וְאֵין בָּהֶם בַּעֲלֵי שִׂנְאָה, הַקָּדוֹשׁ בָּרוּךְ הוּא חָס עֲלֵיהֶם, וְהַדִּין לֹא שׁוֹלֵט בָּהֶם. וְאַף עַל גַּב שֶׁכֻּלָּם עוֹבְדִים לְכוֹכָבִים וּמַזָּלוֹת וְהֵם בְּשָׁלוֹם - הַדִּין לֹא שׁוֹלֵט עֲלֵיהֶם, וּבֵאֲרוּהָ שֶׁכָּתוּב (הושע ד) חבוּר עֲצַבִּים אֶפְרַיִם הַנַּח לוֹ.</p>\n<p>וְכֵן נָגוֹזּוּ וְעָבָר, מַה זֶּה וְכֵן נָגוֹזּוּ? הָיָה צָרִיךְ לִהְיוֹת וְנָגוֹזּוּ! אֶלָּא זֶהוּ רֹאשׁ הַפָּסוּק שֶׁהוּא שָׁלוֹם, אַף כָּאן שָׁלוֹם, וּמִי הוּא? זֶהוּ צְדָקָה. מִשּׁוּם שֶׁצְּדָקָה זֶהוּ שָׁלוֹם, וּמִי שֶׁמַּרְבֶּה בִּצְדָקָה, מַרְבֶּה שָׁלוֹם לְמַעְלָה וּמַרְבֶּה שָׁלוֹם לְמַטָּה, וּמִשּׁוּם כָּךְ וְכֵן נָגוֹזּוּ ועָבָר, שֶׁגּוֹזְזִים מָמוֹנָם בִּצְדָקָה. וְעָבָר? הָיָה צָרִיךְ לִהְיוֹת וְעָבְרוּ. מַה זֶּה וְעָבָר? אֶלָּא זֶה הַדִּין שֶׁל הָרֹגֶז, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כו) עַד יַעֲבָר זָעַם. עָבַר הַדִּין מֵעֲלֵיהֶם.</p>\n<p>דָּבָר אַחֵר כֹּה אָמַר ה' אִם שְׁלֵמִים - אֵלּוּ יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לָהֶם בְּרִית הַקֹּדֶשׁ לִשְׁמֹר אוֹתוֹ תָּמִיד, וְשֶׁהָאָדָם יִהְיֶה בּוֹ שָׁלֵם בְּכָל הַצְּדָדִים, לְמַעְלָה וּלְמַטָּה. וְאִם אֵין הָאָדָם שׁוֹמֵר אוֹתוֹ תָּמִיד, הֲרֵי הוּא פָּגוּם, פָּגוּם בַּכֹּל. מִנַּיִן לָנוּ? שֶׁכָּתוּב (בראשית יז) הִתְהַלֵּךְ לְפָנַי וֶהְיֵה תָמִים. מַה זֶּה תָּמִים? שָׁלֵם. שֶׁעַד שֶׁלֹּא הִתְקַיְמָה בּוֹ בְּרִית, הוּא פָּגוּם.</p>\n<p>וּמִשּׁוּם כָּךְ, אִם שְׁלֵמִים וְכֵן רַבִּים - אִם שְׁלֵמִים שֶׁשּׁוֹמְרִים הַמִּצְוָה הַזּוֹ לִהְיוֹת שְׁלֵמִים, שֶׁלֹּא יִהְיוּ פְגוּמִים. וְכֵן רַבִּים - יִרְבּוּ וְיִגְדְּלוּ בוֹ, מִשּׁוּם שֶׁאֵין הַנְּשָׁמוֹת יוֹצְאוֹת לָעוֹלָם אֶלָּא עִם הַבְּרִית הַזּוֹ. וְכֵן נָגוֹזּוּ - זֶה אִם שְׁלֵמִים שֶׁשּׁוֹמְרִים אוֹתוֹ תָּמִיד, נָגוֹזּוּ מִי שֶׁנִּמּוֹל וְקִבֵּל עָלָיו אֶת הַבְּרִית הַזּוֹ. וְעָבָר - מַה זֶּה וְעָבָר? אוֹתָהּ זֻהֲמַת הָעָרְלָה שֶׁהָיְתָה בּוֹ בָּרִאשׁוֹנָה.</p>\n<p>דָּבָר אַחֵר כֹּה אָמַר ה' אִם שְׁלֵמִים וְכֵן רַבִּים - אֵלּוּ בְּנֵי יַעֲקֹב. שֶׁהֲרֵי כָּל זְמַן שֶׁהָיוּ אֵצֶל יוֹסֵף, הֵם שְׁלֵמִים, שֶׁעוֹמְדִים עִם הַבְּרִית. וְכֵן נָגוֹזּוּ - שֶׁהָלְכוּ וְהִשְׁאִירוּ אֶת יוֹסֵף וְאֶת שִׁמְעוֹן. וְעָבָר - אָז הַדִּין שׁוֹרֶה בִּגְלָלָם (השכינה שרתה ביניהם), כְּמוֹ שֶׁנֶּאֱמַר (שמות יב) וְעָבַר ה' לִנְגֹּף אֶת מִצְרַיִם.</p>\n<p>בֹּא רְאֵה, יֵשׁ דִּין קָשֶׁה וְיֵשׁ דִּין רָפֶה. הַדִּין הַקָּשֶׁה חָזָק, הַדִּין הָרָפֶה חַלָּשׁ. וְכַאֲשֶׁר יוֹנֵק הַדִּין הָרָפֶה הַזֶּה מֵהַדִּין הַקָּשֶׁה, אָז מִתְגַּבֵּר, וְהוּא חָזָק.</p>\n<p>בְּשָׁעָה שֶׁנַּעֲשֶׂה דִּין עַל יִשְׂרָאֵל, נַעֲשֶׂה בַּדִּין הָרָפֶה הַזֶּה, וְאֵינוֹ מִתְגַּבֵּר בְּאוֹתוֹ הַדִּין הַקָּשֶׁה. וּכְשֶׁהַדִּין נַעֲשֶׂה עַל הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, מִתְגַּבֵּר הַדִּין הָרָפֶה הַזֶּה בַּדִּין הַקָּשֶׁה שֶׁלְּמַעְלָה כְּדֵי לְהִתְגַּבֵּר. זֶהוּ שֶׁכָּתוּב וְעָבַר ה' לִנְגֹּף אֶת מִצְרַיִם. וְעָבָר - שֶׁהִתְמַלֵּא עֶבְרָה וָזַעַם וְהִתְגַּבֵּר בַּדִּין הַקָּשֶׁה. אַף כָּאן וְעָבָר. וּבֹא וּרְאֵה, בְּשָׁעָה שֶׁמִּתְכַּנְּסִים עֲשָׂרָה בְּבֵית הַכְּנֶסֶת וְאֶחָד מֵהֶם נִשְׁמָט, אָז הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹגֵז עָלָיו.</p>\n<p>דָּבָר אַחֵר וְכֵן נָגוֹזּוּ - כְּשֶׁמִּתְבַּטְּלִים מֵהֶם אוֹתָם הַמַּעֲשִׂים הָרָעִים, אֲזַי וְעָבָר. מַה זֶּה וְעָבָר? רַבִּי שִׁמְעוֹן אָמַר, בִּזְמַן שֶׁהַנְּשָׁמָה יוֹצֵאת מִן הָעוֹלָם הַזֶּה, הִיא נִדּוֹנֵית בְּכַמָּה דִינִים בְּטֶרֶם תִּכָּנֵס לִמְקוֹמָהּ. אַחַר כָּךְ כָּל אוֹתָן הַנְּשָׁמוֹת יֵשׁ לָהֶן לַעֲבֹר בְּזֶה הַנְּהַר דִּינוּר שֶׁשּׁוֹפֵעַ וְיוֹצֵא וְלִרְחֹץ שָׁם. וּמִי הוּא שֶׁיַּעֲמֹד שָׁם וְיַעֲבֹר בְּלִי פַחַד? כְּמוֹ שֶׁנֶּאֱמַר (תהלים כד) מִי יַעֲלֶה בְהַר ה' וְגוֹ', וְנִשְׁמַת הַצַּדִּיק עוֹבֶרֶת בְּלִי פַחַד, וְיָקוּם בִּמְקוֹם קָדְשׁוֹ.</p>\n<p>וּמִי שֶׁמִּשְׁתַּדֵּל בִּצְדָקָה בָּעוֹלָם הַזֶּה וְיִתֵּן מִמָּמוֹנוֹ לִצְדָקָה, אֲזַי וְעָבַר בְּאוֹתוֹ הַמָּקוֹם וְלֹא פוֹחֵד, וְהַכָּרוֹז קוֹרֵא לַנְּשָׁמָה הַהִיא, (נחום א) וְעִנִּתִךְ לֹא אֲעַנֵּךְ עוֹד. מִי שֶׁזָּכָה לַעֲבֹר בָּזֶה, אֵין לוֹ יוֹתֵר דִּין כְּלָל.</p>\n<p>בֹּא רְאֵה, כָּל זֶה שֶׁל יוֹסֵף עִם אֶחָיו וְכָל הַדְּבָרִים הַלָּלוּ לָמָּה צָרִיךְ? אֶלָּא תּוֹרַת אֱמֶת הִיא הַתּוֹרָה, וְכָל דְּרָכֶיהָ דְּרָכִים קְדוֹשׁוֹת, וְאֵין לְךְ דָּבָר בַּתּוֹרָה שֶׁאֵין בּוֹ סוֹדוֹת עֶלְיוֹנִים וּקְדוֹשִׁים וּדְרָכִים לִבְנֵי אָדָם לְהִתְחַזֵּק בָּהֶם.</p>\n<p>פָּתַח וְאָמַר, (משלי כ) אַל תֹּאמַר אֲשַׁלְּמָה רָע וְגוֹ'. בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה לָאָדָם שֶׁיִּתְגַּבֵּר בַּתּוֹרָה, וְלָלֶכֶת בְּדֶרֶךְ אֱמֶת, וּלְצַד הַיָּמִין, וְלֹא יֵלֵךְ לְצַד הַשְּׂמֹאל. וּמִשּׁוּם שֶׁצָּרִיךְ לָהֶם לָלֶכֶת לְצַד הַיָּמִין, יֵשׁ לָהֶם לְהַרְבּוֹת אַהֲבָה זֶה עִם זֶה, וְלֹא תִהְיֶה שִׂנְאָה זֶה עִם זֶה, כְּדֵי שֶׁלֹּא לְהַכְחִישׁ אֶת הַיָּמִין, שֶׁהוּא הַמָּקוֹם שֶׁיִּשְׂרָאֵל נִדְבָּקִים בּוֹ.</p>\n<p>וּבֹא וּרְאֵה, מִשּׁוּם כָּךְ הוּא יֵצֶר טוֹב וְיֵצֶר רָע, וְיִשְׂרָאֵל צְרִיכִים לְחַזֵּק אֶת יֵצֶר טוֹב עַל יֵצֶר רָע בְּאוֹתָם הַמַּעֲשִׂים הַכְּשֵׁרִים, וְאִם אָדָם סוֹטֶה לִשְׂמֹאל, אָז מִתְגַּבֵּר יֵצֶר רָע עַל יֵצֶר טוֹב. וּמִי שֶׁהָיָה פָגוּם, מַשְׁלִים לוֹ בְּחֶטְאוֹ, שֶׁהֲרֵי אֵין הַמְנֻוָּל הַזֶּה נִתְקָן אֶלָּא בַּחֲטָאִים שֶׁל בְּנֵי הָאָדָם.</p>\n<p>וּמִשּׁוּם כָּךְ צָרִיךְ הָאָדָם לְהִזָּהֵר שֶׁלֹּא יְתֻקַּן אוֹתוֹ יֵצֶר רָע בְּחֶטְאוֹ, וְתָמִיד יִשָּׁמֵר, שֶׁהֲרֵי יֵצֶר טוֹב רוֹצֶה לְהַשְׁלִימוֹ תָּמִיד בִּשְׁלֵמוּת, וְלֹא יֵצֶר הָרָע. וּמִשּׁוּם כָּךְ, אַל תֹּאמַר אֲשַׁלְּמָה רָע קַוֵּה אֶל ה' וְיֹשַׁע לָךְ.</p>\n<p>דָּבָר אַחֵר אַל תֹּאמַר אֲשַׁלְּמָה רָע - כַּכָּתוּב (תהלים לח) וּמְשַׁלְּמֵי רָעָה תַּחַת טוֹבָה. לְמִי שֶׁשִּׁלֵּם לוֹ טוֹבָה - שֶׁלֹּא יְשַׁלֵּם לוֹ רָע, מִשּׁוּם (יראת הקדוש ברוך הוא, כמו שנאמר זאת עשו וחיו, וגם הוא תמיד עושה) שֶׁכָּתוּב (משלי יז) מֵשִׁיב רָעָה תַּחַת טוֹבָה לֹא תָמוּשׁ רָעָה מִבֵּיתוֹ. אֲפִלּוּ לְמִי שֶׁהִשְׁלִימוּ לוֹ רָעוֹת, אֵין לוֹ לְהַשְׁלִים רָע תְּמוּרַת אוֹתוֹ הָרָע שֶׁשִּׁלְּמוּ לוֹ, אֶלָּא קַוֵּה אֶל ה' וְיֹשַׁע לָךְ.</p>\n<p>וְהַפָּסוּק הַזֶּה בֵּאֲרוּהוּ בְּיוֹסֵף הַצַּדִּיק שֶׁלֹּא רָצָה לְשַׁלֵּם רָע לְאֶחָיו בְּשָׁעָה שֶׁנָּפְלוּ בְיָדוֹ. קַוֵּה אֶל ה' וְיֹשַׁע לָךְ, מִשּׁוּם שֶׁהוּא הָיָה יָרֵא מִן הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב זֹאת עֲשׂוּ וִחְיוּ וְגוֹ'. (וגם) וְהוּא הָיָה תָמִיד מְצַפֶּה לַקָּדוֹשׁ- בָּרוּךְ-הוּא. (כמו שנאמר, קוה לה' וישע לך,)</p>\n<p>רַבִּי אַבָּא פָּתַח וְאָמַר, (משלי כ) מַיִם עֲמֻקִּים עֵצָה בְלֶב אִישׁ וְאִישׁ תְּבוּנָה יִדְלֶנָּה. מַיִם עֲמֻקִּים עֵצָה בְלֶב אִישׁ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם שֶׁהוּא עוֹשֶׂה עֵצוֹת, שֶׁמֵּבִיא טְעָמִים לְגַלְגֵּל גִּלְגּוּלִים עַל הָעוֹלָם עַל יְדֵי יוֹסֵף לְקַיֵּם אֶת אוֹתָהּ הַגְּזֵרָה שֶׁגָּזַר רָעָב עַל הָאָרֶץ (העולם). וְאִישׁ תְּבוּנָה יִדְלֶנָּה - זֶה יוֹסֵף שֶׁגִּלָּה אוֹתָם עֳמָקִים שֶׁגָּזַר הַקָּדוֹשׁ בָּרוּךְ הוּא עַל הָעוֹלָם.</p>\n<p>בֹּא רְאֵה, לֹא דַי לְיוֹסֵף שֶׁהוּא לֹא שִׁלֵּם רָע לְאֶחָיו, אֶלָּא שֶׁעָשָׂה עִמָּהֶם חֶסֶד וֶאֱמֶת, וְכָךְ דַּרְכֵי הַצַּדִּיקִים תָּמִיד. מִשּׁוּם זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא חָס עֲלֵיהֶם תָּמִיד, בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>מַיִם עֲמֻקִּים עֵצָה בְלֶב אִישׁ - זֶה יְהוּדָה, וְהִנֵּה פֵּרְשׁוּהָ, בְּשָׁעָה שֶׁהִתְקָרֵב לְיוֹסֵף עַל הָעֵסֶק שֶׁל בִּנְיָמִין. וְאִישׁ תְּבוּנָה יִדְלֶנָּה - זֶה יוֹסֵף.</p>\n<p>רַבִּי אַבָּא הָיָה יוֹשֵׁב עַל שַׁעַר הַכְּנִיסָה שֶׁל לוֹד. רָאָה אִישׁ אֶחָד שֶׁהָיָה בָּא, וְיָשַׁב עַל בְּלִיטָה בְּצַד הָהָר, וְהָיָה עָיֵף מִן הַדֶּרֶךְ, וְיָשַׁב וְיָשַׁן שָׁם. בֵּינְתַיִם רָאָה נָחָשׁ אֶחָד שֶׁהָיָה בָּא אֵלָיו. יָצָא קוֹסְטְפָא דְגוֹרְדְּנָא (מין שרץ) וְהָרַג אֶת הַנָּחָשׁ. כְּשֶׁהִתְעוֹרֵר אוֹתוֹ הָאִישׁ, רָאָה אֶת אוֹתוֹ הַנָּחָשׁ כְּנֶגְדּוֹ שֶׁהָיָה מֵת. הִזְדַּקֵּף אוֹתוֹ הָאִישׁ, וְנָפְלָה אוֹתָהּ הַבְּלִיטָה לָעֹמֶק שֶׁתַּחְתֶּיהָ וְנִצּוֹל.</p>\n<p>בָּא אֵלָיו רַבִּי אַבָּא, אָמַר לוֹ, אֱמֹר לִי מַה מַּעֲשֶׂיךְ, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הִרְחִישׁ לְךְ שְׁנֵי הַנִּסִּים הַלָּלוּ שֶׁאֵינָם לְחִנָּם?</p>\n<p>אָמַר לוֹ אוֹתוֹ הָאִישׁ, כָּל יָמַי לֹא שִׁלֵּם לִי אִישׁ רָע בָּעוֹלָם שֶׁלֹּא הִתְפַּיַּסְתִּי עִמּוֹ וּמָחַלְתִּי לוֹ. וְעוֹד, אִם לֹא יָכֹלְתִּי לְהִתְפַּיֵּס עִמּוֹ, לֹא עָלִיתִי עַל מִטָּתִי עַד שֶׁמָּחַלְתִּי לוֹ וּלְכָל אוֹתָם שֶׁצִּעֲרוּ אוֹתִי, וְלֹא חָשַׁשְׁתִּי כָּל הַיּוֹם לְאוֹתוֹ הָרָע שֶׁשִּׁלֵּם לִי, וְלֹא דַי לִי זֶה, אֶלָּא שֶׁמֵּאוֹתוֹ הַיּוֹם וָהָלְאָה הִשְׁתַּדַּלְתִּי לַעֲשׂוֹת עִמָּהֶם טוֹב.</p>\n<p>בָּכָה רַבִּי אַבָּא וְאָמַר, מַעֲשָׂיו שֶׁל זֶה הֵם יוֹתֵר מִיּוֹסֵף, שֶׁיּוֹסֵף הָיוּ אֶחָיו וַדַּאי, וְהָיָה לוֹ לְרַחֵם עֲלֵיהֶם, אֲבָל מַה שֶּׁזֶּה עָשָׂה - יוֹתֵר מִיּוֹסֵף, נָאֶה הוּא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יַרְחִישׁ לוֹ נֵס עַל נֵס.</p>\n<p>פָּתַח וְאָמַר, (שם י) הוֹלֵךְ בַּתֹּם יֵלֶךְ בֶּטַח וּמְעַקֵּשׁ דְּרָכָיו יִוָּדֵעַ. הוֹלֵךְ בַּתֹּם יֵלֶךְ בֶּטַח - זֶה הָאָדָם הַהוּא שֶׁהוֹלֵךְ בְּדַרְכֵי הַתּוֹרָה, יֵלֶךְ בֶּטַח - שֶׁלֹּא יְכוֹלִים נִזְקֵי הָעוֹלָם לְהָרַע לוֹ. וּמְעַקֵּשׁ דְּרָכָיו יִוָּדֵעַ - מִי יִוָּדֵעַ? זֶה הוּא מִי שֶׁסּוֹטֶה מִדֶּרֶךְ הָאֱמֶת וְרוֹצֶה לִגְבּוֹת מֵחֲבֵרוֹ, יִוָּדֵעַ. מַה זֶּה יִוָּדֵעַ? הוּא יֵכּר בְּעֵינֵי כָּל בַּעֲלֵי הַדִּין שֶׁלֹּא יֹאבַד מֵהֶם הַדְּמוּת שֶׁל אוֹתוֹ הָאָדָם, כְּדֵי לְהָבִיא אוֹתוֹ לְמָקוֹם שֶׁיִּנְקְמוּ מִמֶּנּוּ, וּמִשּׁוּם כָּךְ יִוָּדֵעַ.</p>\n<p>וּבֹא וּרְאֵה, אוֹתוֹ שֶׁהוֹלֵךְ בְּדֶרֶךְ אֱמֶת, הַקָּדוֹשׁ בָּרוּךְ הוּא מְכַסֶּה עָלָיו כְּדֵי שֶׁלֹּא יִוָּדַע וְלֹא יֵכַּר לְבַעֲלֵי הַדִּין, אֲבָל מְעַקֵּשׁ דְּרָכָיו יִוָּדֵעַ וְיֵכַּר לָהֶם. אַשְׁרֵי אוֹתָם בְּנֵי הָאָדָם שֶׁהוֹלְכִים בְּדֶרֶךְ אֱמֶת וְהוֹלְכִים לָבֶטַח עַל הָעוֹלָם, שֶׁהֵם אֵינָם פּוֹחֲדִים בָּעוֹלָם הַזֶּה וְלֹא בָּעוֹלָם הַבָּא.</p>"],[9522011407,"<p>וַיִּירְאוּ הָאֲנָשִׁים כִּי הוּבְאוּ בֵּית יוֹסֵף. רַבִּי יוֹסֵי אָמַר, אוֹי לָהֶם לִבְנֵי הָאָדָם שֶׁאֵין יוֹדְעִים וְאֵין מִסְתַּכְּלִים בְּדַרְכֵי הַתּוֹרָה. אוֹי לָהֶם בְּשָׁעָה שֶׁיָּבֹא הַקָּדוֹשׁ בָּרוּךְ הוּא לִתְבֹּעַ אוֹתָם עַל דִּין מַעֲשֵׂיהֶם, וְיָקוּם הַגּוּף וְהַנֶּפֶשׁ לָתֵת חֶשְׁבּוֹן עַל כָּל מַעֲשֵׂיהֶם בְּטֶרֶם יִפָּרְדוּ הַנֶּפֶשׁ מִן הַגּוּף.</p>\n<p>וְאוֹתוֹ הַיּוֹם הוּא יוֹם הַדִּין, הַיּוֹם שֶׁסְּפָרִים פְּתוּחִים וּבַעֲלֵי הַדִּין עוֹמְדִים, מִשּׁוּם שֶׁבְּאוֹתוֹ הַזְּמַן עוֹמֵד הַנָּחָשׁ בְּקִיּוּמוֹ לִנְשֹׁךְ אוֹתוֹ, וְכָל הָאֵיבָרִים מִתְרַגְּשִׁים אֶצְלוֹ, וְהַנְּשָׁמָה נִפְרֶדֶת מִן הַגּוּף וְהוֹלֶכֶת וּמְשׁוֹטֶטֶת, וְאֵין יוֹדַעַת לְאֵיזוֹ דֶרֶךְ תֵּלֵךְ וּלְאֵיזֶה מָקוֹם מַעֲלִים אוֹתָהּ.</p>\n<p>אוֹי לְאוֹתוֹ הַיּוֹם! הַיּוֹם שֶׁל רֹגֶז וּנְאָצָה אוֹתוֹ הַיּוֹם. מִשּׁוּם כָּךְ צָרִיךְ לָאָדָם לְהַרְגִּיז אֶת יִצְרוֹ כָּל יוֹם, לְהַזְכִּיר לְפָנָיו אוֹתוֹ יוֹם שֶׁיַּעֲמֹד בְּדִין הַמֶּלֶךְ, שֶׁמַּכְנִיסִים אוֹתוֹ תַּחַת הָאָרֶץ לְהֵרָקֵב, וְהַנְּשָׁמָה נִפְרֶדֶת מִמֶּנּוּ.</p>\n<p>וְשָׁנִינוּ, לְעוֹלָם יַרְגִּיז אָדָם יֵצֶר טוֹב עַל יֵצֶר הָרָע וְיִשְׁתַּדֵּל אַחֲרָיו. אִם הוֹלֵךְ מִמֶּנּוּ - יָפֶה, וְאִם לָאו - יִשְׁתַּדֵּל בַּתּוֹרָה, שֶׁהִנֵּה אֵין לְךְ דָּבָר לִשְׁבֹּר אֶת הַיֵּצֶר הָרָע אֶלָּא הַתּוֹרָה. אִם הוֹלֵךְ - מוּטָב, וְאִם לֹא - יַזְכִּיר לוֹ אֶת יוֹם הַמָּוֶת, כְּדֵי לִשְׁבֹּר אוֹתוֹ.</p>\n<p>כָּאן יֵשׁ לְהִסְתַּכֵּל, שֶׁהֲרֵי זֶה הוּא יֵצֶר הָרָע, וְזֶה הוּא מַלְאַךְ הַמָּוֶת, וְכִי מַלְאַךְ הַמָּוֶת נִשְׁבָּר לִפְנֵי יוֹם הַמָּוֶת, וַהֲרֵי הוּא הַהֶרֶג שֶׁל בְּנֵי הָאָדָם, וְנִשְׁמָע שֶׁזּוֹ שִׂמְחָה שֶׁלּוֹ, וּמִשּׁוּם כָּךְ מַסְטֶה אֶת בְּנֵי הָאָדָם תָּמִיד כְּדֵי לְהַמְשִׁיכָם לָזֶה?</p>\n<p>אֶלָּא וַדַּאי מַה שֶּׁנִּתְבָּאֵר שֶׁיִּזְכֹּר לוֹ אָדָם אוֹתוֹ יוֹם הַמָּוֶת - וַדַּאי כֵּן זֶה, כְּדֵי לִשְׁבֹּר אֶת לֵב הָאָדָם, שֶׁהֲרֵי אֵין יֵצֶר הָרָע שׁוֹרֶה אֶלָּא בְּמָקוֹם שֶׁנִּמְצֵאת שִׂמְחַת הַיַּיִן וְגַסּוּת הָרוּחַ, וּכְשֶׁנִּמְצֵאת רוּחַ שְׁבוּרָה, אָז נִפְרָד מִמֶּנּוּ וְאֵין שׁוֹרֶה עִמּוֹ, וּמִשּׁוּם כָּךְ צָרִיךְ לְהַזְכִּירוֹ אֶת יוֹם הַמָּוֶת, וְיִשָּׁבֵר גּוּפוֹ, וְהוּא הוֹלֵךְ לוֹ.</p>\n<p>בֹּא רְאֵה, יֵצֶר טוֹב צָרִיךְ שִׂמְחָה שֶׁל תּוֹרָה, וְיֵצֶר הָרָע שִׂמְחָה שֶׁל יַיִן וְנִאוּפִים וְגַסּוּת רוּחַ, וּמִשּׁוּם כָּךְ צָרִיךְ אָדָם לִרְגֹּז תָּמִיד מֵאוֹתוֹ הַיּוֹם הַגָּדוֹל, יוֹם הַדִּין, יוֹם הַחֶשְׁבּוֹן, שֶׁאֵין לוֹ לָאָדָם לְהָגֵן עָלָיו אֶלָּא מַעֲשָׂיו הַכְּשֵׁרִים שֶׁהוּא עוֹשֶׂה בָּעוֹלָם הַזֶּה כְּדֵי שֶׁיָּגֵנּוּ עָלָיו בְּאוֹתָהּ הַשָּׁעָה.</p>\n<p>בֹּא רְאֵה, וַיִּירְאוּ הָאֲנָשִׁים כִּי הוּבְאוּ בֵּית יוֹסֵף. וּמַה כֻּלָּם הָיוּ גִבּוֹרִים, כֻּלָּם חֲזָקִים, וְעֶלֶם אֶחָד שֶׁהֵבִיא אוֹתָם לְבֵית יוֹסֵף פָּחֲדוּ - כְּשֶׁיָּבֹא הַקָּדוֹשׁ בָּרוּךְ הוּא לִתְבֹּעַ אוֹתוֹ לְדִין אֶת הָאָדָם עַל אַחַת כַּמָּה וְכמָּה.</p>\n<p>מִשּׁוּם כָּךְ צָרִיךְ לָאָדָם לְהִזָּהֵר בָּעוֹלָם הַזֶּה לְהִתְחַזֵּק בַּקָּדוֹשׁ- בָּרוּךְ-הוּא, וְיָשִׂים בּוֹ אֶת בִּטְחוֹנוֹ. שֶׁאַף עַל גַּב שֶׁהוּא חוֹטֵא, אִם יַחֲזר מִמֶּנּוּ בִּתְשׁוּבָה שְׁלֵמָה, הֲרֵי הוּא תַּקִּיף חָזָק, וְיִתְחַזֵּק בּוֹ בַּקָּדוֹשׁ-בָּרוּךְ-הוּא כְּאִלּוּ לֹא חָטָא.</p>\n<p>שֶׁהֲרֵי הַשְּׁבָטִים, מִשּׁוּם שֶׁחָטְאוּ עַל גְּנֵבַת יוֹסֵף הָיוּ פוֹחֲדִים, שֶׁאִלְמָלֵא לֹא חָטְאוּ לֹא הָיוּ פוֹחֲדִים כְּלָל, מִשּׁוּם שֶׁחֲטָאֵי הָאָדָם מְשַׁבְּרִים אֶת לִבּוֹ, וְאֵין לוֹ כְּלָל כֹּחַ. מָה הַטַּעַם? שֶׁהֲרֵי אוֹתוֹ יֵצֶר הַטּוֹב נִשְׁבָּר עִמּוֹ, וְאֵין לוֹ כֹּחַ לְהִתְחַזֵּק עַל אוֹתוֹ יֵצֶר הָרָע, וְעַל זֶה כָּתוּב (דברים כ) מִי הָאִישׁ הַיָּרֵא וְרַךְ הַלֵּבָב, הַיָּרֵא (שיראה זו) מִן הַחֲטָאִים שֶׁבְּיָדוֹ, שֶׁהֵם שֶׁבֶר הַלֵּב שֶׁל הָאָדָם.</p>\n<p>וּבֹא רְאֵה לְכַמָּה דוֹרוֹת נִפְרָע הַקָּדוֹשׁ בָּרוּךְ הוּא מֵאוֹתָם חֲטָאֵי הַשְּׁבָטִים, שֶׁהֲרֵי אֵין נֶאֱבָד מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּלוּם, וְנִפְרָע מִדּוֹר לְדוֹר, וְהַדִּין תָּמִיד עוֹמֵד לְפָנָיו עַד שֶׁנִּפְרָע, וְשׁוֹרֶה הַדִּין בְּמָקוֹם שֶׁצָּרִיךְ.</p>\n<p>מִנַּיִן לָנוּ? מֵחִזְקִיָּהוּ. חִזְקִיָּהוּ חָטָא אֶת אוֹתוֹ הַחֵטְא, שֶׁגִּלָּה אֶת נִסְתְּרוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁאָר הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, שֶׁלֹּא הָיָה צָרִיךְ לְגַלּוֹת, וְהַקָּדוֹשׁ בָּרוּךְ הוּא שָׁלַח אֶת יְשַׁעְיָהוּ וְאָמַר לוֹ, (ישעיה לט) הִנֵּה יָמִים בָּאִים וְנִשָּׂא כָּל אֲשֶׁר בְּבֵיתֶךְ וַאֲשֶׁר אָצְרוּ אֲבֹתֶיךְ עַד הַיּוֹם הַזֶּה וְגוֹ'</p>\n<p>בֹּא רְאֵה כַּמָּה גָרַם אוֹתוֹ הַחֵטְא מִשּׁוּם שֶׁגִּלָּה מַה שֶּׁהָיָה נִסְתָּר, שֶׁכֵּיוָן שֶׁהִתְגַּלָּה, נִתַּן הַמָּקוֹם לְמָקוֹם אַחֵר שֶׁלֹּא צָרִיךְ לִשְׁלֹט עָלָיו. מִשּׁוּם כָּךְ אֵין בְּרָכָה שׁוֹרָה אֶלָּא בְּמָקוֹם נִסְתָּר. וּבֵאֲרוּהָ, מַה שֶּׁהוּא (היה) נִסְתָּר, הַבְּרָכָה (שהיתה) שׁוֹרָה עָלָיו. כֵּיוָן שֶׁנִּתְגַּלָּה, נִתַּן מָקוֹם לְמָקוֹם אַחֵר לִשְׁלֹט עָלָיו.</p>\n<p>כָּתוּב (איכה א) כָּל מְכַבְּדֶיהָ הִזִּילוּהָ כִּי רָאוּ עֶרְוָתָהּ, וּבֵאֲרוּהָ. אֲבָל כָּל מְכַבְּדֶיהָ הִזִּילוּהָ - זוֹ מַלְכוּת בָּבֶל, שֶׁהֲרֵי מִשָּׁם נִשְׁלַח דּוֹרוֹן לִירוּשָׁלַיִם, שֶׁכָּתוּב (ישעיה לט) בָּעֵת הַהִיא שָׁלַח מְרֹאדַךְ בַּלְאֲדָן בֶּן בַּלְאֲדָן מֶלֶךְ בָּבֶל סְפָרִים וּמִנְחָה אֶל חִזְקִיָּהוּ.</p>\n<p>וּמַה כָּתוּב בָּהֶם? שָׁלוֹם לְחִזְקִיָּהוּ מֶלֶךְ יְהוּדָה וְשָׁלוֹם לָאֱלֹהִים הַגָּדוֹל וְשָׁלוֹם לִירוּשָׁלַיִם. כֵּיוָן שֶׁיָּצָא הַפֶּתֶק שֶׁלּוֹ מִמֶּנּוּ, הֶחֱזִיר עַל לִבּוֹ וְאָמַר: לֹא נָאֶה שֶׁעָשִׂיתִי שֶׁהִקְדַּמְתִּי אֶת שְׁלוֹם הָעֶבֶד לִשְׁלוֹם רַבּוֹ. קָם מִכִּסְאוֹ וּפָסַע שָׁלֹשׁ פְּסִיעוֹת, וְהֶחֱזִיר אֶת הַפֶּתֶק שֶׁלּוֹ, וְכָתַב אֲחֵרִים תַּחְתֵּיהֶם. וְכָךְ כָּתַב: שָׁלוֹם לָאֱלוֹהַּ הַגָּדוֹל, שָׁלוֹם לִירוּשָׁלַיִם, וְשָׁלוֹם לְחִזְקִיָּה. וְזֶהוּ מְכַבְּדֶיהָ.</p>\n<p>וְאַחַר כָּךְ הִזִּילוּהָ. מָה הַטַּעַם הִזִּילוּהָ? מִשּׁוּם כִּי רָאוּ עֶרְוָתָהּ, שֶׁהֶרְאָה לָהֶם חִזְקִיָּה, שֶׁאִלְמָלֵא כָּךְ לֹא הִזִּילוּהָ אַחַר כָּךְ. מִתּוֹךְ שֶׁחִזְקִיָּהוּ הָיָה יוֹתֵר צַדִּיק, הִתְעַכֵּב הַדָּבָר מִלָּבא, וְלֹא בָא בְּיָמָיו, שֶׁכָּתוּב (ישעיה לט) כִּי יִהְיֶה שָׁלוֹם וֶאֱמֶת בְּיָמָי. וְאַחַר כָּךְ פָּקַד אֶת אוֹתוֹ הַחֵטְא עַל בָּנָיו אַחֲרָיו.</p>\n<p>כְּמוֹ כֵן אוֹתוֹ הַחֵטְא שֶׁל הַשְּׁבָטִים עָמַד עַד לְאַחַר מִכֵּן, מִשּׁוּם שֶׁהַדִּין שֶׁלְּמַעְלָה לֹא יָכֹל לִשְׁלֹט עֲלֵיהֶם, עַד שֶׁנִּמְצְאָה הַשָּׁעָה לְהִפָּרַע וְנִפְרַע מֵהֶם. וּמִשּׁוּם כָּךְ, כָּל מִי שֶׁיֵּשׁ בְּיָדוֹ חֲטָאִים, תָּמִיד פּוֹחֵד, כְּמוֹ שֶׁנֶּאֱמַר (דברים כח) וּפָחַדְתָּ לַיְלָה וְיוֹמָם וְגוֹ'. וְעַל כֵּן וַיִּירְאוּ הָאֲנָשִׁים כִּי הוּבְאוּ וְגוֹ'.</p>"],[9522011408,"<p>וַיִּשָּׂא עֵינָיו וַיַּרְא אֶת בִּנְיָמִין אָחִיו בֶּן אִמּוֹ וְגוֹ'. רַבִּי חִיָּיא פָּתַח וְאָמַר, (משלי יג) תּוֹחֶלֶת מְמֻשָּׁכָה מַחֲלָה לֵב וְעֵץ חַיִּים תַּאֲוָה בָאָה. זֶה הוּא שֶׁשָּׁנִינוּ, שֶׁאֵין לָאָדָם לְהִתְבּוֹנֵן בְּבַקָּשָׁתוֹ אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא אִם בָּאָה וְאִם לֹא בָאָה. מָה הַטַּעַם? מִשּׁוּם שֶׁאִם הוּא מִתְבּוֹנֵן בָּהּ, כַּמָּה בַּעֲלֵי הַדִּין בָּאִים לְהִתְבּוֹנֵן בְּמַעֲשָׂיו.</p>\n<p>וְסוֹד הוּא, שֶׁהֲרֵי אוֹתָהּ הַהִתְבּוֹנְנוּת שֶׁהוּא מִתְבּוֹנֵן בְּאוֹתָהּ הַבַּקָּשָׁה, גּוֹרֶמֶת לוֹ לְמַחֲלַת לֵב. מַה זֶּה מַחֲלַת לֵב? זֶהוּ מִי שֶׁעוֹמֵד תָּמִיד עַל הָאָדָם לְהַסְטִין לְמַעְלָה וּלְמַטָּה.</p>\n<p>וְעֵץ חַיִּים תַּאֲוָה בָאָה. שָׁנִינוּ, מִי שֶׁרוֹצֶה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יְקַבֵּל אֶת תְּפִלָּתוֹ, יִשְׁתַּדֵּל בַּתּוֹרָה, שֶׁהִיא עֵץ חַיִּים, וְאָז תַּאֲוָה בָאָה. מִי הַתַּאֲוָה? זוֹ הַדַּרְגָּה שֶׁכָּל תְּפִלּוֹת הָעוֹלָם בְּיָדֶיהָ, וּמַכְנִיסָה אוֹתָם לִפְנֵי הַמֶּלֶךְ הָעֶלְיוֹן. כָּתוּב כָּאן בָּאָה, וְכָתוּב שָׁם (אסתר ב) בָּעֶרֶב הִיא בָאָה. וְזוֹ הִיא תַּאֲוָה בָאָה, בָּאָה לִפְנֵי הַמֶּלֶךְ הָעֶלְיוֹן לְהַשְׁלִים אֶת רְצוֹן אוֹתוֹ הָאִישׁ.</p>\n<p>דָּבָר אַחֵר תּוֹחֶלֶת מְמֻשָּׁכָה מַחֲלָה לֵב - זֶהוּ הַמָּקוֹם שֶׁנִּתָּן אוֹתוֹ הַדָּבָר בְּמָקוֹם אַחֵר שֶׁאֵינוֹ צָרִיךְ, וְנִמְשָׁךְ עַד שֶׁנִּתָּן מִיָּד לְיָד, וְלִפְעָמִים שֶׁלֹּא יָבֹא. מָה הַטַּעַם? מִשּׁוּם שֶׁמִּתְפַּשֵּׁט וְנִמְשָׁךְ עִם כָּל אוֹתָם הַמְמֻנִּים לְהוֹרִיד אוֹתוֹ לָעוֹלָם.</p>\n<p>וְעֵץ חַיִּים תַּאֲוָה בָאָה - זוֹ הִיא הַתּוֹחֶלֶת שֶׁלֹּא נִמְשֶׁכֶת, מִשּׁוּם אוֹתָם מְמֻנֵּי הַמֶּרְכָּבוֹת, אֶלָּא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן (להם) לוֹ מִיָּד, מִשּׁוּם שֶׁכַּאֲשֶׁר נִמְשֶׁכֶת בֵּין אוֹתָם מְמֻנֵּי הַמֶּרְכָּבוֹת, כַּמָּה הֵם בַּעֲלֵי הַדִּין שֶׁנִּתֶּנֶת לָהֶם רְשׁוּת לְעַיֵּן וּלְהִסְתַּכֵּל בְּדִינוֹ טֶרֶם יִתְּנוּ לוֹ, וּמַה שֶּׁיָּצָא מִבֵּית הַמֶּלֶךְ וְנִתַּן לוֹ לָאָדָם, בֵּין שֶׁזּוֹכֶה בֵּין שֶׁלֹּא זוֹכֶה - נִתָּן מִיָּד, וְזֶהוּ עֵץ חַיִּים תַּאֲוָה בָאָה.</p>\n<p>דָּבָר אַחֵר תּוֹחֶלֶת מְמֻשָּׁכָה - זֶה יַעֲקֹב, שֶׁנִּמְשְׁכָה לוֹ הַתּוֹחֶלֶת שֶׁל יוֹסֵף עַד לִזְמַן אָרֹךְ. וְעֵץ חַיִּים תַּאֲוָה בָאָה - זֶה הוּא בִּנְיָמִין, שֶׁהֲרֵי מִזְּמַן שֶׁבִּקֵּשׁ אוֹתוֹ יוֹסֵף עַד אוֹתוֹ זְמַן שֶׁהוּא בָּא אֵלָיו לֹא הָיָה אֶלָּא זְמַן מוּעָט, שֶׁאוֹתוֹ הַזְּמַן לֹא נִמְשַׁךְ. זֶהוּ שֶׁכָּתוּב וַיִּשָּׂא עֵינָיו וַיַּרְא אֶת בִּנְיָמִין אָחִיו בֶּן אִמּוֹ. מַה זֶּה בֶּן אִמּוֹ? שֶׁדְּמוּת אִמּוֹ הָיְתָה בּוֹ, וְהָיְתָה דוֹמָה דְמוּתוֹ לִדְמוּת רָחֵל, מִשּׁוּם כָּךְ כָּתוּב וַיִּשָּׂא עֵינָיו וַיַּרְא אֶת בִּנְיָמִין אָחִיו בֶּן אִמּוֹ.</p>\n<p>רַבִּי יוֹסֵי אָמַר, וַהֲרֵי כָּתַב בָּרִאשׁוֹנָה וַיַּרְא יוֹסֵף אִתָּם אֶת בִּנְיָמִין, וְכָאן כָּתוּב וַיִּשָּׂא עֵינָיו וַיַּרְא אֶת בִּנְיָמִין אָחִיו, אֵיזוֹ רְאִיָּה רָאָה? אֶלָּא רָאָה בְּרוּחַ הַקֹּדֶשׁ אֶת בִּנְיָמִין שֶׁחֶלְקוֹ הָיָה עִמָּהֶם בָּאָרֶץ, וּבְחֶלְקָם שֶׁל בִּנְיָמִין וִיהוּדָה תִּשְׁרֶה הַשְּׁכִינָה, שֶׁהֲרֵי רָאָה אֶת יְהוּדָה וְאֶת בִּנְיָמִין שֶׁבְּחֶלְקָם יִהְיֶה הַמִּקְדָּשׁ. וְזֶהוּ וַיַּרְא יוֹסֵף אִתָּם אֶת בִּנְיָמִין, רָאָה אוֹתוֹ עִמָּהֶם, וְאֶת יוֹסֵף שֶׁהָיָה אָחִיו לֹא רָאָה עִמָּהֶם בְּאוֹתוֹ הַחֵלֶק.</p>\n<p>אַף כָּאן, וַיִּשָּׂא עֵינָיו וַיַּרְא אֶת בִּנְיָמִין אָחִיו בֶּן אִמּוֹ. מַה כָּתוּב אַחֲרָיו? וַיְמַהֵר יוֹסֵף כִּי נִכְמְרוּ רַחֲמָיו אֶל אָחִיו וַיְבַקֵּשׁ לִבְכּוֹת וַיָּבֹא הַחַדְרָה וַיֵּבְךָּ שָׁמָּה.</p>\n<p>רַבִּי חִזְקִיָּה פָּתַח וְאָמַר, (ישעיה כב) מַשָּׂא גֵיא חִזָּיוֹן מַה לָּךְ אֵפוֹא כִּי עָלִית כֻּלָּךְ לַגַּגּוֹת. בּא רְאֵה, הֲרֵי פֵּרְשׁוּהָ, בִּזְמַן שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ וְהָיוּ שׂוֹרְפִים אוֹתוֹ בָאֵשׁ, עָלוּ כָּל אוֹתָם הַכֹּהֲנִים עַל כָּתְלֵי (גגות) הַמִּקְדָּשׁ, וְכָל הַמַּפְתְּחוֹת בִּידֵיהֶם, וְאָמְרוּ: עַד כָּאן הָיִינוּ גִזְבָּרִים שֶׁלְּךְ. מִכָּאן וְאֵילָךְ טֹל אֶת שֶׁלְּךְ.</p>\n<p>אֲבָל בֹּא רְאֵה, גֵּיא חִזָּיוֹן - זוֹ הַשְּׁכִינָה שֶׁהָיְתָה בַּמִּקְדָּשׁ, וְכָל בְּנֵי הָעוֹלָם מִמֶּנָּה הָיוּ יוֹנְקִים יְנִיקַת הַנְּבוּאָה. שֶׁאַף עַל גַּב שֶׁכָּל הַנְּבִיאִים הָיוּ מִתְנַבְּאִים מִמָּקוֹם אַחֵר - מִתּוֹכָהּ הָיוּ יוֹנְקִים אֶת נְבוּאָתָם, וְעַל כֵּן הִיא נִקְרֵאת גֵּיא חִזָּיוֹן. חִזָּיוֹן, הִנֵּה פֵּרְשׁוּהָ שֶׁהוּא הַמַּרְאֶה שֶׁל כָּל הַגְּוָנִים הָעֶלְיוֹנִים.</p>\n<p>מַה לָּךְ אֵפוֹא כִּי עָלִית כֻּלָּךְ לַגַּגּוֹת, שֶׁהֲרֵי כְּשֶׁנֶּחֱרַב הַמִּקְדָּשׁ, הַשְּׁכִינָה בָּאָה וְעָלְתָה לְכָל אוֹתָם הַמְּקוֹמוֹת שֶׁהָיָה בָהֶם מְדוֹרָהּ בָּרִאשׁוֹנָה, וְהָיְתָה בּוֹכָה עַל בֵּית מְדוֹרָהּ, וְעַל יִשְׂרָאֵל שֶׁהָלְכוּ לַגָּלוּת, וְעַל כָּל אוֹתָם הַחֲסִידִים וְהַצַּדִּיקִים שֶׁהָיוּ שָׁם וְנֶאֶבְדוּ. וּמִנַּיִן לָנוּ? שֶׁכָּתוּב (ירמיה לא) כֹּה אָמַר ה' קוֹל בְּרָמָה נִשְׁמָע נְהִי בְּכִי תַמְרוּרִים רָחֵל מְבַכָּה עַל בָּנֶיהָ, וַהֲרֵי נִתְבָּאֵר. וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹאֵל אֶת הַשְּׁכִינָה וְאוֹמֵר לָהּ: מַה לָּךְ אֵפוֹא כִּי עָלִית כֻּלָּךְ לַגַּגּוֹת.</p>\n<p>מַה זֶּה כֻּלָּךְ, שֶׁהֲרֵי כִּי עָלִית זֶה מַסְפִּיק. מַה זֶּה כֻּלָּךְ? לְהַכְלִיל עִמָּהּ כָּל הַצְּבָאוֹת וְהַמֶּרְכָּבוֹת הָאֲחֵרִים שֶׁכֻּלָּם בָּכוּ עִמָּהּ עַל חֻרְבַּן בֵּית הַמִּקְדָּשׁ.</p>\n<p>וּמִשּׁוּם כָּךְ מַה לָּךְ אֵפוֹא. אָמְרָה לְפָנָיו: וְכִי בָּנַי בַּגָּלוּת, וְהַמִּקְדָּשׁ נִשְׂרַף, וַאֲנִי מַה לִּי כָּאן? הִתְחִילָה וְאוֹמֶרֶת, (ישעיה כב) תְּשֻׁאוֹת מְלֵאָה עִיר הוֹמִיָּה קִרְיָה עַלִּיזָה חֲלָלַיִךְ לֹא חַלְלֵי חֶרֶב וְלֹא מֵתֵי מִלְחָמָה. עַל כֵּן אָמַרְתִּי שְׁעוּ מִנִּי אֲמָרֵר בַּבֶּכִי וְגוֹ'. וְהִנֵּה בֵּאַרְנוּ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לָהּ (ירמיה שם) כֹּה אָמַר ה' מִנְעִי קוֹלֵךְ מִבֶּכִי וְגוֹ'.</p>\n<p>וּבֹא וּרְאֵה, מִיּוֹם שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, לֹא הָיָה יוֹם שֶׁלֹּא נִמְצְאוּ בוֹ קְלָלוֹת, מִשּׁוּם שֶׁכַּאֲשֶׁר בֵּית הַמִּקְדָּשׁ הָיָה קַיָּם, הָיוּ יִשְׂרָאֵל עוֹבְדִים עֲבוֹדוֹת וּמַקְרִיבִים עוֹלוֹת וְקָרְבָּנוֹת, וְהַשְּׁכִינָה שׁוֹרָה בְּבֵית הַמִּקְדָּשׁ עֲלֵיהֶם כְּמוֹ אֵם שֶׁרוֹבֶצֶת עַל בָּנֶיהָ, וְהָיוּ כָּל הַפָּנִים מְאִירוֹת, עַד שֶׁנִּמְצְאוּ בְרָכוֹת לְמַעְלָה וּלְמַטָּה, וְלֹא הָיָה יוֹם שֶׁלֹּא נִמְצְאוּ בוֹ בְּרָכוֹת וּשְׂמָחוֹת, וְהָיוּ יִשְׂרָאֵל שְׁרוּיִים לָבֶטַח בָּאָרֶץ, וְכָל הָעוֹלָם הָיָה נִזּוֹן בִּגְלָלָם.</p>\n<p>עַכְשָׁו שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, וְהַשְּׁכִינָה עִמָּהֶם בַּגָּלוּת, אֵין לְךְ יוֹם שֶׁלֹּא נִמְצָאִים בּוֹ קְלָלוֹת, וְהָעוֹלָם מְקֵלָּל, וְאֵין נִמְצָאוֹת שְׂמָחוֹת לְמַעְלָה וּלְמַטָּה.</p>\n<p>וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָקִים אֶת כְּנֶסֶת יִשְׂרָאֵל מִן הֶעָפָר כְּמוֹ שֶׁנִּתְבָּאֵר, וּלְשַׂמֵּחַ אֶת הָעוֹלָם בַּכֹּל, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה נו) וַהֲבִיאוֹתִים אֶל הַר קָדְשִׁי וְשִׂמַּחְתִּים בְּבֵית תְּפִלָּתִי וְגוֹ', וְכָתוּב (ירמיה לא) בִּבְכִי יָבאוּ וּבְתַחֲנוּנִים אוֹבִילֵם. כְּמוֹ שֶׁבַּהַתְחָלָה, שֶׁכָּתוּב (איכה א) בָּכוֹ תִבְכֶּה בַּלַּיְלָה וְדִמְעָתָהּ עַל לֶחֱיָהּ, כָּךְ גַּם כֵּן לְאַחַר כָּךְ בִּבְכִי יַחְזְרוּ, שֶׁכָּתוּב בִּבְכִי יָבאוּ וְגוֹ'.</p>"],[9522011409,"<p>הַבֹּקֶר אוֹר וְהָאֲנָשִׁים שֻׁלְּחוּ הֵמָּה וַחֲמֹרֵיהֶם. רַבִּי אֶלְעָזָר אָמַר, כָּאן יֵשׁ לְהִתְבּוֹנֵן, אִם הֵם הָיוּ הוֹלְכִים וְנִשְׁלָחִים, לָמָּה לָנוּ לִכְתֹּב בַּתּוֹרָה הֵמָּה וַחֲמֹרֵיהֶם? אֶלָּא מִשּׁוּם שֶׁכָּתוּב וְלָקַחַת אֹתָנוּ לַעֲבָדִים וְאֶת חֲמֹרֵינוּ, מִשּׁוּם כָּךְ וְהָאֲנָשִׁים שֻׁלְּחוּ הֵמָּה וַחֲמֹרֵיהֶם, כְּדֵי שֶׁלֹּא יִשָּׁאֲרוּ הֵם וַחֲמוֹרֵיהֶם כְּמוֹ שֶׁאָמְרוּ.</p>\n<p>פָּתַח וְאָמַר, (בראשית כב) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר וַיַּחֲבֹשׁ אֶת חֲמוֹרוֹ וְגוֹ'. אוֹתוֹ הַבֹּקֶר שֶׁל אַבְרָהָם הָיָה מֵאִיר לַעֲמֹד עֲלֵיהֶם בִּזְכוּתוֹ, אָז זְכוּתוֹ שֶׁל אַבְרָהָם עָמְדָה עֲלֵיהֶם וְהָלְכוּ בְשָׁלוֹם וְנִצְּלוּ מִן הַדִּין, מִשּׁוּם שֶׁאוֹתָהּ הַשָּׁעָה עָמַד עֲלֵיהֶם הַדִּין לְהִפָּרַע מֵהֶם, רַק שֶׁזְּכוּת אוֹתוֹ הַבֹּקֶר שֶׁל אַבְרָהָם הֵגֵנָּה עֲלֵיהֶם וְנִשְׁלְחוּ מִן הַדִּין, שֶׁלֹּא שָׁלַט עֲלֵיהֶם בְּאוֹתוֹ זְמַן.</p>\n<p>רַבִּי יְהוּדָה פָּתַח וְאָמַר, (שמואל ב כג) וכאור בקר יזרח שמש - זהו האור של אותו בקר של אברהם. יזרח שמש - זה הוא השמש של יעקב, שכתוב (בראשית לב) ויזרח לו השמש. בקר לֹא עָבוֹת - שֶׁאוֹתוֹ בּקֶר הוּא לֹא כָּל כָּךְ עָבוֹת, אֶלָּא מִנֹּגַהּ מִמָּטָר. נֹגַהּ מִמָּטָר - הוּא הַמָּטָר שֶׁבָּא מִצַּד יִצְחָק, שֶׁאוֹתוֹ מָטָר מוֹצִיא דֶשֶׁא מִן הָאָרֶץ.</p>\n<p>דָּבָר אַחֵר וּכְאוֹר בֹּקֶר - בְּאוֹתוֹ אוֹר הַבֹּקֶר שֶׁל אַבְרָהָם יִזְרַח שָׁמֶשׁ, זֶה הוּא יַעֲקֹב, שֶׁאוֹרוֹ כְּאוֹתוֹ אוֹר שֶׁל הַבֹּקֶר. בֹּקֶר לֹא עָבוֹת - מִשּׁוּם שֶׁאוֹתוֹ בֹּקֶר אֵינוֹ חָשׁוּךְ, אֶלָּא מֵאִיר, שֶׁהֲרֵי בְּשָׁעָה שֶׁבָּא הַבּקֶר, הַדִּין לֹא שׁוֹלֵט כְּלָל, אֶלָּא הַכֹּל מֵאִיר בַּצַּד שֶׁל אַבְרָהָם. מִנֹּגַהּ מִמָּטָר - זֶהוּ הַצַּד שֶׁל יוֹסֵף הַצַּדִּיק, שֶׁהוּא מַמְטִיר עַל הָאָרֶץ לְהוֹצִיא דֶשֶׁא וְכָל טוּב הָעוֹלָם.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בֹּא רְאֵה, בְּשָׁעָה שֶׁנִּכְנָס הַלַּיְלָה וּפוֹרֵשׂ כְּנָפָיו עַל הָעוֹלָם, כַּמָּה שׁוֹמְרִים מַזִּיקִים מְזֻמָּנִים לָצֵאת וְלִשְׁלֹט בָּעוֹלָם, וְכַמָּה בַּעֲלֵי הַדִּינִים מִתְעוֹרְרִים בְּכַמָּה צְדָדִים לְמִינָם, וְשׁוֹלְטִים עַל הָעוֹלָם. כֵּיוָן שֶׁמַּגִּיעַ הַבּקֶר וּמֵאִיר, כֻּלָּם מִסְתַּלְּקִים וְלֹא שׁוֹלְטִים, וְכָל אֶחָד וְאֶחָד נִכְנָס לִמְקוֹמוֹ וְשָׁב לִמְקוֹמוֹ.</p>\n<p>כְּמוֹ שֶׁנֶּאֱמַר הַבֹּקֶר אוֹר - זֶה בֹּקֶר שֶׁל אַבְרָהָם. וְהָאֲנָשִׁים שֻׁלְּחוּ - אֵלּוּ בַּעֲלֵי הַדִּין, שֶׁהָיוּ שׁוֹלְטִים בַּלַּיְלָה. הֵמָּה וַחֲמֹרֵיהֶם - (המה אותם בעלי הדינים שאמרנו, וחמריהם ) הֵם שׁוֹמְרֵי הַחֻקִּים שֶׁבָּאִים מִצַּד הַטֻּמְאָה, שֶׁאֵינָם קְדוֹשִׁים וְלֹא שׁוֹלְטִים וְלֹא נִרְאִים מִכְּשֶׁבָּא הַבֹּקֶר. וְהֵם מִצִּדָּם שֶׁל אוֹתָם הַחֲמוֹרִים, שׁוֹמְרֵי הַחֻקִּים שֶׁאָמְרוּ.</p>\n<p>שֶׁהֲרֵי אֵין לְךְ דְּרָגוֹת עֶלְיוֹנוֹת שֶׁאֵין (יש) בָּהֶם יָמִין וּשְׂמֹאל, רַחֲמִים וְדִין, דְּרָגוֹת עַל דְּרָגוֹת קְדוֹשׁוֹת מִצַּד הַקְּדֻשָּׁה, וּטְמֵאוֹת מִצַּד הַטֻּמְאָה, וְכֻלָּם דְּרָגוֹת עַל דְּרָגוֹת, אֵלּוּ עַל אֵלּוּ.</p>\n<p>וּבְכָל מָקוֹם שֶׁמִּתְעוֹרֵר הַבֹּקֶר שֶׁל אַבְרָהָם בָּעוֹלָם, כֻּלָּם עוֹבְרִים וְלֹא שׁוֹלְטִים, מִשּׁוּם שֶׁאֵין לָהֶם (קיום) לַעֲמֹד בְּצַד יָמִין, אֶלָּא בְּצַד שְׂמֹאל. וְהַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה יוֹמָם וָלַיִל לְהַנְהִיג כָּל אֶחָד וְאֶחָד לַצַּד שֶׁלּוֹ כָּרָאוּי לוֹ. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>רַבִּי חִיָּיא פָּתַח וְאָמַר, (מלאכי ג) וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְדָקָה וּמַרְפֵּא בִּכְנָפֶיהָ. בֹּא רְאֵה, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָאִיר לְיִשְׂרָאֵל אוֹתוֹ הַשֶּׁמֶשׁ שֶׁגָּנַז הַקָּדוֹשׁ בָּרוּךְ הוּא מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם (שגנז הקדוש ברוך הוא) מִלִּפְנֵי הָרְשָׁעִים שֶׁל הָעוֹלָם, כְּמוֹ שֶׁכָּתוּב (איוב לח) וְיִמָּנַע מֵרְשָׁעִים אוֹרָם.</p>\n<p>וְאֶת אוֹתוֹ הָאוֹר גָּנַז אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא. שֶׁכַּאֲשֶׁר יָצָא בָּרִאשׁוֹנָה, הָיָה מֵאִיר מִסּוֹף הָעוֹלָם וְעַד סוֹף הָעוֹלָם. כֵּיוָן שֶׁהִסְתַּכֵּל בְּדוֹר אֱנוֹשׁ וּבְדוֹר הַמַּבּוּל וּבְדוֹר הַפְּלַגָּה וּבְכָל אוֹתָם הָרְשָׁעִים, גָּנַז אֶת אוֹתוֹ הָאוֹר.</p>\n<p>כֵּיוָן שֶׁבָּא יַעֲקֹב וְנִדְבַּק בְּאוֹתוֹ הַמְמֻנֶּה הַגָּדוֹל שֶׁל עֵשָׂו וְהִכִּישׁ אוֹתוֹ בִּירֵכוֹ, וְהָיָה נָכֶה, אָז מַה כָּתוּב? וַיִּזְרַח לוֹ הַשֶּׁמֶשׁ. אֵיזֶה שֶׁמֶשׁ? אוֹתוֹ הַשֶּׁמֶשׁ שֶׁגָּנַז, מִשּׁוּם שֶׁיֵּשׁ בּוֹ רְפוּאָה לְרַפֵּא אוֹתוֹ מֵאַרְכֻּבָּתוֹ, וְאַחַר כָּךְ נִרְפָּא בַּשֶּׁמֶשׁ הַהוּא, שֶׁכָּתוּב (בראשית לג) וַיָּבֹא יַעֲקֹב שָׁלֵם, שָׁלֵם בְּגוּפוֹ, שֶׁנִּרְפָּא.</p>\n<p>וְעַל כֵּן עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְגַלּוֹת אֶת הַשֶּׁמֶשׁ הַהוּא וּלְהָאִיר אוֹתוֹ לְיִשְׂרָאֵל, שֶׁכָּתוּב וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְדָקָה. מַה זֶּה שֶׁמֶשׁ צְדָקָה? זֶה הַשֶּׁמֶשׁ שֶׁל יַעֲקֹב שֶׁנִּרְפָּא בּוֹ. וּמַרְפֵּא בִּכְנָפֶיהָ - שֶׁל אוֹתָהּ שֶׁמֶשׁ כֻּלָּם יִתְרַפְּאוּ. מִשּׁוּם שֶׁהִנֵּה בִּזְמַן שֶׁיִּשְׂרָאֵל יָקוּמוּ מִן הֶעָפָר, כַּמָּה חִגְרִים וְכַמָּה סוּמִים יִהְיוּ בָהֶם, וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא יָאִיר לָהֶם אוֹתָהּ הַשֶּׁמֶשׁ לְהֵרָפֵא בָּהּ, שֶׁכָּתוּב וּמַרְפֵּא בִּכְנָפֶיהָ.</p>\n<p>וְאָז יוּאַר אוֹתוֹ הַשֶּׁמֶשׁ מִסּוֹף הָעוֹלָם וְעַד סוֹף הָעוֹלָם, וּלְיִשְׂרָאֵל תִּהְיֶה רְפוּאָה, וְהָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת יִשָּׂרְפוּ בוֹ. אֲבָל לְיִשְׂרָאֵל מַה כָּתוּב? (ישעיה נח) אָז יִבָּקַע כַּשַּׁחַר אוֹרֶךְ וַאֲרֻכָתְךְ מְהֵרָה תִצְמָח וְהָלַךְ לְפָנֶיךְ צִדְקֶךְ כְּבוֹד ה' יַאַסְפֶךְ.</p>"],[9522011410,"<p>אָנוּ חוֹזְרִים לַדְּבָרִים הָרִאשׁוֹנִים. וּלְיוֹסֵף יֵלָּד שְׁנֵי בָנִים בְּטֶרֶם תָּבֹא שְׁנַת הָרָעָב וְגוֹ'. רַבִּי יִצְחָק פָּתַח, (מיכה ה) וְהָיָה שְׁאֵרִית יַעֲקֹב בַּגּוֹיִם בְּקֶרֶב עַמִּים רַבִּים כְּטַל מֵאֵת ה' כִּרְבִיבִים עֲלֵי עֵשֶׂב אֲשֶׁר לֹא יְקַוֶּה לְאִישׁ וְלֹא יְיַחֵל לִבְנֵי אָדָם. בֹּא רְאֵה, בְּכָל יוֹם וָיוֹם כְּשֶׁהָאוֹר עוֹלֶה, מִתְעוֹרֶרֶת צִפּוֹר אַחַת בָּעֵץ שֶׁל גַּן הָעֵדֶן, וְקוֹרֵאת שָׁלֹשׁ פְּעָמִים, וְהַשַּׁרְבִיט מִזְדַּקֵּף, וְהַכָּרוֹז קוֹרֵא בְחַיִל: לָכֶם אוֹמְרִים שָׂרֵי הַמֶּמְשָׁלָה, מִי מִכֶּם שֶׁרוֹאֶה וְלֹא רוֹאֶה, שֶׁעוֹמֵד בָּעוֹלָם וְלֹא יוֹדְעִים עַל מָה קַיָּמִים, וְלֹא מַשְׁגִּיחִים בִּכְבוֹד רִבּוֹנָם, הַתּוֹרָה עוֹמֶדֶת לִפְנֵיהֶם וְלֹא מִשְׁתַּדְּלִים בָּהּ - טוֹב לָהֶם שֶׁלֹּא נִבְרְאוּ, עַל מָה יָקוּמוּ בְּלִי שֵׂכֶל. אוֹי לָהֶם כְּשֶׁיִּתְעוֹרְרוּ יְמֵי רָע וְיִטְרְדוּ אוֹתָם מִן הָעוֹלָם.</p>\n<p>מִי הֵם הַיָּמִים שֶׁל רָע? אִם תַּעֲלֶה עַל דַּעְתְּךְ שֶׁהֵם יְמֵי הַזִּקְנָה - לֹא כָּךְ, שֶׁהֲרֵי יְמֵי הַזִּקְנָה, אִם זָכָה בְּבָנִים וּבְנֵי בָנִים - הֵם יְמֵי טוֹב. מִי הֵם יְמֵי רָע?</p>\n<p>אֶלָּא הֵם כְּמוֹ שֶׁנֶּאֱמַר, שֶׁכָּתוּב (קהלת יב) וּזְכֹר אֶת בּוֹרְאֶיךְ בִּימֵי בְּחוּרֹתֶיךְ עַד אֲשֶׁר לֹא יָבאוּ יְמֵי הָרָעָה. אֵינָם יְמֵי הַזִּקְנָה. אֶלָּא סוֹד הַדָּבָר- כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, בָּרָא אוֹתוֹ בְּאוֹתִיּוֹת הַתּוֹרָה, וְכָל אוֹת וְאוֹת נִכְנְסָה לְפָנָיו, עַד שֶׁהִתְקַיְּמוּ כָּל אוֹתִיּוֹת בָּאוֹת בֵּי\"ת. וְכָל אוֹתָן אַלְפָא בֵּיתוֹת שֶׁהִתְגַּלְגְּלוּ הָאוֹתִיּוֹת, כֻּלָּן עוֹמְדוֹת (כלן) לִבְרֹא הָעוֹלָם.</p>\n<p>כֵּיוָן שֶׁהִתְגַּלְגְּלוּ וְהִתְחַבְּרוּ שְׁתֵּי אוֹתִיּוֹת הַלָּלוּ ט\"ר יַחַד, עָלְתָה טֵי\"ת, וְלֹא הִתְיַשְּׁבָה, עַד שֶׁגָּעַר בָּהּ הַקָּדוֹשׁ בָּרוּךְ הוּא וְאָמַר לָהּ: טֵי\"ת טֵי\"ת, עַל מָה אַתְּ עוֹלָה וְאֵינֵךְ מִתְיַשֶּׁבֶת בִּמְקוֹמֵךְ? אָמְרָה לְפָנָיו: וְכִי עָשִׂיתָ אוֹתִי לִהְיוֹת אוֹת בְּרֹאשׁ שֶׁל טוֹב, שֶׁהֲרֵי הַתּוֹרָה פָּתְחָה בִּי כִּי טוֹב, אֵיךְ אֲנִי מִתְחַבֶּרֶת לְהִתְיַשֵּׁב עִם אוֹת רָע?</p>\n<p>אָמַר לָהּ: שׁוּבִי לִמְקוֹמֵךְ, שֶׁהֲרֵי אַתְּ צְרִיכָה אוֹתָהּ, שֶׁהֲרֵי הָאָדָם שֶׁאֲנִי רוֹצֶה לִבְרֹא בָכֶם, שְׁתֵּיכֶן נִכְלָלִים יַחַד וְיִבָּרֵא, אֲבָל אַתְּ לְיָמִין, וְהוּא לִשְׂמֹאל. וְאָז שָׁבוּ וְהִתְיַשְּׁבוּ זוֹ עִם זוֹ יַחַד.</p>\n<p>בְּאוֹתָהּ שָׁעָה הִפְרִיד אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא, וּבָרָא אוֹתָן אֶת כָּל אַחַת וְאַחַת יָמִים וְשָׁנִים יְדוּעוֹת, אֵלוּ לְיָמִין וְאֵלּוּ לִשְׂמֹאל. אֵלּוּ שֶׁל הַיָּמִין נִקְרָאִים יְמֵי הַטּוֹב, וְאֵלּוּ שֶׁל הַשְּׂמֹאל נִקְרָאִים יְמֵי הָרָעָה. וְעַל כֵּן אָמַר שְׁלֹמֹה, עַד אֲשֶׁר לֹא יָבֹאוּ יְמֵי הָרָעָה, שֶׁאֵלּוּ סוֹבְבִים אֶת הָאָדָם בַּחֲטָאָיו שֶׁהוּא עָשָׂה. כֵּיוָן שֶׁנִּבְרְאוּ יָמִים שֶׁל טוֹב וְיָמִים שֶׁל רָע, אֲזַי שָׁבוּ וְהִתְיַשְּׁבוּ לְהִכָּלֵל בָּאָדָם.</p>\n<p>וּמִשּׁוּם כָּךְ אָמַר דָּוִד, (תהלים מט) לָמָּה אִירָא בִּימֵי רָע עֲון עֲקֵבַי יְסוּבֵּנִי. יְמֵי רָע וַדַּאי, וְזֶה הַסּוֹד. אֵלּוּ נִקְרָאִים יְמֵי רָעָב, שְׁנוֹת הָרָעָב, וְאֵלּוּ נִקְרָאִים יְמֵי הַשָּׂבָע, שְׁנוֹת הַשָּׂבָע.</p>\n<p>וְסוֹד הַדָּבָר - שֶׁלֹּא לְהוֹצִיא אֶת מַעְיַן הַבְּרִית הַקָּדוֹשׁ בִּימֵי הָרָעָב, בִּשְׁנַת הָרָעָב. וּמִשּׁוּם כָּךְ יוֹסֵף, שֶׁהוּא סוֹד הַבְּרִית, סָתַם אֶת מַעְיָנוֹ בִּשְׁנַת הָרָעָב וְלֹא נָתַן לוֹ מָקוֹם לִרְבּוֹת בָּעוֹלָם. וְזֶה צָרִיךְ לָאָדָם, שֶׁכַּאֲשֶׁר שׁוֹלֶטֶת שְׁנַת הָרָעָב, שֶׁיִּסְתֹּם אֶת מַעְיַן הַבְּרִית קֹדֶשׁ שֶׁלּוֹ כְּדֵי שֶׁלֹּא יִתֵּן לוֹ מָקוֹם לִרְבּוֹת בָּעוֹלָם.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, סוֹד זֶה הוּא סוֹד עֶלְיוֹן. בִּשְׁנַת הָרָעָב הַהִיא, כֵּיוָן שֶׁהִיא שׁוֹלֶטֶת, צָרִיךְ לִסְתֹּם אֶת מַעְיָנוֹ, מִשּׁוּם שֶׁאִם אֵינוֹ סוֹתֵם אוֹתוֹ, גּוֹרֵם לִמְשֹׁךְ רוּחַ לְאוֹתוֹ הַוָּלָד מֵהַצַּד הַהוּא, וְנוֹתֵן מָקוֹם לַצַּד הַהוּא לִגְדֹּל בָּעוֹלָם, צַד הַטֻּמְאָה בְּצַד הַקְּדֻשָּׁה. וְעוֹד סוֹד, שֶׁכָּתוּב (משלי ל) תַּחַת שָׁלוֹשׁ רָגְזָה אֶרֶץ וְגוֹ'.</p>\n<p>וּמִשּׁוּם כָּךְ יוֹסֵף הַצַּדִּיק, סוֹד הַבְּרִית, סִלֵּק וְסָתַם אֶת מַעְיָנוֹ בִּשְׁנַת הָרָעָב, שֶׁלֹּא לְהִתְעָרֵב עִמָּהּ כְּלָל וְלָתֵת לָהּ מָקוֹם, וּמִי שֶׁפּוֹתֵחַ מַעְיָנוֹ בַּזְּמַן הַהוּא, עָלָיו כָּתוּב (הושע ה) בַּה' בָּגָדוּ כִּי בָנִים זָרִים יָלָדוּ עַתָּה יֹאכְלֵם וְגוֹ'. שֶׁהֲרֵי אֵלּוּ נִקְרָאִים בָּנִים זָרִים וַדַּאי. בַּה' בָּגָדוּ וַדַּאי. וּמִשּׁוּם כָּךְ אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל הַקְּדוֹשִׁים שֶׁלֹּא הֶחֱלִיפוּ מָקוֹם קָדוֹשׁ בְּמָקוֹם טָמֵא.</p>\n<p>וְעַל זֶה כָּתוּב וּלְיוֹסֵף יֻלָּד שְׁנֵי בָנִים בְּטֶרֶם תָּבא שְׁנַת הָרָעָב, שֶׁהֲרֵי מֵהַזְּמַן הַהוּא שֶׁשָּׁלְטָה שְׁנַת הָרָעָב, סָתַם אֶת מַעְיָנוֹ וְסִלֵּק אֶת מְקוֹרוֹ שֶׁלֹּא לָתֵת בָּנִים לְצַד הַטֻּמְאָה וְלֹא לְהַחֲלִיף מָקוֹם שֶׁל קֹדֶשׁ בְּמָקוֹם שֶׁל טֻמְאָה. וְצָרִיךְ אָדָם לְצַפּוֹת לְרִבּוֹנוֹ כְּשֶׁיָּבֹא וְיִשְׁלֹט, כַּכָּתוּב (ישעיה ח) וְחִכִּיתִי לַה' הַמַּסְתִּיר פָּנָיו מִבֵּית יַעֲקֹב וְקִוֵּיתִי לוֹ.</p>\n<p>אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁיּוֹדְעִים אֶת דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְשׁוֹמְרִים אֶת מִצְווֹת הַתּוֹרָה לָלֶכֶת בָּהֶם, שֶׁכָּתוּב (הושע יד) כִּי יְשָׁרִים דַּרְכֵי ה' וְצַדִּקִים יֵלְכוּ בָם וּפֹשְׁעִים יִכָּשְׁלוּ בָם. וְכָתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם. (ר\"א ל\"ג וכתוב (ויקרא כ) והתקדשתם והייתם קדשים כי קדוש אני (ה'), שהרי הקדוש ברוך הוא רצה לקדש את ישראל בכל, ולא יהיה להם כלום בצד הטמאה) (בא ראה, כשהצד הזה שולט בעולם, לא צריך לאדם להראות לפניו בשוק, משום שיכול להזיק ונתנה לו רשות להשחית, ובא וראה מה כתוב ביעקב, ויאמר יעקב לבניו למה תתראו, שלא רצה להראות לפניו).</p>\n<p>וּמִשּׁוּם זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא הִזְהִיר אֶת יִשְׂרָאֵל לְהִתְקַדֵּשׁ, שֶׁכָּתוּב וִהְיִיתֶם קְדשִׁים כִּי קָדוֹשׁ אָנִי. מִי זֶה אָנִי? זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, מַלְכוּת הַשָּׁמַיִם הַקְּדוֹשָׁה. הַמַּלְכוּת הָאַחֶרֶת שֶׁל עוֹבְדֵי עֲבוֹדָה זָרָה נִקְרֵאת אַחֵר, שֶׁכָּתוּב (שמות לד) כִּי לֹא תִשְׁתַּחֲוֶה לְאֵל אַחֵר כִּי ה' קַנָּא שְׁמוֹ.</p>\n<p>וּבֹא רְאֵה, אֲנִי - שִׁלְטוֹן הָעוֹלָם הַזֶּה וְהָעוֹלָם הַבָּא, וְהַכֹּל תָּלוּי בּוֹ. אַחֵר - צַד הַטֻּמְאָה, אַחֵר, צַד הָאַחֵר בְּצַד הַטֻּמְאָה, וְשִׁלְטוֹנוֹ בָּעוֹלָם הַזֶּה, וְאֵין לוֹ כְּלוּם בָּעוֹלָם הַבָּא, וּמִשּׁוּם זֶה מִי שֶׁנִּדְבָּק בָּאֲנִי הַזֶּה, יֵשׁ לוֹ חֵלֶק בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>וּמִי שֶׁנִּדְבָּק בָּאַחֵר הַזֶּה, נֶאֱבָד מִן הָעוֹלָם הַהוּא וְאֵין לוֹ חֵלֶק בָּעוֹלָם הַבָּא. וְיֵשׁ לוֹ חֵלֶק בָּעוֹלָם הַזֶּה בַּטֻּמְאָה, מִשּׁוּם שֶׁאוֹתָהּ הַמַּלְכוּת הָאַחֶרֶת, עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, כַּמָּה הֵם מְגִנִּים שׁוֹמְרִים מְמֻנִּים בָּהּ לִשְׁלֹט בָּעוֹלָם הַזֶּה.</p>\n<p>וּמִשּׁוּם כָּךְ אֱלִישָׁע אַחֵר שֶׁיָּרַד וְנִדְבַּק בַּדַּרְגָּה הַזּוֹ, נִטְרַד מִן הָעוֹלָם הַבָּא הַהוּא, וְלֹא נִתְּנָה לוֹ רְשׁוּת לַחֲזֹר בִּתְשׁוּבָה וְנִטְרַד מִן הָעוֹלָם הַהוּא, וְעַל כֵּן נִקְרָא אַחֵר.</p>\n<p>וּמִשּׁוּם כָּךְ צָרִיךְ אָדָם לְהִפָּרֵד מִכָּל הַצְּדָדִים שֶׁלֹּא לְהִטָּמֵא בַּצַּד הַהוּא, לִזְכּוֹת בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. וְעַל כֵּן זֶה בְּרָכָה וְזֶה קְלָלָה, זֶה שָׂבָע וְזֶה רָעָב. הַכֹּל בְּהִפּוּךְ זֶה מִזֶּה, וְהִנֵּה בֵּאַרְנוּ.</p>\n<p>וּמִשּׁוּם כָּךְ, בְּאוֹתוֹ זְמַן שֶׁל שְׁנַת הָרָעָב, אֵין לְאָדָם לְהֵרָאוֹת בַּשּׁוּק, וְלֹא לִפְתֹּחַ מַעְינוֹ לְהוֹלִיד בָּנִים לְאֵל אַחֵר, וְהִנֵּה נִתְבָּאֵר.</p>\n<p>אַשְׁרֵי הָאִישׁ שֶׁנִּשְׁמָר לָלֶכֶת בְּדֶרֶךְ אֱמֶת וּלְהִדָּבֵק תָּמִיד בְּרִבּוֹנוֹ, שֶׁכָּתוּב (דברים י) וּבוֹ תִדְבָּק (וכתוב את יי אלהיך תירא אתו תעבד ובו תדבק) וּבִשְׁמוֹ תִּשָּׁבֵעַ. וּבוֹ תִּשָּׁבֵעַ לֹא כָתוּב, אֶלָּא וּבִשְׁמוֹ. מַה זֶּה תִּשָּׁבֵעַ? כְּמוֹ שֶׁבֵּאַרְנוּ, לִהְיוֹת דָּבֵק בְּסוֹד הָאֱמוּנָה.</p>\n<p>שֶׁבַע דְרָגוֹת לְמַעְלָה עֶלְיוֹנוֹת עַל הַכֹּל, הַסּוֹד שֶׁל שְׁלֵמוּת הָאֱמוּנָה וְהַסּוֹד שֶׁל שֶׁבַע דְּרָגוֹת שֶׁלְּמַטָּה מֵהֶם, שֶׁהֵם חִבּוּר אֶחָד וְקֶשֶׁר אֶחָד, אֵלּוּ עִם אֵלּוּ, שֶׁכֻּלָּם יִהְיוּ אֶחָד. וּמִשּׁוּם כָּךְ כָּתוּב (מלכים א ח) שִׁבְעַת יָמִים וְשִׁבְעַת יָמִים אַרְבָּעָה עָשָׂר יוֹם, וְהַכֹּל אֶחָד וְקֶשֶׁר אֶחָד. וְעַל כֵּן כָּתוּב וּבִשְׁמוֹ תִּשָּׁבֵעַ, מִלְמַעְלָה וּמִלְּמַטָּה.</p>\n<p>אַשְׁרָיו (מי שזוכה להתדבק בקדושברוךהוא כראוי, צדיק הוא בעולם הזה ובעולם הבא, שהקדוש ברוך הוא פותח לו אוצרות טובים קדושים בשעה שיצטרך לקבלת התפלה, כמו שנאמר) (ומי שמיחד אלו עם אלו, עליו כתוב) (דברים כח) יִפְתַּח ה' לְךְ אֶת אוֹצָרוֹ הַטּוֹב אֶת הַשָּׁמַיִם. אֵלּוּ הָאוֹצָרוֹת שֶׁלְּמַעְלָה וּלְמַטָּה. שִׁבְעַת יָמִים וְשִׁבְעַת יָמִים כֻּלָּם אֶחָד, שֶׁכָּתוּב אֶת אוֹצָרוֹ הַטּוֹב אֶת הַשָּׁמַיִם. אוֹצָרוֹ אֶחָד, וְהוּא אֶת הַשָּׁמַיִם. (זכריה ד) שִׁבְעָה וְשִׁבְעָה מוּצָקוֹת, וְהֵם אֶחָד.</p>\n<p>רַבִּי חִיָּיא וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים בַּדֶרֶךְ. בֵּינְתַיִם רָאוּ אִישׁ אֶחָד שֶׁהָיָה בָּא מְעֻטָּף בְּעִטּוּף שֶׁל מִצְוָה וּכְלֵי זַיִן קְשׁוּרִים תַּחְתָּיו. אָמַר רַבִּי חִיָּיא, הָאִישׁ הַזֶּה, אֶחָד מִן הַשְּׁנַיִם יֵשׁ בּוֹ - אוֹ שֶׁהוּא צַדִּיק שָׁלֵם, אוֹ שֶׁהוּא בִּשְׁבִיל לְרַמּוֹת אֶת בְּנֵי הָעוֹלָם.</p>\n<p>אָמַר לוֹ רַבִּי יוֹסֵי, הֲרֵי הַחֲסִידִים הָעֶלְיוֹנִים אָמְרוּ, הֱוֵי דָן כָּל אָדָם לְכַף זְכוּת. הִנֵּה שָׁנִינוּ, אָדָם שֶׁיּוֹצֵא לַדֶּרֶךְ, יִתְכַּוֵּן לִשְׁלֹשָׁה דְבָרִים - לְדוֹרוֹן, לִקְרָב, וְלִתְפִלָּה. מִנַּיִן לָנוּ? מִיַּעֲקֹב. שֶׁהֲרֵי הוּא הִתְכַּוֵּן לִשְׁלֹשֶׁת אֵלּוּ, וְזֵרֵז עַצְמוֹ לְדוֹרוֹן, לִקְרָב וְלִתְפִלָּה. וְהָאִישׁ הַזֶּה הוּא הוֹלֵךְ בַּדֶּרֶךְ, הִנֵּה יֵשׁ בּוֹ עִטּוּף שֶׁל מִצְוָה לַתְּפִלָּה, וְהִנֵּה בּוֹ כְּלֵי זַיִן לִקְרָב. כֵּיוָן שֶׁיֵּשׁ בּוֹ שְׁנֵי אֵלֶּה, הַשְּׁלִישִׁי אֵין לִרְדּף אַחֲרֶיהָ.</p>\n<p>כְּשֶׁקָּרַב אֲלֵיהֶם, נָתְנוּ לוֹ שָׁלוֹם וְלֹא הֵשִׁיב לָהֶם. אָמַר רַבִּי חִיָּיא, הִנֵּה אֶחָד מֵאוֹתָם הַשְּׁנַיִם שֶׁרְאוּיִים לִהְיוֹת בּוֹ - אֵין בּוֹ, שֶׁהֲרֵי לֹא תִקֵּן עַצְמוֹ לְדוֹרוֹן, וּבְדוֹרוֹן כָּלוּל הַשָּׁלוֹם. אָמַר רַבִּי יוֹסֵי, אוּלַי הָיָה מִשְׁתַּדֵּל בִּתְפִלָּתוֹ, אוֹ שֶׁמַּרְחִישׁ תַּלְמוּדוֹ כְּדֵי שֶׁלֹּא יִשְׁכַּח אוֹתוֹ.</p>\n<p>הָלְכוּ יַחַד, וְלֹא דִבֵּר אוֹתוֹ הָאִישׁ עִמָּהֶם. אַחַר כָּךְ נִשְׁמְטוּ רַבִּי חִיָּיא וְרַבִּי יוֹסֵי וְהִשְׁתַּדְּלוּ בַּתּוֹרָה. כֵּיון שֶׁרָאָה אוֹתוֹ הָאִישׁ שֶׁמִּשְׁתַּדְּלִים הָיוּ בַּתּוֹרָה, קָרַב אֲלֵיהֶם וְנָתַן לָהֶם שָׁלוֹם.</p>\n<p>אָמַר לָהֶם, רַבּוֹתַי, בַּמָּה חֲשַׁדְתֶּם אוֹתִי כְּשֶׁנְּתַתֶּם לִי שָׁלוֹם וְלֹא הֵשַׁבְתִּי לָכֶם? אָמַר לוֹ רַבִּי יוֹסֵי, אוּלַי הָיִיתָ אוֹמֵר תְּפִלָּה אוֹ מַרְחִישׁ בְּתַלְמוּדְךְ. אָמַר לָהֶם, הַקָּדוֹשׁ בָּרוּךְ הוּא יָדוּן אֶתְכֶם לְכַף זְכוּת.</p>\n<p>אֲבָל אֹמַר לָכֶם, יוֹם אֶחָד הָיִיתִי הוֹלֵךְ בַּדֶּרֶךְ, מָצָאתִי אִישׁ אֶחָד וְהִקְדַּמְתִּי לוֹ שָׁלוֹם, וְאוֹתוֹ אִישׁ הָיָה שׁוֹדֵד, וְקָם עָלַי וְצִעֵר אוֹתִי, וְאִלְמָלֵא שֶׁהִתְגַּבַּרְתִּי עָלָיו הִצְטַעַרְתִּי. מֵאוֹתוֹ יוֹם נָדַרְתִּי שֶׁלֹּא לְהַקְדִּים שָׁלוֹם, רַק לְאָדָם צַדִּיק, אֶלָּא אִם הִכַּרְתִּיו בָּרִאשׁוֹנָה, מִשּׁוּם שֶׁיָּכוֹל לְצַעֵר אוֹתִי וְיִתְגַּבֵּר עָלַי בְּכֹחַ, מִשּׁוּם שֶׁאָסוּר לְהַקְדִּים שָׁלוֹם לְאִישׁ רָשָׁע, שֶׁכָּתוּב (ישעיה מט) אֵין שָׁלוֹם אָמַר ה' לָרְשָׁעִים.</p>\n<p>וְאוֹתָהּ הַשָּׁעָה שֶׁרָאִיתִי אֶתְכֶם וּנְתַתֶּם לִי שָׁלוֹם וְלֹא הֵשַׁבְתִּי לָכֶם, חָשַׁדְתִּי אֶתְכֶם, מִשּׁוּם שֶׁלֹּא רָאִיתִי בָכֶם מִצְוָה שֶׁנִּרְאֵית בַּחוּץ, וּכְמוֹ כֵן הָיִיתִי חוֹזֵר עַל תַּלְמוּדִי, אֲבָל עַכְשָׁו שֶׁרָאִיתִי אֶתְכֶם שֶׁאַתֶּם צַדִּיקִים, הִנֵּה הַדֶּרֶךְ מְתֻקֶּנֶת לְפָנַי.</p>\n<p>פָּתַח וְאָמַר, (תהלים עג) מִזְמוֹר לְאָסָף אַךְ טוֹב לְיִשְׂרָאֵל אֱלֹהִים לְבָרֵי לֵבָב. בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה אֶת הַיָּמִין וְעָשָׂה שְׂמֹאל לְהַנְהִיג אֶת הָעוֹלָם. אֶחָד נִקְרָא טוֹב, וְאֶחָד נִקְרָא רָע. וּבִשְׁנֵי אֵלֶּה נִכְלָל הָאָדָם, וְהִתְקָרֵב בַּכֹּל.</p>\n<p>וּבְאוֹתוֹ הָרָע, שֶׁהוּא הַשְּׂמֹאל, נִכְלְלוּ עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת וְנִתַּן בַּצַּד שֶׁלָּהֶם, מִשּׁוּם שֶׁהֵם עַרְלֵי לֵב וְעַרְלֵי בָשָׂר וּלְהִטָּמֵא בוֹ. אֲבָל בְּיִשְׂרָאֵל מַה כָּתוּב? אַךְ טוֹב לְיִשְׂרָאֵל.</p>\n<p>וְאִם תֹּאמַר, לְכֻלָּם? לֹא, אֶלָּא לְאוֹתָם שֶׁלֹּא נִטְמָאִים עִם אוֹתוֹ הָרָע, שֶׁכָּתוּב לְבָרֵי לֵבָב, מִשּׁוּם שֶׁזֶּה טוֹב וְזֶה רָע. טוֹב לְיִשְׂרָאֵל לְבַדָּם, וְרָע לָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת. אַךְ טוֹב לְיִשְׂרָאֵל כְּדֵי לְהִדָּבֵק בּוֹ, וּבָזֶה נִדְבְּקוּ יִשְׂרָאֵל בְּסוֹד עֶלְיוֹן, בְּסוֹד הָאֱמוּנָה, שֶׁהַכֹּל יִהְיֶה אֶחָד. אָמַר רַבִּי יוֹסֵי, אַשְׁרֵינוּ שֶׁלֹּא טָעִינוּ בְךְ, וַהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שָׁלַח אוֹתְךְ אֵלֵינוּ.</p>\n<p>אָמַר רַבִּי יוֹסֵי, מִשּׁוּם שֶׁטּוֹב הוּא לְיִשְׂרָאֵל, יֵשׁ לְיִשְׂרָאֵל חֵלֶק לָעוֹלָם הַזֶּה, וּבָעוֹלָם הַבָּא לִרְאוֹת עַיִן בְּעַיִן אֶת מַרְאֵה הַכָּבוֹד, כַּכָּתוּב (ישעיה נב) כִּי עַיִן בְּעַיִן יִרְאוּ בְּשׁוּב ה' צִיּוֹן. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9522011411,"<p>וַיִּגַּשׁ אֵלָיו יְהוּדָה וְגוֹ'. רַבִּי אֶלְעָזָר פָּתַח, (ישעיה סג) כִּי אַתָּה אָבִינוּ כִּי אַבְרָהָם לֹא יְדָעָנוּ וְיִשְׂרָאֵל לֹא יַכִּירָנוּ אַתָּה ה' אָבִינוּ גֹּאֲלֵנוּ מֵעוֹלָם שְׁמֶךְ. הַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ. אֲבָל בֹּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, כָּל יוֹם וָיוֹם עָשָׂה מַעֲשֵׂהוּ כָּרָאוּי בְּכָל יוֹם וָיוֹם כְּמוֹ שֶׁצָּרִיךְ. כֵּיוָן שֶׁבָּא הַיּוֹם הַשִּׁשִּׁי וְהִצְטָרֵךְ לִבְרֹא אָדָם, בָּאָה לְפָנָיו הַתּוֹרָה. אָמְרָה (לפני הקדוש ברוך הוא): הָאָדָם הַזֶּה שֶׁאַתָּה רוֹצֶה לִבְרֹא, עָתִיד הוּא לְהַרְגִּיז לְפָנֶיךְ. אִלְמָלֵא לֹא תַאֲרִיךְ רָגְזְךְ, טוֹב לוֹ שֶׁלֹּא יִבָּרֵא. אָמַר לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא: וְכִי לְחִנָּם נִקְרֵאתִי אֶרֶךְ אַפַּיִם?</p>\n<p>אֶלָּא הַכֹּל נִבְרָא בַּתּוֹרָה וְהַכֹּל נִתְקַן בַּתּוֹרָה, מִשּׁוּם שֶׁבְּטֶרֶם בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, בָּאוּ לְפָנָיו כָּל הָאוֹתִיּוֹת, וְנִכְנְסוּ כָּל אַחַת לְמַפְרֵעַ.</p>\n<p>נִכְנְסָה תָּי\"ו, אָמְרָה לְפָנָיו: רְצוֹנְךְ לִבְרֹא בִי אֶת הָעוֹלָם? אָמַר לָהּ: לֹא, שֶׁבָּךְ עֲתִידִים כַּמָּה צַדִּיקִים לָמוּת, שֶׁכָּתוּב וְהִתְוִיתָ תָּו עַל מִצְחוֹת הָאֲנָשִׁים וְגוֹ'. וְשָׁנִינוּ, שֶׁכָּתוּב וּמִמִּקְדָּשִׁי תָּחֵלּוּ, אַל תִּקְרֵי מִמִּקְדָּשִׁי אֶלָּא מִמְקֻדָּשַׁי. וּמִשּׁוּם כָּךְ הָעוֹלָם לֹא יִבָּרֵא בָּךְ.</p>\n<p>נִכְנְסוּ שְׁלֹשׁ הָאוֹתִיּוֹת שִׁי\"ן קוֹ\"ף רֵי\"שׁ, כָּל אַחַת וְאַחַת לְבַדָּהּ. אָמַר לָהֶן הַקָּדוֹשׁ בָּרוּךְ הוּא: אֵינְכֶן כְּדָאִיּוֹת לִבְרֹא בָכֶן אֶת הָעוֹלָם, שֶׁהֲרי אַתֶּן הָאוֹתִיּוֹת שֶׁנִּקְרָא בָכֶן שֶׁקֶר, וְהַשֶּׁקֶר אֵינוֹ כְדַאי לַעֲמֹד לְפָנַי, וְהִנֵּה פֵּרְשׁוּהָ.</p>\n<p>וְנִכְנְסוּ פֵּ\"א צָדִ\"י, וְכֵן כֻּלָּן, עַד שֶׁהִגִּיעוּ הָאוֹתִיּוֹת לָאוֹת כָּ\"ף. כֵּיוָן שֶׁיָּרְדָה כָּ\"ף מֵעַל הַכֶּתֶר, הִזְדַּעְזְעוּ עֶלְיוֹנִים וְתַחְתּוֹנִים וְכוּ', עַד שֶׁהַכֹּל הִתְקַיֵּם בָּאוֹת בֵּי\"ת, שֶׁהִיא סִימַן בְּרָכָה, וּבָהּ הִשְׁתַּכְלֵל הָעוֹלָם וְנִבְרָא.</p>\n<p>וְאִם תֹּאמַר שֶׁאָלֶ\"ף הִיא הָרֹאשׁ שֶׁל כָּל (אותן) הָאוֹתִיּוֹת - (לא) נָאֶה הוּא. אֶלָּא מִשּׁוּם שֶׁנִּקְרָא בּוֹ אָרוּר (משום שנקרא בה ארור), וּמִשּׁוּם זֶה לֹא נִבְרָא בּוֹ הָעוֹלָם, אַף עַל גַּב שֶׁאָלֶ\"ף הִיא אוֹת שֶׁל סוֹד עֶלְיוֹן. כְּדֵי לֹא לָתֵת מָקוֹם לַצַּד הָאַחֵר שֶׁנִּקְרָא אָרוּר, לֹא נִבְרָא בּוֹ הָעוֹלָם, וְנִתְקַן הָעוֹלָם בְּבֵי\"ת, וּבוֹ הוּא נִבְרָא.</p>\n<p>בֹּא רְאֵה, כִּי אַתָּה אָבִינוּ, מִשּׁוּם שֶׁהָעוֹלָם הַזֶּה נִתְקַן וְנִבְרָא בַּדַּרְגָּה הַזּוֹ, וְהָאָדָם נִבְרָא בָּהּ וְיָצָא לָעוֹלָם.</p>\n<p>כִּי אַבְרָהָם לֹא יְדָעָנוּ, שֶׁהֲרֵי אַף עַל גַּב שֶׁבּוֹ קִיּוּם הָעוֹלָם, לֹא הִשְׁתַּדֵּל עָלֵינוּ כְּמוֹ שֶׁהִשְׁתַּדֵּל עַל יִשְׁמָעֵאל, שֶׁאָמַר לוּ יִשְׁמָעֵאל יִחְיֶה לְפָנֶיךְ. וְיִשְׂרָאֵל לֹא יַכִּירָנוּ, מִשּׁוּם שֶׁכָּל הַבְּרָכוֹת שֶׁהִצְטָרֵךְ לְבָרֵךְ אֶת בָּנָיו, הִשְׁאִיר לַדַּרְגָּה הַזּוֹ לְבָרֵךְ אֶת כֻּלָּם.</p>\n<p>אַתָּה ה' אָבִינוּ, שֶׁהֲרֵי אַתָּה תָּמִיד עוֹמֵד עָלֵינוּ לְבָרֵךְ וּלְהַשְׁגִּיחַ עָלֵינוּ, כְּמוֹ אָב שֶׁמַּשְׁגִּיחַ עַל הַבָּנִים בְּכָל מַה שֶּׁצָּרִיךְ לָהֶם. גֹּאֲלֵנוּ מֵעוֹלָם שְׁמֶךְ, שֶׁהֲרֵי אַתָּה הוּא גוֹאֵל, שֶׁכָּךְ נִקְרָא הַמַּלְאָךְ הַגּוֹאֵל, וְזֶה גֹּאֲלֵנוּ מֵעוֹלָם שְׁמֶךְ, שְׁמֶךְ וַדַּאי. שָׁנִינוּ, אֵין מַפְסִיקִים בֵּין גְּאֻלָּה לִתְפִלָּה, כְּמוֹ שֶׁלֹּא מַפְסִיקִים בֵּין תְּפִלָּה שֶׁל יָד לִתְפִלָּה שֶׁל רֹאשׁ, שֶׁצָּרִיךְ לְהַרְאוֹת שֶׁהַכֹּל אֶחָד, וְהִנֵּה פֵּרְשׁוּהָ.</p>"],[9522011412,"<p>רַבִּי יִצְחָק וְרַבִּי יְהוּדָה הָיוּ יוֹשְׁבִים לַיְלָה אֶחָד וְעוֹסְקִים בַּתּוֹרָה. אָמַר רַבִּי יִצְחָק לְרַבִּי יְהוּדָה, הִנֵּה שָׁנִינוּ, שֶׁכַּאֲשֶׁר בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, עָשָׂה אֶת הָעוֹלָם הַתַּחְתּוֹן כְּמוֹ שֶׁהָעוֹלָם הָעֶלְיוֹן, וְהַכֹּל זֶה כְּנֶגֶד זֶה, (כדי להיות זה כנגד זה) וְהוּא כְבוֹדוֹ לְמַעְלָה וּלְמַטָּה.</p>\n<p>אָמַר רַבִּי יְהוּדָה, כָּךְ זֶה וַדַּאי, וּבָרָא אָדָם עַל הַכֹּל. זֶהוּ שֶׁכָּתוּב (ישעיה מה) אָנֹכִי עָשִׂיתִי אֶרֶץ וְאָדָם עָלֶיהָ בָרָאתִי. אָנֹכִי עָשִׂיתִי אֶרֶץ, וַדַּאי. מָה הַטַּעַם עָשִׂיתִי אֶרֶץ? מִשּׁוּם שֶׁאָדָם עָלֶיהָ בָרָאתִי, שֶׁהוּא קִיּוּמוֹ שֶׁל הָעוֹלָם, שֶׁיִּהְיֶה הַכֹּל בִּשְׁלֵמוּת אַחַת.</p>\n<p>פָּתַח וְאָמַר, (שם מב) כֹּה אָמַר הָאֵל ה' בּוֹרֵא הַשָּׁמַיִם וְנוֹטֵיהֶם רֹקַע הָאָרֶץ וְצֶאֱצָאֶיהָ נֹתֵן נְשָׁמָה לָעָם עָלֶיהָ וְרוּחַ לַהֹלְכִים בָּהּ. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ, אֲבָל כֹּה אָמַר הָאֵל ה' בּוֹרֵא הַשָּׁמַיִם וְנוֹטֵיהֶם - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה לְמַעְלָה, שֶׁהוּא בּוֹרֵא הַשָּׁמַיִם, וְהִתְקִינָם תָּמִיד, בְּכָל זְמַן. רֹקַע הָאָרֶץ וְצֶאֱצָאֶיהָ - זוֹ הָאָרֶץ הַקְּדוֹשָׁה, צְרוֹר הַחַיִּים. נֹתֵן נְשָׁמָה לָעָם עָלֶיהָ. (הארץ) זוֹ הִיא שֶׁנּוֹתֶנֶת נְשָׁמָה וְגוֹ'.</p>\n<p>אָמַר רַבִּי יִצְחָק, הַכֹּל הוּא לְמַעְלָה, שֶׁהֲרֵי מִשָּׁם יוֹצֵאת נִשְׁמַת חַיִּים לָאָרֶץ הַזּוֹ, וְהָאָרֶץ הַזּוֹ לוֹקַחַת הַנְּשָׁמָה לָתֵת לַכֹּל, מִשּׁוּם שֶׁהַנָּהָר הַהוּא שֶׁשּׁוֹפֵעַ וְיוֹצֵא, הוּא נוֹתֵן וּמַכְנִיס נְשָׁמוֹת לָאָרֶץ הַזּוֹ, וְהִיא לוֹקַחַת אוֹתָן וְנוֹתֶנֶת לַכֹּל.</p>\n<p>בֹּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָאָדָם, כִּנֵּס אֶת עֲפָרוֹ מֵאַרְבָּעָה הַצְּדָדִים שֶׁל הָעלָם, וְעָשָׂה אֶת עַצְמוֹ בִּמְקוֹם הַמִּקְדָּשׁ לְמַטָּה, וְהִמְשִׁיךְ עָלָיו נִשְׁמַת חַיִּים מִבֵּית הַמִּקְדָּשׁ לְמַעְלָה.</p>\n<p>וְהַנְּשָׁמָה הִיא כְלוּלָה בְּשָׁלֹשׁ דְּרָגוֹת, וְעַל כֵּן שְׁלֹשָׁה שֵׁמוֹת הֵם לַנְּשָׁמָה, כְּמוֹ שֶׁהַסּוֹד הָעֶלְיוֹן: נֶפֶ\"שׁ, רוּ\"חַ, נְשָׁמָ\"ה. נֶפֶשׁ, הִנֵּה פֵּרְשׁוּהָ, שֶׁהִיא תַחְתּוֹנָה מֵהַכֹּל. רוּחַ, הִיא הַקִּיּוּם שֶׁשּׁוֹלֵט עַל הַנֶּפֶשׁ, וְהִיא דַרְגָּה עֶלְיוֹנָה עָלֶיהָ לַעֲמֹד עָלֶיהָ בַּכֹּל כָּרָאוּי. הַנְּשָׁמָה הִיא הַקִּיּוּם הָעֶלְיוֹן עַל הַכֹּל, וְשׁוֹלֵטֶת עַל הַכֹּל, דַּרְגָּה קְדוֹשָׁה, עֶלְיוֹנָה עַל כֻּלָּם.</p>\n<p>אֵלּוּ שְׁלֹשׁ הַדְּרָגוֹת כְּלוּלוֹת בִּבְנֵי הָאָדָם, לְאוֹתָם שֶׁזּוֹכִים לַעֲבוֹדַת רִבּוֹנָם. שֶׁהֲרֵי בַּהַתְחָלָה יֵשׁ בּוֹ נֶפֶשׁ, וְהוּא הַתִּקּוּן הַקָּדוֹשׁ לְתַקֵּן בּוֹ אֶת הָאָדָם. כֵּיוָן שֶׁבָּא הָאָדָם לְהִטָּהֵר בַּדַּרְגָּה הַזּוֹ, נִתְקָן לְהִתְעַטֵּר בְּרוּחַ, שֶׁהִיא דַרְגָּה קְדוֹשָׁה שֶׁשּׁוֹרָה עַל הַנֶּפֶשׁ לְהִתְעַטֵּר בָּאָדָם הַהוּא שֶׁזּוֹכֶה.</p>\n<p>כֵּיוָן שֶׁהִתְעַלָּה בָהֶם, בַּנֶּפֶשׁ וְהָרוּחַ, וְנִכְנַס וְנִתְקַן בַּעֲבוֹדַת רִבּוֹנוֹ כָּרָאוּי, אָז שׁוֹרָה עָלָיו נְשָׁמָה, דַּרְגָּה עֶלְיוֹנָה קְדוֹשָׁה, שֶׁשּׁוֹלֶטֶת עַל הַכֹּל, כְּדֵי לְהִתְעַטֵּר בְּדַרְגָּה עֶלְיוֹנָה קְדוֹשָׁה. וְאָז הוּא הַשָּׁלֵם שֶׁל הַכֹּל, שָׁלֵם בְּכָל הַצְּדָדִים, לִזְכּוֹת בָּעוֹלָם הַבָּא, וְהוּא אוֹהֲבוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר לְהַנְחִיל אֹהֲבַי יֵשׁ. מִי הֵם אוֹהֲבַי? אֵלּוּ הֵם שֶׁבָּהֶם נְשָׁמָה קְדוֹשָׁה.</p>\n<p>אָמַר רַבִּי יְהוּדָה, אִם כָּךְ, הֲרֵי כָּתוּב כֹּל אֲשֶׁר נִשְׁמַת רוּחַ חַיִּים בְּאַפָּיו וְגוֹ'. אָמַר לוֹ, כָּךְ הוּא וַדַּאי, שֶׁהֲרֵי לֹא נִשְׁאַר בָּהֶם. מִכָּל אוֹתָם שֶׁהָיְתָה בָהֶם נְשָׁמָה קְדוֹשָׁה כְּמוֹ חֲנוֹךְ, יֶרֶד, וְכָל הַצַּדִּיקִים, כְּדֵי לְהָגֵן עַל הָאָרֶץ שֶׁלֹּא תֻשְׁמַד בִּגְלָלָם. זֶהוּ שֶׁכָּתוּב כֹּל אֲשֶׁר נִשְׁמַת רוּחַ חַיִּים בְּאַפָּיו מִכֹּל אֲשֶׁר בֶּחָרָבָה מֵתוּ, כְּבָר מֵתוּ וְהִסְתַּלְּקוּ מִן הָעוֹלָם, וְלֹא נִשְׁאַר מֵהֶם מִי שֶׁיָּגֵן עַל הָעוֹלָם בַּזְּמַן הַהוּא.</p>\n<p>בֹּא רְאֵה, הַכֹּל הֵם דְּרָגוֹת אֵלּוּ עַל אֵלּוּ, נֶפֶ\"שׁ, רוּ\"חַ, נְשָׁמָ\"ה, דַּרְגָּה עַל דַּרְגָּה. הַנֶּפֶשׁ בָּרִאשׁוֹנָה, וְהִיא הַדַּרְגָּה הַתַּחְתּוֹנָה, כְּפִי שֶׁאָמַרְנוּ. אַחַר כָּךְ רוּחַ, שֶׁשּׁוֹרָה עַל הַנֶּפֶשׁ וְעוֹמֶדֶת עָלֶיהָ. הַנְּשָׁמָה הַדַּרְגָּה שֶׁעוֹלָה עַל הַכֹּל, וּבֵאֲרוּהָ.</p>\n<p>נֶפֶשׁ - זוֹ נֶפֶשׁ דָּוִד, וְהִיא שֶׁעוֹמֶדֶת לְקַבֵּל הַנֶּפֶשׁ מֵאוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא. רוּחַ - זוֹ הָרוּחַ שֶׁעוֹמֶדֶת עַל הַנֶּפֶשׁ, וְאֵין קִיּוּם לַנֶּפֶשׁ אֶלָּא בָּרוּחַ, וְזוֹ הָרוּחַ שֶׁשּׁוֹרָה בֵּין הָאֵשׁ וְהַמַּיִם, וּמִכָּאן נִזּוֹנֵית הַנֶּפֶשׁ הַזּוֹ.</p>\n<p>הָרוּחַ עוֹמֶדֶת בְּקִיּוּם שֶׁל דַּרְגָּה אַחֶרֶת עֶלְיוֹנָה שֶׁנִּקְרֵאת נְשָׁמָה, שֶׁהֲרֵי מִשָּׁם יוֹצְאוֹת נֶפֶשׁ וְרוּחַ, מִשָּׁם נִזּוֹנֵית הָרוּחַ. וּכְשֶׁנּוֹסַעַת הָרוּחַ, אָז נוֹסַעַת הַנֶּפֶשׁ, וְהַכֹּל אֶחָד. וּמִתְקָרְבִים זֶה לָזֶה. הַנֶּפֶשׁ נִקְרֶבֶת לָרוּחַ, וְהָרוּחַ נִקְרֶבֶת לַנְּשָׁמָה, וְהַכֹּל אֶחָד.</p>\n<p>בֹּא רְאֵה, וַיִּגַּשׁ אֵלָיו, הִתְקָרְבוּת שֶׁל עוֹלָם עִם עוֹלָם, לְהֵאָחֵז זֶה עִם זֶה, שֶׁהַכֹּל יִהְיֶה אֶחָד. מִשּׁוּם שֶׁיְּהוּדָה הוּא מֶלֶךְ וְיוֹסֵף מֶלֶךְ, הִתְקָרְבוּ זֶה לָזֶה וְנֶאֶחְזוּ זֶה עִם זֶה.</p>"],[9522011413,"<p>רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהלים מח) כִּי הִנֵּה הַמְּלָכִים נוֹעֲדוּ - זֶה יְהוּדָה וְיוֹסֵף, מִשּׁוּם שֶׁשְּׁנֵיהֶם מְלָכִים, וְהִתְקָרְבוּ זֶה לָזֶה לְהִתְוַכֵּחַ שְׁנֵיהֶם יַחַד, מִשּׁוּם שֶׁיְּהוּדָה עָרַב לְבִנְיָמִין, וְהָיָה עָרֵב לְאָבִיו בּוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, וְעַל כֵּן הִתְקָרֵב לִפְנֵי יוֹסֵף לְהִתְוַכֵּחַ עִמּוֹ עַל עִסְקוֹ שֶׁל בִּנְיָמִין, שֶׁלֹּא לִהְיוֹת בְּנִדּוּי בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, כְּמוֹ שֶׁנֶּאֱמַר (בראשית מג) אָנֹכִי אֶעֶרְבֶנּוּ מִיָּדִי תְּבַקְשֶׁנּוּ אִם לֹא הֲבִיאֹתִיו אֵלֶיךְ וְהִצַּגְתִּיו לְפָנֶיךְ וְחָטָאתִי לְךְ כָּל הַיָּמִים, בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>וְעַל כֵּן, כִּי הִנֵּה הַמְּלָכִים נוֹעֲדוּ עָבְרוּ יַחְדָּו, הִתְרַגְּזוּ יַחַד וְהִתְרַגְּזוּ זֶה עִם זֶה בִּשְׁבִיל בִּנְיָמִין. מַה כָּתוּב? הֵמָּה רָאוּ כֵּן תָּמָהוּ נִבְהֲלוּ נֶחְפָּזוּ רְעָדָה אֲחָזָתַם שָׁם, לְכָל אוֹתָם שֶׁהָיוּ שָׁם. (לכל שאר השבטים שהיו שם,)</p>\n<p>חִיל כַּיּוֹלֵדָה, מִשּׁוּם שֶׁהָיוּ פוֹחֲדִים לַהֲרֹג וּלְהֵהָרֵג, וְהַכֹּל בִּשְׁבִיל בִּנְיָמִין. (מה כתוב? כן תמהו נבהלו נחפזו, והכל בגללו) שֶׁהֲרֵי יוֹסֵף נִמְכַּר בִּגְלַל יְהוּדָה וְאָבַד לְאָבִיו, וְכָעֵת עָרַב לוֹ לְבִנְיָמִין, וּפָחַד שֶׁלֹּא יֹאבַד, וּמִשּׁוּם כָּךְ וַיִּגַּשׁ אֵלָיו יְהוּדָה.</p>\n<p>דָּבָר אַחֵר כִּי הִנֵּה הַמְּלָכִים נוֹעֲדוּ - זֶה יְהוּדָה וְיוֹסֵף שֶׁהִזְדַּמְּנוּ לְהִתְוַכֵּחַ זֶה עִם זֶה, לְהִתְוַכֵּחַ שְׁנֵיהֶם יַחַד, מִשּׁוּם שֶׁיְּהוּדָה הָיָה מֶלֶךְ וְיוֹסֵף הָיָה מֶלֶךְ, וּשְׁנֵיהֶם בָּאוּ יַחַד לְהִתְוַכֵּחַ זֶה עִם זֶה, זֶה עַל בִּנְיָמִין - וְזֶה עַל בִּנְיָמִין.</p>\n<p>כִּי הִנֵּה הַמְּלָכִים, אָמַר רַבִּי יְהוּדָה, סוֹד הָאֱמוּנָה כָּאן, שֶׁהֲרֵי כְּשֶׁנִּמְצָא הָרָצוֹן, וְהַקֶּשֶׁר מִתְעַטֵּר יַחַד, אֲזַי שְׁנֵי עוֹלָמוֹת נִקְשָׁרִים יַחַד וּמִזְדַּמְּנִים יַחַד, זֶה לִפְתֹּחַ אֶת הָאוֹצָר - וְזֶה לְלַקֵּט וְלִכְנֹס לְתוֹכוֹ. וְאָז, כִּי הִנֵּה הַמְּלָכִים נוֹעֲדוּ, שְׁנֵי עוֹלָמוֹת קְדוֹשִׁים, הָעוֹלָם הָעֶלְיוֹן וְהָעוֹלָם הַתַּחְתּוֹן.</p>\n<p>עָבְרוּ יַחְדָּו, סוֹד הַדָּבָר - שֶׁכַּאֲשֶׁר מִתְחַבְּרִים יַחַד, אֲזַי עָבְרוּ יַחְדָּו, מִשּׁוּם שֶׁכָּל הַחֲטָאִים שֶׁל הָעוֹלָם לֹא מִתְבַּטְּלִים לְהִכָּנַע עַד שֶׁמִּתְחַבְּרִים יַחַד, כַּכָּתוּב וְעֹבֵר עַל פֶּשַׁע, וְעַל כֵּן עָבְרוּ יַחְדָּו. עָבְרוּ - אוֹתָם הַחֲטָאִים הִתְכַּפְּרוּ, מִשּׁוּם שֶׁהִנֵּה אָז כָּל הַפָּנִים מְאִירוֹת וְכָל הַחֲטָאִים הִתְבַּטְּלוּ.</p>\n<p>רַבִּי חִיָּיא אָמַר, הַסּוֹד הַזֶּה הוּא בְּתִקּוּן הַקָּרְבָּן, שֶׁהֲרֵי כַּאֲשֶׁר נִקְרָב הַקָּרְבָּן, וְכֻלָּם מְקַבְּלִים הַסְפָּקָתָם כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ, אָז הַכֹּל נִקְשָׁר יַחַד וְכָל הַפָּנִים מְאִירוֹת, וְנִמְצָא קֶשֶׁר אֶחָד, וְאָז הַמְּלָכִים נוֹעֲדוּ וּמִזְדַּמְּנִים יַחַד לְכַפֵּר עַל הַחֲטָאִים, לְהַעֲבִיר אוֹתָם. וְאָז הַמְּלָכִים נוֹעֲדוּ וְנִקְשָׁרִים יַחַד. עָבְרוּ יַחְדָּו, לְהָאִיר כָּל הַפָּנִים, וְשֶׁיִּהְיֶה הַכֹּל רָצוֹן אֶחָד.</p>\n<p>הֵמָּה רָאוּ כֵּן תָּמָהוּ, הֲתַעֲלֶה עַל דַּעְתְּךְ שֶׁהֵם מְלָכִים? אֶלָּא אֵלּוּ בַּעֲלֵי הַדִּינִים, שֶׁשִּׂמְחָתָם לַעֲשׂוֹת אֶת הַדִּין הַהוּא שֶׁהִצְטַוּוּ עָלָיו. וְאָז, כְּשֶׁהַמְּלָכִים מִזְדַּמְּנִים שְׁנֵיהֶם בְּרָצוֹן אֶחָד, אָז הֵמָּה רָאוּ אוֹתוֹ הָרָצוֹן שֶׁל שְׁנֵי עוֹלָמוֹת. כֵּן תָּמָהוּ נִבְהֲלוּ נֶחְפָּזוּ, מִשּׁוּם שֶׁכָּל בַּעֲלֵי הַדִּין נִכְנָעִים וְעוֹבְרִים מִן הָעוֹלָם וְלֹא יְכוֹלִים לִשְׁלֹט, וְאָז קִיּוּמָם עוֹבֵר, וּמַעֲבִירִים אֶת שִׁלְטוֹנָם.</p>\n<p>רַבִּי אֶלְעָזָר אוֹמֵר: וַיִּגַּשׁ אֵלָיו יְהוּדָה. מָה הַטַּעַם יְהוּדָה? מִשּׁוּם שֶׁכָּךְ צָרִיךְ, שֶׁהוּא עָרֵב, כְּמוֹ שֶׁנֶּאֱמַר כִּי עַבְדְּךְ עָרַב אֶת הַנַּעַר. וְסוֹד הַדָּבָר - יְהוּדָה וְיוֹסֵף כָּךְ הִצְטָרְכוּ לְהִתְקָרֵב יַחַד, מִשּׁוּם שֶׁיּוֹסֵף הוּא צַדִּיק, יְהוּדָה הוּא מֶלֶךְ, וְעַל כֵּן וַיִּגַּשׁ אֵלָיו יְהוּדָה, מִשּׁוּם שֶׁהַקִּרְבָה שֶׁלָּהֶם, שֶׁהִתְקָרְבוּ יַחַד, גָּרְמָה לְכַמָּה טוֹבוֹת בָּעוֹלָם, גָּרְמָה שָׁלוֹם לְכָל הַשְּׁבָטִים, גָּרְמָה לְשָׁלוֹם בֵּינֵיהֶם, גָּרְמָה לְיַעֲקֹב שֶׁהִתְקַיְּמָה רוּחוֹ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית מה) וַתְּחִי רוּחַ יַעֲקֹב אֲבִיהֶם. וְעַל כֵּן הַהִתְקָרְבוּת שֶׁל זֶה עִם זֶה הֻצְרְכָה בְּכָל הַצְּדָדִים, לְמַעְלָה וּלְמַטָּה.</p>"],[9522011414,"<p>רַבִּי אַבָּא פָּתַח וְאָמַר, (תהלים מח) יְפֵה נוֹף מְשׂוֹשׂ כָּל הָאָרֶץ הַר צִיּוֹן יַרְכְּתֵי צָפוֹן קִרְיַת מֶלֶךְ רָב. הַפָּסוּק הַזֶּה הוּא סוֹד הָאֱמוּנָה. יְפֵה נוֹף - זֶהוּ יוֹסֵף הַצַּדִּיק, שֶׁכָּתוּב בּוֹ וַיְהִי יוֹסֵף יְפֵה תֹאַר וִיפֵה מַרְאֶה. מְשׂוֹשׂ כָּל הָאָרֶץ - הוּא חֶדְוָה וְשִׂמְחָה לְמַעְלָה וּלְמַטָּה. הַר צִיּוֹן יַרְכְּתֵי צָפוֹן - מִשּׁוּם שֶׁבְּחֶלְקוֹ עוֹמֵד מִשְׁכַּן שִׁילֹה. הַר צִיּוֹן - זוֹ יְרוּשָׁלַיִם. יַרְכְּתֵי צָפוֹן, כָּךְ זֶה וַדַּאי לְמַעְלָה וּלְמַטָּה.</p>\n<p>קִרְיָת מֶלֶךְ רָב - מָקוֹם מְתֻקָּן הוּא כְּנֶגֶד מֶלֶךְ רָב, זֶה הַמֶּלֶךְ הֶעֶלְיוֹן שֶׁל הַכֹּל, קֹדֶשׁ הַקְּדָשִׁים, שֶׁהֲרֵי מִשָּׁם בָּא כָּל הָאוֹר וְכָל הַבְּרָכוֹת וְכָל הַשִּׂמְחָה שֶׁל הַכֹּל, שֶׁהֲרֵי מִשָּׁם כָּל הַפָּנִים מְאִירוֹת, וּבֵית הַמִּקְדָּשׁ מִתְבָּרֵךְ מִשָּׁם, וּכְשֶׁהִיא מִתְבָּרֶכֶת, מִשָּׁם יוֹצְאוֹת בְּרָכוֹת לְכָל הָעוֹלָם, שֶׁהֲרֵי מִשָּׁם כָּל הָעוֹלָם מִתְבָּרֵךְ.</p>"],[9522011415,"<p>רַבִּי יְהוּדָה וְרַבִּי יוֹסֵי נִפְגְּשׁוּ לִכְפַר חָנָן. בְּעוֹדָם יוֹשְׁבִים בְּבֵית מְלוֹנָם, בָּא אִישׁ אֶחָד, וּמַשָּׂא שֶׁל חֲמוֹר לְפָנָיו, וְנִכְנַס לַבַּיִת. בֵּין כָּךְ אָמַר רַבִּי יְהוּדָה לְרַבִּי יוֹסִי, הִנֵּה שָׁנִינוּ שֶׁדָּוִד הַמֶּלֶךְ הָיָה מִתְנַמְנֵם כְּמוֹ סוּס וּשְׁנָתוֹ מוּעֶטֶת, אֵיךְ הָיָה קָם בַּחֲצוֹת הַלַּיְלָה, הַשִּׁעוּר הַזֶּה הוּא קָטָן, וְלֹא הָיָה מִתְעוֹרֵר אֲפִלּוּ בִּשְׁלִישׁ הַלַּיְלָה?</p>\n<p>אָמַר לוֹ, בְּשָׁעָה שֶׁנִּכְנַס הַלַּיְלָה, הָיָה יוֹשֵׁב עִם כָּל גְּדוֹלֵי בֵיתוֹ וְדָן אֶת הַדִּין וְעוֹסֵק בְּדִבְרֵי תוֹרָה, וְאַחַר כָּךְ הָיָה יָשֵׁן שְׁנָתוֹ עַד חֲצוֹת הַלַּיְלָה, וְקָם בַּחֲצוֹת הַלַּיְלָה וּמִתְעוֹרֵר, וּמִשְׁתַּדֵּל בַּעֲבוֹדַת רִבּוֹנוֹ בְּשִׁירִים וְתִשְׁבָּחוֹת.</p>\n<p>בֵּינְתַיִם אָמַר הָאִישׁ הַהוּא, וְכִי הַדָּבָר הַזֶּה שֶׁאַתֶּם אוֹמְרִים הוּא כָּךְ? סוֹד הַדָּבָר יֵשׁ כָּאן, שֶׁהִנֵּה דָּוִד הַמֶּלֶךְ חַי וְקַיָּם לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים, וְדָוִד הַמֶּלֶךְ הָיָה שׁוֹמֵר כָּל יָמָיו שֶׁלֹּא יִטְעַם טַעַם מִיתָה, מִשּׁוּם שֶׁהַשֵּׁנָה אֶחָד מִשִּׁשִּׁים בְּמִיתָה הִיא, וְדָוִד, מִשּׁוּם מְקוֹמוֹ שֶׁהוּא חַי, לֹא הָיָה יָשֵׁן אֶלָּא שִׁשִּׁים נְשִׁימוֹת, שֶׁעַד שִׁשִּׁים נְשִׁימוֹת חָסֵר אַחַת הוּא חַי, מִשָּׁם וָהָלְאָה טוֹעֵם אָדָם טַעַם מִיתָה וְשׁוֹלֵט בּוֹ הַצַּד שֶׁל רוּחַ הַטֻּמְאָה.</p>\n<p>וְזֶה הָיָה שׁוֹמֵר דָּוִד הַמֶלֶךְ, שֶׁלֹּא יִטְעַם טַעַם שֶׁל מִיתָה, וְשׁוֹלֵט (שלא ישלט) בּוֹ צַד שֶׁל רוּחַ אַחֶרֶת, מִשּׁוּם שֶׁשִּׁשִּׁים נְשִׁימוֹת חָסֵר אַחַת הוּא הַסּוֹד שֶׁל הַחַיִּים שֶׁלְּמַעְלָה, עַד שִׁשִּׁים נְשִׁימוֹת שֶׁהֵם שִׁשִּׁים (חסר נשימה אחת) נְשִׁימוֹת עֶלְיוֹנוֹת, וְאֵלּוּ הַסּוֹד שֶׁלָּהֶן, שֶׁהַחַיִּים תְּלוּיִים בָּהֶם, וּמִכָּאן וָמַטָּה הוּא סוֹד הַמָּוֶת.</p>\n<p>וְעַל כֵּן דָּוִד הָיָה מְשַׁעֵר אֶת שִׁעוּר הַלַּיְלָה כְּדֵי שֶׁיִּתְקַיֵּם בַּחַיִּים, שֶׁלֹּא יִשְׁלֹט בּוֹ טַעַם הַמָּוֶת, וּכְשֶׁנֶּחֱלַק הַלַּיְלָה הָיָה דָוִד עוֹמֵד בִּמְקוֹמוֹ, מִשּׁוּם שֶׁכַּאֲשֶׁר מִתְעוֹרֵר חֲצוֹת הַלַּיְלָה וְהַכֶּתֶר הַקָּדוֹשׁ מִתְעוֹרֵר, צָרִיךְ שֶׁלֹּא יִמְצָא אֶת דָּוִד קָשׁוּר בְּמָקוֹם אַחֵר, בִּמְקוֹם הַמָּוֶת.</p>\n<p>מִשּׁוּם שֶׁכַּאֲשֶׁר נֶחֱלָק הַלַּיְלָה וְהַקְּדֻשָּׁה הָעֶלְיוֹנָה מִתְעוֹרֶרֶת, וְאָדָם שֶׁיָּשֵׁן בְּמִטָּתוֹ וְלֹא מִתְעוֹרֵר לְהַשְׁגִּיחַ בִּכְבוֹד רִבּוֹנוֹ, הִנֵּה הוּא נִקְשָׁר בְּסוֹד הַמָּוֶת, וְנִדְבָּק לְמָקוֹם אַחֵר, וְעַל כֵּן דָּוִד הַמֶּלֶךְ הָיָה עוֹמֵד לְהַשְׁגִּיחַ בִּכְבוֹד רִבּוֹנוֹ תָּמִיד, חַי אֵצֶל חַי, וְלֹא נִרְדַּם בַּשֵּׁנָה לִטְעֹם טַעַם הַמָּוֶת, וּמִשּׁוּם כָּךְ הָיָה מִתְנַמְנֵם כְּמוֹ סוּס, שִׁשִּׁים נְשִׁימוֹת, וְלֹא בִּשְׁלֵמוּת.</p>\n<p>בָּאוּ רַבִּי יְהוּדָה וְרַבִּי יוֹסֵי וּנְשָׁקוּהוּ. אָמְרוּ לוֹ, מַה שִּׁמְךְ? אָמַר לָהֶם, חִזְקִיָּה. אָמְרוּ לוֹ, יִישַׁר כֹּחֲךְ וְתִתְחַזֵּק תּוֹרָתְךְ. יָשְׁבוּ. אָמַר רַבִּי יְהוּדָה, הוֹאִיל וְהִתְחַלְתָּ, אֱמֹר לָנוּ מֵעַתָּה סוֹדוֹת עֶלְיוֹנִים שֶׁאָמַרְתָּ.</p>\n<p>פָּתַח וְאָמַר, (משלי ג) ה' בְּחָכְמָה יָסַד אָרֶץ כּוֹנֵן שָׁמַיִם בִּתְבוּנָה. בֹּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, רָאָה שֶׁלֹּא יָכוֹל לַעֲמֹד, עַד שֶׁבָּרָא אֶת הַתּוֹרָה, מִשּׁוּם שֶׁמִּמֶּנָּה יוֹצְאִים כָּל הַנְהָגוֹת הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים, וּבָהּ עוֹמְדִים עֶלְיוֹנִים וְתַחְתּוֹנִים. זֶהוּ שֶׁכָּתוּב ה' בְּחָכְמָה יָסַד אָרֶץ כּוֹנֵן שָׁמַיִם בִּתְבוּנָה, שֶׁהֲרֵי בְּחָכְמָה עוֹמְדִים כָּל הַקִּיּוּמִים שֶׁל הָעוֹלָם, וְכֻלָּם יוֹצְאִים מִתּוֹכָהּ.</p>\n<p>דָּבָר אַחֵר ה' בְּחָכְמָה יָסַד אָרֶץ - הָעוֹלָם הָעֶלְיוֹן לֹא נִבְרָא אֶלָּא מִתּוֹךְ הַחָכְמָה, וְהָעוֹלָם הַתַּחְתּוֹן לֹא נִבְרָא אֶלָּא מִתּוֹךְ הַחָכְמָה הַתַּחְתּוֹנָה, וְכֻלָּם יוֹצְאִים מִתּוֹךְ הַחָכְמָה הָעֶלְיוֹנָה וּמִתּוֹךְ הַחָכְמָה הַתַּחְתּוֹנָה. כּוֹנֵן שָׁמַיִם בִּתְבוּנָה. כּוֹנֵן, מַה זֶּה כּוֹנֵן? אֶלָּא כּוֹנֵן כָּל יוֹם וָיוֹם וְלֹא פוֹסֵק, וְלֹא נִתְקָן בִּזְמַן אֶחָד, אֶלָּא בְּכָל יוֹם וָיוֹם מַתְקִין אוֹתוֹ.</p>\n<p>וְהַיְנוּ סוֹד הַכָּתוּב (איוב טו) וְשָׁמַיִם לֹא זַכּוּ בְעֵינָיו. וְכִי תַעֲלֶה עַל דַּעְתְּךְ שֶׁהַחִסָּרוֹן הוּא מִשָּׁמַיִם? אֶלָּא חֲשִׁיבוּת הַשָּׁמַיִם הִיא מִשּׁוּם הַחֲבִיבוּת וְרָצוֹן רַב שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בָהֶם וַחֲבִיבוּתָם אֶצְלוֹ, שֶׁהֲרֵי אַף עַל גַּב שֶׁהוּא מַתְקִין אוֹתָם בְּכָל יוֹם וָיוֹם, אֵין דּוֹמֶה בְעֵינָיו שֶׁהֵם מְתֻקָּנִים כָּרָאוּי, מִשּׁוּם שֶׁאַהֲבָתָם אֶצְלוֹ, וּרְצוֹנוֹ לְהָאִיר לָהֶם תָּמִיד בְּלִי הֶפְסֵק, שֶׁהֲרֵי הָעוֹלָם הַבָּא מוֹצִיא אוֹרוֹת זוֹהֲרִים כָּל יוֹם וָיוֹם תָּמִיד בְּלִי הֶפְסֵק, כְּדֵי לְהָאִיר לָהֶם תָּמִיד, וְעַל כֵּן לֹא זַכּוּ בְעֵינָיו. לֹא זַכּוּ לְבַדּוֹ לֹא כָתוּב, אֶלָּא לֹא זַכּוּ בְעֵינָיו, וּמִשּׁוּם כָּךְ כּוֹנֵן שָׁמַיִם בִּתְבוּנָה.</p>\n<p>מִי הַשָּׁמַיִם? זֶה הַסּוֹד שֶׁל הָאָבוֹת, וְהַסּוֹד שֶׁל הָאָבוֹת זֶהוּ יַעֲקֹב, שֶׁהוּא הַכְּלָלוּת שֶׁלָּהֶם, מִשּׁוּם שֶׁיַּעֲקֹב הוּא הַבָּחִיר שֶׁבָּאָבוֹת, וְהוּא עוֹמֵד לְהָאִיר עַל הָעוֹלָם.</p>\n<p>וּמִשּׁוּם שֶׁהוּא הִסְתַּלֵּק לְתוֹךְ הָעוֹלָם הַבָּא, יָצָא מִמֶּנּוּ עָנָף אֶחָד יָפֶה לְמַרְאֶה, וְכָל הָאוֹרוֹת יוֹצְאִים מִמֶּנּוּ וְכָל הַשָּׂבָע וְשֶׁמֶן הַמִּשְׁחָה לְהָאִיר לָאָרֶץ, וּמִי הוּא? זֶה יוֹסֵף הַצַּדִּיק, שֶׁהוא נוֹתֵן שָׂבָע לְכָל הָעוֹלָם, וְהָעוֹלָם נִזּוֹן מִמֶּנּוּ. וּמִשּׁוּם כָּךְ, כָּל מַה שֶּׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם, הַכֹּל הוּא בְּסוֹד עֶלְיוֹן, וְהַכֹּל כָּרָאוּי.</p>\n<p>בֵּינְתַיִם בָּא רַבִּי אֶלְעָזָר. כֵּיוָן שֶׁרָאָה אוֹתָם, אָמַר, וַדַּאי שֶׁהַשְּׁכִינָה כָּאן. אָמַר לָהֶם, בַּמָּה עֲסַקְתֶּם? אָמְרוּ לוֹ אֶת כָּל הַמַּעֲשֶׂה. אָמַר, וַדַּאי שֶׁיָּפֶה אָמַר, אֲבָל אוֹתָם שִׁשִּׁים הַנְּשִׁימוֹת, וַדַּאי שֶׁשִּׁשִּׁים נְשִׁימוֹת הֵן שֶׁל חַיִּים, בֵּין לְמַעְלָה בֵּין לְמַטָּה. מִכָּאן וָהָלְאָה יֵשׁ שִׁשִּׁים נְשִׁימוֹת אֲחֵרוֹת שֶׁהֵן כֻּלָּן מִצַּד הַמָּוֶת, וְדַרְגַּת הַמָּוֶת עֲלֵיהֶן, וְנִקְרָאוֹת תַּרְדֵּמָה, וְכֻלָּן טַעַם הַמָּוֶת.</p>\n<p>וּמִשּׁוּם כָּךְ דָּוִד הַמֶּלֶךְ הוּא הָיָה נִדְבָּק לְאוֹתָם שִׁשִּׁים הַנְּשִׁימוֹת שֶׁל חַיִּים, וּמִשָּׁם וָהָלְאָה לֹא יָשַׁן כְּלָל. זֶהוּ שֶׁכָּתוּב (תהלים קלב) אִם אֶתֵּן שְׁנָת לְעֵינַי לְעַפְעַפַּי תְּנוּמָה. וְעַל כֵּן יָפֶה אָמַר, כְּדֵי שֶׁיָּקוּם דָּוִד חַי, בַּצַּד שֶׁל הַחַי, וְלֹא בְּצַד הַמָּוֶת. כֻּלָּם יָשְׁבוּ וְהִשְׁתַּדְּלוּ בַתּוֹרָה וְהִתְחַבְּרוּ יַחַד.</p>\n<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (שם פח) ה' אֱלֹהֵי יְשׁוּעָתִי יוֹם צָעַקְתִּי בַלַּיְלָה נֶגְדֶּךְ. בּא רְאֵה, דָּוִד הַמֶּלֶךְ הָיָה קָם בַּחֲצוֹת הַלַּיְלָה וּמִשְׁתַּדֵּל בַּתּוֹרָה בְּשִׁירִים וְתִשְׁבָּחוֹת לְשִׂמְחַת הַמֶּלֶךְ וְהַגְּבִירָה, וְזוֹ הָיְתָה שִׂמְחַת הָאֱמוּנָה בָּאָרֶץ, מִשּׁוּם שֶׁזֶּהוּ הַשֶּׁבַח שֶׁל הָאֱמוּנָה שֶׁנִּרְאֶה בָאָרֶץ.</p>\n<p>שֶׁהֲרֵי לְמַעְלָה פּוֹתְחִים בְּשִׂמְחָה שִׁירָה, כַּמָּה מַלְאָכִים עֶלְיוֹנִים בְּכַמָּה מִינִים שֶׁמְּשַׁבְּחִים בַּלַּיְלָה בְּכָל הַצְּדָדִים. כְּמוֹ כֵן לְמַטָּה בָּאָרֶץ, מִי שֶׁמְּשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאָרֶץ בַּלַּיְלָה, בּוֹ חָפֵץ הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכָל אוֹתָם הַמַּלְאָכִים הַקְּדוֹשִׁים שֶׁמְּשַׁבְּחִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, כֻּלָּם מַקְשִׁיבִים לְאוֹתוֹ שֶׁמְּשַׁבֵּחַ אוֹתוֹ בַּלַּיְלָה בָּאָרֶץ, שֶׁהַשֶּׁבַח הַזֶּה הוּא בִּשְׁלֵמוּת, לְהַעֲלוֹת אֶת כְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא מִלְּמַטָּה וּלְזַמֵּר בַּשִּׂמְחָה שֶׁל הַיִּחוּד.</p>\n<p>בֹּא רְאֵה, דָּוִד הַמֶּלֶךְ כָּתַב, ה' אֱלֹהֵי יְשׁוּעָתִי וְגוֹ'. ה' אֱלֹהֵי יְשׁוּעָתִי, מָתַי הוּא יְשׁוּעָתִי? בְּאוֹתוֹ יוֹם שֶׁהִקְדַּמְתִּי שֶׁבַח בַּלַּיְלָה אֶצְלְךְ, אָז הוּא יְשׁוּעָתִי בַּיּוֹם.</p>\n<p>וּבֹא רְאֵה, שֶׁהֲרֵי בַּלַּיְלָה, מִי שֶׁמְּשַׁבֵּחַ אֶת רִבּוֹנוֹ בַּשֶּׁבַח שֶׁל הַתּוֹרָה, אָז מִתְחַזֵּק בְּחֹזֶק בַּיּוֹם בְּצַד הַיָּמִין, שֶׁהִנֵּה חוּט אֶחָד יוֹצֵא מִצַּד הַיָּמִין, וְאָז נִמְשָׁךְ עָלָיו וּמִתְגַּבֵּר בּוֹ, וְעַל כֵּן אָמַר ה' אֱלֹהֵי יְשׁוּעָתִי יוֹם צָעַקְתִּי וְגוֹ'.</p>\n<p>וּמִשּׁוּם כָּךְ אָמַר לֹא הַמֵּתִים יְהַלְלוּ יָהּ. לֹא הַמֵּתִים, מִשּׁוּם שֶׁצָּרִיךְ לְשַׁבֵּחַ חַי לְחַי. וּמֵת לְחַי לֹא כֵן, שֶׁכָּתוּב לֹא הַמֵּתִים יְהַלְלוּ יָהּ, וַאֲנַחְנוּ נְבָרֵךְ יָהּ, שֶׁהֲרֵי אָנוּ חַיִּים, וְאֵין לָנוּ חֵלֶק בְּצַד הַמָּוֶת כְּלָל. חִזְקִיָּהוּ אָמַר, (ישעיה לח) חַי חַי הוּא יוֹדֶךְ כָּמוֹנִי, מִשּׁוּם שֶׁחַי מִתְקָרֵב לְחַי. דָּוִד הַמֶּלֶךְ הוּא חַי, וְהַקִּרְבָה שֶׁלּוֹ לְחַי הָעוֹלָמִים, וּמִי שֶׁנִּקְרָב אֵלָיו הוּא חַי, שֶׁכָּתוּב וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם, וְכָתוּב וּבְנָיָהוּ בֶּן יְהוֹיָדָע בֶּן אִישׁ חַי רַב פְּעָלִים מִקַּבְצְאֵל.</p>"],[9522011416,"<p>פָּתַח אוֹתוֹ הַיְּהוּדִי אַחֲרָיו וְאָמַר, (דברים ח) וְאָכַלְתָּ וְשָׂבָעְתָּ וּבֵרַכְתָּ אֶת ה' אֱלֹהֶיךְ. וְכִי לֹא מְבָרְכִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא טֶרֶם נֹאכַל, וַהֲרֵי יֵשׁ לָנוּ לְהַקְדִּים בַּבֹּקֶר, וּלְסַדֵּר אֶת הַשֶּׁבַח שֶׁלּוֹ (של רבונו) כָּרָאוּי, וּלְבָרֵךְ אֶת שְׁמוֹ טֶרֶם שֶׁיְּבָרֵךְ מִישֶׁהוּ אַחֵר בָּעוֹלָם, וְכָתוּב (ויקרא יט) לֹא תֹאכְלוּ עַל הַדָּם, אָסוּר לוֹ לֶאֱכֹל טֶרֶם שֶׁיְּבָרֵךְ אֶת רִבּוֹנוֹ, וְעַכְשָׁו כָּתוּב וְאָכַלְתָּ וְשָׂבָעְתָּ וּבֵרַכְתָּ?</p>\n<p>אֶלָּא, זוֹ הַבְּרָכָה שֶׁל תְּפִלַּת הַיִּחוּד, וְזוֹ בִּרְכַּת הַמָּזוֹן, לְהַרְאוֹת כְּלַפֵּי דַרְגַּת הָאֱמוּנָה שָׂבָע כָּרָאוּי. וְאָז צָרִיךְ לְבָרֵךְ אוֹתוֹ כָּרָאוּי, שֶׁאוֹתָהּ הַדַּרְגָּה שֶׁל הָאֱמוּנָה תִּתְרַוֶּה וְתִתְבָּרֵךְ, וְיִתְמַלֵּא שִׂמְחָה מֵהַחַיִּים שֶׁלְּמַעְלָה כְּמוֹ שֶׁצָּרִיךְ, כְּדֵי לָתֵת לָנוּ מְזוֹנוֹת.</p>\n<p>שֶׁהֲרֵי קָשִׁים מְזוֹנוֹתָיו שֶׁל אָדָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמוֹ קְרִיעַת יַם סוּף, מָה הַטַּעַם? מִשּׁוּם שֶׁהַמָּזוֹן שֶׁל הָעוֹלָם שֶׁלְּמַעְלָה הוּא, שֶׁשָּׁנִינוּ בָּנִים חַיִּים וּמְזוֹנוֹת וְכוּ'. וּמִשּׁוּם כָּךְ קָשִׁים לְפָנָיו מְזוֹנוֹת הָעוֹלָם. שֶׁהֲרֵי בְּמַזָּל תָּלוּי הַדָּבָר שֶׁיּוֹצְאִים מִמֶּנּוּ מְזוֹנוֹת וְחַיִּים וּבָנִים. וּמִשּׁוּם כָּךְ קָשִׁים לְפָנָיו הַמְּזוֹנוֹת שֶׁל הָעוֹלָם, שֶׁהֲרֵי זֶה לֹא עוֹמֵד בִּרְשׁוּתוֹ עַד שֶׁהוּא יִתְבָּרֵךְ.</p>\n<p>כְּמוֹ כֵן הַזִּוּוּגִים שֶׁל הָעוֹלָם קָשִׁים לְפָנָיו, וְהַכֹּל מִשּׁוּם שֶׁרְקִיעַ וִילוֹן אֵינוֹ מְשַׁמֵּשׁ כְּלוּם, וְכָל שֶׁכֵּן הַדְּבָרִים הַלָּלוּ שֶׁעוֹמְדִים לְמַעְלָה בְּמָקוֹם אַחֵר, וְעַל כֵּן צָרִיךְ לְהִתְבָּרֵךְ.</p>\n<p>בֹּא רְאֵה, כָּל הַזִּוּוּגִים שֶׁל הָעוֹלָם קָשִׁים לִפְנֵי הַדַּרְגָּה הַזּוֹ, מִשּׁוּם שֶׁכַּאֲשֶׁר הַזִּוּוּג הַקָּדוֹשׁ נִמְצָא, יוֹצְאוֹת כָּל הַנְּשָׁמוֹת מִתּוֹךְ הַמַּזָּל הַזֶּה לְמַעְלָה, שֶׁהוּא אוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא. וְכַאֲשֶׁר הַהִשְׁתּוֹקְקוּת נִמְצֵאת מִלְּמַטָּה לְמַעְלָה, וְאָז פּוֹרְחוֹת הַנְּשָׁמוֹת, וְנִתָּנוֹת כֻּלָּן זָכָר וּנְקֵבָה יַחַד בַּדַּרְגָּה הַזּוֹ, וְאַחַר כָּךְ הוּא מַפְרִיד אוֹתָן, כָּל אַחַת וְאַחַת לִמְקוֹמָהּ כָּרָאוּי לָהּ. וְאַחַר כָּךְ קָשִׁים לִפְנֵי הַדַּרְגָּה הַזּוֹ לְחַבֵּר אוֹתָם כְּבָרִאשׁוֹנָה, מִשּׁוּם שֶׁאֵין מִתְחַבְּרִים, רַק בְּאוֹתָם דַּרְכֵי הָאָדָם, וְהַכֹּל תְּלוּיִים לְמַעְלָה.</p>\n<p>וְעַל כֵּן קָשִׁים לְפָנָיו כִּקְרִיעַת יַם סוּף. שֶׁהֲרֵי קְרִיעַת הַיָּם שֶׁיִּפָּתְחוּ בוֹ שְׁבִילִים הִיא לְמַעְלָה, וּכְמוֹ שֶׁנִּפְתָּחִים בּוֹ שְׁבִילִים וּדְרָכִים, כָּךְ נִבְקָע וְנִפְתָּח.</p>\n<p>וּמִשּׁוּם כָּךְ הַכֹּל תָּלוּי לְמַעְלָה, וּצְרִיכִים לְבָרֵךְ אוֹתוֹ וְלָתֵת לוֹ חֹזֶק מִלְּמַטָּה כְּדֵי שֶׁיִּתְבָּרֵךְ מִלְמַעְלָה וְיִתְחַזֵּק כָּרָאוּי, וְעַל כֵּן כָּתוּב וּבֵרַכְתָּ אֶת ה', דַּוְקָא אֶת.</p>\n<p>וּכְלַפֵּי הַמָּקוֹם הַזֶּה צָרִיךְ לְהַרְאוֹת לְפָנָיו שּׁבַע וְהֶאָרַת פָּנִים, וּכְלַפֵּי הַצַּד הָאַחֵר, בִּזְמַן שֶׁשּׁוֹלֵט בָּעוֹלָם, צָרִיךְ לְהַרְאוֹת לְפָנָיו רָעָב, שֶׁאוֹתָהּ הַדַּרְגָּה הִיא שֶׁל רָעָב, וְרָאוּי לְהַרְאוֹת לְפָנֶיהָ רָעָב וְלֹא שָׂבָע, הוֹאִיל וְהַשָּׂבָע לֹא שׁוֹלֵט בָּעוֹלָם, וְעַל כֵּן וְאָכַלְתָּ וְשָׂבָעְתָּ וּבֵרַכְתָּ אֶת ה' אֱלֹהֶיךְ. אָמַר רַבִּי אֶלְעָזָר, כָּךְ זֶה וַדַּאי וְכָךְ צָרִיךְ!</p>\n<p>אָמַר רַבִּי יְהוּדָה, אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁקִּרְבָתָם הִיא שָׁלוֹם בָּעוֹלָם, מִשּׁוּם שֶׁיּוֹדְעִים לְיַחֵד אֶת הַיִּחוּד וּמְקָרְבִים קִרְבָה לְהַרְבּוֹת שָׁלוֹם בָּעוֹלָם, שֶׁהֲרֵי יוֹסֵף וִיהוּדָה בְּטֶרֶם הִתְקָרְבוּ זֶה עִם זֶה, לֹא הָיָה שָׁלוֹם. כֵּיוָן שֶׁהִתְקָרְבוּ יוֹסֵף וִיהוּדָה יַחַד, אָז הִרְבּוּ שָׁלוֹם בָּעוֹלָם, וְהַשִּׂמְחָה נוֹסְפָה לְמַעְלָה וּלְמַטָּה, כְּמוֹ שֶׁהַקִּרְבָה שֶׁל יְהוּדָה וְיוֹסֵף, וְכָל הַשְּׁבָטִים נִמְצְאוּ יַחַד עִם יוֹסֵף, וְאוֹתָהּ הַקִּרְבָה הִרְבְּתָה שָׁלוֹם בָּעוֹלָם, כְּמוֹ שֶׁבֵּאַרְנוּ שֶׁכָּתוּב וַיִּגַּשׁ אֵלָיו יְהוּדָה.</p>"],[9522011417,"<p>וְלֹא יָכֹל יוֹסֵף לְהִתְאַפֵּק לְכֹל הַנִּצָּבִים עָלָיו וְגוֹ'. רַבִּי חִיָּיא פָּתַח וְאָמַר, (תהלים קיב) פִּזַּר נָתַן לָאֶבְיוֹנִים צִדְקָתוֹ עֹמֶדֶת לָעַד קַרְנוֹ תָּרוּם בְּכָבוֹד. בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָא אֶת הָעוֹלָם וְהִשְׁלִיט עָלָיו אֶת הָאָדָם שֶׁיִּהְיֶה מֶלֶךְ עַל הַכֹּל.</p>\n<p>וְהָאָדָם הַזֶּה נִפְרָדִים מִמֶּנּוּ בָּעוֹלָם כַּמָּה מִינִים, מֵהֶם צַדִּיקִים וּמֵהֶם רְשָׁעִים, מֵהֶם טִפְּשִׁים וּמֵהֶם חֲכָמִים, וְכֻלָּם מִתְקַיְּמִים בָּעוֹלָם, עֲשִׁירִים וַעֲנִיִּים, וְכֻלָּם כְּדֵי לִזְכּוֹת אֵלּוּ בְאֵלּוּ, לִזְכּוֹת צַדִּיקִים עִם רְשָׁעִים, לִזְכּוֹת חֲכָמִים עִם טִפְּשִׁים, לִזְכּוֹת עֲשִׁירִים עִם עֲנִיִּים, שֶׁהֲרֵי מִשּׁוּם כָּךְ זוֹכֶה הָאָדָם לְחַיֵּי הָעוֹלָם וְנִקְשָׁר בְּעֵץ הַחַיִּים. וְלֹא עוֹד, אֶלָּא שֶׁהִנֵּה הַצְּדָקָה שֶׁהוּא עוֹשֶׂה עוֹמֶדֶת לְעוֹלָמִים, שֶׁכָּתוּב וְצִדְקָתוֹ עֹמֶדֶת לָעַד.</p>\n<p>פִּזַּר נָתַן לָאֶבְיוֹנִים. רַבִּי אֶלְעָזָר אָמַר, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, הֶעֱמִיד אוֹתוֹ עַל עַמּוּד אֶחָד וּשְׁמוֹ צַדִּיק, וְהַצַּדִּיק הַזֶּה הוּא הַקִּיּוּם שֶׁל הָעוֹלָם, וְזֶה הוּא שֶׁמַּשְׁקֶה וְזָן לַכֹּל, שֶׁכָּתוּב (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים.</p>\n<p>וּמִשָּׁם יִפָּרֵד, מַה זֶּה יִפָּרֵד? אֶלָּא הַמָּזוֹן הַהוּא וְהַמַּשְׁקֶה שֶׁל הַנָּהָר הַהוּא נוֹטֵל הַגָּן הַכֹּל, וְאַחַר כָּךְ מִתְפַּזֵר הַמַּשְׁקֶה הַהוּא לְאַרְבָּעָה צְדָדִים שֶׁל הָעוֹלָם, וְכַמָּה הֵם שֶׁמְּצַפִּים לִהְיוֹת מֻשְׁקִים וּלְהִזּוֹן מִשָּׁם, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קמה) עֵינֵי כֹל אֵלֶיךְ יְשַׂבֵּרוּ וְאַתָּה נוֹתֵן לָהֶם אֶת אָכְלָם בְּעִתּוֹ. וּמִשּׁוּם כָּךְ פִּזַּר נָתַן לָאֶבְיוֹנִים - זֶה צַדִּיק. צִדְקָתוֹ עֹמֶדֶת לָעַד - זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁמִּשּׁוּם כָּךְ הִיא עוֹמֶדֶת בְּסוֹד שֶׁל שָׁלוֹם בְּקִיּוּם שָׁלֵם. רָשָׁע יִרְאֶה וְכָעָס - זוֹ מַלְכוּת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת.</p>\n<p>בֹּא רְאֵה, מַלְכוּת שָׁמַיִם הִיא בֵּית הַמִּקְדָּשׁ, לְקַיֵּם כָּל הָעֲנִיִּים בְּתוֹךְ הַצֵּל שֶׁל רֵאשִׁית הַשְּׁכִינָה, וְהַצַּדִּיק הַזֶּה הוּא נִקְרָא גַּבַּאי צְדָקָה, לָחֹן וְלָזוּן אֶת הַכֹּל, שֶׁכָּתוּב פִּזַּר נָתַן לָאֶבְיוֹנִים, מִשּׁוּם כָּךְ גַּבָּאֵי צְדָקָה נוֹטְלִים שָׂכָר כְּנֶגֶד כָּל הַנּוֹתְנִים צְדָקָה.</p>\n<p>בֹּא רְאֵה, וְלֹא יָכֹל יוֹסֵף לְהִתְאַפֵּק לְכָל הַנִּצָּבִים - אֵלּוּ הֵם כָּל הָעוֹמְדִים לְהִזּוֹן וּלְהִשָּׁקוֹת מִמֶּנּוּ. וְלֹא עָמַד אִישׁ אִתּוֹ בְּהִתְוַדַּע יוֹסֵף אֶל אֶחָיו. אִתּוֹ - זוֹ כְּנֶסֶת יִשְׂרָאֵל. אֶחָיו - אֵלּוּ שְׁאָר הַמֶּרְכָּבוֹת הַחֲיָלוֹת, שֶׁכָּתוּב בָּהֶם לְמַעַן אַחַי וְרֵעַי. דָּבָר אַחֵר וְלֹא עָמַד אִישׁ אִתּוֹ - בִּזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בָּא לְהִתְחַבֵּר עִם כְּנֶסֶת יִשְׂרָאֵל. בְּהִתְוַדַּע יוֹסֵף אֶל אֶחָיו, בִּזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה מִתְחַבֵּר בָּהֶם בְּיִשְׂרָאֵל, מִשּׁוּם שֶׁהֵם נוֹטְלִים לְבַדָּם, וְלֹא חִבּוּר שֶׁל עַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת עִמָּם. מִשּׁוּם כָּךְ, (במדבר כט) בַּיּוֹם הַשְּׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם, שֶׁהֲרֵי בַּזְּמַן הַזֶּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ בְּחִבּוּר אֶחָד עִם יִשְׂרָאֵל, שֶׁכָּתוּב בָּהֶם לְמַעַן אַחַי וְרֵעַי, כְּמוֹ שֶׁבֵּאֲרוּהָ.</p>\n<p>רַבִּי יֵיסָא פָּתַח הַפָּסוּק, בִּזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יָקִים אֶת כְּנֶסֶת יִשְׂרָאֵל מִן הֶעָפָר וְיִרְצֶה לְהִנָּקֵם נְקָמָה מֵעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, אֲזַי כָּתוּב (ישעיה סג) וּמֵעַמִּים אֵין אִישׁ אִתִּי, וְכָתוּב כָּאן וְלֹא עָמַד אִישׁ אִתּוֹ בְּהִתְוַדַּע יוֹסֵף אֶל אֶחָיו, כְּמוֹ שֶׁנֶּאֱמַר וַיְנַטְּלֵם וַיְנַשְּׂאֵם כָּל יְמֵי עוֹלָם.</p>\n<p>וְלֹא יָכֹל יוֹסֵף לְהִתְאַפֵּק. רַבִּי חִזְקִיָּה פָּתַח וְאָמַר, (תהלים קכג) שִׁיר הַמַּעֲלוֹת אֵלֶיךְ נָשָׂאתִי אֶת עֵינַי הַיֹּשְׁבִי בַּשָּׁמָיִם. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ וְנִתְבָּאֵר, אֲבָל בּא רְאֵה, אֵלֶיךְ נָשָׂאתִי אֶת עֵינַי, וְכָתוּב (תהלים קכא) אֶשָּׂא עֵינַי אֶל הֶהָרִים. אֶלָּא, זֶה לְמַעְלָה וְזֶה לְמַטָּה. אֶשָּׂא עֵינַי אֶל הֶהָרִים - זֶה לְמַעְלָה, כְּדֵי לְהַמְשִׁיךְ בְּרָכוֹת מִמַּעְלָה לְמַטָּה, מֵהֶהָרִים הַלָּלוּ הָעֶלְיוֹנִים לִמְשֹׁךְ מֵהֶם בְּרָכוֹת לִכְנֶסֶת יִשְׂרָאֵל שֶׁמִּתְבָּרֶכֶת מֵהֶם. אֵלֶיךְ נָשָׂאתִי אֶת עֵינַי, לְצַפּוֹת וּלְחַכּוֹת לְאוֹתָן בְּרָכוֹת שֶׁיּוֹרְדוֹת מִשָּׁם לְמַטָּה.</p>\n<p>הַיּשְׁבִי בַּשָּׁמָיִם, שֶׁכָּל תָּקְפָּהּ וְקִיּוּמָהּ וְחֵילָהּ הוּא בַּשָּׁמַיִם. מִשּׁוּם שֶׁכַּאֲשֶׁר הַיּוֹבֵל פּוֹתֵחַ הַמַּעְיָנוֹת שֶׁל כָּל אוֹתָם הַשְּׁעָרִים, כֻּלָּם עוֹמְדִים בַּשָּׁמַיִם. וְכֵיוָן שֶׁשָּׁמַיִם נוֹטְלִים כָּל אוֹתָם אוֹרוֹת שֶׁיּוֹצְאִים מֵהַיּוֹבֵל, אָז הוּא זָן וּמַשְׁקֶה אֶת כְּנֶסֶת יִשְׂרָאֵל עַל יְדֵי צַדִּיק אֶחָד.</p>\n<p>וְכֵיוָן שֶׁזֶּה מִתְעוֹרֵר אֵלֶיהָ, כַּמָּה הֵם שֶׁעוֹמְדִים בְּכָל הַצְּדָדִים לִהְיוֹת מֻשְׁקִים וּלְהִתְבָּרֵךְ מִשָּׁם, כְּמוֹ שֶׁנֶּאֱמַר הַכְּפִירִים שּאֲגִים לַטָּרֶף וּלְבַקֵּשׁ מֵאֵל אָכְלָם. וְאָז הִיא עוֹלָה בְּסוֹד הַסּוֹדוֹת כָּרָאוּי (לו), וּמְקַבֶּלֶת עִדּוּנִים מִבַּעְלָהּ כָּרָאוּי, וְכָל הָעוֹמְדִים בְּכָל הַצְּדָדִים עוֹמְדִים לְבַדָּם, כְּמוֹ שֶׁנֶּאֱמַר וְלֹא עָמַד אִישׁ אִתּוֹ, שֶׁכָּתוּב וַיִּקְרָא הוֹצִיאוּ כָל אִישׁ מֵעָלָי. וְאַחַר שֶׁהִיא מְקַבֶּלֶת עִדּוּנִים מִבַּעְלָהּ, כֻּלָּם נִשְׁקִים לְאַחַר מִכֵּן וְנִזּוֹנִים, כְּמוֹ שֶׁנֶּאֱמַר יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי יִשְׁבְּרוּ פְרָאִים צְמָאָם.</p>"],[9522011418,"<p>רַבִּי יוֹסֵי פָּתַח הַפָּסוּק בְּאֵלִיָּהוּ, שֶׁכָּתוּב (מלכים א יז) וַיִּקְרָא אֶל ה' וַיֹּאמַר ה' אֱלֹהָי הֲגַם עַל הָאַלְמָנָה אֲשֶׁר אֲנִי מִתְגּוֹרֵר עִמָּהּ הֲרֵעוֹתָ לְהָמִית אֶת בְּנָהּ. בֹּא רְאֵה, שְׁנַיִם הָיוּ שֶׁאָמְרוּ דְבָרִים כְּנֶגֶד הַקָּדוֹשׁ בָּרוּךְ הוּא, מֹשֶׁה וְאֵלִיָּהוּ. מֹשֶׁה אָמַר (שמות ה) לָמָה הֲרֵעֹתָה לָעָם הַזֶּה. וְאֵלִיָּהוּ אָמַר, הֲרֵעוֹתָ לְהָמִית אֶת בְּנָהּ. וּשְׁנֵיהֶם אָמְרוּ דָבָר אֶחָד.</p>\n<p>מָה הַטַּעַם? אֶלָּא סוֹד הוּא. מֹשֶׁה אָמַר לָמָה הֲרֵעֹתָה, מָה הַטַּעַם? אֶלָּא מִשּׁוּם שֶׁנִּתְּנָה רְשׁוּת לַצַּד הָאַחֵר לִשְׁלֹט עַל יִשְׂרָאֵל. הֲרֵעֹתָה - נָתַתָּ רְשׁוּת לַצַּד הָאַחֵר שֶׁל רַע לִשְׁלֹט עֲלֵיהֶם. אֵלִיָּהוּ אָמַר הֲרֵעוֹתָ - נָתַן רְשׁוּת לַצַּד הָרָע לִטֹּל נִשְׁמָתוֹ שֶׁל זֶה, וְזֶהוּ הוּא הֲרֵעוֹתָ, וְהַכֹּל סוֹד אֶחָד.</p>\n<p>בֹּא רְאֵה, אֵלִיָּהוּ אָמַר, הֲגַם עַל הָאַלְמָנָה אֲשֶׁר אֲנִי מִתְגּוֹרֵר עִמָּהּ. מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לוֹ לְאֵלִיָּהוּ, הִנֵּה צִוִּיתִי שָׁם אִשָּׁה אַלְמָנָה לְכַלְכְּלֶךְ, וְכָל מִי שֶׁזָּן וּמְפַרְנֵס לְמִי שֶׁצָּרִיךְ לוֹ, וְכָל שֶׁכֵּן בִּימֵי רָעָב, הֲרֵי נֶאֱחָז בְּעֵץ הַחַיִּים, וְגוֹרֵם לוֹ וּלְבָנָיו חַיִּים, וְהִנֵּה בֵּאַרְנוּ. וְעַכְשָׁו אֵלִיָּהוּ אָמַר, כָּל מִי שֶׁמְּקַיֵּם נֶפֶשׁ בָּעוֹלָם, זוֹכֶה לוֹ חַיִּים, וְזוֹכֶה לְהֵאָחֵז בְּעֵץ הַחַיִּים, וְעַכְשָׁו שׁוֹלֵט עֵץ הַמָּוֶת, הַצַּד שֶׁל רַע, עַל הָאַלְמָנָה שֶׁאַתָּה צִוִּיתָ לָזוּן אוֹתִי, מִשּׁוּם כָּךְ הֲרֵעוֹתָ (למה הרעתה).</p>\n<p>וְאִם תֹּאמַר שֶׁרַע לֹא נַעֲשֶׂה לְאִישׁ מֵעִם הַקָּדוֹשׁ בָּרוּךְ הוּא - בֹּא רְאֵה, בִּזְמַן שֶׁאָדָם הוֹלֵךְ לְיָמִין, שְׁמִירָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא תָּמִיד אֶצְלוֹ, וְלֹא יָכוֹל הַצַּד הָאַחֵר לִשְׁלֹט עָלָיו, וְהָרָע הַזֶּה נִכְנָע לְפָנָיו וְלֹא יָכוֹל לִשְׁלֹט. וְכֵיוָן שֶׁשְּׁמִירַת הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹבֶרֶת מִמֶּנּוּ, מִשּׁוּם שֶׁהוּא נִדְבָּק בָּרָע, אָז אוֹתוֹ הָרָע, כֵּיוָן שֶׁרוֹאֶה שֶׁאֵין עִמּוֹ שְׁמִירָה, אָז שׁוֹלֵט עָלָיו וּבָא לְהַשְׁמִיד אוֹתוֹ, וְאָז נִתֶּנֶת לוֹ רְשׁוּת וְנוֹטֵל אֶת נִשְׁמָתוֹ.</p>\n<p>מֹשֶׁה אָמַר לָמָה הֲרֵעֹתָה, שֶׁנִּתְּנָה רְשׁוּת לַצַּד הָרָע לִשְׁלֹט עַל יִשְׂרָאֵל, לִהְיוֹת בַּשִּׁעְבּוּד שֶׁלּוֹ. דָּבָר אַחֵר לָמָה הֲרֵעֹתָה - שֶׁרָאָה כַּמָּה מֵהֶם שֶׁהָיוּ מֵתִים וְנִמְסְרוּ לַצַּד הָרָע.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁהַטּוֹב מִתְעוֹרֵר, שֶׁהוּא הַיָּמִין, כָּל הַשִּׂמְחָה וְכָל הַטּוּב וְכָל הַבְּרָכוֹת נִמְצָאוֹת, וְהַכֹּל הוּא בַּחֲשַׁאי, כְּמוֹ שֶׁבֵּאֲרוּהָ שֶׁאוֹמְרִים בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד בַּחֲשַׁאי, וְזֶה הַסּוֹד, מִשּׁוּם (שזהו יחוד) שֶׁאָז הוּא הַיִּחוּד כָּרָאוּי.</p>\n<p>אָמַר רַבִּי חִיָּיא, וְכִי אֵלִיָּהוּ, כֵּיוָן שֶׁהוּא גּוֹזֵר וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְקַיֵּם, וְהוּא גָּזַר עַל הַשָּׁמַיִם שֶׁלֹּא לְהוֹרִיד טַל וּמָטָר, אֵיךְ הוּא פָּחַד מֵאִיזֶבֶל שֶׁשָּׁלְחָה לוֹ, שֶׁכָּתוּב (מלכים א יט) כִּי כָעֵת מָחָר אָשִׂים אֶת נַפְשְׁךְ כְּנֶפֶשׁ אַחַד מֵהֶם, וּמִיָּד פָּחַד וּבָרַח עַל נַפְשׁוֹ?</p>\n<p>אָמַר לוֹ רַבִּי יוֹסֵי, הִנֵּה פֵּרְשׁוּהָ שֶׁהַצַּדִּיקִים לֹא רוֹצִים לְהַטְרִיחַ אֶת רִבּוֹנָם בְּמָקוֹם שֶׁנֵּזֶק נִמְצָא (לו) לָעַיִן, כְּמוֹ שֶׁשְּׁמוּאֵל, שֶׁכָּתוּב (שמואל א טז) אֵיךְ אֵלֵךְ וְשָׁמַע שָׁאוּל וַהֲרָגָנִי. אָמַר לוֹ, עֶגְלַת בָּקָר תִּקַּח בְּיָדֶךְ, מִשּׁוּם שֶׁצַּדִּיקִים לֹא רוֹצִים לְהַטְרִיחַ אֶת רִבּוֹנָם בְּמָקוֹם שֶׁנִּמְצָא נֶזֶק. אַף כָּךְ אֵלִיָּהוּ, כֵּיוָן שֶׁרָאָה שֶׁנֶּזֶק נִמְצָא, לֹא רָצָה לְהַטְרִיחַ אֶת רִבּוֹנוֹ.</p>\n<p>אָמַר לוֹ, אֲנִי שָׁמַעְתִּי דָבָר, שֶׁהִנֵּה בְּאֵלִיָּהוּ לֹא כָתוּב בּוֹ וַיִּירָא וַיֵּלֶךְ אֶל נַפְשׁוֹ, אֶלָּא וַיַּרְא, רְאִיָּה רָאָה. וּמָה רָאָה? אֶלָּא רָאָה שֶׁהִנֵּה מִכַּמָּה שָׁנִים הוֹלֵךְ אַחֲרָיו מַלְאַךְ הַמָּוֶת, וְלֹא נִמְסָר בְּיָדוֹ, וְעַכְשָׁו וַיֵּלֶךְ אֶל נַפְשׁוֹ. מַה זֶּה וַיֵּלֶךְ אֶל נַפְשׁוֹ? הָלַךְ לְקִיּוּם הַנֶּפֶשׁ, וּמִי הוּא? עֵץ הַחַיִּים לְהִדָּבֵק שָׁם.</p>\n<p>בֹּא רְאֵה, כֻּלָּם כָּתוּב אֶת נַפְשׁוֹ, וְכָאן כָּתוּב אֶל נַפְשׁוֹ, וְסוֹד זֶה שָׁמַעְתִּי, שֶׁאָמַר רַבִּי שִׁמְעוֹן, כָּל הַנְּשָׁמוֹת שֶׁל הָעוֹלָם, כֻּלָּם יוֹצְאִים מֵאוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, וְאֶת כֻּלָּם הוּא לוֹקֵחַ אוֹתוֹ צְרוֹר הַחַיִּים, וּכְשֶׁהַנְּקֵבָה מִתְעַבֶּרֶת מִן הַזָּכָר, כֻּלָּם בִּתְשׁוּקַת שְׁנֵי הַצְּדָדִים, בִּתְשׁוּקַת הַנְּקֵבָה לַזָּכָר, וּכְשֶׁתְּשׁוּקַת הַזָּכָר יוֹצֵאת בְּרָצוֹן, אָז אוֹתָן הַנְּשָׁמוֹת בְּקִיּוּם יוֹתֵר, מִשּׁוּם שֶׁהַכֹּל בִּתְשׁוּקָה וְרָצוֹן שֶׁל עֵץ הַחַיִּים. וְאֵלִיָּהוּ, מִשּׁוּם שֶׁהָיָה מֵאוֹתוֹ רָצוֹן יוֹתֵר מֵאָדָם אַחֵר, הִתְקַיֵּם.</p>\n<p>וּמִשּׁוּם כָּךְ כָּתוּב אֶל נַפְשׁוֹ, וְלֹא כָתוּב אֶת נַפְשׁוֹ, שֶׁהֲרֵי אֶת נַפְשׁוֹ - זוֹ הַנְּקֵבָה. וְאִם תֹּאמַר וְאֶל הָאִשָּׁה אָמַר - הַכְּלָלוּת שֶׁל זָכָר וּנְקֵבָה כְּשֶׁהִיא בְּתוֹךְ הַזָּכָר, אָז וְאֶל הָאִשָּׁה אָמַר. אֶת הָאִשָּׁה - הַנְּקֵבָה לְבַדָּהּ, וְלֹא שֶׁל הַזָּכָר. כְּמוֹ זֶה אֶל נַפְשׁוֹ - הַזָּכָר לְבַדּוֹ. אֶת נַפְשׁוֹ - הַנְּקֵבָה לְבַדָּהּ וְלֹא הִתְכַּלְּלוּת שֶׁל זָכָר. וּמִשּׁוּם שֶׁהוּא מִצַּד הַזָּכָר יוֹתֵר מִכָּל בְּנֵי הָעוֹלָם, הִתְקַיֵּם בְּקִיּוּמוֹ יוֹתֵר, וְלֹא מֵת כִּשְׁאָר בְּנֵי הָעוֹלָם, מִשּׁוּם שֶׁהַכֹּל הוּא מֵעֵץ הַחַיִּים, וְלֹא מִתּוֹךְ הֶעָפָר. וּמִשּׁוּם כָּךְ הִסְתַּלֵּק לְמַעְלָה וְלֹא מֵת כְּדֶרֶךְ כָּל בְּנֵי הָעוֹלָם, שֶׁכָּתוּב (מלכים ב ב) וַיַּעַל אֵלִיָּהוּ בַּסֳּעָרָה הַשָּׁמָיִם.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב, וְהִנֵּה רֶכֶב אֵשׁ וְסוּסֵי אֵשׁ וְגוֹ', שֶׁהֲרֵי אָז הִתְפַּשֵּׁט הַגּוּף מִן הָרוּחַ וְהִסְתַּלֵּק שֶׁלֹּא כִּשְׁאָר דֶּרֶךְ בְּנֵי הָעוֹלָם, וְנִשְׁאָר מַלְאָךְ קָדוֹשׁ כִּשְׁאָר קְדוֹשִׁים עֶלְיוֹנִים, וְעוֹשֶׂה שְׁלִיחוּת בָּעוֹלָם, וַהֲרֵי פֵּרְשׁוּהָ, שֶׁהַנִּסִּים שֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם, נַעֲשִׂים עַל יָדוֹ.</p>\n<p>וּבֹא וּרְאֵה מַה כָּתוּב, וַיִּשְׁאַל אֶת נַפְשׁוֹ. בָּרִאשׁוֹנָה וַיֵּלֶךְ אֶל נַפְשׁוֹ, כְּמוֹ שֶׁנִּתְבָּאֵר בַּקִּיּוּם, וְכָאן אֶת נַפְשׁוֹ לָמוּת, הָעֵץ שֶׁבּוֹ שׁוֹרֶה הַמָּוֶת, וְשָׁם נִגְלָה עָלָיו הַקָּדוֹשׁ בָּרוּךְ הוּא, כַּכָּתוּב צֵא וְעָמַדְתָּ בָהָר. מַה כָּתוּב אַחֲרָיו? וְאַחַר הָרַעַשׁ אֵשׁ לֹא בָאֵשׁ ה' וְאַחַר הָאֵשׁ קוֹל דְּמָמָה דַקָּה. זֶהוּ הַמָּקוֹם הַפְּנִימִי שֶׁל הַכֹּל, שֶׁמִּמֶּנּוּ יוֹצְאִים כָּל הָאוֹרוֹת.</p>\n<p>מַה כָּתוּב? וַיְהִי כִּשְׁמֹעַ אֵלִיָּהוּ וַיָּלֶט פָּנָיו בְּאַדַּרְתּוֹ וְגוֹ' וְהִנֵּה אֵלָיו קוֹל וַיֹּאמֶר מַה לְּךְ פֹה אֵלִיָּהוּ. וַיֹּאמֶר קַנֹּא קִנֵּאתִי. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, עַד מָתַי אַתָּה מְקַנֵּא לִי? סָגַרְתָּ אֶת הַדֶּלֶת שֶׁלֹּא יָכוֹל לִשְׁלֹט בְּךְ הַמָּוֶת לְעוֹלָם, וְהָעוֹלָם לֹא יָכוֹל לִסְבֹּל אוֹתְךְ עִם בָּנַי (אדם). אָמַר לוֹ, כִּי עָזְבוּ בְרִיתְךְ בְּנֵי יִשְׂרָאֵל וְגוֹ'. אָמַר לוֹ, חַיֶּיךְ שֶׁבְּכָל מָקוֹם שֶׁבָּנַי (אדם) יְקַיְּמוּ אֶת בְּרִית הַקֹּדֶשׁ, אַתָּה תִהְיֶה מְזֻמָּן לְשָׁם. (והרי נתבאר שמשום כך מתקנים כסא לאליהו, שהוא מזמן לשם,)</p>\n<p>בֹּא רְאֵה מַה גָּרַם אוֹתוֹ הַדִּבּוּר שֶׁל אֵלִיָּהוּ, שֶׁכָּתוּב וְהִשְׁאַרְתִּי בְיִשְׂרָאֵל שִׁבְעַת אֲלָפִים כָּל הַבִּרְכַּיִם אֲשֶׁר לֹא כָרְעוּ לַבַּעַל וְכָל הַפֶּה אֲשֶׁר לֹא נָשַׁק לוֹ. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, מִכָּאן וָהָלְאָה, שֶׁאֵין הָעוֹלָם לִסְבֹּל אוֹתְךְ עִם בָּנַי (אדם). וְאֶת אֱלִישָׁע בֶּן שָׁפָט מֵאָבֵל מְחוֹלָה תִּמְשַׁח לְנָבִיא תַּחְתֶּיךְ, יִהְיֶה נָבִיא אַחֵר אֵצֶל בָּנַי (אדם), וְאַתָּה תִּסְתַּלֵּק לִמְקוֹמְךְ.</p>\n<p>וּבֹא רְאֵה, כָּל אוֹתוֹ אָדָם שֶׁמְּקַנֵּא לַקָּדוֹשׁ-בָּרוּךְ-הוּא, לֹא יָכוֹל מַלְאַךְ הַמָּוֶת לִשְׁלֹט בּוֹ כִּשְׁאָר בְּנֵי אָדָם, וְיִתְקַיֵּם בּוֹ שָׁלוֹם, וְהִנֵּה פֵּרְשׁוּהָ כְּמוֹ שֶׁנֶּאֱמַר בְּפִנְחָס, (במדבר כה) לָכֵן אֱמֹר הִנְנִי נֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם.</p>"],[9522011419,"<p>וַיִּפֹּל עַל צַוְּארֵי בִנְיָמִן אָחִיו וַיֵּבְךָּ וּבִנְיָמִן בָּכָה עַל צַוָּארָיו. רַבִּי יִצְחָק אָמַר, הִנֵּה פֵּרְשׁוּהָ שֶׁבָּכָה עַל מִקְדָּשׁ רִאשׁוֹן וְעַל מִקְדָּשׁ שֵׁנִי.</p>\n<p>פָּתַח וְאָמַר, כְּמִגְדַּל דָּוִיד צַוָּארֵךְ בָּנוּי לְתַלְפִּיּוֹת אֶלֶף הַמָּגֵן תָּלוּי עָלָיו כֹּל שִׁלְטֵי הַגִּבּרִים. כְּמִגְדַּל דָּוִיד, מִי מִגְדַּל דָּוִיד? זֶה וַדַּאי מִגְדַּל דָּוִד שֶׁבָּנָה אוֹתוֹ דָּוִד וְהֶעֱלָה אוֹתוֹ לְתוֹךְ יְרוּשָׁלַיִם. אֶלָּא כְּמִגְדַּל דָּוִיד - זוֹ יְרוּשָׁלַיִם שֶׁל מַעְלָה, שֶׁכָּתוּב בָּהּ (משלי יא) מִגְדַּל עֹז שֵׁם ה' בּוֹ יָרוּץ צַדִּיק וְנִשְׂגָּב. מִי הַנִּשְׂגָּב? אֶלָּא אוֹתוֹ מִגְדָּל נִשְׂגָּב, מִשּׁוּם שֶׁבּוֹ יָרוּץ צַדִּיק.</p>\n<p>צַוָּארֵךָ - זֶה בֵּית הַמִּקְדָּשׁ שֶׁלְּמַטָּה, שֶׁעוֹמֵד בְּתִקּוּן שֶׁל יֹפִי כְּצַוָּאר לַגּוּף. מָה הַצַּוָּאר הוּא הַיֹּפִי שֶׁל כָּל הַגּוּף - כָּךְ גַּם בֵּית הַמִּקְדָּשׁ הוּא הַיֹּפִי שֶׁל כָּל הָעוֹלָם.</p>\n<p>בָּנוּי לְתַלְפִּיּוֹת - תֵּל שֶׁכָּל בְּנֵי הָעוֹלָם הָיוּ מִסְתַּכְּלִים בּוֹ. וְכָךְ בֵּאֲרוּהוּ, תַּלְפִּיּוֹת - תֵּל שֶׁכָּל הַפִּיּוֹת שֶׁל הָעוֹלָם מְשַׁבְּחִים וּמִתְפַּלְלִים אֵלָיו.</p>\n<p>אֶלֶף הַמָּגֵן תָּלוּי עָלָיו - אֵלּוּ אֶלֶף הַתִּקּוּנִים שֶׁמְּתַקְנִים בּוֹ כָּרָאוּי. כֹּל שִׁלְטֵי הַגִּבֹּרִים - שֶׁכֻּלָּם בָּאִים מִצַּד הַדִּין הַקָּשֶׁה.</p>\n<p>מָה הַצַּוָּאר כָּל תִּקּוּנֵי הָאִשָּׁה תְּלוּיִים בּוֹ - כָּךְ בַּמִּקְדָּשׁ כָּל תִּקּוּנֵי הָעוֹלָם תְּלוּיִים וּשְׁרוּיִים בּוֹ. וַהֲרֵי פֵּרְשׁוּהָ, שֶׁכָּתוּב (איכה ה) עַל צַוָּארֵנוּ נִרְדָּפְנוּ, עַל בֵּית הַמִּקְדָּשׁ, שֶׁהוּא הַצַּוָּאר וְהַיֹּפִי שֶׁל כָּל הָעוֹלָם. נִרְדָּפְנוּ יָגַעְנוּ, לִבְנוֹת אוֹתוֹ פַּעֲמַיִם. וְלֹא הוּנַּח לָנוּ, שֶׁהֲרֵי לֹא הִשְׁאִירוּהוּ לָנוּ, וְנֶחֱרַב וְלֹא נִבְנָה לְאַחַר מִכֵּן.</p>\n<p>מָה הַצַּוָּאר, כֵּיוָן שֶׁהֻשְׁמַד, כָּל הַגּוּף מֻשְׁמָד עִמּוֹ - כָּךְ גַּם בֵּית הַמִּקְדָּשׁ, כֵּיוָן שֶׁהֻשְׁמַד וְנֶחְשַׁךְ, כָּל הָעוֹלָם כָּךְ גַּם נֶחְשַׁךְ, וְלֹא מֵאִיר הַשֶּׁמֶשׁ, וְלֹא שָׁמַיִם וְאֶרֶץ וְכוֹכָבִים.</p>\n<p>מִשּׁוּם כָּךְ בָּכָה עַל זֶה יוֹסֵף, וְאַחַר שֶׁבָּכָה עַל זֶה, בָּכָה עַל הַשְּׁבָטִים שֶׁיֵּגֶלוּ. כְּשֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, כָּל הַשְּׁבָטִים גָּלוּ מִיָּד וְהִתְפַּזְּרוּ בֵּין הָעַמִּים. זֶהוּ שֶׁכָּתוּב וַיְנַשֵּׁק לְכָל אֶחָיו וַיֵּבְךָּ עֲלֵהֶם. עֲלֵהֶם וַדַּאי.</p>\n<p>עַל כֻּלָּם בָּכָה, עַל בֵּית הַמִּקְדָּשׁ שֶׁנֶּחֱרַב פַּעֲמַיִם, וְעַל אֶחָיו עֲשֶׂרֶת הַשְּׁבָטִים שֶׁהֻגְלוּ לַגָּלוּת וְהִתְפַּזְּרוּ בֵּין הָעַמִּים. וְאַחֲרֵי כֵן דִּבְּרוּ אֶחָיו אִתּוֹ, וְלֹא כָתוּב וַיִּבְכּוּ, שֶׁהֲרֵי הוּא בָּכָה, שֶׁנִּצְנְצָה בּוֹ רוּחַ הַקֹּדֶשׁ, וְהֵם לֹא בָכוּ, שֶׁלֹּא שָׁרְתָה עֲלֵיהֶם רוּחַ הַקֹּדֶשׁ.</p>"],[9522011420,"<p>וְהַקֹּל נִשְׁמַע בֵּית פַּרְעֹה. רַבִּי (אלעזר) אַבָּא פָּתַח וְאָמַר, (תהלים פד) נִכְסְפָה וְגַם כָּלְתָה נַפְשִׁי לְחַצְרוֹת ה' לִבִּי וּבְשָׂרִי יְרַנְּנוּ אֶל אֵל חָי. בּא רְאֵה, כָּל אָדָם שֶׁמִּתְפַּלֵּל תְּפִלָּתוֹ (וקם) לִפְנֵי רִבּוֹנוֹ, צָרִיךְ לוֹ לְהַקְדִּים לוֹ בְּרָכוֹת בְּכָל יוֹם וָיוֹם וּלְהִתְפַּלֵּל תְּפִלָּתוֹ לִפְנֵי רִבּוֹנוֹ בַּזְּמַן שֶׁצָּרִיךְ.</p>\n<p>בַּבֹּקֶר לֶאֱחֹז בַּיָּמִין שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, בְּמִנְחָה לֶאֱחֹז בַּשְּׂמֹאל. וּתְפִלָּה וּבַקָּשָׁה צָרִיךְ לָאָדָם בְּכָל יוֹם וָיוֹם כְּדֵי לְהֵאָחֵז בּוֹ. וּבֵאַרְנוּ, מִי שֶׁמִּתְפַּלֵּל תְּפִלָּתוֹ (ועומד) לִפְנֵי רִבּוֹנוֹ, צָרִיךְ לוֹ שֶׁלֹּא לִשְׁמֹעַ קוֹלוֹ בִּתְפִלָּתוֹ, וּמִי שֶׁשּׁוֹמֵעַ קוֹלוֹ בִּתְפִלָּתוֹ, תְּפִלָּתוֹ לֹא נִשְׁמַעַת.</p>\n<p>מָה הַטַּעַם? מִשּׁוּם שֶׁהַתְּפִלָּה אֵינָהּ אוֹתוֹ הַקּוֹל שֶׁנִּשְׁמָע, שֶׁאוֹתוֹ קוֹל שֶׁנִּשְׁמָע אֵינוֹ תְפִלָּה. וּמַה הִיא תְּפִלָּה? זֶהוּ קוֹל אַחֵר שֶׁתָּלוּי בַּקּוֹל שֶׁנִּשְׁמָע. וּמִי הוּא הַקּוֹל שֶׁנִּשְׁמָע? זֶה אוֹתוֹ הַקּוֹל שֶׁהוּא בְּוָא\"ו, הַקּוֹל שֶׁתָּלוּי בּוֹ, זֶהוּ קֹל בְּלִי וָא\"ו.</p>\n<p>וּמִשּׁוּם כָּךְ לֹא צָרִיךְ לָאָדָם לִשְׁמֹעַ קוֹלוֹ בִּתְפִלָּתוֹ, אֶלָּא לְהִתְפַּלֵּל בְּלַחַשׁ בְּאוֹתוֹ הַקּוֹל שֶׁלֹּא נִשְׁמָע, וְזוֹ הַתְּפִלָּה שֶׁמִּתְקַבֶּלֶת תָּמִיד, וְסִימָן לַדָּבָר - וְהַקֹּל נִשְׁמַע. קֹל בְּלִי וָא\"ו, נִשְׁמַע. זוֹ הִיא הַתְּפִלָּה שֶׁהִיא בַּחֲשַׁאי, שֶׁכָּתוּב בְּחַנָּה וְקוֹלָהּ לֹא יִשָּׁמֵעַ. זוֹ הִיא הַתְּפִלָּה שֶׁמְּקַבֵּל הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁנַּעֲשֵׂית בְּתוֹךְ רָצוֹן וְכַוָּנָה וְתִקּוּן כָּרָאוּי, וּלְיַחֵד אֶת הַיִּחוּד שֶׁל רִבּוֹנוֹ כָּרָאוּי בְּכָל יוֹם. (והקל נשמע בית פרעה, והקל נשמע, חסר וא\"ו, מה הטעם? אמר רבי אלעזר, זו היא השכינה שבוכה על חרבן בית המקדש ועל גלותם של ישראל, כתוב כאן והקל נשמע, וכתוב שם, (ירמיה לא) קול ברמה נשמע, מה לפנינו שכינה, אף כאן גם כן שכינה).</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, הַקּוֹל בַּחֲשַׁאי זֶהוּ קוֹל עֶלְיוֹן שֶׁכָּל הַקּוֹלוֹת יוֹצְאִים מִשָּׁם. אֲבָל קֹל בְּלִי וָא\"ו, זוֹהִי הַתְּפִלָּה שֶׁל מַטָּה, שֶׁהִיא הוֹלֶכֶת לְהִתְעַלּוֹת בְּוָא\"ו וּלְהִתְחַבֵּר בּוֹ.</p>\n<p>בֹּא רְאֵה, וְהַקֹּל נִשְׁמַע, זֶה הוּא הַקֹּל בְּלִי וָא\"ו, זֶהוּ הַקּוֹל שֶׁבָּכָה עַל מִקְדָּשׁ רִאשׁוֹן וְעַל מִקְדָּשׁ שֵׁנִי. נִשְׁמַע, כְּמוֹ שֶׁנֶּאֱמַר קוֹל בְּרָמָה נִשְׁמָע. בְּרָמָה, מַה זֶּה בְּרָמָה? זֶה הוּא הָעוֹלָם הָעֶלְיוֹן, הָעוֹלָם הַבָּא, וְסִימָן לַדָּבָר - מִן הָרָמָה וְעַד בֵּית אֵל, (תהלים קו) מִן הָעוֹלָם וְעַד הָעוֹלָם. כָּאן בְּרָמָה - זֶה הָעוֹלָם הָעֶלְיוֹן, שֶׁהֲרֵי בַּשָּׁעָה הַהִיא שֶׁבְּרָמָה נִשְׁמָע, אָז מַה כָּתוּב? (ישעיה כב) וַיִּקְרָא ה' אֱלֹהִים צְבָאוֹת בַּיּוֹם הַהוּא לִבְכִי וּלְמִסְפֵּד וְגוֹ'.</p>\n<p>וְהַקֹל נִשְׁמַע, לְמַעְלָה לְמַעְלָה. מָה הַטַּעַם? מִשּׁוּם שֶׁוָּא\"ו הִתְרַחֵק וְהִסְתַּלֵּק מִמֶּנָּה, וְאָז רָחֵל מְבַכָּה עַל בָּנֶיהָ מֵאֲנָה לְהִנָּחֵם עַל בָּנֶיהָ כִּי אֵינֶנּוּ. כִּי אֵינֶנּוּ? כִּי אֵינָם צָרִיךְ הָיָה לִהְיוֹת! אֶלָּא כִּי אֵינֶנּוּ, וְהִנֵּה בֵּאַרְנוּ כִּי אֵינֶנּוּ, שֶׁבַּעְלָהּ לֹא נִמְצָא עִמָּהּ, שֶׁאִלְמָלֵא הָיָה בַּעְלָהּ נִמְצָא עִמָּהּ, תִּתְנַחֵם עֲלֵיהֶם, שֶׁהֲרֵי אָז בָּנֶיהָ לֹא יִהְיוּ בַּגָּלוּת, וּמִשּׁוּם שֶׁאֵינֶנּוּ, אֵינָהּ מִתְנַחֶמֶת עַל בָּנֶיהָ, מִשּׁוּם שֶׁבָּנֶיהָ הִתְרַחֲקוּ מִמֶּנָּה עַל שֶׁאֵינֶנּוּ עִמָּהּ.</p>\n<p>בֹּא רְאֵה, בֵּית פַּרְעֹה - זֶה הוּא סִימָן לַדָּבָר לְמַעְלָה, הַבַּיִת שֶׁנִּפְרָעִים וּמִתְגַּלִּים מִמֶּנּוּ כָּל הָאוֹרוֹת וְכָל הַמְּאוֹרוֹת, כָּל מַה שֶּׁהָיָה סָתוּם מִשָּׁם הִתְגַּלָּה, וּמִשּׁוּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא הוֹצִיא אֶת כָּל הָאוֹרוֹת וְכָל הַמְּאוֹרוֹת, כְּדֵי לְהָאִיר לְאוֹתוֹ הַקּוֹל שֶׁנִּקְרָא קֹל בְּלִי וָא\"ו.</p>\n<p>בֹּא רְאֵה, כַּאֲשֶׁר יָקִים הַקָּדוֹשׁ בָּרוּךְ הוּא לְזֶה הַקּוֹל מֵהֶעָפָר וְיִתְחַבֵּר בָּאוֹת וָא\"ו, אָז כָּל מַה שֶּׁנֶּאֱבַד מֵהֶם בִּזְמַן הַגָּלוּת יַחֲזֹר, וְיִתְעַדְּנוּ בְּאוֹרוֹת עֶלְיוֹנִים שֶׁנּוֹסָפִים מִתּוֹךְ הָעוֹלָם הָעֶלְיוֹן, כְּמוֹ שֶׁנֶּאֱמַר וְהָיָה בַּיּוֹם הַהוּא יִתָּקַע בְּשׁוֹפָר גָּדוֹל וּבָאוּ הָאֹבְדִים בְּאֶרֶץ אַשּׁוּר וְהַנִּדָּחִים בְּאֶרֶץ מִצְרָיִם וְהִשְׁתַּחֲווּ לַה' בְּהַר הַקֹּדֶשׁ בִּירוּשָׁ לם.</p>"],[9522011421,"<p>וְאַתָּה צֻוֵּיתָה זאת עָשׂוּ קְחוּ לָכֶם מֵאֶרֶץ מִצְרַיִם וְגוֹ'. רַבִּי חִיָּיא פָּתַח, שִׂמְחוּ אֶת יְרוּשָׁלם וְגִילוּ בָהּ כָּל אֹהֲבֶיהָ שִׂישׂוּ אִתָּהּ מָשׂוֹשׂ וְגוֹ'. בֹּא רְאֵה, כְּשֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ וְגָרְמוּ הַחֲטָאִים וְגָלוּ יִשְׂרָאֵל מִן הָאָרֶץ, הִסְתַּלֵּק הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה לְמַעְלָה, וְלֹא הִשְׁגִּיחַ עַל חֻרְבַּן בֵּית הַמִּקְדָּשׁ וְעַל עַמּוֹ שֶׁגָּלוּ, וְאָז הַשְּׁכִינָה גָּלְתָה עִמָּהֶם.</p>\n<p>כְּשֶׁיָּרַד, הִשְׁגִּיחַ עַל בֵּיתוֹ שֶׁנִּשְׂרַף, הִסְתַּכֵּל עַל עַמּוֹ - וְהִנֵּה הָגְלָה. שָׁאַל עַל הַגְּבִירָה - וְהִיא גֹּרְשָׁה. אָז וַיִּקְרָא ה' אֱלֹהִים צְבָאוֹת בַּיּוֹם הַהוּא לִבְכִי וּלְמִסְפֵּד וּלְקָרְחָה וְלַחֲגֹר שַׂק. וְהִיא גַם הִיא מַה כָּתוּב בָּהּ? (יואל א) אֱלִי כִּבְתוּלָה חֲגֻרַת שַׂק עַל בַּעַל נְעוּרֶיהָ, כְּמוֹ שֶׁנֶּאֱמַר כִּי אֵינֶנּוּ, מִשּׁוּם שֶׁהִסְתַּלֵּק מִמֶּנָּה וְנִמְצָא פֵרוּד.</p>\n<p>וַאֲפִלּוּ שָׁמַיִם וָאָרֶץ כֻּלָּם הִתְאַבְּלוּ עָלָיו, שֶׁכָּתוּב (ישעיה כ) אַלְבִּישׁ שָׁמַיִם קַדְרוּת וְשַׂק אָשִׂים כְּסוּתָם. מַלְאָכִים עֶלְיוֹנִים כֻּלָּם הִתְאַבְּלוּ עָלֶיהָ, שֶׁנֶּאֱמַר הֵן אֶרְאֶלָּם צָעֲקוּ חֻצָה מַלְאֲכֵי שָׁלוֹם מַר יִבְכָּיוּן. הַשֶּׁמֶשׁ וְהַלְּבָנָה הִתְאַבְּלוּ וְהֶחְשִׁיכוּ אֶת אוֹרָם, שֶׁכָּתוּב חָשַׁךְ הַשֶּׁמֶשׁ בְּצֵאתוֹ וְגוֹ', וְכָל הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים בָּכוּ עָלֶיהָ וְהִתְאַבְּלוּ. מָה הַטַּעַם? מִשּׁוּם שֶׁשּׁוֹלֵט עָלֶיהָ הַצַּד הָאַחֵר שֶׁשּׁוֹלֵט עַל הָאָרֶץ הַקְּדוֹשָׁה.</p>\n<p>פָּתַח וְאָמַר, (יחזקאל ז) וְאַתָּה בֶּן אָדָם כֹּה אָמַר ה' אֱלֹהִים לְאַדְמַת יִשְׂרָאֵל קֵץ בָּא הַקֵּץ עַל אַרְבַּע כַּנְפוֹת הָאָרֶץ. הַפָּסוּק הַזֶּה הוּא עֶלְיוֹן. מַה זֶּה לְאַדְמַת יִשְׂרָאֵל קֵץ, וְכִי אַדְמַת יִשְׂרָאֵל הִיא קֵץ? אֶלָּא כָּךְ זֶה וַדַּאי, וְנִתְבָּאֵר. הַקֵּץ הוּא לְיָמִין, וְהַקֵּץ הוּא לִשְׂמֹאל. קֵץ לְיָמִין - שֶׁכָּתוּב (דניאל יב) לְקֵץ הַיָּמִין. קֵץ לִשְׂמֹאל - שֶׁכָּתוּב (בראשית ו) קֵץ שָׂם לַחֹשֶׁךְ וּלְכָל תַּכְלִית הוּא חֹקֵר, וְזֶהוּ קֵץ כָּל בָּשָׂר, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>קֵץ שֶׁל הַיָּמִין - הַיְנוּ שֶׁכָּתוּב לְאַדְמַת יִשְׂרָאֵל קֵץ. בָּא הַקֵּץ - זֶה קֵץ הַשְּׂמֹאל. הַקֵּץ שֶׁל הַיָּמִין זֶה הַקֵּץ שֶׁל יֵצֶר הַטּוֹב. הַקֵּץ שֶׁל הַשְּׂמֹאל זֶה הַקֵּץ שֶׁל יֵצֶר הָרָע. וְזֶה הוּא שֶׁכַּאֲשֶׁר הַחֲטָאִים גָּרְמוּ וְהִתְגַּבְּרוּ, נִגְזַר וְנִתַּן הַשִּׁלְטוֹן לְמַלְכוּת הָרִשְׁעָה לִשְׁלֹט וּלְהַחֲרִיב בֵּיתוֹ וּמִקְדָּשׁוֹ, וְזֶהוּ שֶׁכָּתוּב (יחזקאל ז) כֹּה אָמַר ה' אֱלֹהִים רָעָה אַחַת רָעָה הִנֵּה בָאָה, וְהַכֹּל אֶחָד.</p>\n<p>וּמִשּׁוּם כָּךְ הִתְאַבְּלוּ עֶלְיוֹנִים וְתַחְתּוֹנִים, עַל שֶׁנִּתַּן הַשִּׁלְטוֹן לַקֵּץ הַזֶּה שֶׁל הַשְּׂמֹאל. וּמִשּׁוּם כָּךְ, כֵּיוָן שֶׁהַמַּלְכוּת הַקְּדוֹשָׁה, מַלְכוּת הַשָּׁמַיִם נִכְנְעָה, וּמַלְכוּת הָרִשְׁעָה (האחרת) הִתְגַּבְּרָה, (אז) יֵשׁ לְכָל אָדָם לְהִתְאַבֵּל עִמָּהּ וּלְהִכָּנַע עִמָּהּ, וּמִשּׁוּם שֶׁכַּאֲשֶׁר הִיא תִזְדַּקֵּף וְהָעוֹלָם יִתְחַדֵּשׁ הוּא יִתְחַדֵּשׁ עִמָּהּ, שֶׁכָּתוּב (ישעיה סו) שִׂישׂוּ אִתָּהּ מָשׂוֹשׂ כָּל הַמִּתְאַבְּלִים עָלֶיהָ.</p>\n<p>בֹּא רְאֵה, כָּתוּב בְּמִצְרַיִם (ירמיה מו) עֶגְלָה יְפֵה פִיָּה מִצְרָיִם, וְהַסּוֹד שֶׁל הָעֶגְלָה הַזּוֹ הָיוּ יִשְׂרָאֵל תַּחַת שִׁלְטוֹנָהּ כַּמָּה פְעָמִים וְכַמָּה שָׁנִים. וּמִשּׁוּם שֶׁיִּשְׂרָאֵל עֲתִידִים אַחַר כָּךְ לִשְׁלֹט עָלֶיהָ, נִרְמָז לָהֶם כָּאן עֲגָלוֹת.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, רֶמֶז רָמַז יוֹסֵף לְיַעֲקֹב עַל עֶגְלָה עֲרוּפָה, שֶׁהֲרֵי בְּאוֹתוֹ פֶרֶק נִפְרַד מִמֶּנּוּ. וּבֵאֲרוּהָ, עֶגְלָה עֲרוּפָה, שֶׁהִיא בָּאָה עַל שֶׁנִּמְצָא הָרוּג וְלֹא נוֹדָע מִי הָרַג אוֹתוֹ, וּכְדֵי שֶׁלֹּא יִשְׁלְטוּ עַל הָאָרֶץ רוּחוֹת רָעוֹת שֶׁאֵינָן צְרִיכוֹת, נוֹתְנִים אֶת הָעֶגְלָה הַזּוֹ לְתִקּוּן, כְּדֵי שֶׁלֹּא יִתְוַדְּעוּ אֵלָיו וְלֹא יִשְׁלְטוּ עֲלֵיהֶם.</p>\n<p>בֹּא רְאֵה, כָּל בְּנֵי הָאָדָם, כֻּלָּם עוֹבְרִים עַל יְדֵי מַלְאַךְ הַמָּוֶת, פְּרָט לָזֶה, שֶׁהִקְדִּימוּ אוֹתוֹ בְּנֵי אָדָם טֶרֶם הִגִּיעַ זְמַנּוֹ לִשְׁלֹט בּוֹ וְלִטֹּל רְשׁוּת, שֶׁהֲרֵי אֵין שׁוֹלֵט בָּאָדָם עַד שֶׁנּוֹטֵל רְשׁוּת.</p>\n<p>וּמִשּׁוּם כָּךְ יֵשׁ לוֹ דִּין לִשְׁלֹט עַל אוֹתוֹ מָקוֹם, כְּמוֹ שֶׁנֶּאֱמַר לֹא נוֹדַע מִי הִכָּהוּ. גַּם כָּךְ יֵשׁ לוֹ דִּין שֶׁלֹּא נוֹדַע כְּדֵי לְקַטְרֵג עַל אוֹתוֹ מָקוֹם, וְעַל כֵּן (דברים כא) וְלָקְחוּ זִקְנֵי הָעִיר הַהִיא עֶגְלַת בָּקָר וְגוֹ', כְּדֵי לְהַעֲבִיר דִּינוֹ שֶׁל הַמָּקוֹם הַהוּא, וּלְהִתַּקֵּן שֶׁלֹּא יִשְׁלֹט בּוֹ הַמְקַטְרֵג וּלְהִנָּצֵל מִמֶּנּוּ.</p>\n<p>בֹּא רְאֵה, כְּשֶׁנִּפְרַד יוֹסֵף מֵאָבִיו, בְּלִי לְוָיָה וּבְלִי אֲכִילָה נִשְׁלַח, וְהָיָה מַה שֶּׁהָיָה, וּכְשֶׁאָמַר יַעֲקֹב (בראשית לז) טָרֹף טֹרַף יוֹסֵף, אָמַר כִּי אֵרֵד אֶל בְּנִי אָבֵל שְׁאֹלָה, שֶׁאֲנִי גָרַמְתִּי לוֹ, וְעוֹד - שֶׁהָיִיתִי יוֹדֵעַ שֶׁאֶחָיו שׂוֹנְאִים אוֹתוֹ וְשָׁלַחְתִּי אוֹתוֹ, וְרֶמֶז הוּא רָמַז לוֹ.</p>\n<p>אָמַר לוֹ רַבִּי יְהוּדָה, אֶת אוֹתָם הָעֲגָלוֹת שָׁלַח אוֹתָם עַל פִּי פַרְעֹה, שֶׁכָּתוּב וַיִּתֵּן לָהֶם יוֹסֵף עֲגָלוֹת עַל פִּי פַרְעֹה. אָמַר לוֹ, דִּיּוּקוֹ שֶׁל דָּבָר, שֶׁכָּתוּב וְאַתָּה צֻוֵּיתָה זאת עֲשׂוּ. וְאַתָּה צֻוֵּיתָה דַּוְקָא, וּמִשּׁוּם כָּךְ כָּתוּב בְּהֵ\"א, מַשְׁמָע שֶׁיּוֹסֵף בִּקֵּשׁ אוֹתָם, וּמִשּׁוּם כָּךְ וַיִּתֵּן לָהֶם יוֹסֵף עֲגָלוֹת עַל פִּי פַרְעֹה, וְיַעֲקֹב לֹא עָמַד בַּדָּבָר עַד שֶׁרָאָה אוֹתָם, שֶׁכָּתוּב וַיַּרְא אֶת הָעֲגָלוֹת אֲשֶׁר שָׁלַח יוֹסֵף לָשֵׂאת אֹתוֹ וַתְּחִי רוּחַ יַעֲקֹב אֲבִיהֶם.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בָּרִאשׁוֹנָה וַתְּחִי רוּחַ יַעֲקֹב, וְאַחַר כָּךְ וַיּאמֶר יִשְׂרָאֵל רַב עוֹד יוֹסֵף בְּנִי חָי. אֶלָּא בָּרִאשׁוֹנָה קָרְאָה לוֹ הַתּוֹרָה יַעֲקֹב, מִשּׁוּם הַשֻּׁתָּפוּת, שֶׁשִּׁתְּפוּ אֶת הַשְּׁכִינָה בְּאוֹתוֹ חֵרֶם כְּשֶׁנִּמְכַּר יוֹסֵף, וְעַכְשָׁו שֶׁשְּׁכִינָה עָלְתָה, אָז הִיא וַתְּחִי רוּחַ יַעֲקֹב אֲבִיהֶם, וְזֶה הוּא סוֹד הַשְּׁכִינָה. וְאַחַר שֶׁהִיא עָמְדָה בְקִיּוּם, (משום) אָז הַדַּרְגָּה שֶׁלְּמַעְלָה עָבְרָה אֵלֶיהָ, הַדַּרְגָּה שֶׁהִיא יִשְׂרָאֵל. (אז הדרגה שלמעלה התעוררה אליה, וזוהי דרגה של ישראל) מִכָּאן שֶׁהַדַּרְגָּה שֶׁלְּמַעְלָה לֹא מִתְעוֹרֶרֶת לְמַעְלָה עַד שֶׁמִּתְעוֹרֶרֶת בָּרִאשׁוֹנָה לְמַטָּה, שֶׁהֲרֵי כָּאן וַתְּחִי רוּחַ יַעֲקֹב בָּרִאשׁוֹנָה, וְאַחַר כָּךְ וַיֹּאמֶר יִשְׂרָאֵל.</p>\n<p>וַיֹּאמֶר אֱלֹהִים לְיִשְׂרָאֵל בְּמַרְאֹת הַלַּיְלָה. בְּמַרְאַת כָּתוּב. בּא רְאֵה, וַיִּזְבַּח זְבָחִים לֵאלֹהֵי אָבִיו יִצְחָק, בָּרִאשׁוֹנָה, כְּדֵי לְהָעִיר אֶת הַשְּׂמֹאל בַּסּוֹד שֶׁל הָאַהֲבָה. וְאָז - וַיֹּאמֶר אֱלֹהִים לְיִשְׂרָאֵל בְּמַרְאֹת הַלַּיְלָה, בַּדַּרְגָּה הַזּוֹ שֶׁאָמַרְנוּ, שֶׁהִיא מַרְאוֹת הַלַּיְלָה.</p>\n<p>וַיֹּאמֶר אָנֹכִי הָאֵל אֱלֹהֵי אָבִיךְ. מָה הַטַּעַם? מִשּׁוּם שֶׁצַּד הַקְּדֻשָּׁה שֶׁלְּמַעְלָה כָּךְ הוּא, שֶׁהֲרֵי צַד הַטֻּמְאָה לֹא מַזְכִּיר אֶת שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכָל צַד הַקְּדֻשָּׁה נִזְכָּר בִּשְׁמוֹ. אָנֹכִי אֵרֵד עִמְּךְ מִצְרַיְמָה וְגוֹ'. מִכָּאן שֶׁשְּׁכִינָה יָרְדָה עִמּוֹ בַּגָּלוּת, וּבְכָל מָקוֹם שֶׁיִּשְׂרָאֵל גָּלוּ - שְׁכִינָה גָּלְתָה עִמָּהֶם, וְהִנֵּה פֵּרְשׁוּהָ.</p>\n<p>בֹּא רְאֵה, כַּמָּה עֲגָלוֹת הָיוּ? שֵׁשׁ, כְּמוֹ שֶׁנֶּאֱמַר (במדבר ז) שֵׁשׁ עֶגְלוֹת צָב. דָּבָר אַחֵר, שִׁשִּׁים הָיוּ, וְהַכֹּל סוֹד אֶחָד. בָּרִאשׁוֹנָה כָּתוּב בָּעֲגָלוֹת אֲשֶׁר שָׁלַח יוֹסֵף, וּלְבַסּוֹף - אֲשֶׁר שָׁלַח פַּרְעֹה. אֶלָּא כֻּלָּם שֶׁשָּׁלַח יוֹסֵף הָיוּ בַּחֶשְׁבּוֹן כָּרָאוּי, וְאוֹתָם שֶׁשָּׁלַח פַּרְעֹה יוֹתֵר מֵהֶם, לֹא הָיוּ בְּסוֹד זֶה וְלֹא הָיוּ בַּחֶשְׁבּוֹן.</p>\n<p>וְאֵלֶּה וְאֵלֶּה בָּאוּ, מִשּׁוּם כָּךְ אֲשֶׁר שָׁלַח יוֹסֵף, אֲשֶׁר שָׁלַח פַּרְעֹה. וּכְשֶׁיָּצְאוּ יִשְׂרָאֵל מִן הַגָּלוּת מַה כָּתוּב? (ישעיה סו) וְהֵבִיאוּ אֶת כָּל אֲחֵיכֶם מִכָּל הַגּוֹיִם מִנְחָה לַה' וְגוֹ'.</p>"],[9522011422,"<p>וַיֶּאְסֹר יוֹסֵף מֶרְכַּבְתּוֹ. רַבִּי יִצְחָק פָּתַח וְאָמַר, (יחזקאל א) וּדְמוּת עַל רָאשֵׁי הַחַיָּה רָקִיעַ כְּעֵין הַקֶּרַח הַנּוֹרָא נָטוּי עַל רָאשֵׁיהֶם מִלְמַעְלָה. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ, אֲבָל בֹּא רְאֵה, יֵשׁ חַיָּה לְמַעְלָה מִן הַחַיָּה, וְיֵשׁ חַיָּה קְדוֹשָׁה שֶׁעוֹמֶדֶת עַל רֹאשׁ הַחַיּוֹת.</p>\n<p>וְיִשִׁ חַיָּה עֶלְיוֹנָה לְמַעְלָה עַל כָּל שְׁאָר הַחַיּוֹת, וְזוֹ (ויש) הַחַיָּה שׁוֹלֶטֶת עַל כֻּלָּם, מִשּׁוּם שֶׁכַּאֲשֶׁר הַחַיָּה הַזּוֹ נוֹתֶנֶת וּמְאִירָה לְכֻלָּם, אָז כֻּלָּן נוֹסְעוֹת לְמַסְעוֹתֵיהֶן וְנוֹתְנוֹת זוֹ לָזוֹ וְשׁוֹלְטוֹת זוֹ עַל זוֹ.</p>\n<p>וְיִשִׁ חַיָּה לְמַעְלָה עַל הַתַּחְתּוֹנִים עַל שְׁאָר הַחַיּוֹת שֶׁלְּמַטָּה, וְכֻלָּם נִזּוֹנִים מִמֶּנָּה, וְאַרְבַּעַת צִדְדֵי הָעוֹלָם רְשׁוּמִים בָּהּ, פָּנִים מְאִירוֹת יְדוּעוֹת (דינים) לְכָל צַד, וְהִיא שׁוֹלֶטֶת עַל אַרְבָּעָה צְדָדִים, וְהִנֵּה פֵּרְשׁוּהָ, שֶׁהֵם שָׁלֹשׁ לְצַד זֶה וְשָׁלֹשׁ לְצַד זֶה, וְכֵן לְאַרְבַּעַת צִדְדֵי הָעוֹלָם.</p>\n<p>וְיִשִׁ רָקִיעַ לְמַעְלָה מִן הָרָקִיעַ, וְהָרָקִיעַ הַזֶּה שֶׁשּׁוֹלֵט עֲלֵיהֶם, כֻּלָּם מִסְתַּכְּלִים כְּלַפָּיו. מַה כָּתוּב? (יחזקאל א) וְתַחַת הָרָקִיעַ כַּנְפֵיהֶם יְשָׁרוֹת אִשָּׁה אֶל אֲחוֹתָהּ וְגוֹ', מִשּׁוּם שֶׁכֻּלָּם שׁוֹלְטִים עַל מַה שֶּׁנִּפְקְדוּ, וּשְׁלִיחוּת שֶׁל מִדַּת הַחֶבֶל בָּהֶם.</p>\n<p>וְהֵם תִּשְׁעָה לְכָל צַד, לְאַרְבַּעַת צִדְדֵי הָעוֹלָם, וְהֵם ל\"ו בְּחֶשְׁבּוֹן. וּכְשֶׁכֻּלָּם מִתְחַבְּרִים, נַעֲשִׂים רִשּׁוּם אֶחָד, בְּסוֹד שֶׁל שֵׁם אֶחָד, בְּיִחוּד שָׁלֵם כָּרָאוּי.</p>\n<p>וּכְשֶׁנִּתְקָנִים כְּלַפֵּי הַכִּסֵּא, מַה כָּתוּב? וּמִמַּעַל לָרָקִיעַ אֲשֶׁר עַל רֹאשָׁם כְּמַרְאֵה אֶבֶן סַפִּיר דְּמוּת כִּסֵּא וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה. וַהֲרֵי בֵּאַרְנוּ, (דמות) שֶׁהָאֶבֶן הַטּוֹבָה הַזּוֹ בַּכִּסֵּא, שֶׁעוֹמֵד עַל אַרְבָּעָה עַמּוּדִים, וְעַל אוֹתוֹ הַכִּסֵּא דְּמוּת שֶׁל אָדָם, לְהִתְחַבֵּר בּוֹ יַחַד וּלְהִתְבָּרֵךְ כָּרָאוּי.</p>\n<p>וּכְשֶׁהִיא נִתְקֶנֶת כְּלַפֵּי אָדָם, שֶׁהַכֹּל יִהְיֶה מֶרְכָּבָה (נ\"א: קדושה, ואז כל המרכבה) אַחַת לָאָדָם הַזֶּה, אָז כָּתוּב: וַיֶּאְסֹר יוֹסֵף מֶרְכַּבְתּוֹ - זֶה הַצַּדִּיק. וַיַּעַל לִקְרַאת יִשְׂרָאֵל אָבִיו גֹּשְׁנָה. לִקְרַאת יִשְׂרָאֵל - זֶה הַסּוֹד שֶׁל אָדָם. גֹּשְׁנָה - הִתְקָרְבוּת אַחַת, לְהִתְקָרֵב יַחַד בְּקָרְבָּן אֶחָד וְיִחוּד אֶחָד.</p>\n<p>וַיֵּרָא אֵלָיו - שֶׁכְּשֶׁנִּרְאֶה הַשֶּׁמֶשׁ עִם הַלְּבָנָה, אָז מְאִירָה הַלְּבָנָה, וּמְאִירָה לְכֻלָּם שֶׁלְּמַטָּה. וְכֵן כְּמוֹ זֶה, כָּל זְמַן שֶׁהַקְּדֻשָּׁה שֶׁלְּמַעְלָה שׁוֹרָה עַל הַמִּקְדָּשׁ שֶׁלְּמַטָּה, מֵאִיר בֵּית הַמִּקְדָּשׁ וְעוֹמֵד בִּשְׁלֵמוּתוֹ. וּכְשֶׁמִּסְתַּלֵּק מִמֶּנּוּ וְנֶחֱרָב בֵּית הַמִּקְדָּשׁ, אָז וַיֵּבְךָּ עַל צַוָּארָיו עוֹד, שֶׁכֻּלָּם בָּכוּ עַל הַמִּקְדָּשׁ שֶׁנֶּחֱרָב. עוֹד, מַה זֶּה עוֹד? זוֹ הַגָּלוּת הָאַחֲרוֹנָה.</p>\n<p>אָז כֵּיוָן שֶׁרָאָה יַעֲקֹב וְהִסְתַּכֵּל שֶׁהִנֵּה הַתִּקּוּן שֶׁלְּמַטָּה נִתְקַן כְּמוֹ שֶׁלְּמַעְלָה, אָז אָמַר אָמוּתָה הַפָּעַם וְגוֹ'. כִּי עוֹדְךְ חָי, שֶׁהִתְקַיַּמְתָּ בַּסּוֹד שֶׁל הַבְּרִית הַקָּדוֹשׁ שֶׁנִּקְרָא חַי הָעוֹלָמִים, וּמִשּׁוּם כָּךְ כִּי עוֹדְךְ חָי. וְעַל כֵּן בָּרִאשׁוֹנָה אָמַר, רַב עוֹד יוֹסֵף בְּנִי חָי, שֶׁצָּרִיךְ לַעֲמֹד בַּסּוֹד שֶׁל חַי, וְהִנֵּה נִתְבָּאֵר.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב, וַיְבָרֶךְ יַעֲקֹב אֶת פַּרְעֹה. אָמַר רַבִּי יוֹסֵי, פַּרְעֹה, אַף עַל גַּב שֶׁבֵּאֲרוּהוּ בְּסוֹד אַחֵר, סֶמֶךְ שֶׁסּוֹמְכִים בָּעוֹלָם.</p>\n<p>אֲבָל בֹּא רְאֵה, (שיר א) לְסֻסָתִי בְּרִכְבֵי פַרְעֹה דִּמִּיתִיךְ רַעְיָתִי. בֹּא רְאֵה, יֵשׁ מֶרְכָּבוֹת לִשְׂמֹאל בַּסּוֹד שֶׁל הַצַּד הָאַחֵר, וְיֵשׁ מֶרְכָּבוֹת לְיָמִין בַּסּוֹד שֶׁל לְמַעְלָה שֶׁל קְדֻשָּׁה, וְאֵלֶּה כְּנֶגֶד אֵלֶּה. אֵלֶּה שֶׁל רַחֲמִים, וְאֵלֶּה שֶׁל דִּין.</p>\n<p>וּכְשֶׁהַקָּדוֹשׁ בָּרוּךָ הוּא עָשָׂה דִין בְּמִצְרַיִם, כָּל הַדִּין שֶׁעָשָׂה, בְּאוֹתָהּ צוּרָה, שֶׁהֵם הַמֶּרְכָּבוֹת מַמָּשׁ, וּכְמוֹ שֶׁל אוֹתוֹ הַצַּד מַמָּשׁ. מָה אוֹתוֹ הַצַּד (ממש) הוֹרֵג וּמוֹצִיא נְשָׁמוֹת, כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה כְּאוֹתָהּ צוּרָה מַמָּשׁ, שֶׁכָּתוּב (שמות יג) וַיַּהֲרֹג ה' כָּל בְּכוֹר, וְכֵן בְּכָל מִצְרַיִם בְּאוֹתָהּ צוּרָה מַמָּשׁ. וּמִשּׁוּם כָּךְ דִּמִּיתִיךְ רַעְיָתִי, כְּמוֹ שֶׁלָּהּ מַמָּשׁ לַהֲרֹג, שֶׁכָּתוּב כִּי אֲנִי ה' אֲנִי הוּא וְלֹא אַחֵר. וְלֶעָתִיד לָבא מַה כָּתוּב? (ישעיה סג) מִי זֶה בָּא מֵאֱדוֹם חֲמוּץ בְּגָדִים מִבָּצְרָה וְגוֹ'</p>\n<p>בֹּא רְאֵה מַה כָּתוּב. וַיֵּשֶׁב יִשְׂרָאֵל בְּאֶרֶץ מִצְרַיִם בְּאֶרֶץ גֹּשֶׁן וַיֵּאָחֲזוּ בָהּ וַיִּפְרוּ וַיִּרְבּוּ מְאֹד. וַיֵּאָחֲזוּ בָהּ - יְרֻשַּׁת עוֹלָמִים. וַיֵּאָחֲזוּ בָהּ - שֶׁהֲרֵי לָהֶם רְאוּיָה, כְּמוֹ שֶׁבֵּאֲרוּהָ. (אמר רבי יוסי) וַיִּפְרוּ וַיִּרְבּוּ מְאֹד, וַדַּאי, שֶׁהֲרֵי הַצַּעַר לֹא שָׁרָה בָהֶם וְעָמְדוּ בְּתַפְנוּקֵי הָעוֹלָם, וּמִשּׁוּם כָּךְ וַיִּפְרוּ וַיִּרְבּוּ מְאֹד. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9522011423,"<p>וַיְחִי יַעֲקֹב בְּאֶרֶץ מִצְרַיִם שְׁבַע עֶשְׂרֵה שָׁנָה וְגוֹ'. אָמַר רַבִּי יוֹסֵי, הַלֵּב רוֹאֶה בַּנְּבוּאָה, בְּמִצְרַיִם, שֶׁיִּהְיוּ בָנָיו בְּכַמָּה גָלֻיּוֹת, עַד כָּאן, וְעַד עִדָּן שֶׁל קֵץ הַמָּשִׁיחַ.</p>\n<p>וְלֹא הִגִּיעָה לַנְּבוּאָה שֶׁל וַיְחִי אֶלָּא בְּמִצְרַיִם, וְהִיא הַנְּבוּאָה הַמְעֻלָּה מִשֶּׁהִתְנַבְּאוּ (שלא התנבאו) כְּמוֹתָהּ וְלֹא הִגִּיעָה לְשׁוּם אִישׁ מִבְּנֵי הַנְּבִיאִים, אֶלָּא הוּא וּמֹשֶׁה. בְּמֹשֶׁה כָּתוּב (שמות לג) כִּי לֹא יִרְאַנִי הָאָדָם וָחָי. בְּיַעֲקֹב כָּתוּב וַיְחִי יַעֲקֹב. וַיְחִי, נְבוּאָה שֶׁיָּרְדָה מֵהָאַסְפַּקְלַרְיָה (מאירה) הַמְּאִירָה.</p>\n<p>רָצָה לוֹמַר, (חפץ ההוא היה בעיניו) נְבוּאַת הַגָּלוּת שֶׁתִּקְרֶה לְבָנָיו בְּאֶרֶץ כְּנַעַן וּבְכָל אֶרֶץ הִתְיַשֵּׁב בָהּ, מֵאֶרֶץ מִצְרַיִם הָיָה שָׁבוּר לִבּוֹ, שֶׁכָּתוּב כִּי יֵשׁ שֶׁבֶר בְּמִצְרַיִם.</p>\n<p>וְעַל כֵּן הִגִּיעַ וַיְחִי יַעֲקֹב בְּמִצְרַיִם, וְלֹא הָיָה שָׂמֵחַ, כִּי בָּאָרֶץ הַהִיא קִשְׁרָם שֶׁל הָעַמִּים, סַפִּירִים שֶׁל כִּסֵּא הַכָּבוֹד, וְלֹא הִגִּיעַ לָהֶם שׁוּם אִישׁ, לֹא מֵהָעֶלְיוֹנִים וְלֹא מִן הַתַּחְתּוֹנִים, אֶלָּא חַ\"י, וְסוֹד זֶה - כִּי לֹא יִרְאַנִי הָאָדָם וָחָי.</p>\n<p>כַּמָּה הוּא סוֹד עֶלְיוֹן בַּפָּסוּק הַזֶּה, וְאָנוּ הַחֲבֵרִים תְּמֵהִים עֲלֵיהֶם, עַל וַיְחִי שֶׁמַּזְכִּיר עִמּוֹ יַעֲקֹב, הָיָה לוֹ לוֹמַר לְפָנָיו יִשְׂרָאֵל. יִשְׂרָאֵל מִנַּיִן? שֶׁכָּתוּב (ירמיה ב) קֹדֶשׁ יִשְׂרָאֵל לַה' רֵאשִׁית וְגוֹ'. (שמות ד) בְּנִי בְכֹרִי יִשְׂרָאֵל. רַבִּי אֶלְעָזָר בְּנוֹ שֶׁל רַבִּי שִׁמְעוֹן אָמַר, וְכִי לֹא אָמַר הַכָּתוּב (בראשית כה) וַיִּמְכֹּר אֶת בְּכֹרָתוֹ לְיַעֲקֹב?</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן אָבִיו, בִּזְמַן שֶׁהָיוּ יִשְׂרָאֵל אֲמִתִּיִּים וְצַדִּיקִים וְעוֹשִׂים זְכֻיּוֹת וְלֹא הָיוּ פוֹחֲדִים יִשְׂרָאֵל, אֶלָּא יַעֲקֹב לְבַדּוֹ. מִשּׁוּם הַטּוֹבוֹת שֶׁעָשׂוּ הָיָה לַעֲשׂוֹת לָהֶם טוֹבוֹת רַבּוֹת זֶה בָּזֶה.</p>\n<p>מִשֶּׁחָטְאוּ וְהֻגְלוּ עַל חֲטָאֵיהֶם וְעַל מַעֲשֵׂיהֶם הָרָעִים, לֹא הָיוּ סוֹבְלִים אוֹתוֹ שֶׁלֹּא יִשָּׁאֲרוּ בָּעוֹלָם בֶּאֱמֶת עַל חֲטָאֵיהֶם, וְעַל זֶה בָּאָה מִדַּת הָרַחֲמִים וְהַדִּין לְחוּד, יִשְׂרָאֵל, וְנָתְנָה אוֹתָם בְּאֶרֶץ גָּלוּתָם.</p>\n<p>יָפֶה שָׁאַלְתָּ, בְּנִי, אֲבָל אִישׁ הַמִּסְתַּכֵּל וְיוֹדֵעַ אוֹתוֹ, יַעֲקֹב הַמְחֻבָּר עִם וַיְחִי הוּא קֹדֶשׁ, וְעַל סוֹד זֶה אוֹמְרִים, יַעֲקֹב בָּחַר אוֹתוֹ לִהְיוֹת סַפִּיר בְּכִסֵּא הַכָּבוֹד.</p>\n<p>רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (ישעיה נז) וְאֶת דַּכָּא וּשְׁפַל רוּחַ לְהַחֲיוֹת רוּחַ שְׁפָלִים וּלְהַחֲיוֹת לֵב נִדְכָּאִים. לֵב נִדְכָּאִים - זֶה יַעֲקֹב, כְּמוֹ שֶׁנֶּאֱמַר, תַּחַת מֵהַדַּרְגָּה יָרְדָה עָלָיו נְבוּאוֹת וּבְרָכוֹת בְּמִצְרַיִם.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי אַבָּא, הַלֵּב רוֹאֶה, שֶׁהָיָה יַעֲקֹב בְּמִצְרַיִם אֵין נְבוּאָתוֹ מְעֻלָּה. (שהארץ שנואה). אֶרֶץ גְּדוֹלָה.</p>\n<p>בֹּא רְאֵה, לֹא זָכָה לְבָרֵךְ אֶת אֶחָד מִבָּנָיו וְלֹא הָיְתָה בְּיָדוֹ רוּחַ לְבָרֵךְ אֶלָּא בְּמִצְרַיִם, כְּשֶׁבֵּרַךְ אוֹתָם כָּל אֶחָד וְאֶחָד בְּסוֹד, וְסוֹד - (בראשית מב) וַיַּרְא יַעֲקֹב כִּי יֵשׁ שֶׁבֶר בְּמִצְרַיִם וַיֹּאמֶר יַעֲקֹב לְבָנָיו לָמָּה תִּתְרָאוּ בּא רְאֵה שֶׁלֹּא נִתְּנָה הַנְּבוּאָה אֶלָּא לִשְׁבוּרֵי הַלֵּב, כְּמוֹ שֶׁנֶּאֱמַר רְדוּ שָׁמָּה וְשִׁבְרוּ לָנוּ מִשָּׁם וְנִחְיֶה וְלֹא נָמוּת.</p>\n<p>אָמַר רַבִּי יוֹסֵי, תַּחַת כִּסֵּא הַכָּבוֹד הַקָּדוֹשׁ, יַעֲקֹב סַפִּיר, שֶׁהִיא מִדַּת הַדִּין לְצִדּוֹ. בָּא וְאָמַר, (שם לב) לֹא יַעֲקֹב יֵאָמֵר עוֹד שִׁמְךְ כִּי אִם יִשְׂרָאֵל כִּי שָׂרִיתָ עִם אֱלֹהִים וְעִם אֲנָשִׁים וַתּוּכָל. אַתָּה מוֹצֵא שֶׁיַּעֲקֹב רָאָה לְצִדּוֹ מִדַּת הַדִּין. וַיִּזְרַח לוֹ הַשֶּׁמֶשׁ כַּאֲשֶׁר עָבַר אֶת פְּנוּאֵל וְגוֹ', וְסוֹד הַדָּבָר - (ירמיה ו) אוֹי לָנוּ כִּי פָנָה הַיּוֹם כִּי יִנָּטוּ צִלְלֵי עָרֶב.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, כְּשֶׁהֻגְלוּ מִירוּשָׁלַיִם וְהוּסַר הַתָּמִיד, וְטִמֵּא הַשּׂוֹנֵא אֶת הַהֵיכָל, בַּזְּמַן הַהוּא לֹא סָבְלָה הַמַּלְכוּת אֶת יִשְׂרָאֵל מִשּׁוּם חֲטָאֵיהֶם, אֶלָּא יִשְׂרָאֵל, מִשּׁוּם שֶׁהִיא מִשְּׁנֵי צְדָדִים - רַחֲמִים וְדִין.</p>\n<p>וְהַמִּלָּה שֶׁל לֹא יַעֲקֹב יֵאָמֵר עוֹד שִׁמְךְ כִּי אִם יִשְׂרָאֵל, כַּאֲשֶׁר מִתְבָּאֵר בִּסבָרָא. יִשְׂרָאֵל וְיַעֲקֹב - זֶה עֶלְיוֹן מִזֶּה, וּבִגְלָלָם הָיָה מַטֵּה מֹשֶׁה חָקוּק מִשְּׁנֵי צְדָדָיו מִשְּׁמוֹ הַקָּדוֹשׁ, אֶחָד רַחֲמִים בְּדִין, וְאֶחָד דִּין בְּדִין.</p>\n<p>וְסוֹד (במדבר כג) לֹא הִבִּיט אָוֶן בְּיַעֲקֹב וְלֹא רָאָה עָמָל בְּיִשְׂרָאֵל - מִשֶּׁאָנוּ בַּגָּלוּת דְּחוּקִים בֵּין שׂוֹנְאִים, וְהִסְתַּלְּקָה הַמַּלְכָּה מִן הַמֶּלֶךְ וְהִתְרַחֲקָה מִמֶּנּוּ, הוּא יַשְׁרֶה שְׁכִינָתוֹ בֵּינֵינוּ וְיִגְאָלֵנוּ, וְהַסּוֹד שֶׁל (ישעיה מד) כֹּה אָמַר ה' מֶלֶךְ יִשְׂרָאֵל וְגֹאֲלוֹ ה' צְבָאוֹת. וַיְחִי חַי, כֹּה אָמַר ה' הַשָּׁמַיִם כִּסִאִי וְהָאָרֶץ הֲדוֹם רַגְלָי.</p>\n<p>בַּבִּנְיָןֹ הָעֶלְיוֹן שְׁתֵּ\"י רַגְלַיִם חַי, לְי' גְּדוֹלָה י' לְח' קְטַנָּה, ח' לְתָי\"ו, וְי' לְו', ו' לְד', זֶה מַה שֶּׁיּוֹצֵא מֵהָעֶלְיוֹן.</p>\n<p>תַּחַת כִּסֵּא הַכָּבוֹד מֵאֶבֶן טוֹבָה בְּאֶרֶץ מִצְרַיִם, הַיְנוּ מַה שֶּׁכָּתוּב וְנָגַף ה' אֶת מִצְרַיִם וְגוֹ', שְׁתֵּי חֲלֻקּוֹת. כִּי טַל אוֹרוֹת טַלֶּךְ - מִשּׁוּם חֲלֻקָּה אַחַת.</p>\n<p>וְלָכֵן מִתְחַלְּפִים כְּאֶחָד. ב' הַפֵּרוּשׁ עַל הַגָּלוּת, א' הַפֵּרוּשׁ הָרִאשׁוֹן. בּא רְאֵה מַה שֶּׁכָּתוּב, בֵּית יַעֲקֹב לְכוּ וְנֵלְכָה בְּאוֹר ה', בַּגָּלוּת, הָאוֹתִיּוֹת שֶׁנִּגְזַר עֲלֵיהֶן עַל חֲטָאֵיהֶם, בֶּאֱמֶת בְּדִין הָיוּ. בַּתּוֹרָה יֵשׁ תַּקָּנָה, וְתֵצְאוּ מֵחֹמֶר הַטִּיט, שֶׁהִיא גָלוּת, וְתֵלְכוּ לְאוֹר ה'.</p>\n<p>א', רְצוֹנוֹ לוֹמַר בָּאָרֶץ, נִרְאֵית בָּאָה בִּגְזֵרַת סֵפֶר הַתּוֹרָה, וְהֵם מִתְחַלְּקִים בָּאָרֶץ בָּאָרֶץ אַתָּה מוֹצֵא בִּגְזֵרַת סֵפֶר הַתּוֹרָה, ר\"ץ מִתְחַבְּרִים כְּאֶחָד גָּלוּת. מַהִי גָּלוּת מִצְרַיִם? אַרְבַּע מֵאוֹת שָׁנָה הָיָה אוֹמֵר לְאַבְרָהָם שֶׁתִּהְיֶה גָלוּת לְבָנָיו בְּמִצְרַיִם, וּכְשֶׁהָיִיתָ מוֹנֶה אוֹתָם, מָאתַיִם וְתִשְׁעִים שָׁנִים הָיוּ.</p>\n<p>בֹּא רְאֵה, וַיָּמָת יוֹסֵף בֶּן מֵאָה וְעֶשֶׂר שָׁנִים. רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (ישעיה ז) הִנֵּה הָעַלְמָה הָרָה וְיֹלֶדֶת בֵּן וְקָראת שְׁמוֹ עִמָּנוּאֵל. הֵרָיוֹן וְלֵדָה, שֶׁנִּתְמַלְּאוּ לְגָלֻיּוֹת וּלְצָרוֹת רַבּוֹת וְעִדָּנִים רָעִים. וְאַף עַל גַּב שֶׁיִּהְיֶה עִמָּנוּ, הַמַּלְכָּה מִזְדַּעְזַעַת וּמִתְרַחֶקֶת מִבַּעְלָהּ, תִּהְיֶה עִמָּנוּ בַּגָּלוּת, בֶּן מֵאָה וְעֶשֶׂר הָיְתָה הַחֲקִיקָה שֶׁנִּתּוֹסְפָה. יִרְצֶה לוֹמַר שֶׁהָיָה עוֹבֵר מִן הַגָּלוּת מֵאָה וְעֶשֶׂר שָׁנִים וּמָאתַיִם וְתִשְׁעִים, וְיִהְיוּ אַרְבַּע מֵאוֹת שָׁנָה. וְלֹא נִמְנֵית גָּלוּתוֹ שֶׁל יַעֲקֹב אֶלָּא מִשֶּׁמֵּת יוֹסֵף.</p>\n<p>וַיְהִי יְמֵי יַעֲקֹב שְׁנֵי חַיָּיו שֶׁבַע שָׁנִים וְאַרְבָּעִים וּמְאַת שָׁנָה. כָּאן סוֹד בַּגָּלוּת בְּמִנְיָן, תִּקּוּנֵי הַגָּלֻיּוֹת שֶׁיִּהְיוּ הַבָּנִים בְּמִדַּת הַדִּין שָׁלֹשׁ גָּלֻיּוֹת. רִאשׁוֹנָה שֶׁל מִצְרַיִם, שֶׁנִּמְשַׁל בְּשֶׁבַע שָׁנִים. רַבִּי חִיָּיא פָּתַח וְאָמַר, (שיר ב) הִשְׁבַּעְתִּי אֶתְכֶם בְּנוֹת יְרוּשָׁלם בִּצְבָאוֹת אוֹ בְּאַיְלוֹת וְגוֹ'.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, מִכָּאן (ירמיה לא) מֵרָחוֹק ה' נִרְאָה לִי וְאַהֲבַת עוֹלָם אֲהַבְתִּיךְ וְגוֹ'. כָּאן סוֹד הַגָּלוּת, הַתַּקָּנָה שֶׁיִּהְיוּ בְּנֵי יִשְׂרָאֵל מְשֻׁחְרָרִים מִגָּלֻיּוֹת, וְיִתְרַצֶּה לוֹמַר שֶׁיִּהְיוּ הַבָּנִים הַקְּדוֹשִׁים, שֶׁהֻגְלוּ עַל חֲטָאֵיהֶם בְּדִין, שָׁנִים רַבּוֹת יִהְיֶה, (ויקרא כו) שֶׁבַע כְּחַ אתֵיכֶם, (בראשית ד) כִּי שִׁבְעָתַיִם יֻקַּם קָיִן, בַּגָּלוּת הָרִאשׁוֹנָה שֶׁל מִצְרַיִם שֶׁהִיא קְטַנָּה.</p>\n<p>שֵׁנִית - גָּלוּת הַשּׁוֹפְטִים שֶׁנִּמְשְׁלָה לְאַרְבָּעִים שָׁנִים, בְּשֶׁבַע שֶׁהֵם רַבִּים מִמֶּנּוּ.</p>\n<p>שְׁלִישִׁית - הַגָּלוּת שֶׁאָנוּ בָּהּ, אֲרֻכָּה, שֶׁנִּמְשְׁלָה לְמֵאָה שָׁנִים, לְאַרְבָּעִים. וְהַיְנוּ שֶׁגִּלָּה הָעֶלְיוֹן שֶׁאָמַר (דניאל יב) וּמֵעֵת הוּסַר הַתָּמִיד וְלָתֵת שִׁקּוּץ שּמֵם וְגוֹ'.</p>"],[9522011424,"<p>וַיִּקְרְבוּ יְמֵי יִשְׂרָאֵל לָמוּת. רַבִּי חִזְקִיָּה אָמַר, רָאָה צָרָה זוֹ שֶׁל הַגָּלוּת שֶׁהָיְתָה קוֹרֵאת לְבָנָיו קִרְבָה עַל נַפְשׁוֹ וְדָחֲקָה לָמוּת, לֹא נִשְׁאַר חַי. כְּשֶׁהָיָה יוֹרֵד מִדְּרָגוֹת מִשּׁוּם חֲטָאֵי יִשְׂרָאֵל, לֹא יָרַד עִמָּם בַּגָּלוּת. אַשְׁרֵי חֶלְקָם. שֶׁאִם לֹא יָרַד עִמָּם בַּגָּלוּת, יִשָּׁאֲרוּ בֵּין הָעַמִּים, וְאַתָּה אָמַרְתָּ (ישעיה נ) מַדּוּעַ בָּאתִי וְאֵין אִישׁ קָרָאתִי וְאֵין עוֹנֶה. וְאֵין עוֹנֶה - זֶה יִשְׂרָאֵל. בָּאתִי וְאֵין אִישׁ - זוֹ שְׁכִינָה. הֲקָצוֹר קָצְרָה יָדִי מִפְּדוּת וְאִם אֵין בִּי כֹחַ לְהַצִּיל הֵן בְּגַעֲרָתִי אַחֲרִיב יָם אָשִׂים נְהָרוֹת מִדְבָּר. הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן חֵלֶק לְיִשְׂרָאֵל שֶׁלֹּא יִשְׁלֹט גָּדוֹל אַחֵר עֲלֵיהֶם. יָרְדוּ לַגָּלוּת - שְׁכִינָה עִמָּהֶם, וְהוּא רָחוֹק מִן הַמַּלְכָּה.</p>"],[9522011425,"<p>וַיִּקְרָא לִבְנוֹ לְיוֹסֵף וַיֹּאמֶר לוֹ אִם נָא מָצָאתִי חֵן בְּעֵינֶיךְ. חָקַר אֶת בָּנָיו כֻּלָּם וְאָמַר לָהֶם: צָרוֹת רַבּוֹת, רעוֹת גְּדוֹלוֹת, אֲנִי רוֹאֶה לָבֹא עַל דּוֹרוֹתֵיכֶם נִמְצְאוּ רַחֲמִים עֶלְיוֹנִים.</p>\n<p>וְאִם אַתֶּם רוֹצִים לָצֵאת מִכָּל צָרָה, הִשָּׁבְעוּ לִי וּתְנוּ בֵינֵינוּ רִבּוֹן הָעוֹלָם, וְתַעֲשׂוּ אֱמֶת וְדִין, וְתִהְיוּ כַאֲבוֹתֵיכֶם, וְצַוּוּ בְּכָל דּוֹר וָדוֹר שֶׁיֵּלְכוּ אַחֲרֵיהֶם. וְאִם אַתֶּם רוֹצִים לַעֲשׂוֹת כָּךְ, תֵּצְאוּ מִכָּל צָרָה שֶׁתָּבֹא עֲלֵיכֶם.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, (עמוס ה) וְהַצִּיגוּ בַשַּׁעַר מִשְׁפָּט אוּלַי יֶחֱנַן ה' אֱלֹהֵי צְבָאוֹת שְׁאֵרִית יוֹסֵף.</p>\n<p>וְאִם תַּעֲשׂוּ כָּךְ, לֹא תִקְבְּרוּ אֶחָד מִן בָּנַי, אֶלָּא אִתִּי תָּשׁוּבוּ לְאַרְצְכֶם בְּשָׁלוֹם.</p>\n<p>זֶהוּ שֶׁכָּתוּב (בראשית כד) שִׂים נָא יָדְךְ תַּחַת יְרֵכִי. מַהוּ יָדְךְ? פָּתַח וְאָמַר, (תהלים מה) חֲגוֹר חַרְבְּךְ עַל יָרֵךְ גִּבּוֹר הוֹדְךְ וַהֲדָרֶךְ. חֶרֶב שֶׁיֵּשׁ בָּהּ חֶסֶד וֶאֱמֶת, שְׁתֵּי סְפִירוֹת, וְלֹא עוֹזְבִים זֶה אֶת זֶה. וְלָכֵן אָמַר חֶסֶד וֶאֱמֶת יְקַדְּמוּ פָנֶיךְ, (איכה ד) פְּנֵי ה' חִלְּקָם. וְאִם יִהְיוּ בָנָיו טוֹבִים וְעוֹשִׂים מַה שֶּׁנִּשְׁבְּעוּ, לֹא מֵת אֶחָד מִבְּנֵיהֶם בְּמִצְרַיִם, שֶׁכָּל טוֹב וְטוֹב שֶׁגָּזַר שֵׁם הָאֱלוֹהַּ עַל אֲנָשִׁים, אֵינוֹ אֶלָּא עַל שֶׁיִּהְיוּ טוֹבִים, וְאִם לֹא - לֹא, כְּמוֹ שֶׁאָמַר דָּוִד (מלכים א ב) לְמַעַן יָקִים ה' אֶת דְּבָרוֹ אֲשֶׁר דִּבֶּר עָלַי לֵאמֹר אִם יִשְׁמְרוּ בָנֶיךְ אֶת דַּרְכָּם לָלֶכֶת לְפָנַי בֶּאֱמֶת. וְאִם לֹא - לֹא.</p>\n<p>בֹּא רְאֵה כַּמָּה הוּא עָדִיף רוּחַ הָאָב מֵרוּחַ הַבֵּן, שֶׁרוּחַ הָאָב הוּא רוּחַ הַבֵּן, רוּחַ מֵרוּחַ עוֹלֶה. וְאִם סִיְּעָה אֲוִיר אַחֶרֶת בָּרוּחַ, לֹא יוֹצֵא שָׁלֵם, שֶׁהֲרֵי הוּא חָסֵר בָּאֲוִיר הַזֶּה, וְהַיְנוּ (ירמיה ב) פֶּרֶא לִמֻּד מִדְבָּר בְּאַוַּת נַפְשָׁהּ שָׁאֲפָה רוּחַ.</p>\n<p>לָמַדְנוּ, רַב הַמְנוּנָא הַזָּקֵן הָלַךְ לְקַפּוֹטְקִיָּא. נִכְנַס לִפְנֵיהֶם רַב יֵיסָא הַזָּקֵן. אָמַר לוֹ, בַּמָּה עֲסַקְתֶּם? אוֹי לוֹ אוֹי לְנַפְשׁוֹ אִם נִשְׁלְפָה רוּחַ טֻמְאָה שֶׁנִּמְצֵאת עִמּוֹ וְהוֹרִישׁ אוֹתָהּ לִבְנוֹ. וְזֶהוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אֵין לוֹ חֵלֶק, מַשְׁאִיר לוֹ חֵלֶק וּמַשְׁאִיר אוֹתוֹ לְהִשָּׁמֵד מִן הָעוֹלָם הַבָּא. אָמַר לוֹ, מִנַּיִן לְךְ זֶה? אָמַר לוֹ, כָּךְ לָמַדְתִּי, שֶׁהַיְרֻשָּׁה הָרָעָה הַזּוֹ יוֹרְשִׁים כָּל בָּנָיו אִם לֹא יָשׁוּבוּ, שֶׁהֲרֵי אֵין דָּבָר הָעוֹמֵד בִּפְנֵי הַתְּשׁוּבָה. וַאֲנִי כָּךְ לָמַדְתִּי, שֶׁהֲרֵי רְפוּאָה זוֹ נָתְנוּ לִי פַּעַם אַחַת שֶׁהָיִיתִי רָשׁוּם בְּפָנַי, וְיוֹם אֶחָד הָיִיתִי הוֹלֵךְ בַּדֶּרֶךְ וּפָגַשְׁתִּי צַדִּיק אֶחָד, וְעַל יָדוֹ עָבַר מִמֶּנִּי אוֹתוֹ הָרֹשֶׁם. אָמַר לוֹ, מַה שִּׁמְךְ? אָמַר לוֹ, אֶלְעָזָר, וְקָרָאתִי לוֹ אֶלְעָזָר אַחֵר. אָמַר לוֹ, בָּרוּךְ הָרַחֲמָן שֶׁרָאִיתִי אוֹתְךְ, אַשְׁרֵי חֶלְקְךְ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>וַיֹּאמֶר הִשָּׁבְעָה לִי וְגוֹ'. רַבִּי חִזְקִיָּה פָּתַח וְאָמַר, (ישעיה סב) נִשְׁבַּע ה' בִּימִינוֹ וּבִזְרוֹעַ עֻזּוֹ. נִשְׁבַּע הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיּוֹצִיא אֶת יִשְׂרָאֵל מֵהַגָּלוּת שֶׁלָּהֶם, וְזֶה נִשְׁבַּע לָהֶם שְׁבוּעָה שֶׁלֹּא יַעֲזֹב אוֹתָם בְּאֶרֶץ שׂוֹנְאֵיהֶם.</p>\n<p>וַיֹּאמֶר שַׁלְּחֵנִי כִּי עָלָה הַשָּׁחַר וַיֹּאמֶר לֹא אֲשַׁלֵּחֲךְ כִּי אִם בֵּרַכְתָּנִי (בראשית לב). מַה זֶּה בֵּרַכְתָּנִי? נָתַן לָהֶם גָּלוּת, וְנִשְׁבַּע לָהֶם שֶׁיֵּצְאוּ מִמֶּנָּה.</p>\n<p>שָׁנִינוּ, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְנֵי יִשְׂרָאֵל שֶׁיִּהְיוּ כָּל אֶחָד וְאֶחָד תַּחַת כִּסְאוֹ וְיִהְיוּ מְעֻלִּים מִכָּל הָעֶלְיוֹנִים. בִּשְׁבִיל זֶה תִּמְצָא וָא\"ו אֲרֻכָּה. נִשְׁבַּע הַקָּדוֹשׁ בָּרוּךְ הוּא לַשְּׁלֵמוּת שֶׁל שִׁשָּׁה דוֹרוֹת, וּבִשְׁבִיל שֵׁשׁ וַיִּשְׁתַּחוּ יִשְׂרָאֵל עַל רֹאשׁ הַמִּטָּה. הִשְׁתַּחֲוָה יִשְׂרָאֵל שֶׁיָּבֹא הַמָּשִׁיחַ בְּסוֹף הַמִּנְיָן הַזֶּה וְתִשְׁרֶה שְׁכִינָה עִמָּם.</p>"],[9522011426,"<p>וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה וַיֹּאמֶר לְיוֹסֵף הִנֵּה אָבִיךְ חוֹלֶה וְגוֹ'. מִשְׁנָה, אָמַר רַבִּי חִזְקִיָּה, לֹא בָא הַכָּתוּב לְהַשְׁמִיעֵנוּ מַה שֶּׁעָשָׂה, אֶלָּא בָּא הַכָּתוּב לְהָבִיא מַה שֶּׁיִּהְיֶה בְּסוֹף הַגָּלוּת כָּל אֵלֶּה לְסוֹף הַמִּנְיָן שֶׁנִּמְנֶה. רוֹצֶה לוֹמַר שֶׁיָּבֹא הַמָּשִׁיחַ, וְיֹאמַר לוֹ, אָבִיךְ שֶׁבַּשָּׁמַיִם מְמַהֵר לְקַבֵּל פָּנֶיךְ הַצּוֹפוֹת לְקֵץ הַמָּשִׁיחַ. יְהִי רָצוֹן מֵאֱלֹהֵי הַשָּׁמַיִם שֶׁיִּשָּׂא בָנָיו שֶׁהִרְבּוּ בַגָּלוּת וּמִשֶּׁנִּשְׁכְּחוּ בָהֶם, שֶׁשָּׁכַח אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא בַּחֲטָאֵיהֶם בֶּאֱמֶת.</p>\n<p>כְּשֶׁבָּא רַבִּי אַבָּא, אָמַר, לֹא לִדְרָשָׁה בָּאתִי, חֲשֹׁב סוֹד הַדָּבָר (שם ל) יֹסֵף ה' לִי בֵּן אַחֵר, כְּפִי שֶׁפֵּרַשְׁנוּ לְעֵיל. הֲרֵי שְׁמוֹ הַקָּדוֹשׁ בְּיוֹסֵף, יה\"ו יֹאמַר, הֲרֵי אָבִיךְ רִבּוֹן הָעוֹלָם שֶׁבָּא לַעֲשׂוֹת טוֹב לְבָנָיו שֶׁיֵּצְאוּ מֵהַגָּלוּת שֶׁלָּהֶם, וְאִם אֵינְךְ רוֹצֶה בַּאֲמִתְּךְ, הָרִבּוּעַ ידו\"ד אֶחָד יַעֲשֶׂה אוֹתְךְ, וְיוֹדְעִים שֶׁתָּשׁוּב הַמַּלְכָּה לִמְקוֹמָהּ.</p>\n<p>שֶׁאֲבוֹתֵינוּ הֵם מֶרְכָּבוֹת שֶׁלְּמַעְלָה, וַיַּעַל אֱלֹהִים מֵעַל אַבְרָהָם, הָאָבוֹת שׁוֹקֵי הָעוֹלָם, (מיכה ז) תִּתֵּן אֱמֶת לְיַעֲקֹב חֶסֶד לְאַבְרָהָם. שָׁנִינוּ שֶׁיָּבֹא הַמָּשִׁיחַ.</p>"],[9522011427,"<p>רַבִּי יוֹסֵי פָּתַח וְאָמַר, (זכריה יד) וְהָיָה יוֹם אֶחָד הוּא יִוָּדַע לַה' לֹא יוֹם וְלֹא לַיְלָה וְהָיָה לְעֵת עֶרֶב יִהְיֶה אוֹר. רוֹצֶה לוֹמַר, שְׁנֵי מִקְרִים רָעִים שֶׁבָּאוּ לְבָנָיו לִהְיוֹת בַּגָּלוּת בְּאֶרֶץ שׂוֹנְאֵיהֶם, וְלֹא יִסְתַּכֵּל בָּהֶם כַּמָּה שָׁנִים רַבּוֹת עַל חֲטָאֵיהֶם בֶּאֱמֶת, כֵּן יִזְנַח אוֹתָם בְּאֶרֶץ שׂוֹנְאֵיהֶם, וְיִשָּׂא בָנָיו שֶׁאֵרְעוּ לָהֶם הָרָעוֹת הַלָּלוּ, וְיַנְהִיגֵם לְאֶרֶץ טוֹבָה כְּפֵרוּשׁ הַכָּתוּב.</p>\n<p>וְהָיָה שְׁנֵי גְדוֹלִים רַבִּים מְעֻלִּים הָיוּ דוֹפְקִים תַּחַת כִּסֵּא הַכָּבוֹד, שֶׁאֶפּוֹטְרוֹפּוֹס שֶׁל יִשְׂרָאֵל מִדָּה חֲמִישִׁית, מִשּׁוּם הֱיוֹתָם בַּגָּלוּת כָּל הַזְּמַן הַזֶּה, וְקָרָה שֶׁיִּשְׁכַּח אוֹתָם בְּאֶרֶץ שׂוֹנְאֵיהֶם.</p>\n<p>וְהוּא שְׁתֵּי מִדּוֹת בִּשְׁתֵּי חֲלֻקּוֹת. יָצְאָה אַחַת וְדִבְּרָה כְּנֶגֶד רִבּוֹן הָעוֹלָם, וְנָתַן לָהּ רְשׁוּת לְדַבֵּר כָּל מַה שֶּׁתִּרְצֶה, וְרָאֲתָה בְּיִשְׂרָאֵל מִצַּד אֶחָד לִגְזר עַל יִשְׂרָאֵל שֶׁיֵּצְאוּ מֵהַגָּלוּת בִּזְכוּת אֲבוֹתֵיהֶם, וּמִצַּד אַחֵר רָצְתָה לִגְזֹר עֲלֵיהֶם בִּשְׁבִיל חֲטָאֵיהֶם כְּשֶׁאָמְרוּ עֲלֵיהֶם רָעָה גְדוֹלָה, הֲרֵי אַרְבַּע מִדּוֹת, וְלֹא הָיְתָה בָהֶם מִדָּה חֲמִישִׁית אֶפּוֹטְרוֹפּוֹס שֶׁל יִשְׂרָאֵל, וְדִבְּרוּ כָּל מַה שֶּׁרָצוּ.</p>\n<p>עַד שֶׁהִגִּיעָה לָהֶם הַמִּדָּה הַחֲמִישִׁית, וְהָיָה בְּכִסֵּא הַכָּבוֹד מִן הַשֵּׁם הַקָּדוֹשׁ, וְאָמְרָה עַל בְּנֵי יִשְׂרָאֵל טוֹב, וְלֹא הָיוּ פוֹחֲדוֹת שְׁתֵּי מִדּוֹת הָרִאשׁוֹנוֹת לְדַבֵּר לְפָנָיו, בִּזְכוּת הַמִּדָּה הַחֲמִישִׁית שֶׁנִּמְשְׁלָה לְלַיְלָה, וְיָצְאָה לְהָאִיר לָהֶם. וְלָכֵן פָּתַח, וְהָיָה יוֹם אֶחָד הוּא יִוָּדַע לַה' לֹא יוֹם וְלֹא לַיְלָה וְהָיָה לְעֵת עֶרֶב יִהְיֶה אוֹר.</p>\n<p>שָׁנִינוּ, (בראשית א) וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם וְלַחֹשֶׁךְ קָרָא לָיְלָה. וְשָׁם אָמַר וְחֹשֶׁךְ עַל פְּנֵי תְהוֹם. וְקָשֶׁה שֶׁלּוֹ עַל שֶׁלּוֹ. בָּא רַבִּי אֶלְעָזָר לְרַבִּי שִׁמְעוֹן אָבִיו וְאָמַר לוֹ, אָבִי מוֹרִי, מַה זֶּה? אָמַר לוֹ, מִבְּרֵאשִׁית עַד ו' דּוֹרוֹת בָּרָא ידו\"ד אֶחָד, רוֹצֶה לוֹמַר, ו' שֶׁל שְׁמוֹ נָתַן בּוֹ רוּחַ חָכְמָה. עַד כָּאן לֹא הָיָה יוֹדֵעַ מַהוּ חֹשֶׁךְ. קָם רַבִּי אֶלְעָזָר וְנָשַׁק יָדוֹ שֶׁל אָבִיו.</p>\n<p>קָם רַבִּי אַבָּא וְשָׁאַל, מַה זֶּה חֹשֶׁךְ? סָבְבוּ הַחֲבֵרִים וְלֹא הִגִּיעוּ לְמַה שֶּׁשָּׁאַל. עָשׂוּ מַעֲשֶׂה, וְהִגִּיעַ קוֹל מִלִּפְנֵי רִבּוֹן הָעוֹלָם בְּפָסוּק זֶה, (איוב י) אֶרֶץ עֵפָתָה וְגוֹ', צַלְמָוֶת וְלֹא סְדָרִים וַתֹּפַע כְּמוֹ אֹפֶל. גֵּיהִנֹּם מִלִּפְנֵי שֶׁנִּבְרָא הָעוֹלָם הָיָה גָנוּז לָרְשָׁעִים. אוֹי לָרְשָׁעִים שֶׁיִּהְיוּ כְּשֶׁיַּעֲשֶׂה הָאֱלוֹהַּ אֶת אֵלֶּה, (ישעיה ס) כִּי הִנֵּה הַחֹשֶׁךְ יְכַסֶּה אֶרֶץ וַעֲרָפֶל לְאֻמִּים וְעָלַיִךְ יִזְרַח ה' וּכְבוֹדוֹ עָלַיִךְ יֵרָאֶה. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא בָרָא לָהֶם זֶה. (תהלים קמד) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ אַשְׁרֵי הָעָם שֶׁה' אֱלֹהָיו.</p>"],[9522011428,"<p>וַיַּגֵּד לְיַעֲקֹב וַיֹּאמֶר הִנֵּה בִּנְךְ יוֹסֵף בָּא אֵלֶיךְ. רַבִּי יוֹסֵי אָמַר, מַלְאָךְ הוּא שֶׁהָיָה עָתִיד לוֹמַר טוֹב עַל בְּנֵי יִשְׂרָאֵל כְּשֶׁיָּשׁוּבוּ לַקָּדוֹשׁ- בָּרוּךְ-הוּא בְּכָל צָרָתָם, כְּשֶׁיָּבֹא קֵץ הַמָּשִׁיחַ. בְּכָל צָרָה שֶׁתָּבֹא עֲלֵיהֶם יֹאמְרוּ לַמִּדָּה: בָּנַיִךְ בָּאִים אֵלַיִךְ. וְיִגָּאֲלוּ הַטּוֹבִים.</p>\n<p>אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁנִּקְרְאוּ בְּנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֵם כְּמוֹ מַלְאָכִים. (איוב לח) וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. הוי\"ה מָה?</p>\n<p>בֹּא רְאֵה, מִנַּיִן שֶׁקָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא לְיַעֲקֹב אֵל? אַתָּה בָּעֶלְיוֹנִים, וַאֲנִי אֶהְיֶה בַּתַּחְתּוֹנִים, (אתה תהיה בתחתונים, ואני אהיה אלוה בעליונים). מַה זֶּה אוֹמֵר? (בראשית יז) וַיַּעַל אֱלֹהִים מֵעַל אַבְרָהָם. הָאָבוֹת הֵם מֶרְכְּבוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא. שָׁנִינוּ (מיכה יז) תִּתֵּן אֱמֶת לְיַעֲקֹב חֶסֶד לְאַבְרָהָם. הֲרֵי שְׁתֵּי סְפִירוֹת בִּשְׁתֵּי מֶרְכָּבוֹת גְּדוֹלוֹת עֶלְיוֹנוֹת.</p>\n<p>שְׁלִישִׁי יִצְחָק. מַה זֶּה (בראשית לא) וַיִּשָּׁבַע יַעֲקֹב בְּפַחַד אָבִיו יִצְחָק. וּמִשּׁוּם פַּחַד יִצְחָק שֶׁהָיָה סְפִירָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא כִּסֵּא כָבוֹד, מֶרְכָּבָה עֶלְיוֹנָה, וּסְפִירָה שֶׁל יִצְחָק הִיא מֵעֶלְיוֹנִים, מְפֹרֶשֶׁת יוֹתֵר מִכָּל הַסְּפִירוֹת שֶׁל הָאָבוֹת. זֶהוּ שֶׁכָּתוּב וַיִּשָּׁבַע יַעֲקֹב בְּפַחַד אָבִיו יִצְחָק.</p>\n<p>רַבִּי אַבָּא פָּתַח וְאָמַר, אֱלֹהֵי אַבְרָהָם וֵאלֹהֵי נָחוֹר יִשְׁפְּטוּ בֵינֵינוּ אֱלֹהֵי אֲבִיהֶם וַיִּשָּׁבַע יַעֲקֹב בְּפַחַד אָבִיו יִצְחָק. מִפָּסוּק זֶה אַתָּה יָכוֹל לָדַעַת זֶה.</p>"],[9522011429,"<p>וַיִּתְחַזֵּק יִשְׂרָאֵל וַיֵּשֶׁב עַל הַמִּטָּה. וְסוֹד הַכָּתוּב (דניאל יב) וּבָעֵת הַהִיא יַעֲמֹד מִיכָאֵל הַשַּׂר הַגָּדוֹל הָעֹמֵד עַל בְּנֵי עַמֶּךְ וְהָיְתָה עֵת צָרָה. רַבִּי שִׁמְעוֹן אָמַר, זוֹ גְּבוּרַת יַד מִיכָאֵל הַגָּדוֹל, כְּמוֹ שֶׁהָיָה מִשְׁתַּחֲוֶה לָהּ מִקֹּדֶם לָכֵן. לְמִי הָיָה מִשְׁתַּחֲוֶה? מִשְׁתַּחֲוֶה לַמִּטָּה. הָיְתָה הַמִּטָּה פְּתוּחָה פָנֶיהָ. לַמִּילָה הָיָה מִשְׁתַּחֲוֶה, שֶׁהֲרֵי הָיְתָה חֲבִיבָה עָלָיו.</p>\n<p>כִּי חִלֵּל יְהוּדָה קֹדֶשׁ ה' אֲשֶׁר אָהֵב וּבָעַל בַּת אֵל נֵכָר (מלאכי ב). כְּשֶׁהִסְתַּלֵּק זִיווֹ מִמֶּנּוּ עַל חֲטָאֵיהֶם, וְלֹא הָיָה לָהּ לַעֲמֹד לְפָנָיו, וְגֹרְשָׁה הַמַּלְכָּה מִן הַמֶּלֶךְ מִשּׁוּם שֶׁלֹּא יָכְלָה לְהַשְׁאִיר אֶת בָּנֶיהָ בֵּין הָעַמִּים לַהֲרֹג אוֹתָם, וְהוּא הָיָה בָּאָרֶץ הַקְּדוֹשָׁה, בָּזֶה שֶׁיִּהְיוּ עַמִּים נָכְרִים מִן עַמּוֹ. רוֹצֶה לוֹמַר, הִכְנִיס שְׁכִינָה בֵּינֵיהֶם בַּגָּלוּת וּבִזְמַן שֶׁלֹּא הָיְתָה בָּאָרֶץ, וְהִיא בְּאֶרֶץ הָעַמִּים בַּזִּיו שֶׁל יִשְׂרָאֵל נִשְׁמְרוּ הָעַמִּים שֶׁסְּבִיבוֹתֵיהֶם.</p>\n<p>לָמַדְנוּ, אָמַר רַבִּי יוֹסֵי, שְׁנֵי גְדוֹלִים הָיוּ תַּחַת כִּסֵּא הַכָּבוֹד הַקָּדוֹשׁ, וַהֲרֵי שְׁמוֹ אֶחָד מֵהֶם הוּא מִטָּה, שֶׁהָיָה שׁוֹרֶה בָּאוֹצָר שֶׁל הַהֵיכָל. וַהֲרֵי אָנוּ בַּגָּלוּת, לֹא נִשְׁאָר בֵּינֵינוּ אֶלָּא זֶה שֶׁהוּא מַטְבֵּעַ שֶׁלּוֹ, וְהוּא חָתוּם מִשְּׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>זֶהוּ שֶׁכָּתוּב (שמות כג) הִנֵּה אָנֹכִי שֹׁלֵחַ מַלְאָךְ לְפָנֶיךְ לִשְׁמָרְךְ וְגוֹ'. לֹא לְדַבֵּר כָּךְ, אֶלָּא בָּעוֹלָם הַבָּא, כְּמוֹ שֶׁפֵּרַשְׁנוּ בִּמְקוֹמוֹ וְהִיא הַשְּׁמִירָה בַּדֶּרֶךְ, אֲנִי הִשְׁרֵיתִי שְׁכִינָה בֵּינֵיכֶם לִשְׁמֹר אֶתְכֶם בַּגָּלוּת, וְהִיא שָׁמְרָה אֶתְכֶם עַד שֶׁתָּבִיא אֶתְכֶם לְאַרְצְכֶם כְּמוֹ שֶׁהֱיִיתֶם מִקֹּדֶם לָזֶה. אֲשֶׁר הֲכִנֹתִי - מוֹשָׁבוֹת מִקֹּדֶם לָזֶה.</p>\n<p>זוֹ שְׁכִינָה מִן מטטרו\"ן, וְגֹרְשָׁה הַמַּלְכָּה מֵהַמֶּלֶךְ עַד שֶׁתָּשׁוּב לִמְקוֹמָהּ, וְסוֹד - כִּי רַק עוֹג מֶלֶךְ הַבָּשָׁן נִשְׁאַר מִיֶּתֶר הָרְפָאִים הִנֵּה עַרְשׂוֹ עֶרֶשׂ בַּרְזֶל הֲלֹה הִוא בְּרַבַּת בְּנֵי עַמּוֹן, כְּמוֹ שֶׁפֵּרַשְׁנוּ בִּמְקוֹמוֹ.</p>\n<p>וְהַדֶּרֶךְ, שֶׁנִּמְשְׁלָה לַגָּלוּת, שָׁמַר אוֹתָם בַּגָּלוּת עַל צָרָה שֶׁתָּבֹא עֲלֵיכֶם, עַד שֶׁיָּבֹא וְיַכְנִיס אֶתְכֶם לָאָרֶץ שֶׁנִּשְׁבַּע לַאֲבוֹתֵיכֶם שֶׁנִּשְׁמְרָה.</p>\n<p>שַׂר הַשֵּׁנִי הוּא, שֶׁהוּא תַּחַת כִּסֵּא הַקָּדוֹשׁ, הַשּׁוֹרֶה בְּאוֹצַר הַהֵיכָל הוּא נוּרִיאֵל. כִּי הַשַּׂר שֶׁל יִשְׂרָאֵל שֶׁנִּתְמַנָּה עֲלֵיהֶם, בְּכָל עֵת שֶׁהָיְתָה הַשְּׁכִינָה עִם הַמֶּלֶךְ הָיָה יוֹצֵא וְנִכְנַס לִפְנֵיהֶם הוּא מְטַטְרוֹן. וְהוּא, מְקַבֵּל עֲבוֹדָתָם שֶׁל יִשְׂרָאֵל להקב\"ה כְּאֵשׁ, וְכַאֲשֶׁר נִתְבַּטֵּל הָאֵשׁ, כִּי הָגְלוּ, נִסְתַּלֵּק אוֹרָה שֶׁל הַשְּׁכִינָה, וְנִסְתַּלְּקָה הַשְּׁכִינָה מִן הַמֶּלֶךְ.</p>\n<p>רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (רות ג) לִינִי הַלַּיְלָה וְהָיָה בַבֹּקֶר אִם יִגְאָלֵךְ טוֹב יִגְאָל. אָמַר רַבִּי יוֹסֵי, הִשְׁלִיט רַחֲמִים עַל הַדִּין. (בראשית א) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב. אוֹר וְטוֹב שָׁוִים, שֶׁהוּא מַבּוּעֵי הַנְּחָלִים שֶׁיּוֹצֵא מֵהֶם הַיָּם וְהַנַּחַל שֶׁבָּעוֹלָם.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי שִׁמְעוֹן, פַּעַם אַחַת עָלִיתִי וְיָרַדְתִּי לְהָאִיר בְּמַבּוּעֵי הַנְּחָלִים, וְעָלָה אַחֲרַי רַבִּי אַבָּא. אָמַר לִי, בַּמָּה עֲסַקְתֶּם? אָמַרְתִּי לוֹ, בַּפָּסוּק הַזֶּה (קהלת א) שֶׁכָּל הַנְּחָלִים הוֹלְכִים אֶל הַיָּם וְהַיָּם אֵינֶנּוּ מָלֵא. מִזִּיווֹ נִבְרְאוּ כָּל הַגְּדוֹלִים שֶׁמִּן הָעוֹלָם, וּמִזִּיווֹ נוֹבְעִים כָּל הַנְּחָלִים, הַנְּחָלִים שֶׁהֵם בַּפָּסוּק הַזֶּה נְמוּכִים בַּגָּלוּת הַזֹּאת, שֶׁהֲרֵי חֹשֶׁךְ וַאֲפֵלָה, חִבַּת הָאֵם עָשָׂה לָהֶם, וְאִם לֹא, הַנַּחַל עוֹשֶׂה לְבִתּוֹ. גְּדֻלָּה שְׁנִיָּה הוּא, הוּא תַּחַת הַקָּדוֹשׁ שֶׁשּׁוֹכֵב עַל גַּנֵּי הַהֵיכָל, שֶׁהֲרֵי הַשַּׂר שֶׁל יִשְׂרָאֵל שֶׁהָיָה מְמֻנֶּה עֲלֵיהֶם, בְּכָל זְמַן שֶׁהָיְתָה הַגְּבִירָה עִם הַמֶּלֶךְ, הָיָה יוֹצֵא וּבָא לִפְנֵיהֶם מטטרו\"ן, וְהוּא מַקְרִיב עֲבוֹדָתָם לְהַקָּדוֹשׁ בָּרוּךְ הוּא כְּאֵשׁ. כַּאֲשֶׁר הִתְבַּטְּלָה הָאֵשׁ וְגָלוּ, הִסְתַּלֵּק זִיוָהּ, וְהִסְתַּלְּקָה הַגְּבִירָה מִן הַמֶּלֶךְ. זֶה לֹא הָיָה שָׁלֵם עַד שֶׁיָּבֹא צַד אַחֵר שֶׁלֹּא הָיָה נִמְנֶה בַגָּלוּת.</p>"],[9522011430,"<p>וְהַשֵּׁמוֹת שֶׁנִּקְרָאִים יָד, הִיא מַבּוּעַ לַכֹּל, וְתִמְצָא יַד הוי\"ה, (ישעיה נט) הֵן לֹא קָצְרָה יַד יְהֹוָה, שֶׁלֹּא נִזְכַּר יָד אֶלָּא בַשֵּׁם אֶחָד.</p>\n<p>בָּא רַבִּי אֶלְעָזָר וְשָׁאַל לְרַבִּי שִׁמְעוֹן אָבִיו, וּבָכָה וְאָמַר לוֹ, גַּלֵּה לִי זֶה הַסּוֹד אָבִי מוֹרִי. אָמַר לוֹ, בְּזֶה הַפָּסוּק יִתְגַּלֶּה לְךְ, (שמות יז) כִּי יָד עַל כֵּס יָהּ מִלְחָמָה לַה'. כֵּס מִשּׁוּם הוי\"ה, שׁוֹלְטִים רַחֲמִים עַל דִּין. רוֹצֶה לוֹמַר, יְהִי רָצוֹן שֶׁיִּהְיֶה לָעוֹלָם בִּמְקוֹם הַגְּבוּרָה יַד ה' הַגְּדוֹלָה מִלְחָמָה שֶׁהָיְתָה בְּמִצְרַיִם, וְאִם לֹא, הָיוּ בְדִינִים.</p>\n<p>וּכְשֶׁיָּבֹא הַמָּשִׁיחַ, יָבֹא בְּהִתְחַדְּשׁוּת בְּיָד גְּדוֹלָה וְיַעֲרֹךְ קְרָב בַּעֲמָלֵק. בְּחֹזֶק יָד הוֹצִיאֲךְ ה' מִמִּצְרַיִם. וּכְשֶׁיָּבֹא שֵׁם שֶׁל יָד בְּחֹזֶק יָד לְבַדּוֹ, הוּא בִּזְמַן שֶׁיַּעֲרֹךְ קְרָב בַּעֲמָלֵק, יָבא הַמָּשִׁיחַ. רַבִּי אֶלְעָזָר מְסַיֵּעַ, (זכריה יד) וְיָצָא ה' וְנִלְחַם בַּגּוֹיִם הָהֵם כְּיוֹם הִלָּחֲמוֹ בְּיוֹם קְרָב. כ\"ס בִּשְׁבִיל יהו\"ה.</p>\n<p>בֹּא רְאֵה, כַּמָּה הִיא יָד הַגְּדוֹלָה שֶׁלֹּא מַגִּיעָה לַיָּד הַזּוֹ הָעֶלְיוֹנָה, לָאָבוֹת הַגְּדוֹלָה לֹּא אַגניּם, וּבְזוֹ הַיָּד יָצְאוּ מִמִּצְרַיִם מִשּׁוּם שֶׁמִּנְיָנָם שָׁוֶה, מוֹנֶה י' לְי', ד' לְד', שָׁוִים זֶה לָזֶה, שֵׁם שֶׁל הַיָּד הַגְּדוֹלָה שֶׁיָּצָא מֵהֶם שָׁוִים בְּאוֹתִיּוֹתֵיהֶם, שֶׁמִּנְיָנָם כְּמִנְיָנָם, שֶׁקִּבְּלָה שְׁתֵּי יָדַיִם, שְׁתַּיִם.</p>\n<p>כֵּיצַד לֹא נִמְנְעוּ זֶה מִזֶּה, וְלֹא שָׁוִים? נִתְבָּאֵר שְׁנֵי אֵלֶּה שֶׁבְּאוֹתִיּוֹתֵיהֶם יָד הֵם שָׁוִים בָּעִנְיָן, שְׁנַיִם לֹא בְעֵינֵיהֶם מִתְבָּאֵר. מֵאֵלּוּ נִבְרְאוּ שָׁמַיִם וָאָרֶץ וְשֶׁעִמָּהֶם. וְאֵלּוּ סְפִירָה רִאשׁוֹנָה, שֶׁהִיא כֶתֶר עֶלְיוֹן. (משלי טו) בכל מקום עיני ה' צפות רעים וטובים. הן מסיעות לשם אחד אות ו' שעשה כמה אותות בארץ מצרים.</p>"],[9522011431,"<p>וַיֹּאמֶר יַעֲקֹב אֶל יוֹסֵף אֵל שַׁדַּי נִרְאָה אֵלַי בְלוּז בְּאֶרֶץ כְּנָעַן. רִבִּי אַבָּא אָמַר, לוּז זוֹ יְרוּשָׁלַיִם הָעֶלְיוֹנָה, שֶׁשּׁוֹרָה שְׁכִינָה בְתוֹכָהּ. אָמַר יַעֲקֹב הָעֶלְיוֹן לְמַטָּה, תֵּן לִי בְרָכָה שֶׁהוּא רוֹצֶה, לְהַרְבּוֹת אֶתְכֶם אֲנִי, וְלָתֵת אֶת הָאָרֶץ לִבְנֵיכֶם. לוּז זוֹ יְרוּשָׁלַיִם הָעֶלְיוֹנָה, הַקָּדוֹשׁ בָּרוּךְ הוּא, נָתַן הַשַּׂר שֶׁהָיוּ בְּרָכָה זוֹ עַל יָדוֹ בְּאֶרֶץ הַקֹּדֶשׁ, אֲבָל מִחוּץ לְאֶרֶץ אַחֶרֶת לֹא תִהְיֶה בְּרָכָה.</p>\n<p>רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (משלי כז) מְבָרֵךְ רֵעֵהוּ בְּקוֹל גָּדוֹל בַּבֹּקֶר הַשְׁכֵּים קְלָלָה תֵּחָשֶׁב לוֹ. הַקָּדוֹשׁ בָּרוּךְ הוּא קָרָא לְיִשְׂרָאֵל אַחִים וְרֵעִים. אֵיזוֹ בְרָכָה נָתַן לָהֶם? שֶׁיִּהְיוּ עַם זֶה טָהוֹר תַּחַת יָדוֹ, וְלִהְיוֹת עֲלֵיהֶם שׁוֹמֵר.</p>\n<p>אַשְׁרֵי חֶלְקוֹ שֶׁל הָעָם הַטָּהוֹר הַזֶּה שֶׁהוּא עֲלֵיהֶם, שֶׁנִּקְרָאִים בָּעֶלְיוֹנִים בָּנִים חֲבִיבִים יוֹתֵר מֵהָעֶלְיוֹנִים. כָּתוּב (דברים יד) בָּנִים אַתֶּם לַה', מַהוּ הַכֹּל בִּשְׁבִיל זֶה. מַה הוּא? בִּשְׁבִיל שֶׁהִשְׁתַּלֵּם הַשֵּׁם בַּחוֹתָם שֶׁלָּהֶם, שֶׁהֵם מְהוּלִים.</p>\n<p>בֹּא רְאֵה, בִּפְנֵי הָאָדָם שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְחָסֵר יוֹ\"ד מִמֶּנּוּ וְלֹא נִתְקָן. בָּא אַבְרָהָם וְחִבֵּב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאָמַר לוֹ, בְּךְ יְתֻקַּן הַשֵּׁם, וְנִמּוֹל, וְנִתְקַן הַשֵּׁם בַּיּוֹ\"ד שֶׁל הַמִּילָה. בִּפְנֵי הָאָדָם שִׁי\"ן שֶׁל שַׁדַּ\"י וְד', חָסֵר יוֹ\"ד, נִתְקַן בַּיּוֹ\"ד שֶׁל הַמִּילָה, וְאָז נִקְרְאוּ בָּנִים לַה', בָּנִים קְדוֹשִׁים.</p>\n<p>וּכְשֶׁמְּטַמְּאִים אֶת אוֹת הַבְּרִית הַקְּדוֹשָׁה וּמַכְנִיסוֹ לְרָשׁוּת אַחֶרֶת, עוֹלָה מִמֶּנּוּ קְדֻשַּׁת הַחוֹתָם, וְהוּא כְּמוֹ שֶׁהֶחֱרִיב עוֹלָם, וְטִמֵּא אֶת הַחוֹתָם שֶׁנִּתְקָן בּוֹ שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וַהֲרֵי הוּא הֶחֱרִיב אֶת הָעוֹלָם.</p>\n<p>רַבִּי אַבָּא הָיָה הוֹלֵךְ מִקַּפּוֹטְקִיָּא, וְהָיָה עִמּוֹ רַבִּי יוֹסֵי. עַד שֶׁהָיוּ הוֹלְכִים, רָאוּ אִישׁ אֶחָד שֶׁהָיָה בָּא וְרֹשֶׁם אֶחָד בְּפָנָיו. אֲבָל אוֹי לָהֶם לָרְשָׁעִים שֶׁיָּמוּתוּ בְּלִי תְשׁוּבָה, שֶׁלֹּא יָזוּז מִמֶּנּוּ הָרֹשֶׁם לֹא בָּעוֹלָם הַזֶּה וְלֹא בָּעוֹלָם הַבָּא.</p>"],[9522011432,"<p>וַיֹּאמֶר אֵלַי הִנְנִי מַפְרְךְ וְהִרְבִּיתִךְ. רַבִּי אַבָּא פָּתַח וְאָמַר, פָּסוּק זֶה (ישעיה כט) לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב וְלֹא עַתָּה פָּנָיו יֶחֱוָרוּ, וְכִי אִישׁ שֶׁאוֹמֵר טוֹב לְבֶן אָדָם כְּמוֹתוֹ, אִם לֹא יַשְׁלִים מַה שֶּׁאָמַר, פָּנָיו מִתְבַּיְּשׁוֹת, עַל אַחַת כַּמָּה וְכַמָּה מֵהָעֶלְיוֹנִים לִבְנֵי אָדָם, שֶׁאִם לֹא מֵבִיא כָּל טוֹב שֶׁאָמַר עַל בָּנָיו, פָּנָיו מִתְבַּיְּשׁוֹת.</p>\n<p>אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, אֲנִי יִשְׂרָאֵל הָעֶלְיוֹן שֶׁאֲנִי מַרְבְּךְ וּמְגַדֶּלְךְ, הַבְּרָכָה הַזּוֹ שֶׁנָּתַן לִי, וְאֶתֵּן אֶרֶץ זוֹ לִבְנֵיכֶם לֹא הָיְתָה בָּאָרֶץ, לֹא הָיָה עִמָּם כְּשֶׁיָּבא קֵץ הַמָּשִׁיחַ וִיתֻקַּן. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב - כָּעֵת (לא) פְּנֵי יַעֲקֹב שֶׁלְּמַעְלָה לֹא מִתְבַּיְּשִׁים מִשֶּׁאָמַר לָהֶם אֶתֵּן, הֲרֵי עַד עַכְשָׁו לֹא הָיוּ בְיָדוֹ, וְהָיוּ פָנִים מְבֻיָּשׁוֹת. כָּעֵת שֶׁלּוֹ מִסְתַּיֵּעַ מִלִּפְנֵי רִבּוֹן הַשָּׁמַיִם וְהָאָרֶץ.</p>\n<p>כְּמוֹ שֶׁאָמַרְנוּ, נִלְחָמִים בַּעֲמָלֵק כְּשֶׁיִּשְׁתַּלֵּם הַקֵּץ, וְלֹא יִהְיֶה אֶלָּא בְּחֹזֶק יָד, כְּמוֹ שֶׁהָיִיתָ בְּיוֹם קְרָב, וְיָצָא ה' וְנִלְחַם בַּגּוֹיִם הָהֵם, שֶׁלּוֹ וְלֹא אַחֵר.</p>"],[9522011433,"<p>וְעַתָּה שְׁנֵי בָנֶיךְ הַנּוֹלָדִים לְךְ - זֶה יִשְׂרָאֵל שֶׁלְּמַטָּה שֶׁמְּקוֹמָם בַּגָּלוּת, בָּנָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנּוֹלְדוּ בֵּין הָעַמִּים. לָמַדְנוּ, אָמַר רַבִּי יוֹסֵי, יִשְׂרָאֵל, כְּשֶׁיִּהְיוּ בָּאָרֶץ הַקְּדוֹשָׁה שֶׁל יִשְׂרָאֵל דָּרִים בָּאָרֶץ, כְּשֶׁיָּבא הַמָּשִׁיחַ יִהְיוּ עִם אֲחֵיהֶם שֶׁיִּלָּווּ אַחֲרֵיהֶם, שֶׁלֹּא נִקְרָא גָלוּת אֶלָּא לְמִי שֶׁהוּא דָר בְּאֶרֶץ נָכְרִיָּה, הֵם נִקְרָאִים גּוֹלִים.</p>\n<p>וְזָכַרְתִּי אֶת בְּרִית יַעֲקוֹב (ויקרא כו), וָא\"ו יְתֵרָה. תָּבא וָא\"ו שֶׁהִסְתַּלְּקָה כְּשֶׁחָרַב הַבַּיִת, וְתִהְיֶה סִיּוּעַ לְיַעֲקֹב כְּשֶׁזֶּה יִהְיֶה, וְיִהְיֶה לְבֵן קָדוֹשׁ אֶרֶץ יְרֻשַּׁת עוֹלָם, וְיִהְיוּ בָנָיו בְּאַרְצָם, שֶׁגָּרוּ בָהּ מִקֹּדֶם לָזֶה בְּאַרְצָם. אַשְׁרֵי חֶלְקָם.</p>\n<p>כָּעֵת בָּנִים, שֶׁקָּרָה לָהֶם (תהיו הולכים גדולים) שֶׁהֻגְלוּ לְחוּץ לָאָרֶץ וְנִשְׁכְּחוּ, וְהִתְרַבּוּ, וְיֹאמַר יַעֲקֹב הָעֶלְיוֹן לַתַּחְתּוֹן: בָּנִים שֶׁלְּךְ שֶׁהֵם בְּחוּץ לָאָרֶץ שֶׁנּוֹלְדוּ בַּגָּלוּת בְּכָל אֶרֶץ וְאֶרֶץ, עַד שֶׁאֲנִי אֶכָּנֵס לְמִצְרַיִם וְאֶעֱשֶׂה בָהֶם דִּין עַל חֲטָאֵיהֶם, אֵינִי מַעֲלֶה אֶת בָּנֶיךְ שֶׁנִּבְרְאוּ בַּגָּלוּת בְּחוּץ לָאָרֶץ בְּאֶרֶץ רְחוֹקָה, וְאַף עַל גַּב שֶׁהֵם רַבִּים וְנִשְׁכְּחוּ הֵם שֶׁלִּי, כְּשֶׁרָאִיתִי גָּלוּת זוֹ שֶׁלָּהֶם וְרִפֵּאתִי אֶת כְּאֵבֵיכֶם וְשָׁמַעְתִּי אֶת קוֹלָם. רְאוּבֵן - (בראשית כט) כִּי רָאָה ה' אֶת עָנְיִי. שִׁמְעוֹן - כִּי שָׁמַע ה' כִּי שְׂנוּאָה אָנֹכִי. וְחָשַׁבְתָּ בְּלִבְּךְ כְּאִלּוּ יִהְיוּ לְפָנַי הֵם, וּמִשֶּׁנָּשׁוּב מִמִּצְרַיִם מִלַּעֲשׂוֹת דִּין, נַעֲלֶה אוֹתָם מֵאֶרֶץ גָּלוּתָם.</p>\n<p>רַבִּי אַבָּא אָמַר, מִכָּאן (ישעיה סו) וְהֵבִיאוּ אֶת כָּל אֲחֵיכֶם מִכָּל הַגּוֹיִם מִנְחָה לַה'. רוֹצֶה לוֹמַר, כְּשֶׁיִּהְיֶה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּדִין בְּמִצְרַיִם, בְּאוֹתוֹ זְמַן יָבִיאוּ כָּל הָעַמִּים מִנְחָה כְּשֶׁיִּשְׁמְעוּ שְׁמוּעָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, הַיְנוּ (שם ב) וְנָהֲרוּ אֵלָיו כָּל הַגּוֹיִם.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי שִׁמְעוֹן, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת לְכָל צַדִּיק וְצַדִּיק חֻפָּה בִּירוּשָׁלַיִם, (ירמיה טז) קוֹל שָׂשׂוֹן וְקוֹל שִׂמְחָה קוֹל חָתָן וְקוֹל כַּלָּה, כְּשֶׁתָּשׁוּב הַמַּלְכָּה לַמֶּלֶךְ וְיַעֲשֶׂה לָהּ אֵרוּסִין. זֶהוּ שֶׁכָּתוּב (שיר ג) צְאֶינָה וּרְאֶינָה וְגוֹ' בְּיוֹם חֲתֻנָּתוֹ וּבְיוֹם שִׂמְחַת לִבּוֹ. בְּיוֹם חֲתֻנָּתוֹ - זֶה מַתַּן תּוֹרָה. וּבְיוֹם שִׂמְחַת לִבּוֹ - זֶה בִּנְיַן בֵּית הַמִּקְדָּשׁ, שֶׁיִּבָּנֶה בִּמְהֵרָה בְיָמֵינוּ.</p>\n<p>וּמוֹלַדְתְּךָ אֲשֶׁר הוֹלַדְתָּ אַחֲרֵיהֶם לְךְ יִהְיוּ, זֶה יִשְׂרָאֵל לְמַטָּה, לָאָבוֹת שֶׁהֵם מֶרְכָּבוֹת יִהְיוּ שְׁמוֹתֵיהֶם בְּסוֹד שֶׁנּוֹלְדוּ לְאַחַר מִכֵּן, עַל שֵׁם שֶׁאֲחֵיהֶם יִהְיוּ מַקְרִיבִים בַּיְרֻשָּׁה שֶׁלָּהֶם.</p>\n<p>לָמַדְנוּ, אָמַר רַבִּי שִׁמְעוֹן, וּמוֹלַדְתְּךְ - זוֹ יְרוּשָׁלַיִם שֶׁל מַטָּה, (ויקרא יח) מוֹלֶדֶת בַּיִת, בְּפָרָשַׁת עֲרָיוֹת. יְרוּשָׁלַיִם לְמַטָּה. גְּבָרִים שֶׁנּוֹלְדוּ זוֹ יְרוּשָׁלַיִם. אַחַר זֶה שֶׁיָּשׁוּבוּ הָעוֹלָם לְרִבּוֹן הַשָּׁמַיִם בִּירוּשָׁלַיִם, כְּשֶׁהִתְגַּיְּרוּ לֹא נִקְרְאוּ אֶלָּא עַל שְׁמָם, שֶׁהוּא בֶּן יִשְׂרָאֵל, וְלֹא יִקָּרְאוּ כְּמוֹ שֶׁאֲבוֹתֵיהֶם, גֵּר מִקַּפּוֹטְקִיָּא, אֶלָּא בְּזֶה יִשְׂרָאֵל.</p>\n<p>לְךָ יִהְיוּ - צָרִיךְ לוֹמַר עַל שֵׁם יִשְׂרָאֵל הֵם יִקָּרְאוּ, עַל שֵׁם אֲחֵיהֶם יִקָּרְאוּ בְנַחֲלָתָם, וּכְשֶׁיָּשׁוּבוּ לֹא יְקַבְּלוּ יְרֻשָּׁה אֵלּוּ עִם יִשְׂרָאֵל בָּאָרֶץ, וְיִטֹּל כָּל שֵׁבֶט וְשֵׁבֶט אֶת שֶׁלּוֹ, וְהָאֲנָשִׁים מִמֶּנּוּ, כָּל אֶחָד לְפִי מִנְיָנוֹ.</p>"]]});
